files.canvas/CanvasDirector.re:
open Virtual_dom.Vdom;
open Util.WebUtil;

/* CanvasDirector — the canvas's orchestrator outside Hazel.

   It holds the previous snapshot and layout; on a new snapshot plus a
   cause it queues a beat (CanvasBuffer's pacing), and each render lays the
   paced graph out, diffs it against the previous render into a
   CanvasScore.diff, plans the score, validates it and plays it
   (CanvasEnact), with the avatar, camera, bubbles and ripple field as in
   Hazel.

   This replaces what CanvasSidebar + CanvasPresentation did for the
   canvas itself. The sections marked LIFTED are taken from Hazel's
   CanvasSidebar.re (commit in UPSTREAM.md) with the Hazel model swapped
   for this module's state; they are kept in upstream's order and wording
   so a diff against CanvasSidebar.view_impl stays readable. Left out:
   authoring, probes and value cards, the info panel, the toolbar, the
   replay panel, settings persistence. */

open Js_of_ocaml;

/* ---------- what the host says ---------- */

type cause = {
  label: string, /* the tool or step that produced the snapshot */
  site: option(string), /* the definition it acted on (qualified name) */
  ok: bool,
};

/* the one board: a reset starts a new "slide" so every per-slide memory
   (previous snapshot, frame, camera exposure, avatar site) starts over,
   exactly as a slide switch does upstream */
let slide_no: ref(int) = ref(0);
let current_slide = (): string => "board/" ++ string_of_int(slide_no^);

/* the newest snapshot the host pushed (upstream: the live editor) */
let live: ref(CanvasGraph.t) = ref(CanvasGraph.empty);
/* the last cause: where the avatar rests between scores */
let last_cause: ref(option((cause, float))) = ref(None);

/* settings (upstream: globals.settings.canvas_*) */
let pace: ref(bool) = ref(true);
let follow: ref(bool) = ref(true);
let canvas_zoom: ref(float) = ref(1.);
/* the host's agent is working (upstream: awaiting a reply) */
let busy: ref(bool) = ref(false);
/* streamed reasoning for the thought cloud */
let thought: ref(string) = ref("");

/* selection (upstream: sidebar.canvas_focus / canvas_focus_ty) */
let focused: ref(option(string)) = ref(None);
let focused_ty: ref(option(string)) = ref(None);
let focused_value: ref(option(string)) = ref(None);
let hovered_edge: ref(option(string)) = ref(None);
/* (name, kind, where) of what was clicked; kind is "function", "type",
   "module", "value", "test", "builtin", "derived", "ghost" or "product" */
let on_select:
  ref((string, string, option(CanvasGraph.handle)) => unit) =
  ref((_, _, _) => ());

/* manual arrangement (upstream: settings.canvas_node_offsets), per slide */
let node_offsets: ref(list((string, (float, float)))) = ref([]);

/* ---------- render loop ---------- */

let render_fwd: ref(unit => unit) = ref(() => ());
let render_queued: ref(bool) = ref(false);
/* upstream: globals.inject_global(Set(CanvasTick)) */
let request_render = (): unit =>
  if (! render_queued^) {
    render_queued := true;
    ignore(
      Dom_html.window##requestAnimationFrame(
        Js.wrap_callback(_ => {
          render_queued := false;
          render_fwd^();
        }),
      ),
    );
  };
let tick: Effect.t(unit) = Effect.of_sync_fun(request_render, ());

let schedule_tick = (delay: float): unit => {
  let cb =
    Js.Unsafe.callback(() => {
      CanvasBuffer.tick_fired();
      render_fwd^();
    });
  ignore(Js.Unsafe.global##setTimeout(cb, delay));
};

/* ---------- LIFTED: CanvasSidebar.re top-level state ---------- */

let pan_slack = CanvasRipple.pan_slack;
/* set to force a re-anchor on the next render (fit button) */
let pending_anchor: ref(bool) = ref(false);
/* where anchoring scrolls to; recomputed each render so the content
   sits centered in the pane (infinite canvas: centering can borrow
   the slack when the graph is smaller than the pane) */
let anchor_target: ref((float, float)) = ref((pan_slack, pan_slack));

/* pinch-zoom plumbing: the wheel listener must be non-passive (to
   preventDefault the browser's page zoom on ctrl+wheel), so it is
   installed raw on the scroll element; these refs carry the current
   zoom and dispatcher across renders */
let zoom_now = CanvasCamera.zoom_now;
let zoom_send = CanvasCamera.zoom_send;
let install_zoom_listener = (): unit => {
  switch (Util.JsUtil.get_elem_by_id_opt("canvas-scroll")) {
  | None => ()
  | Some(el) =>
    let el' = Js.Unsafe.coerce(el);
    let installed: bool =
      Js.Optdef.test(Js.Unsafe.get(el', "__zoomInstalled"));
    if (!installed) {
      Js.Unsafe.set(el', "__zoomInstalled", Js.bool(true));
      /* panning and pane resizes must redraw the viewport-fixed dot
         field (a resize otherwise leaves a stale, mis-scaled frame
         until the next scroll) */
      ignore(
        Js.Unsafe.meth_call(
          el',
          "addEventListener",
          [|
            Js.Unsafe.inject(Js.string("scroll")),
            Js.Unsafe.inject(
              Js.Unsafe.callback(() => {
                CanvasCamera.note_scroll();
                CanvasRipple.request_draw();
              }),
            ),
            Js.Unsafe.inject(
              Js.Unsafe.obj([|
                ("passive", Js.Unsafe.inject(Js.bool(true))),
              |]),
            ),
          |],
        ),
      );
      if (Js.Optdef.test(Js.Unsafe.get(Js.Unsafe.global, "ResizeObserver"))) {
        let obs =
          Js.Unsafe.new_obj(
            Js.Unsafe.get(Js.Unsafe.global, "ResizeObserver"),
            [|
              Js.Unsafe.inject(
                Js.Unsafe.callback(() => {
                  CanvasRipple.request_draw();
                  /* PORTOLAN: no app loop re-renders on a resize here */
                  request_render();
                }),
              ),
            |],
          );
        ignore(
          Js.Unsafe.meth_call(obs, "observe", [|Js.Unsafe.inject(el')|]),
        );
      };
      let last = ref(0.);
      let pending_dy = ref(0.);
      let anim_off_until = ref(0.);
      let cb =
        Js.Unsafe.callback((evt: Js.t(Js.Unsafe.any)) => {
          let ctrl: bool = Js.to_bool(Js.Unsafe.coerce(evt)##.ctrlKey);
          if (ctrl) {
            ignore(Js.Unsafe.meth_call(evt, "preventDefault", [||]));
            let dy: float = Js.Unsafe.coerce(evt)##.deltaY;
            let now: float =
              Js.Unsafe.coerce(Js.Unsafe.global)##._Date##now();
            /* accumulate between throttle windows: dropping deltas
               made pinching feel sluggish */
            pending_dy := pending_dy^ +. dy;
            if (now -. last^ > 30.) {
              last := now;
              let z0 = zoom_now^;
              let z = z0 *. exp(-. pending_dy^ *. 0.018);
              pending_dy := 0.;
              /* detent at 1:1 so pinching back to normal lands exactly */
              let z = abs_float(z -. 1.) < 0.05 ? 1. : z;
              let z = CanvasZoom.clamp(z);
              switch (zoom_send^) {
              | Some(send) =>
                /* apply the zoom IMPERATIVELY and correct the scroll
                   in the same frame: the old flow (state update, then
                   a delayed correction) let the anchor point jump and
                   snap back on every step — the pinch judder. The
                   auto-fit zoom transition is suppressed while a
                   pinch is live for the same reason. */
                let root =
                  Js.Unsafe.meth_call(
                    Js.Unsafe.global##.document,
                    "querySelector",
                    [|Js.Unsafe.inject(Js.string(".canvas-root"))|],
                  );
                switch (Js.Opt.to_option(root)) {
                | None => send(z)
                | Some(root) =>
                  let cl =
                    Js.Unsafe.get(Js.Unsafe.coerce(root), "classList");
                  if (now > anim_off_until^) {
                    ignore(
                      Js.Unsafe.meth_call(
                        cl,
                        "add",
                        [|Js.Unsafe.inject(Js.string("no-zoom-anim"))|],
                      ),
                    );
                  };
                  anim_off_until := now +. 250.;
                  ignore(
                    Js.Unsafe.global##setTimeout(
                      Js.Unsafe.callback(() =>
                        if (Js.Unsafe.coerce(Js.Unsafe.global)##._Date##now()
                            >= anim_off_until^) {
                          ignore(
                            Js.Unsafe.meth_call(
                              cl,
                              "remove",
                              [|
                                Js.Unsafe.inject(Js.string("no-zoom-anim")),
                              |],
                            ),
                          );
                        }
                      ),
                      260,
                    ),
                  );
                  Js.Unsafe.coerce(root)##.style##.zoom :=
                    Js.string(Printf.sprintf("%.4f", z));
                  let rect =
                    Js.Unsafe.meth_call(el', "getBoundingClientRect", [||]);
                  /* measure from the scroll ORIGIN (inside the
                     border), not the border box */
                  let mx: float =
                    Js.Unsafe.coerce(evt)##.clientX
                    -.
                    Js.Unsafe.coerce(rect)##.left
                    -.
                    Js.Unsafe.coerce(el')##.clientLeft;
                  let my: float =
                    Js.Unsafe.coerce(evt)##.clientY
                    -.
                    Js.Unsafe.coerce(rect)##.top
                    -.
                    Js.Unsafe.coerce(el')##.clientTop;
                  let sl: float = Js.Unsafe.coerce(el')##.scrollLeft
                  and st: float = Js.Unsafe.coerce(el')##.scrollTop;
                  let r = z /. z0;
                  /* the pan slack doesn't scale with zoom, so the
                     fixed-point math runs in board coordinates */
                  Js.Unsafe.coerce(el')##.scrollLeft :=
                    (sl +. mx -. pan_slack) *. r +. pan_slack -. mx;
                  Js.Unsafe.coerce(el')##.scrollTop :=
                    (st +. my -. pan_slack) *. r +. pan_slack -. my;
                  zoom_now := z;
                  CanvasRipple.zoom := z;
                  CanvasCamera.note_user_zoom();
                  CanvasRipple.request_draw();
                  send(z);
                };
              | None => ()
              };
            };
          };
        });
      ignore(
        Js.Unsafe.meth_call(
          el',
          "addEventListener",
          [|
            Js.Unsafe.inject(Js.string("wheel")),
            Js.Unsafe.inject(cb),
            Js.Unsafe.inject(
              Js.Unsafe.obj([|
                ("passive", Js.Unsafe.inject(Js.bool(false))),
              |]),
            ),
          |],
        ),
      );
    };
  };
};

/* fit: one camera animation moving zoom AND scroll together so the
   graph center stays pinned at the pane center throughout */
let animate_fit =
    (~z_to: float, ~lw: float, ~lh: float, ~aw: float, ~ah: float): unit =>
  CanvasCamera.animate(
    ~aw,
    ~ah,
    ~zoom=Some(z_to),
    ~dur=320.,
    ~easing=CanvasCamera.EaseOut,
    (lw /. 2., lh /. 2.),
  );
let last_anchor_slide: ref(string) = ref("");
/* anchor the scroll to the board (skipping the slack margin) whenever
   the pane is fresh, the slide changed, or an anchor was requested */
let ensure_scroll_anchor = (slide: string): unit =>
  ignore(
    Dom_html.window##requestAnimationFrame(
      Js.wrap_callback(_ => {
        switch (Util.JsUtil.get_elem_by_id_opt("canvas-scroll")) {
        | None => ()
        | Some(el) =>
          let el' = Js.Unsafe.coerce(el);
          let fresh = !Js.Optdef.test(Js.Unsafe.get(el', "__panAnchored"));
          if (fresh || last_anchor_slide^ != slide || pending_anchor^) {
            Js.Unsafe.set(el', "__panAnchored", Js.bool(true));
            last_anchor_slide := slide;
            pending_anchor := false;
            CanvasCamera.mark_driving();
            let (tx, ty) = anchor_target^;
            el'##.scrollLeft := tx;
            el'##.scrollTop := ty;
          };
        }
      }),
    ),
  );

/* avatar continuity: hold the last successfully resolved site so the
   avatar persists through interstitials (turn start, pathless tools,
   paths gone stale mid-burst) instead of blinking out */
let last_avatar_id: ref(option(string)) = ref(None: option(string));

/* While a node drag is in progress the pane measurements are FROZEN:
   any mid-drag change (scrollbar appearing, overlay quirks, content
   growth) would otherwise re-derive the fit/centering frame and bounce
   every node between adjacent grid cells under the user's cursor. */
let drag_active: ref(bool) = ref(false);
let cached_avail_w: ref(option(float)) = ref(None: option(float));
let cached_avail_h: ref(option(float)) = ref(None: option(float));

/* Sticky frame for manually-arranged slides: pins/offsets are stored in
   the pre-normalization frame, so re-deriving the frame from a changed
   program re-anchors EVERY manual position (placement pins landed away
   from the click; pinned nodes flew off-pane on unrelated edits). Once a
   slide has any manual position, its frame (origin + scales) is frozen
   here — re-derived only on pane resize, slide switch, or reset layout. */
type frame_cache = {
  fc_slide: string,
  fc_burst: int, /* the burst it was derived in (CanvasLog turn) */
  fc_nodes: int, /* nodes in the graph it was derived from */
  fc_origin: CanvasLayout.pos,
  fc_x_scale: float,
  fc_y_scale: float,
  fc_avail_w: float,
};
let cached_frame: ref(option(frame_cache)) =
  ref(None: option(frame_cache));

/* the previous render's layout, and the elements a score is still erasing:
   a removed node or arrow stays on the board as a ghost (rendered from
   this layout, at its old place) until its act's cue — A2 for removals */
let last_layout: ref(option(CanvasLayout.t)) = ref(Option.none);
type leaving = {
  l_nodes: list(CanvasLayout.node_layout),
  l_edges: list(CanvasLayout.edge_layout),
  l_until: float /* ms; dropped from the render after this */
};
let leaving: ref(option(leaving)) = ref(Option.none);

/* an element's LOOK: what a viewer would notice changing without an
   actor (A2 for modifications). Tests/values from evaluation are not
   the agent's edit and are exempt. */
let node_look = (n: CanvasGraph.tynode) => (
  n.label,
  n.ctrs,
  n.n_ty,
  n.n_err,
  n.deps,
);
let edge_look = (e: CanvasGraph.edge) => (
  e.e_label,
  e.e_ty,
  e.e_err,
  e.e_hole,
  e.e_src,
  e.dst,
  e.e_deps,
);
/* a changed element renders with its OLD record until its act's cue
   (absolute ms), then swaps with a pulse */
type staged = {
  s_nodes: list((string, float, CanvasGraph.tynode)),
  s_edges: list((string, float, CanvasGraph.edge)),
};
let staged: ref(staged) =
  ref({
    s_nodes: [],
    s_edges: [],
  });

/* value badges present at the previous render, for the score's diff */
let last_value_snapshot: ref((string, list(string))) = ref(("", []));
/* values share the score's node namespace under a prefix */
let value_score_key = (v_name: string): string => "val:" ++ v_name;
let value_of_score_key = (k: string): option(string) =>
  String.length(k) > 4 && String.sub(k, 0, 4) == "val:"
    ? Some(String.sub(k, 4, String.length(k) - 4)) : None;

let last_placed: ref(list((string, float))) = ref([]);
let note_placed = (key: string): unit =>
  last_placed :=
    [(key, CanvasBuffer.now())]
    @ List.filter(((k, _)) => k != key, last_placed^);

/* previous render's nodes, for removal detection: a node that vanishes
   gets a suction ripple (negative amplitude) at its last position.
   Slide switches and wholesale rewrites are gated by the removal count. */
let last_node_snapshot: ref((string, list((string, (float, float))))) =
  ref(("", []));
/* previous render's function edges (by name), for the arrival
   choreography: new edges during an agent beat are drawn by the avatar */
let last_edge_snapshot: ref((string, list(string))) = ref(("", []));

/* collapsed module hulls (root module names); toggled from the hull
   label */
let collapsed_modules: ref(list(string)) = ref([]);
/* collapse/expand transitions must not read as node deletions: the
   removal differ skips its suctions inside this window */
let collapse_fx_until: ref(float) = ref(0.);

/* hide a collapsed module's internals pre-layout: members, their edges
   and orbit values, and the satellite terminals their functions grew.
   The former node and the module's own value stay. Returns the graph +
   (root, hidden-member count) pairs for the hull label. */
let collapse_filter =
    (g: CanvasGraph.t): (CanvasGraph.t, list((string, int))) =>
  if (collapsed_modules^ == []) {
    (g, []);
  } else {
    let hidden = r => List.mem(r, collapsed_modules^);
    let member_edges =
      List.filter(
        (e: CanvasGraph.edge) =>
          switch (e.m_path) {
          | [r, ..._] => hidden(r)
          | [] => false
          },
        g.edges,
      );
    let member_values =
      List.filter(
        (v: CanvasGraph.value) =>
          switch (v.m_path) {
          | [r, ..._] => hidden(r)
          | [] => false
          },
        g.values,
      );
    let member_qnames =
      List.map((e: CanvasGraph.edge) => e.e_name, member_edges)
      @ List.map((v: CanvasGraph.value) => v.v_name, member_values);
    let is_member_sat = (n: CanvasGraph.tynode): bool =>
      switch (n.sat) {
      | Some(_) =>
        List.exists(
          qn => {
            let suffix = "@" ++ qn;
            let ln = String.length(n.key)
            and ls = String.length(suffix);
            ln >= ls && String.sub(n.key, ln - ls, ls) == suffix;
          },
          member_qnames,
        )
      | None => false
      };
    let drop_node = (n: CanvasGraph.tynode): bool =>
      switch (n.m_path) {
      | [r, ..._] => hidden(r) && n.key != "{}@" ++ r
      | [] => is_member_sat(n)
      };
    let counts =
      List.map(
        r => {
          let c =
            List.length(
              List.filter(
                (n: CanvasGraph.tynode) =>
                  switch (n.m_path) {
                  | [r', ..._] => r' == r && n.key != "{}@" ++ r
                  | [] => false
                  },
                g.nodes,
              ),
            )
            + List.length(
                List.filter(
                  (e: CanvasGraph.edge) =>
                    switch (e.m_path) {
                    | [r', ..._] => r' == r
                    | [] => false
                    },
                  g.edges,
                ),
              )
            + List.length(
                List.filter(
                  (v: CanvasGraph.value) =>
                    switch (v.m_path) {
                    | [r', ..._] => r' == r
                    | [] => false
                    },
                  g.values,
                ),
              );
          (r, c);
        },
        collapsed_modules^,
      );
    (
      {
        ...g,
        nodes: List.filter(n => !drop_node(n), g.nodes),
        edges:
          List.filter(
            (e: CanvasGraph.edge) => !List.mem(e, member_edges),
            g.edges,
          ),
        values:
          List.filter(
            (v: CanvasGraph.value) => !List.mem(v, member_values),
            g.values,
          ),
      },
      counts,
    );
  };

let last_avatar_pos: ref(option(CanvasLayout.pos)) = ref(None);
let last_followed_id: ref(option(string)) = ref(None);
let last_followed: ref(option(CanvasLayout.pos)) = ref(None);
let last_followed_busy: ref(bool) = ref(false);
let last_seen_slide: ref(string) = ref("");
let last_pacing_live: ref(bool) = ref(false);
let last_logged_avatar: ref((option(string), string)) = ref((None, "off"));
let last_logged_busy: ref(bool) = ref(false);

/* collapse/uncollapse memo: the layout memo keys on the graph's physical
   identity, so the filtered graph must be the same value while its
   inputs are */
let collapse_cache:
  ref(option((CanvasGraph.t, list(string), (CanvasGraph.t, list((string, int)))))) =
  ref(None);
let collapse_cached = (g: CanvasGraph.t) =>
  switch (collapse_cache^) {
  | Some((g0, c0, r)) when g0 === g && c0 == collapsed_modules^ => r
  | _ =>
    let r = collapse_filter(g);
    collapse_cache := Some((g, collapsed_modules^, r));
    r;
  };

/* beat weight for pacing: graph elements (by stable name) that differ
   between two states — nodes by key, edges by qualified name */
let graph_delta = (a: CanvasGraph.t, b: CanvasGraph.t): int => {
  let keys = (g: CanvasGraph.t) =>
    List.map((n: CanvasGraph.tynode) => n.key, g.nodes)
    @ List.map((e: CanvasGraph.edge) => "e:" ++ e.e_name, g.edges);
  let ka = keys(a)
  and kb = keys(b);
  List.length(List.filter(k => !List.mem(k, kb), ka))
  + List.length(List.filter(k => !List.mem(k, ka), kb));
};

/* a card just opened / closed / resized: re-fit the camera after the
   render that lays it out */
let fit_pending: ref(bool) = ref(false);
let overview_pending: ref(bool) = ref(false);
/* the render right after a burst ends re-frames the graph: that one big
   move is the tidy act. A big move the USER caused is not scored: it
   plays on the staged beat at once, not after an actor's drift. */
let burst_end_reframe: ref(bool) = ref(false);

/* ---- imperative layout follow (node drag): apply a layout's geometry
   straight to the DOM — no vdom, no render ---- */
module LayoutDom = {
  let set_attr = (el, name: string, v: string) =>
    ignore(
      Js.Unsafe.meth_call(
        el,
        "setAttribute",
        [|
          Js.Unsafe.inject(Js.string(name)),
          Js.Unsafe.inject(Js.string(v)),
        |],
      ),
    );
  let set_pos = (id: string, x: float, y: float) =>
    switch (Util.JsUtil.get_elem_by_id_opt(id)) {
    | Some(el) =>
      let st = Js.Unsafe.coerce(el)##.style;
      st##.left := Js.string(Printf.sprintf("%.1fpx", x));
      st##.top := Js.string(Printf.sprintf("%.1fpx", y));
    | None => ()
    };
  let fmt' = (v: float) => Printf.sprintf("%f", v);
  let pull_back = (p: CanvasLayout.pos, c: CanvasLayout.pos, d: float) => {
    let vx = p.x -. c.x
    and vy = p.y -. c.y;
    let len = max(1., Float.hypot(vx, vy));
    CanvasLayout.{
      x: p.x -. vx /. len *. d,
      y: p.y -. vy /. len *. d,
    };
  };
  let apply_layout = (l: CanvasLayout.t): unit => {
    List.iter(
      (nl: CanvasLayout.node_layout) =>
        set_pos(CanvasView.node_dom_id(nl.node.key), nl.p.x, nl.p.y),
      l.nodes,
    );
    List.iter(
      (el: CanvasLayout.edge_layout) => {
        let e = el.edge;
        if (el.endo) {
          switch (
            Util.JsUtil.get_elem_by_id_opt(
              "corbit-" ++ CanvasView.sanitize(e.e_name),
            )
          ) {
          | Some(c) =>
            set_attr(c, "cx", fmt'(el.dst_p.x));
            set_attr(c, "cy", fmt'(el.dst_p.y));
          | None => ()
          };
        } else {
          switch (
            Util.JsUtil.get_elem_by_id_opt(
              "cpath-" ++ CanvasView.sanitize(e.e_name),
            )
          ) {
          | Some(path_el) =>
            set_attr(path_el, "d", CanvasLayout.edge_path(~pull=9., el))
          | None => ()
          };
        };
        set_pos(
          CanvasView.edge_dom_id(e.e_name),
          el.label_p.x,
          el.label_p.y,
        );
        switch (
          Util.JsUtil.get_elem_by_id_opt(
            "clead-" ++ CanvasView.sanitize(e.e_name),
          )
        ) {
        | Some(lel) =>
          set_attr(lel, "x1", fmt'(el.label_p.x));
          set_attr(lel, "y1", fmt'(el.label_p.y -. 8.));
          set_attr(lel, "x2", fmt'(el.label_anchor.x));
          set_attr(lel, "y2", fmt'(el.label_anchor.y));
        | None => ()
        };
      },
      l.edges,
    );
    List.iteri(
      (
        _i,
        (a, b, cp, pp): (string, string, CanvasLayout.pos, CanvasLayout.pos),
      ) => {
        let pp' = pull_back(pp, cp, 5.);
        switch (
          Util.JsUtil.get_elem_by_id_opt(CanvasView.formation_dom_id(a, b))
        ) {
        | Some(el) =>
          set_attr(
            el,
            "d",
            CanvasLayout.relation_path(
              ~nodes=l.nodes,
              ~from_key=a,
              ~to_key=b,
              cp,
              pp',
            ),
          )
        | None => ()
        };
      },
      l.formations,
    );
    List.iteri(
      (
        _i,
        (a, b, dp, tp): (string, string, CanvasLayout.pos, CanvasLayout.pos),
      ) => {
        let tp' = pull_back(tp, dp, 5.);
        switch (Util.JsUtil.get_elem_by_id_opt(CanvasView.dep_dom_id(a, b))) {
        | Some(el) =>
          set_attr(
            el,
            "d",
            CanvasLayout.relation_path(
              ~nodes=l.nodes,
              ~from_key=a,
              ~to_key=b,
              dp,
              tp',
            ),
          )
        | None => ()
        };
      },
      l.dep_links,
    );
    List.iter(
      (vl: CanvasLayout.value_layout) =>
        set_pos(CanvasView.value_dom_id(vl.value.v_name), vl.p.x, vl.p.y),
      l.values,
    );
    /* hull sausages track exactly (no springs for paths) */
    List.iter(
      path =>
        List.iter(
          ((id, d, _)) =>
            switch (Util.JsUtil.get_elem_by_id_opt(id)) {
            | Some(el) => set_attr(el, "d", d)
            | None => ()
            },
          CanvasView.hull_sausages_at(l, path),
        ),
      CanvasView.hull_paths_of(l),
    );
    CanvasJelly.set_targets(CanvasView.hull_targets(l));
  };
};

let px_float = (s: string): float =>
  try(float_of_string(String.sub(s, 0, String.length(s) - 2))) {
  | _ => 0.
  };

/* ---------- PORTOLAN: the avatar's site, by name ---------- */

/* The agent's current work site: the last cause's definition (upstream
   reads the last tool result's jump path). */
let avatar_target = (): option((string, string)) =>
  switch (last_cause^) {
  | Some(({site: Some(site), ok, _}, landed_at)) =>
    let agent_busy = busy^ || CanvasBuffer.fake_busy();
    /* "edit" only around a landed edit (a score playing it, or one
       just landed); a busy agent is otherwise THINKING */
    let editing =
      CanvasBuffer.score_playing() || CanvasBuffer.now() -. landed_at < 1500.;
    let state =
      if (!ok) {
        "err";
      } else if (agent_busy && editing) {
        "edit";
      } else {
        "";
      };
    Some((site, state));
  | _ => None
  };

/* Map a definition's name to a canvas position: an exact hit on an
   edge / node / value, then looser readings of the name (a path written
   with '/', a module, a bare unqualified name). Upstream climbs statics
   ancestors instead. */
let locate = (lay: CanvasLayout.t, id: string): option(CanvasLayout.pos) => {
  let dots = String.map(c => c == '/' ? '.' : c);
  let id' = dots(id);
  let edge = (pred: CanvasGraph.edge => bool, ()) =>
    List.find_opt((el: CanvasLayout.edge_layout) => pred(el.edge), lay.edges)
    |> Option.map((el: CanvasLayout.edge_layout) => el.label_p);
  let node = (pred: CanvasGraph.tynode => bool, ()) =>
    List.find_opt((nl: CanvasLayout.node_layout) => pred(nl.node), lay.nodes)
    |> Option.map((nl: CanvasLayout.node_layout) => nl.p);
  let value = (pred: CanvasGraph.value => bool, ()) =>
    List.find_opt(
      (vl: CanvasLayout.value_layout) => pred(vl.value),
      lay.values,
    )
    |> Option.map((vl: CanvasLayout.value_layout) => vl.p);
  List.find_map(
    f => f(),
    [
      edge(e => e.e_id == id),
      node(n => n.n_id == Some(id)),
      value(v => v.v_id == id),
      edge(e => dots(e.e_name) == id'),
      node(n => dots(n.key) == id'),
      value(v => dots(v.v_name) == id'),
      node(n => n.key == "{}@" ++ id'),
      edge(e => e.e_label == id),
      node(n => n.sat == None && n.label == id),
      value(v => v.v_label == id),
    ],
  );
};

let kind_name = (n: CanvasGraph.tynode): string =>
  String.length(n.key) >= 3 && String.sub(n.key, 0, 3) == "{}@"
    ? "module"
    : (
      switch (n.kind) {
      | Alias => "type"
      | Builtin => "builtin"
      | Derived => "derived"
      | Ghost => "ghost"
      | Product => "product"
      }
    );

/* ---------- the view (LIFTED from CanvasSidebar.view_impl) ---------- */

let view = (graph0: CanvasGraph.t): Node.t => {
  let slide = current_slide();
  CanvasLayoutExperiments.scene := slide;
  {
    /* the layout frame is frozen while beats play and re-derives when
       they stop: that re-frame must glide, not snap */
    let pl = CanvasBuffer.pacing_live();
    if (last_pacing_live^ && !pl) {
      CanvasBuffer.stage_beat(~slow=true, ());
      burst_end_reframe := true;
    };
    last_pacing_live := pl;
  };
  if (last_seen_slide^ != slide) {
    /* per-slide state: a site remembered from the previous slide put the
       avatar off the new board */
    last_seen_slide := slide;
    last_avatar_pos := None;
    last_avatar_id := None;
    last_followed := None;
    last_followed_id := None;
    CanvasCamera.reset_exposure();
    CanvasBuffer.avatar_site := None;
    last_followed_busy := false;
    CanvasBuffer.beat_avatar := None;
    CanvasCamera.roi := [];
  };
  /* the graph MUST derive from the PACED snapshot */
  let (graph, collapsed_counts) = collapse_cached(graph0);
  CanvasEnact.label_of :=
    (
      k =>
        switch (value_of_score_key(k)) {
        | Some(v) => v
        | None =>
          switch (
            List.find_opt((n: CanvasGraph.tynode) => n.key == k, graph.nodes)
          ) {
          | Some(n) =>
            /* a module's former: its name; a terminal: its type */
            String.length(k) >= 3 && String.sub(k, 0, 3) == "{}@"
              ? String.sub(k, 3, String.length(k) - 3) : n.label
          | None => CanvasGraph.display_label(k)
          }
        }
    );
  let zoom = canvas_zoom^;
  zoom_now := zoom;
  CanvasBuffer.canvas_zoom := zoom;
  CanvasRipple.zoom := zoom;
  zoom_send :=
    Some(
      z => {
        canvas_zoom := z;
        request_render();
      },
    );
  install_zoom_listener();
  CanvasCamera.install_testers();
  CanvasEnact.install_testers();
  let offsets = node_offsets^;
  let pins = [];
  /* stretch columns to fill the panel when the graph is narrower than it;
     panel width is read from the (pre-patch) DOM, so the first render
     after a resize uses the previous width */
  let avail_width =
    switch (Util.JsUtil.get_elem_by_id_opt("canvas-scroll")) {
    | Some(el) =>
      let w = Js.Unsafe.coerce(el)##.clientWidth;
      w > 50 ? Some(float_of_int(w)) : None;
    | None => None
    };
  let (avail_height, layout_height) =
    switch (Util.JsUtil.get_elem_by_id_opt("canvas-scroll")) {
    | Some(el) =>
      let h: int = Js.Unsafe.coerce(el)##.clientHeight;
      (
        h > 100 ? Some(float_of_int(h)) : None,
        h > 100 ? Some(float_of_int(h)) : None,
      );
    | None => (None, None)
    };
  /* frame freeze during drags (see drag_active) */
  let avail_width =
    if (drag_active^) {
      switch (cached_avail_w^) {
      | Some(_) as c => c
      | None => avail_width
      };
    } else {
      cached_avail_w := avail_width;
      avail_width;
    };
  let avail_height =
    if (drag_active^) {
      switch (cached_avail_h^) {
      | Some(_) as c => c
      | None => avail_height
      };
    } else {
      cached_avail_h := avail_height;
      avail_height;
    };
  CanvasLayout.card_extents := [];
  /* PORTOLAN: the layouts that pack aim for the pane's shape (in coarse
     steps, so a small resize is not a new arrangement) */
  switch (avail_width, avail_height) {
  | (Some(w), Some(h)) =>
    CanvasOptions.aspect :=
      max(0.5, min(4., Float.round(w /. h *. 4.) /. 4.))
  | _ => ()
  };
  let lay = {
    /* pins/offsets for nodes that no longer exist must not keep a stale
       frame alive */
    let node_keys = List.map((n: CanvasGraph.tynode) => n.key, graph.nodes);
    let live = ((k, _)) => List.mem(k, node_keys);
    let manual = List.exists(live, offsets) || List.exists(live, pins);
    let aw = Option.value(~default=0., avail_width);
    /* the frame stays frozen for the whole burst (B2: a node keeps its
       place unless an act moves it); the burst-end re-frame is one tidy */
    let outgrown = CanvasBuffer.pacing_live() && !manual;
    /* a frozen frame that would push the new content past the pane is
       re-fit at this beat instead (the drift makes room first, so the
       whole graph glides to the new fit before anything blooms) */
    let fits_cached =
      switch (cached_frame^, avail_height) {
      | (Some(fc), Some(ah)) when !manual =>
        let l =
          CanvasLayout.layout(
            ~x_scale=fc.fc_x_scale,
            ~y_scale=fc.fc_y_scale,
            ~origin_override=Some(fc.fc_origin),
            ~cards=[],
            graph,
          );
        l.height <= ah -. 8. && l.width <= aw +. 40.;
      | _ => true
      };
    let runtime_frame =
      switch (cached_frame^) {
      | Some(fc)
          when
            fits_cached
            && (
              manual
              || outgrown
              /* a new burst keeps the frozen frame until it adds nodes;
                 re-deriving on the bare tool beat that opens a burst moved
                 everything mid-score */
              && (
                fc.fc_burst == CanvasLog.turn_no()
                || List.length(graph.nodes) <= fc.fc_nodes
              )
            )
            /* a frame derived from an empty graph (the bare tool beat
               before the first insertion) would spread the real one */
            && fc.fc_nodes > 0
            && fc.fc_slide == slide
            && Float.abs(fc.fc_avail_w -. aw) < 2. =>
        Some((fc.fc_origin, fc.fc_x_scale, fc.fc_y_scale))
      | _ => None
      };
    switch (runtime_frame) {
    | Some((origin, xs, ys)) =>
      /* sticky frame: manual positions never re-anchor (see cached_frame) */
      cached_frame :=
        Some({
          fc_slide: slide,
          fc_burst: CanvasLog.turn_no(),
          fc_nodes: List.length(graph.nodes),
          fc_origin: origin,
          fc_x_scale: xs,
          fc_y_scale: ys,
          fc_avail_w: aw,
        });
      CanvasLayout.layout(
        ~x_scale=xs,
        ~y_scale=ys,
        ~origin_override=Some(origin),
        ~offsets,
        ~pins,
        graph,
      );
    | None =>
      /* ALL frame decisions (fit scales, normalization origin) derive
         from the VIRGIN layout — no user offsets/pins — so dragging a
         node can never rescale or re-anchor the rest of the graph. The
         final layout applies the frozen frame plus the user's edits. */
      let virgin = CanvasLayout.layout(~cards=[], graph);
      let y_scale =
        switch (layout_height) {
        | Some(h) => min(2.1, max(1., (h -. 40.) /. virgin.height))
        | None => 1.
        };
      let x_scale =
        switch (avail_width) {
        | Some(avail) =>
          /* fill the pane, less a margin the camera can see as "all in" */
          let target = avail -. 56.;
          /* never tighter than the layout's natural size: the layout
             keeps its spacing and the camera does the fitting */
          let s1 = min(1.8, max(1., target /. virgin.width));
          if (s1 >= 1.8 || s1 <= 1.) {
            s1;
          } else {
            let v1 =
              CanvasLayout.layout(~x_scale=s1, ~y_scale, ~cards=[], graph);
            v1.width >= target -. 30. && v1.width <= target +. 30.
              ? s1 : min(1.8, max(1., s1 *. target /. v1.width));
          };
        | None => 1.
        };
      let framed =
        CanvasLayout.layout(
          ~x_scale,
          ~y_scale,
          ~center_within=avail_width,
          ~cards=[],
          graph,
        );
      cached_frame :=
        Some({
          fc_slide: slide,
          fc_burst: CanvasLog.turn_no(),
          fc_nodes: List.length(graph.nodes),
          fc_origin: framed.origin,
          fc_x_scale: x_scale,
          fc_y_scale: y_scale,
          fc_avail_w: aw,
        });
      /* the rendered layout: the frozen frame plus the user's edits */
      CanvasLayout.layout(
        ~x_scale,
        ~y_scale,
        ~origin_override=Some(framed.origin),
        ~offsets,
        ~pins,
        graph,
      );
    };
  };

  /* ---- selection (PORTOLAN: the host is told; no info panel) ---- */
  let select = (name: string, kind: string, id: option(string)) =>
    Effect.of_sync_fun(
      () =>
        on_select^(
          name,
          kind,
          Option.bind(id, CanvasGraph.handle_of(graph)),
        ),
      (),
    );
  let focus_dom = dom_id =>
    Effect.of_sync_fun(CanvasView.focus_selector, "#" ++ dom_id);
  let inject_jump = (id: string) =>
    Effect.Many([
      select(id, "test", Some(id)),
      Effect.Stop_propagation,
    ]);
  let on_edge_click = (e: CanvasGraph.edge) => {
    focused_value := None;
    focused := Some(e.e_name);
    focused_ty := None;
    Effect.Many([
      select(e.e_name, "function", Some(e.e_id)),
      tick,
      Effect.Stop_propagation,
      focus_dom(CanvasView.edge_dom_id(e.e_name)),
    ]);
  };
  let click_effect = (n: CanvasGraph.tynode) => {
    focused_value := None;
    focused_ty := Some(n.key);
    focused := None;
    let name =
      kind_name(n) == "module"
        ? String.sub(n.key, 3, String.length(n.key) - 3) : n.key;
    Effect.Many([
      select(name, kind_name(n), n.n_id),
      tick,
      focus_dom(CanvasView.node_dom_id(n.key)),
    ]);
  };
  /* drag-vs-click on a node: document listeners move the div imperatively;
     release either commits a layout delta or fires the click */
  let start_node_drag =
      (n: CanvasGraph.tynode, evt: Js.t(Dom_html.mouseEvent))
      : Effect.t(unit) => {
    open LayoutDom;
    let sx: int = Js.Unsafe.coerce(evt)##.clientX;
    let sy: int = Js.Unsafe.coerce(evt)##.clientY;
    /* dragging while the actor works pauses the workload; it resumes on
       release, re-planned around the moved node */
    let during_score = CanvasBuffer.pacing_live();
    if (during_score) {
      CanvasEnact.pause_score();
    } else {
      /* a beat may still be morphing or revealing geometry (dash arrays
         left on paths would truncate them as they stretch): the drag takes
         over cleanly */
      List.iter(
        id =>
          switch (Util.JsUtil.get_elem_by_id_opt(id)) {
          | Some(el) =>
            let anims = Js.Unsafe.meth_call(el, "getAnimations", [||]);
            let len: int = Js.Unsafe.get(anims, "length");
            for (i in 0 to len - 1) {
              ignore(
                Js.Unsafe.meth_call(Js.Unsafe.get(anims, i), "cancel", [||]),
              );
            };
            ignore(
              Js.Unsafe.meth_call(
                el,
                "removeAttribute",
                [|Js.Unsafe.inject(Js.string("stroke-dasharray"))|],
              ),
            );
            let st = Js.Unsafe.get(el, "style");
            Js.Unsafe.set(st, "strokeDasharray", Js.string(""));
            Js.Unsafe.set(st, "strokeDashoffset", Js.string(""));
          | None => ()
          },
        Util.JsUtil.ids_with_prefix("cpath-")
        @ Util.JsUtil.ids_with_prefix("cform-")
        @ Util.JsUtil.ids_with_prefix("corbit-"),
      );
    };
    let base =
      Option.value(~default=(0., 0.), List.assoc_opt(n.key, offsets));
    let commit = ((dx, dy)) =>
      node_offsets :=
        [
          (n.key, (fst(base) +. dx, snd(base) +. dy)),
          ...List.remove_assoc(n.key, node_offsets^),
        ];
    let orig =
      switch (Util.JsUtil.get_elem_by_id_opt(CanvasView.node_dom_id(n.key))) {
      | Some(el) =>
        let st = Js.Unsafe.coerce(el)##.style;
        Some((
          el,
          px_float(Js.to_string(st##.left)),
          px_float(Js.to_string(st##.top)),
        ));
      | None => None
      };
    drag_active := true;
    let moved = ref(false);
    let delta = ref((0., 0.));
    /* EXACT drag follow: recompute the REAL layout with the pending
       delta (same frame + offsets the commit will use) and apply every
       piece of geometry imperatively — no vdom, no render, and nothing
       left to jump on drop. Hull circles go through the jelly springs as
       targets. */
    let lay_with = ((dx, dy)): option(CanvasLayout.t) => {
      let offsets' = [
        (n.key, (fst(base) +. dx, snd(base) +. dy)),
        ...List.remove_assoc(n.key, offsets),
      ];
      switch (cached_frame^) {
      | Some(fc) =>
        Some(
          CanvasLayout.layout(
            ~x_scale=fc.fc_x_scale,
            ~y_scale=fc.fc_y_scale,
            ~origin_override=Some(fc.fc_origin),
            ~offsets=offsets',
            ~pins,
            graph,
          ),
        )
      | None => None
      };
    };
    let raf_busy = ref(false);
    let pending: ref(option((float, float))) =
      ref(None: option((float, float)));
    let follow_edges = (dx: float, dy: float) => {
      pending := Some((dx, dy));
      if (! raf_busy^) {
        raf_busy := true;
        let _ =
          Js.Unsafe.meth_call(
            Js.Unsafe.global##.window,
            "requestAnimationFrame",
            [|
              Js.Unsafe.inject(
                Js.Unsafe.callback(() => {
                  raf_busy := false;
                  switch (pending^) {
                  | Some(d) =>
                    switch (lay_with(d)) {
                    | Some(l) => apply_layout(l)
                    | None => ()
                    }
                  | None => ()
                  };
                }),
              ),
            |],
          );
        ();
      };
    };
    let doc = Js.Unsafe.coerce(Dom_html.document);
    let move_cb = ref(Js.Unsafe.inject(Js.null));
    let up_cb = ref(Js.Unsafe.inject(Js.null));
    let on_move = e => {
      let x: int = Js.Unsafe.coerce(e)##.clientX;
      let y: int = Js.Unsafe.coerce(e)##.clientY;
      /* CSS zoom scales screen deltas; convert to layout px */
      let z = CanvasZoom.clamp(zoom_now^);
      let dx = float_of_int(x - sx) /. z
      and dy = float_of_int(y - sy) /. z;
      if (abs_float(dx) +. abs_float(dy) > 4.) {
        moved := true;
      };
      if (moved^) {
        /* snap the drag itself to the dot lattice: the visual position
           is always exactly what the committed layout will produce, so
           the imperative style can never disagree with the re-render */
        let dx = CanvasLayout.snap(dx)
        and dy = CanvasLayout.snap(dy);
        delta := (dx, dy);
        switch (orig) {
        | Some((el, l, t)) =>
          let st = Js.Unsafe.coerce(el)##.style;
          st##.left := Js.string(Printf.sprintf("%.1fpx", l +. dx));
          st##.top := Js.string(Printf.sprintf("%.1fpx", t +. dy));
          /* bow wave: the unsnapped position, so the field glides */
          CanvasRipple.set_field(
            Some((
              l +. float_of_int(x - sx) /. z,
              t +. float_of_int(y - sy) /. z,
            )),
          );
        | None => ()
        };
        /* incident edges, labels, orbits and orbit rings follow by
           DIRECT DOM mutation */
        follow_edges(dx, dy);
      };
    };
    let on_up = _ => {
      drag_active := false;
      if (moved^) {
        /* settle: a soft splash where the node lands */
        switch (orig) {
        | Some((_, l, t)) =>
          let (dx, dy) = delta^;
          CanvasRipple.splash(~amp=4.5, (l +. dx, t +. dy));
        | None => ()
        };
      };
      CanvasRipple.set_field(None);
      let _ = doc##removeEventListener(Js.string("mousemove"), move_cb^);
      let _ = doc##removeEventListener(Js.string("mouseup"), up_cb^);
      if (during_score) {
        CanvasEnact.resume_score();
        if (moved^) {
          switch (CanvasEnact.visible_site()) {
          | Some(pos) => CanvasEnact.replan_score(~pos, ())
          | None => ()
          };
        };
      };
      if (moved^) {
        commit(delta^);
      };
      Effect.Expert.handle_non_dom_event_exn(click_effect(n));
    };
    move_cb := Js.Unsafe.inject(Js.wrap_callback(on_move));
    up_cb := Js.Unsafe.inject(Js.wrap_callback(on_up));
    let _ = doc##addEventListener(Js.string("mousemove"), move_cb^);
    let _ = doc##addEventListener(Js.string("mouseup"), up_cb^);
    Effect.Prevent_default;
  };
  /* Explicit Fit is an overview, independent of Follow's readability
     floor. Include the rendered labels and wires, not just node radii:
     any of them can extend beyond the layout's nominal box. */
  let fit_view = (~cap: option(float)=None, ()) => {
    let capped = z =>
      switch (cap) {
      | Some(c) => min(c, z)
      | None => z
      };
    let aw = Option.value(~default=lay.width, avail_width)
    and ah = Option.value(~default=lay.height, avail_height);
    let top = min(max(0., ah -. 40.), CanvasCamera.overview_top_inset());
    CanvasCamera.note_user_zoom();
    let bounds =
      switch (CanvasCamera.rendered_graph_bbox()) {
      | Some(b) => Some(b)
      | None => CanvasCamera.graph_bbox^
      };
    switch (bounds) {
    | Some((x0, y0, x1, y1)) =>
      let z =
        capped(
          CanvasZoom.fit(
            ~width=x1 -. x0,
            ~height=y1 -. y0,
            ~aw,
            ~ah=ah -. top,
          ),
        );
      CanvasCamera.animate(
        ~aw,
        ~ah,
        ~zoom=Some(z),
        ~dur=320.,
        ~easing=CanvasCamera.EaseOut,
        ((x0 +. x1) /. 2., (y0 +. y1) /. 2. -. top /. (2. *. z)),
      );
    | None =>
      animate_fit(
        ~z_to=
          capped(
            CanvasZoom.fit(~width=lay.width, ~height=lay.height, ~aw, ~ah),
          ),
        ~lw=lay.width,
        ~lh=lay.height,
        ~aw,
        ~ah,
      )
    };
  };
  if (fit_pending^) {
    fit_pending := false;
    CanvasEnact.after_render(fit_view);
  };
  /* PORTOLAN: a snapshot shown without a story is framed whole, but
     never magnified past 1:1 */
  if (overview_pending^) {
    overview_pending := false;
    CanvasEnact.after_render(fit_view(~cap=Some(1.)));
  };

  /* ---- the avatar ---- */
  let agent_busy = busy^ || CanvasBuffer.fake_busy();
  let avatar = {
    /* while beats are on screen, the avatar target rides them (captured
       per cause at push time) instead of reading the live state and
       arriving ahead of the paced graph */
    let target =
      switch (CanvasBuffer.pacing_live() ? CanvasBuffer.beat_avatar^ : None) {
      | Some(_) as beat_site => beat_site
      | None => avatar_target()
      };
    let resolved_from_target =
      target
      |> Util.OptUtil.and_then(((id, state)) =>
           switch (locate(lay, id)) {
           | Some(p) =>
             last_avatar_id := Some(id);
             last_avatar_pos := Some(p);
             Some((p, state));
           | None =>
             /* target no longer resolves (edits moved on): try the last
                good id against the current layout, else hold position */
             switch (last_avatar_id^ |> Util.OptUtil.and_then(locate(lay))) {
             | Some(p) =>
               last_avatar_pos := Some(p);
               Some((p, state));
             | None => last_avatar_pos^ |> Option.map(p => (p, state))
             }
           }
         );
    let resolved =
      switch (CanvasBuffer.avatar_site^) {
      | Some((x, y)) =>
        let p =
          CanvasLayout.{
            x,
            y,
          };
        last_avatar_pos := Some(p);
        /* the state comes from the last cause (edit only around a
           landed edit, thinking otherwise) — busy alone is not editing */
        let st =
          switch (resolved_from_target) {
          | Some((_, st)) => st
          | None => ""
          };
        Some((p, agent_busy ? st : ""));
      | None => resolved_from_target
      };
    switch (resolved) {
    | Some((p, state)) =>
      /* busy with no fresh edit landing = thinking */
      Some((p, agent_busy && state == "" ? "think" : state))
    | None when agent_busy =>
      /* nothing resolved yet: embody the agent from the first thinking
         token anyway — at its last known spot, else at the viewport
         center (where the user is looking); its first hop then travels
         from there. */
      let on_board = (p: CanvasLayout.pos) =>
        p.x >= (-60.)
        && p.x <= lay.width
        +. 60.
        && p.y >= (-60.)
        && p.y <= lay.height
        +. 60.;
      let p =
        switch (last_avatar_pos^) {
        | Some(p) when on_board(p) => Some(p)
        | _ =>
          switch (avail_width, avail_height) {
          | (Some(aw), Some(ah)) =>
            CanvasCamera.center(~aw, ~ah)
            |> Option.map(((x, y)) =>
                 CanvasLayout.{
                   x,
                   y,
                 }
               )
          | _ =>
            Some(
              CanvasLayout.{
                x: lay.width /. 2.,
                y: lay.height /. 2.,
              },
            )
          }
        };
      switch (p) {
      | Some(p) =>
        last_avatar_pos := Some(p);
        Some((p, "think"));
      | None => None
      };
    | None => None
    };
  };
  /* the camera judges "fits"/"all visible" against the nodes themselves,
     not the pane-sized layout box (which never fits with a margin) */
  CanvasCamera.graph_bbox :=
    (
      switch (lay.nodes) {
      | [] => None
      | ns =>
        Some(
          List.fold_left(
            ((x0, y0, x1, y1), nl: CanvasLayout.node_layout) =>
              (
                min(x0, nl.p.x -. nl.r),
                min(y0, nl.p.y -. nl.r),
                max(x1, nl.p.x +. nl.r),
                max(y1, nl.p.y +. nl.r +. 18.),
              ),
            (infinity, infinity, neg_infinity, neg_infinity),
            ns,
          ),
        )
      }
    );
  switch (avail_width, avail_height) {
  | (Some(aw), Some(ah)) =>
    CanvasCamera.note_exposure(
      ~aw,
      ~ah,
      List.map(
        (nl: CanvasLayout.node_layout) => (nl.node.key, (nl.p.x, nl.p.y)),
        lay.nodes,
      ),
    )
  | _ => ()
  };
  /* camera follow: a hop (or a resting avatar waking) hands the site to
     the camera; the dead zone decides whether it actually moves */
  switch (avatar, avail_width, avail_height) {
  | (Some((p, _)), Some(aw), Some(ah))
      when
        follow^
        /* while beats are paced the score owns the camera (its frames
           are planned per act); the generic follow is for the rest */
        && !CanvasBuffer.pacing_live()
        && CanvasBuffer.now() >= CanvasCamera.scored_until^ =>
    let hopped = last_avatar_id^ != last_followed_id^;
    let woke = agent_busy && ! last_followed_busy^;
    if (hopped || woke) {
      last_followed := Some(p);
      last_followed_id := last_avatar_id^;
      CanvasCamera.follow(~aw, ~ah, (p.x, p.y));
    };
    last_followed_busy := agent_busy;
  | _ => ()
  };
  if (agent_busy != last_logged_busy^) {
    last_logged_busy := agent_busy;
    CanvasBuffer.note_agent_busy(agent_busy);
    CanvasLog.log(agent_busy ? "agent: busy" : "agent: idle");
  };
  {
    let (pid, pstate) = last_logged_avatar^;
    let cur_state =
      switch (avatar) {
      | Some((_, st)) => st == "" ? "at rest" : st
      | None => "off"
      };
    let cur_id = last_avatar_id^;
    /* name the node the avatar landed nearest, so the journal reads
       as a story ("hop -> Recipe") */
    let site = () =>
      switch (avatar) {
      | Some((p, _)) =>
        lay.nodes
        |> List.fold_left(
             (best, nl: CanvasLayout.node_layout) => {
               let d = abs_float(nl.p.x -. p.x) +. abs_float(nl.p.y -. p.y);
               switch (best) {
               | Some((bd, _)) when bd <= d => best
               | _ => Some((d, nl.node.key))
               };
             },
             None,
           )
        |> Option.map(((_, k)) => " @ " ++ k)
        |> Option.value(~default="")
      | None => ""
      };
    if (cur_state != pstate) {
      CanvasLog.log("avatar: " ++ cur_state ++ site());
      last_logged_avatar := (cur_id, cur_state);
    } else if (cur_id != pid) {
      CanvasLog.log("avatar: hop (" ++ cur_state ++ ")" ++ site());
      last_logged_avatar := (cur_id, cur_state);
    };
  };
  /* the thought bubble shows while the model streams; its text is
     driven outside the vdom (CanvasBubble) from the full streamed text.
     Actions are called out by the speech bubble, fed by the player. */
  if (! CanvasBubble.force_cloud^) {
    CanvasBubble.source := thought^;
  };
  CanvasBubble.thought_available :=
    CanvasBubble.force_cloud^
    || agent_busy
    && pace^
    && String.length(thought^) > 0;
  CanvasBubble.ensure_loop();

  CanvasRipple.request_draw();
  switch (avail_width, avail_height) {
  | (Some(aw), Some(ah)) =>
    /* PORTOLAN: an empty board is anchored as if it were as wide as the
       pane (a layout with content is, through ~center_within), so the
       first content lands centred without a scroll jump (B1). Upstream
       slides rarely start empty; a pushed code base does. */
    let lw = lay.nodes == [] ? aw : lay.width *. zoom;
    anchor_target :=
      (
        max(0., pan_slack +. (lw -. aw) /. 2.),
        max(0., pan_slack +. (lay.height *. zoom -. ah) /. 2.),
      )
  | _ => ()
  };
  ensure_scroll_anchor(slide);
  /* hull circles follow these targets (CanvasJelly): on a scored render
     they glide on the nodes' schedule (set below, once the score is
     planned); otherwise they spring — drags and collapses wobble */
  let hull_targets = CanvasView.hull_targets(lay);
  {
    let (prev_slide, prev_nodes) = last_node_snapshot^;
    if (prev_slide != slide) {
      CanvasLog.log("slide: " ++ slide);
    };
    let cur_keys =
      List.map((nl: CanvasLayout.node_layout) => nl.node.key, lay.nodes);
    let removed =
      List.filter(((k, _)) => !List.mem(k, cur_keys), prev_nodes);
    let cur_edge_names =
      List.map((el: CanvasLayout.edge_layout) => el.edge.e_name, lay.edges);
    let removed_edge_layouts =
      switch (last_layout^) {
      | Some(prev) when prev_slide == slide =>
        List.filter(
          (el: CanvasLayout.edge_layout) =>
            !List.mem(el.edge.e_name, cur_edge_names),
          prev.edges,
        )
      | _ => []
      };
    let removed_node_layouts =
      switch (last_layout^) {
      | Some(prev) when prev_slide == slide =>
        List.filter(
          (nl: CanvasLayout.node_layout) =>
            List.mem_assoc(nl.node.key, removed),
          prev.nodes,
        )
      | _ => []
      };
    /* elements present in both renders whose look differs */
    let (changed_nodes, changed_edges) =
      switch (last_layout^) {
      | Some(prev) when prev_slide == slide => (
          List.filter_map(
            (nl: CanvasLayout.node_layout) =>
              switch (
                List.find_opt(
                  (pl: CanvasLayout.node_layout) =>
                    pl.node.key == nl.node.key,
                  prev.nodes,
                )
              ) {
              | Some(pl) when node_look(pl.node) != node_look(nl.node) =>
                Some((nl, pl.node))
              | _ => None
              },
            lay.nodes,
          ),
          List.filter_map(
            (el: CanvasLayout.edge_layout) =>
              switch (
                List.find_opt(
                  (pe: CanvasLayout.edge_layout) =>
                    pe.edge.e_name == el.edge.e_name,
                  prev.edges,
                )
              ) {
              | Some(pe) when edge_look(pe.edge) != edge_look(el.edge) =>
                Some((el, pe.edge))
              | _ => None
              },
            lay.edges,
          ),
        )
      | _ => ([], [])
      };
    if (prev_slide == slide
        && removed != []
        && CanvasBuffer.now() > collapse_fx_until^) {
      if (List.length(removed) <= 4) {
        List.iter(((_, (x, y))) => CanvasRipple.suction((x, y)), removed);
        CanvasLog.log(
          Printf.sprintf(
            "-%d node(s): %s (suction ripple)",
            List.length(removed),
            String.concat(", ", List.map(fst, removed)),
          ),
        );
      } else {
        CanvasLog.log(
          Printf.sprintf(
            "-%d nodes at once (removal effects skipped)",
            List.length(removed),
          ),
        );
      };
    };
    /* agent rainfall: nodes that appear during a paced burst arrive with
       a small splash + grow-in */
    let added =
      List.filter(
        (nl: CanvasLayout.node_layout) =>
          !List.mem_assoc(nl.node.key, prev_nodes)
          && !List.mem_assoc(nl.node.key, last_placed^),
        lay.nodes,
      );
    /* value badges (constants, module values) are canvas content too: a
       new one is a terminal of its type's definition act (A2) */
    let (_, prev_values) = last_value_snapshot^;
    let added_values =
      List.filter(
        (vl: CanvasLayout.value_layout) =>
          !List.mem(vl.value.v_name, prev_values),
        lay.values,
      );
    last_value_snapshot :=
      (
        slide,
        List.map(
          (vl: CanvasLayout.value_layout) => vl.value.v_name,
          lay.values,
        ),
      );
    /* ---- the beat's score (A1): ONE plan from this render's diff. The
       actor visits each new definition, pulls each new arrow, and the
       rest of the graph drifts last. Arrival times feed Animation before
       the render lands; the player runs one frame after it. ---- */
    let (_, prev_edges) = last_edge_snapshot^;
    let new_edges =
      lay.edges
      |> List.filter_map((el: CanvasLayout.edge_layout) =>
           if (List.mem(el.edge.e_name, prev_edges)) {
             None;
           } else {
             let product =
               lay.nodes
               |> List.find_opt((nl: CanvasLayout.node_layout) =>
                    nl.node.key == el.edge.e_src
                  )
               |> Util.OptUtil.and_then((nl: CanvasLayout.node_layout) =>
                    nl.node.kind == CanvasGraph.Product
                    && nl.node.parts != []
                    && !List.mem_assoc(nl.node.key, prev_nodes)
                      ? Some((nl.node.key, nl.node.parts)) : None
                  );
             Some(
               CanvasScore.{
                 name: el.edge.e_name,
                 src: el.edge.e_src,
                 dst: el.edge.dst,
                 product,
               },
             );
           }
         );
    if (added != [] || new_edges != []) {
      let nodes =
        List.map((nl: CanvasLayout.node_layout) => nl.node.key, added)
      and edges = List.map(e => e.CanvasScore.name, new_edges);
      CanvasEnact.after_render(() => CanvasEnact.revive(~nodes, ~edges));
    };
    let moved =
      lay.nodes
      |> List.filter_map((nl: CanvasLayout.node_layout) =>
           switch (List.assoc_opt(nl.node.key, prev_nodes)) {
           | Some((px, py))
               when
                 abs_float(px -. nl.p.x) > 1. || abs_float(py -. nl.p.y) > 1. =>
             Some((
               nl.node.key,
               CanvasLayout.{
                 x: px,
                 y: py,
               },
               nl.p,
             ))
           | _ => None
           }
         );
    let big_move =
      List.length(
        List.filter(
          ((_, f: CanvasLayout.pos, t: CanvasLayout.pos)) =>
            abs_float(f.x -. t.x) > 40. || abs_float(f.y -. t.y) > 40.,
          moved,
        ),
      )
      >= 3;
    let scored =
      prev_slide == slide
      && pace^
      && (
        CanvasBuffer.pacing_live()
        && (
          added != []
          || added_values != []
          || new_edges != []
          || removed != []
          || removed_edge_layouts != []
          || changed_nodes != []
          || changed_edges != []
        )
        || big_move
        && burst_end_reframe^
      );
    burst_end_reframe := false;
    if (scored) {
      /* a render nobody staged (the burst-end re-frame) still needs its
         movers recorded before the patch, or the drift is a jump */
      if (!Animation.staged()) {
        CanvasBuffer.stage_beat(~slow=true, ());
      };
      List.iter(
        (nl: CanvasLayout.node_layout) => note_placed(nl.node.key),
        added,
      );
      let pos_of = k =>
        lay.nodes
        |> List.find_opt((nl: CanvasLayout.node_layout) => nl.node.key == k)
        |> Option.map((nl: CanvasLayout.node_layout) => nl.p);
      /* the story's order (CanvasScore.new_node.order): graph nodes and
         edges are extracted in program order; a glyph nobody names takes
         the place of the first edge that touches it */
      let order_of = (k: string): int => {
        let rec idx = (i, ks) =>
          switch (ks) {
          | [] => Option.none
          | [x, ..._] when x == k => Option.some(i)
          | [_, ...rest] => idx(i + 1, rest)
          };
        let is_module = key =>
          String.length(key) >= 3 && String.sub(key, 0, 3) == "{}@";
        let named =
          List.filter_map(
            (n: CanvasGraph.tynode) =>
              switch (n.kind) {
              | CanvasGraph.Builtin => None
              | CanvasGraph.Product => is_module(n.key) ? Some(n.key) : None
              | _ => Some(n.key)
              },
            graph.nodes,
          );
        /* a module leads its members: the agent wrote `module M = {`
           before anything inside it */
        let module_first = (k: string): int =>
          if (is_module(k)) {
            let root = String.sub(k, 3, String.length(k) - 3);
            let first_member =
              List.mapi((i, key) => (i, key), named)
              |> List.find_opt(((_, key)) =>
                   List.exists(
                     (n: CanvasGraph.tynode) =>
                       n.key == key
                       && (
                         switch (n.m_path) {
                         | [r, ..._] => r == root
                         | [] => false
                         }
                       ),
                     graph.nodes,
                   )
                 );
            switch (first_member) {
            | Some((i, _)) => 2 * i - 1 /* just before that member */
            | None => max_int
            };
          } else {
            max_int;
          };
        switch (idx(0, named)) {
        | Some(i) => min(2 * i, module_first(k))
        | None =>
          let n = List.length(named);
          let touching =
            List.mapi((i, e: CanvasGraph.edge) => (i, e), graph.edges)
            |> List.find_opt(((_, e: CanvasGraph.edge)) =>
                 e.e_src == k
                 || e.dst == k
                 || List.mem(k, e.e_deps)
                 || (
                   switch (
                     List.find_opt(
                       (pn: CanvasGraph.tynode) => pn.key == e.e_src,
                       graph.nodes,
                     )
                   ) {
                   | Some(pn) => List.mem(k, pn.parts)
                   | None => false
                   }
                 )
               );
          switch (touching) {
          | Some((i, _)) => 2 * (n + i)
          | None => max_int
          };
        };
      };
      let diff =
        CanvasScore.{
          d_cause: Option.value(~default="edit", CanvasBuffer.shown_label^),
          added:
            List.map(
              (nl: CanvasLayout.node_layout) =>
                CanvasScore.{
                  key: nl.node.key,
                  anchor: Option.map(fst, nl.node.sat),
                  p: nl.p,
                  order: order_of(nl.node.key),
                },
              added,
            )
            @ List.map(
                (vl: CanvasLayout.value_layout) =>
                  CanvasScore.{
                    key: value_score_key(vl.value.v_name),
                    anchor: Some(vl.value.v_key),
                    p: vl.p,
                    order: order_of(vl.value.v_key),
                  },
                added_values,
              ),
          edges: new_edges,
          removed:
            List.map(
              ((k, (x, y))) =>
                (
                  k,
                  CanvasLayout.{
                    x,
                    y,
                  },
                ),
              removed,
            ),
          removed_edges:
            List.map(
              (el: CanvasLayout.edge_layout) => (el.edge.e_name, el.label_p),
              removed_edge_layouts,
            ),
          changed:
            List.map(
              ((nl: CanvasLayout.node_layout, _)) => (nl.node.key, nl.p),
              changed_nodes,
            )
            @ List.map(
                ((el: CanvasLayout.edge_layout, _)) =>
                  (el.edge.e_name, el.label_p),
                changed_edges,
              ),
          moved,
          actor: last_avatar_pos^,
        };
      let score = CanvasScore.plan(~pos_of, diff);
      let score =
        switch (avail_width, avail_height) {
        | (Some(aw), Some(ah)) when follow^ =>
          switch (CanvasCamera.center(~aw, ~ah)) {
          | Some((cx, cy)) =>
            CanvasScore.with_frames(
              ~pane=(aw, ah),
              ~cur=
                CanvasScore.{
                  center:
                    CanvasLayout.{
                      x: cx,
                      y: cy,
                    },
                  zoom: CanvasCamera.zoom_now^,
                },
              ~pos_of=
                CanvasScore.with_edge_positions(
                  ~pos_of,
                  ~edges=
                    List.map(
                      (el: CanvasLayout.edge_layout) =>
                        (el.edge.e_name, el.src_p, el.dst_p),
                      lay.edges @ removed_edge_layouts,
                    ),
                ),
              ~all_keys=cur_keys,
              ~exposed=CanvasCamera.exposed_keys(),
              score,
            )
          | None => score
          }
        | _ => score
        };
      /* Appear/Pill times drive Animation's arrivals; movers wait for
         the drift act */
      let pills =
        CanvasScore.effects_abs(score)
        |> List.filter_map(((t, _, e: CanvasScore.timed_effect)) =>
             switch (e.effect) {
             | Pill(name) => Some((CanvasView.edge_dom_id(name), t))
             | Reveal(name) =>
               Some((CanvasView.edge_dom_id(name), t + e.dur))
             | _ => None
             }
           );
      /* module hulls grow with their members: every hull circle (a
         node's or a label's, ancestor copies included) arrives with the
         node or pill it stands for, and the member-edge sausages draw on
         with their pills. Times are looked up from the hull ids
         themselves, so the two enumerations cannot disagree. */
      let (hull_arrivals, hull_geoms) = {
        let node_t =
          List.map(
            ((k, t)) => (CanvasView.sanitize(k), t),
            CanvasScore.appear_times(score),
          );
        let edge_t =
          CanvasScore.effects_abs(score)
          |> List.filter_map(((t, _, e: CanvasScore.timed_effect)) =>
               switch (e.effect) {
               | Pill(name) => Some((CanvasView.sanitize(name), t))
               | Reveal(name) =>
                 Some((CanvasView.sanitize(name), t + e.dur))
               | _ => None
               }
             );
        let after = (pre: string, id: string): option(string) =>
          String.length(id) > String.length(pre)
          && String.sub(id, 0, String.length(pre)) == pre
            ? Some(
                String.sub(
                  id,
                  String.length(pre),
                  String.length(id) - String.length(pre),
                ),
              )
            : None;
        /* an ancestor copy carries a "--v<path>" suffix */
        let base = (s: string): string => {
          let n = String.length(s);
          let rec go = i =>
            i + 3 > n
              ? s
              : String.sub(s, i, 3) == "--v"
                  ? String.sub(s, 0, i) : go(i + 1);
          go(0);
        };
        let time_of = (id: string): option(int) =>
          switch (
            after("hullc-n-", id),
            after("hullc-l-", id),
            after("hulls-e-", id),
          ) {
          | (Some(s), _, _) => List.assoc_opt(base(s), node_t)
          | (_, Some(s), _)
          | (_, _, Some(s)) => List.assoc_opt(base(s), edge_t)
          | _ => None
          };
        let ids =
          List.map(((id, _, _)) => id, CanvasView.hull_targets(lay));
        let sausage_ids =
          CanvasView.hull_paths_of(lay)
          |> List.concat_map(path =>
               List.map(
                 ((id, _, _)) => id,
                 CanvasView.hull_sausages_at(lay, path),
               )
             );
        (
          List.filter_map(id => Option.map(t => (id, t), time_of(id)), ids),
          List.filter_map(
            id => Option.map(t => (id, Option.some(t)), time_of(id)),
            sausage_ids,
          ),
        );
      };
      Animation.set_arrival_schedule(
        List.map(
          ((k, t)) =>
            switch (value_of_score_key(k)) {
            | Some(v) => (CanvasView.value_dom_id(v), t)
            | None => (CanvasView.node_dom_id(k), t)
            },
          CanvasScore.appear_times(score),
        )
        @ pills
        @ hull_arrivals,
      );
      Animation.set_movers_at(CanvasScore.drift_at(score));
      /* the hulls move with the nodes: same start (the drift act, or the
         beat's lead), same duration, same curve */
      CanvasJelly.set_targets(
        ~glide=
          Some((
            CanvasBuffer.now()
            +. float_of_int(
                 max(
                   CanvasBuffer.lead_ms,
                   Option.value(CanvasScore.drift_at(score), ~default=0),
                 ),
               ),
            float_of_int(CanvasBuffer.relayout_ms),
          )),
        hull_targets,
      );
      {
        /* new geometry follows its act: formation/dep lines draw on right
           after the node they attach to blooms; new function paths stay
           hidden until the actor rides them; label leaders come with pills */

        let appear = CanvasScore.appear_times(score);
        let at_key = k => List.assoc_opt(k, appear);
        let pair = (a, b, id) =>
          switch (at_key(a), at_key(b)) {
          | (Some(ta), Some(tb)) => [(id, Some(max(ta, tb) + 80))]
          | (Some(t), None)
          | (None, Some(t)) => [(id, Some(t + 80))]
          | (None, None) => []
          };
        /* lines into a product an act FORMS are drawn by that act: read
           it off the score's effects, so ownership can never disagree
           with what the score will actually do */
        let formed =
          CanvasScore.effects_abs(score)
          |> List.filter_map(((_, _, e: CanvasScore.timed_effect)) =>
               switch (e.effect) {
               | Form(pk, _) => Some(pk)
               | _ => None
               }
             );
        let forms =
          List.concat_map(
            ((a, b, _, _)) =>
              List.mem(b, formed)
                ? [(CanvasView.formation_dom_id(a, b), Option.none)]
                : pair(a, b, CanvasView.formation_dom_id(a, b)),
            lay.formations,
          );
        let deps =
          List.concat_map(
            ((a, b, _, _)) => pair(a, b, CanvasView.dep_dom_id(a, b)),
            lay.dep_links,
          );
        let (draws, leaders) =
          CanvasScore.effects_abs(score)
          |> List.fold_left(
               ((ds, ls), (t, _, e: CanvasScore.timed_effect)) =>
                 switch (e.effect) {
                 | Draw(name) => (
                     /* an endofunction's orbit ring cannot be ridden: it
                        draws on when the ride would have ended */
                     [
                       (CanvasView.path_dom_id(name), Option.none),
                       /* drawn on over the ride's span, so it is whole
                          before the pill lands */
                       (CanvasView.orbit_dom_id(name), Option.some(t)),
                       ...ds,
                     ],
                     ls,
                   )
                 | Reveal(name) => (
                     /* a path or, for an endofunction, an orbit ring:
                        schedule both ids (one exists); the label's leader
                        comes with the pill */
                     [
                       (CanvasView.path_dom_id(name), Option.some(t)),
                       (CanvasView.orbit_dom_id(name), Option.some(t)),
                       ...ds,
                     ],
                     [
                       (
                         "clead-" ++ CanvasView.sanitize(name),
                         Option.some(t + e.dur),
                       ),
                       ...ls,
                     ],
                   )
                 | Pill(name) => (
                     ds,
                     [
                       ("clead-" ++ CanvasView.sanitize(name), Some(t)),
                       ...ls,
                     ],
                   )
                 | _ => (ds, ls)
                 },
               ([], []),
             );
        /* a label leader that appears on an EXISTING edge (its pill was
           pushed by the relayout) belongs to the drift, not to a beat's
           default stagger */
        let drift_t = Option.value(CanvasScore.drift_at(score), ~default=0);
        let old_leaders =
          lay.edges
          |> List.filter_map((el: CanvasLayout.edge_layout) =>
               List.exists(
                 (e: CanvasScore.new_edge) => e.name == el.edge.e_name,
                 new_edges,
               )
                 ? None
                 : Some((
                     "clead-" ++ CanvasView.sanitize(el.edge.e_name),
                     Option.some(drift_t),
                   ))
             );
        Animation.set_geom_schedule(
          forms @ deps @ draws @ leaders @ old_leaders @ hull_geoms,
        );
      };
      CanvasBuffer.extend_dwell(float_of_int(score.total_ms) +. 600.);
      {
        let t0 = CanvasBuffer.now();
        let cue = k =>
          switch (List.assoc_opt(k, CanvasScore.change_times(score))) {
          | Some(t) => t0 +. float_of_int(t)
          | None => t0
          };
        staged :=
          {
            s_nodes:
              List.map(
                ((nl: CanvasLayout.node_layout, old)) =>
                  (nl.node.key, cue(nl.node.key), old),
                changed_nodes,
              ),
            s_edges:
              List.map(
                ((el: CanvasLayout.edge_layout, old)) =>
                  (el.edge.e_name, cue(el.edge.e_name), old),
                changed_edges,
              ),
          };
      };
      if (removed_node_layouts != [] || removed_edge_layouts != []) {
        leaving :=
          Option.some({
            l_nodes: removed_node_layouts,
            l_edges: removed_edge_layouts,
            l_until:
              CanvasBuffer.now() +. float_of_int(score.total_ms) +. 400.,
          });
      };
      CanvasLog.log(CanvasScore.to_string(score));
      List.iter(
        v => CanvasLog.log("SCORE: " ++ v),
        CanvasScore.validate(score) @ CanvasScore.coverage(diff, score),
      );
      let zoom = CanvasCamera.zoom_now^;
      CanvasEnact.jump_snapshot(~zoom);
      CanvasEnact.after_render(() => {
        CanvasEnact.check_jumps(~zoom);
        CanvasEnact.play(~zoom, score);
      });
    } else {
      if (prev_slide == slide && CanvasBuffer.in_burst() && added != []) {
        CanvasLog.log(
          Printf.sprintf(
            "+%d node(s) (unscored render)",
            List.length(added),
          ),
        );
      };
      CanvasJelly.set_targets(hull_targets);
    };
    /* layout churn: how much did EXISTING nodes move this render?
       (the metric behind "the layout suddenly reshuffled") */
    let moved =
      List.filter_map(
        (nl: CanvasLayout.node_layout) =>
          switch (List.assoc_opt(nl.node.key, prev_nodes)) {
          | Some((px, py)) =>
            let d = max(abs_float(nl.p.x -. px), abs_float(nl.p.y -. py));
            d > 21. ? Some(d) : None;
          | None => None
          },
        lay.nodes,
      );
    if (prev_slide == slide && moved != [] && ! drag_active^) {
      CanvasLog.log(
        Printf.sprintf(
          "layout: %d/%d nodes moved (max %.0fpx)",
          List.length(moved),
          List.length(lay.nodes),
          List.fold_left(max, 0., moved),
        ),
      );
    };
    /* record positions (grid cells) whenever the layout meaningfully
       changed, for post-hoc before/after diffing */
    if (! drag_active^
        && (prev_slide != slide || moved != [] || added != [] || removed != [])) {
      let pos_line =
        lay.nodes
        |> List.map((nl: CanvasLayout.node_layout) =>
             Printf.sprintf(
               "%s(%.0f,%.0f)",
               nl.node.key,
               nl.p.x /. 14.,
               nl.p.y /. 14.,
             )
           )
        |> String.concat(" ");
      CanvasLog.record_layout(
        CanvasLog.stamp() ++ " " ++ slide ++ " | " ++ pos_line,
      );
    };
    last_node_snapshot :=
      (
        slide,
        List.map(
          (nl: CanvasLayout.node_layout) => (nl.node.key, (nl.p.x, nl.p.y)),
          lay.nodes,
        ),
      );
    last_layout := Option.some(lay);

    /* the edge set for the next render's diff (edges are enacted by the
       score planned above) */
    let cur_edges =
      List.map((el: CanvasLayout.edge_layout) => el.edge.e_name, lay.edges);
    last_edge_snapshot := (slide, cur_edges);
  };
  /* dependency fan: subdued under-layer curves from the hovered or
     focused function's pill to what it references */
  let dep_fan = {
    let fan_for = (name: string) =>
      switch (
        List.find_opt(
          (el: CanvasLayout.edge_layout) => el.edge.e_name == name,
          lay.edges,
        )
      ) {
      | None => []
      | Some(el) =>
        let uses =
          el.edge.e_deps
          |> List.filter_map(dep => {
               let tgt =
                 switch (
                   List.find_opt(
                     (dl: CanvasLayout.edge_layout) => dl.edge.e_name == dep,
                     lay.edges,
                   )
                 ) {
                 | Some(dl) => Some(dl.label_p)
                 | None =>
                   List.find_opt(
                     (vl: CanvasLayout.value_layout) =>
                       vl.value.v_name == dep,
                     lay.values,
                   )
                   |> Option.map((vl: CanvasLayout.value_layout) => vl.p)
                 };
               tgt |> Option.map(t => (el.label_p, t));
             });
        /* and the reverse: who uses THIS function */
        let used_by =
          lay.edges
          |> List.filter_map((dl: CanvasLayout.edge_layout) =>
               dl.edge.e_name != name && List.mem(name, dl.edge.e_deps)
                 ? Some((dl.label_p, el.label_p)) : None
             );
        uses @ used_by;
      };
    switch (hovered_edge^, focused^) {
    | (Some(n), _)
    | (None, Some(n)) => fan_for(n)
    | (None, None) => []
    };
  };
  let on_hull_toggle = (root: string) => {
    let collapsing = !List.mem(root, collapsed_modules^);
    collapsed_modules :=
      collapsing
        ? [root, ...collapsed_modules^]
        : List.filter(r => r != root, collapsed_modules^);
    collapse_fx_until := CanvasBuffer.now() +. 900.;
    /* the effect emanates from the module node itself */
    switch (
      Util.JsUtil.get_elem_by_id_opt(CanvasView.node_dom_id("{}@" ++ root))
    ) {
    | Some(el) =>
      let st = Js.Unsafe.coerce(el)##.style;
      let px = (v: Js.t(Js.js_string)): float => {
        let str = Js.to_string(v);
        switch (String.index_opt(str, 'p')) {
        | Some(i) =>
          Option.value(
            ~default=0.,
            float_of_string_opt(String.sub(str, 0, i)),
          )
        | None => 0.
        };
      };
      let l = px(st##.left)
      and tp = px(st##.top);
      let r = float_of_int(Js.Unsafe.coerce(el)##.offsetWidth) /. 2.;
      collapsing
        ? CanvasRipple.suction((l +. r, tp +. r))
        : CanvasRipple.splash(~amp=8., (l +. r, tp +. r));
    | None => ()
    };
    tick;
  };
  let on_edge_hover = (h: option(string)) => {
    hovered_edge := h;
    tick;
  };
  /* clicking empty canvas clears the selection */
  let on_canvas_plain_click = () =>
    if (focused^ != None || focused_ty^ != None || focused_value^ != None) {
      focused_value := None;
      focused := None;
      focused_ty := None;
      tick;
    } else {
      Effect.Ignore;
    };
  let on_value_click = (v: CanvasGraph.value) => {
    focused_value := Some(v.v_name);
    focused := None;
    focused_ty := None;
    Effect.Many([
      select(v.v_name, "value", Some(v.v_id)),
      tick,
      Effect.Stop_propagation,
    ]);
  };
  let just_placed = {
    let now = CanvasBuffer.now();
    last_placed := List.filter(((_, t)) => now -. t < 2500., last_placed^);
    List.map(fst, last_placed^);
  };
  Node.div(
    ~attrs=[Attr.id("canvas-sidebar"), clss(["portolan-canvas"])],
    [
      Node.div(
        ~attrs=[
          Attr.id("canvas-scroll"),
          Attr.tabindex(-1),
          clss(["canvas-scroll"]),
        ],
        [
          /* the dot field: a viewport-fixed canvas UNDER the board
             (sticky 0x0 holder), redrawn on scroll/zoom with the
             lattice window + edge fade (CanvasRipple) */
          Node.div(
            ~attrs=[clss(["canvas-dots-holder"])],
            [
              Node.create(
                "canvas",
                ~attrs=[Attr.id("canvas-dots"), clss(["canvas-dots"])],
                [],
              ),
            ],
          ),
          CanvasView.view(
            ~inject_jump,
            ~collapsed_counts,
            ~on_hull_toggle,
            ~dep_fan,
            ~on_edge_hover,
            ~on_value_click=Some(on_value_click),
            ~on_canvas_plain_click,
            ~just_placed,
            ~on_node_select=n => click_effect(n),
            ~on_delete_definition=_ => Effect.Ignore,
            ~on_edge_contextmenu=(_, _) => Effect.Ignore,
            ~focused_ty=focused_ty^,
            ~on_edge_click,
            ~on_node_mousedown=start_node_drag,
            ~zoom,
            ~min_size=(
              (Option.value(~default=0., avail_width) -. 2.) /. zoom,
              (Option.value(~default=0., avail_height) -. 2.) /. zoom,
            ),
            ~focused=focused^,
            ~avatar,
            ~loose_tests=graph.loose_tests,
            {
              /* ghosts of what a running score is erasing ride along, at
                 their old places, until the score is done */

              let now = CanvasBuffer.now();
              /* changed elements keep their old look until their cue */
              let lay = {
                let st = staged^;
                if (st.s_nodes == [] && st.s_edges == []) {
                  lay;
                } else {
                  let live =
                    List.exists(((_, t, _)) => now < t, st.s_nodes)
                    || List.exists(((_, t, _)) => now < t, st.s_edges);
                  if (!live) {
                    staged :=
                      {
                        s_nodes: [],
                        s_edges: [],
                      };
                    lay;
                  } else {
                    CanvasLayout.{
                      ...lay,
                      nodes:
                        List.map(
                          (nl: CanvasLayout.node_layout) =>
                            switch (
                              List.find_opt(
                                ((k, t, _)) => k == nl.node.key && now < t,
                                st.s_nodes,
                              )
                            ) {
                            | Some((_, _, old)) => {
                                ...nl,
                                node: old,
                              }
                            | None => nl
                            },
                          lay.nodes,
                        ),
                      edges:
                        List.map(
                          (el: CanvasLayout.edge_layout) =>
                            switch (
                              List.find_opt(
                                ((n, t, _)) =>
                                  n == el.edge.e_name && now < t,
                                st.s_edges,
                              )
                            ) {
                            | Some((_, _, old)) => {
                                ...el,
                                edge: old,
                              }
                            | None => el
                            },
                          lay.edges,
                        ),
                    };
                  };
                };
              };
              switch (leaving^) {
              | Some(l) when now < l.l_until =>
                let cur =
                  List.map(
                    (nl: CanvasLayout.node_layout) => nl.node.key,
                    lay.nodes,
                  );
                let cur_e =
                  List.map(
                    (el: CanvasLayout.edge_layout) => el.edge.e_name,
                    lay.edges,
                  );
                CanvasLayout.{
                  ...lay,
                  nodes:
                    lay.nodes
                    @ List.filter(
                        (nl: CanvasLayout.node_layout) =>
                          !List.mem(nl.node.key, cur),
                        l.l_nodes,
                      ),
                  edges:
                    lay.edges
                    @ List.filter(
                        (el: CanvasLayout.edge_layout) =>
                          !List.mem(el.edge.e_name, cur_e),
                        l.l_edges,
                      ),
                };
              | Some(_) =>
                leaving := Option.none;
                lay;
              | None => lay
              };
            },
          ),
        ],
      ),
    ],
  );
};

/* ---------- mounting and the render pass ---------- */

let host: ref(option(Js.t(Dom_html.element))) = ref(None);
let rendered: ref(option((Node.t, Js.t(Dom_html.element)))) = ref(None);

/* upstream: CanvasSidebar.present_editor + Page's view + Main's
   Animation.go after display */
let render = (): unit =>
  switch (host^) {
  | None => ()
  | Some(host_el) =>
    CanvasEnact.request_tick := schedule_tick;
    let graph =
      CanvasBuffer.observe(
        ~enabled=pace^,
        ~weight=graph_delta,
        ~schedule_tick,
        live^,
      );
    let node = view(graph);
    switch (rendered^) {
    | None =>
      let el = Node.to_dom(node);
      Dom.appendChild(host_el, el);
      rendered := Some((node, el));
    | Some((prev, el)) =>
      let patch = Node.Patch.create(~previous=prev, ~current=node);
      let el = Node.Patch.apply(patch, el);
      rendered := Some((node, el));
    };
    Animation.go();
  };
render_fwd := render;

let mount = (el: Js.t(Dom_html.element)): unit => {
  switch (rendered^) {
  | Some((_, old)) =>
    Js.Opt.iter(old##.parentNode, p => ignore(p##removeChild((old :> Js.t(Dom.node)))))
  | None => ()
  };
  rendered := None;
  host := Some(el);
  Animation.slow_hook := CanvasLog.log;
  /* twice: the first pass creates the pane, the second measures it */
  render();
  render();
};

/* a new snapshot and what caused it: one beat (upstream:
   CanvasPresentation.push — seed with the state before, queue the state
   after, labelled, with the avatar's site) */
let push = (g: CanvasGraph.t, c: cause): unit => {
  CanvasBuffer.seed(live^);
  CanvasBuffer.note_tool();
  CanvasBuffer.push_lazy(
    ~label=c.label,
    ~avatar=Option.map(s => (s, c.ok ? "edit" : "err"), c.site),
    lazy(g),
  );
  last_cause := Some((c, CanvasBuffer.now()));
  live := g;
  request_render();
};

/* a snapshot with no story: shown at once when nothing is playing (an
   already-existing code base, a reload) */
let show = (g: CanvasGraph.t): unit => {
  live := g;
  overview_pending := true;
  request_render();
};

/* a clean board */
let reset = (): unit => {
  CanvasEnact.cancel_score();
  CanvasBuffer.reset();
  CanvasBuffer.last_agent_action := 0.;
  CanvasCamera.gen := CanvasCamera.gen^ + 1;
  CanvasCamera.inflight := Option.none;
  CanvasCamera.scored_until := 0.;
  slide_no := slide_no^ + 1;
  live := CanvasGraph.empty;
  last_cause := None;
  cached_frame := None;
  last_layout := None;
  leaving := None;
  staged :=
    {
      s_nodes: [],
      s_edges: [],
    };
  last_placed := [];
  node_offsets := [];
  collapsed_modules := [];
  focused := None;
  focused_ty := None;
  focused_value := None;
  hovered_edge := None;
  thought := "";
  pending_anchor := true;
  /* synchronously, so a push right after a reset is diffed against the
     empty board */
  render();
  /* and owes no dwell to whatever was showing before */
  CanvasBuffer.cur_dwell := CanvasBuffer.dwell_base_ms;
  CanvasBuffer.last_beat := 0.;
};

let fit = (): unit => {
  fit_pending := true;
  request_render();
};

/* PORTOLAN: the host selects a definition by its qualified name (a search
   result), as a click on it would. */
let select = (~is_type: bool, name: string): unit => {
  focused_value := None;
  focused := is_type ? None : Some(name);
  focused_ty := is_type ? Some(name) : None;
  request_render();
};

/* PORTOLAN: the layout and the edge style (CanvasOptions). The graph on
   the board is laid out again and glides to its new places; positions
   set by dragging belonged to the old arrangement and are dropped. */
let relayout = (): unit => {
  cached_frame := None;
  node_offsets := [];
  CanvasBuffer.stage_beat(~slow=true, ());
  fit_pending := true;
  request_render();
};
let set_layout = (k: string): bool => {
  let ok = CanvasOptions.set_layout(k);
  if (ok) {
    CanvasLog.log("layout: " ++ k);
    relayout();
  };
  ok;
};
let set_edges = (k: string): bool => {
  let ok = CanvasOptions.set_edges(k);
  if (ok) {
    CanvasLog.log("edges: " ++ k);
    relayout();
  };
  ok;
};

let set_follow = (b: bool): unit => {
  follow := b;
  request_render();
};
let set_pace = (b: bool): unit => {
  pace := b;
  request_render();
};
let set_busy = (b: bool): unit => {
  busy := b;
  request_render();
};
let set_thought = (s: string): unit => {
  thought := s;
  request_render();
};
let pending = (): int => List.length(CanvasBuffer.queue^);

files.canvas/CanvasGraph.re:
/* CanvasGraph — the architectural graph the canvas draws: named types are
   nodes, top-level functions are edges, values dock to their type's node,
   tests attach to the functions they mention. Multi-argument functions
   get an explicit Product node fed by formation lines from the component
   types. Builtin types (int, string, ...) duplicate per use-site as small
   satellite terminals — like ground symbols in a circuit diagram — so
   they never act as hubs.

   PORTOLAN: the record types are Hazel's (src/web/app/canvas/CanvasGraph.re)
   with the same field names, so the copied canvas files read them
   unchanged. What differs:
   - an id is a string (the definition's qualified name), not a Hazel Id.t;
   - terms are source text, not Exp.t;
   - there is no extraction here: a graph arrives as Portolan's graph
     record (graph/graph.re) and `of_graph` makes the picture of it. */

module Id = Haz3lcore.Id;
module Graph = Portolan_graph.Graph;

module TestStatus = {
  type t =
    | Pass
    | Fail
    | Indet;
};

type node_kind =
  | Alias /* a named type declared in the project */
  | Builtin /* int, bool, ... */
  | Derived /* 'a list, anonymous sums/arrows */
  | Ghost /* referenced but undefined, or hole */
  | Product; /* tuple-formation node for a multi-arg input */

type tynode = {
  key: string,
  label: string,
  /* enclosing module chain, outermost first ([] = top level) */
  m_path: list(string),
  n_id: option(Id.t), /* jump anchor */
  kind: node_kind,
  ctrs: list(string), /* constructor names when alias body is a sum */
  n_ty: option(string), /* alias body pretty — a second name for matching */
  n_doc: option(string),
  n_err: bool,
  deps: list(string), /* node keys this node's body/components reference */
  /* deps that are displayed through former nodes instead of plain dep
     links (they still participate in layer ordering) */
  hidden_deps: list(string),
  parts: list(string), /* Product / folded alias: component node keys (formation lines) */
  sat: option((string, bool)), /* satellite: (anchor node key, output side) */
  /* glyph of the type former an alias body IS ("()", "[]", "+"): the
     former is folded into the alias node — one object, drawn once */
  former: option(string),
};

type test_info = {
  t_id: Id.t,
  status: option(TestStatus.t), /* None = not yet evaluated */
  t_body: string, /* the tested expression, as source text */
  /* every function (edge name) the body mentions */
  t_refs: list(string),
};

type edge = {
  e_name: string, /* path-qualified, unique (dom ids, focus keys) */
  e_label: string, /* bare display name */
  m_path: list(string),
  e_id: Id.t, /* jump anchor */
  e_ty: string, /* full pretty type, for tooltip */
  e_src: string, /* input node key (component, product, or satellite) */
  dst: string,
  e_doc: option(string),
  e_err: bool,
  e_hole: bool, /* definition contains a hole => ghost/obligation styling */
  main: bool,
  tests: list(test_info),
  /* Hazel's probe-sample anchors: always empty here */
  e_arg_ids: list(Id.t),
  e_whole_ids: list(Id.t),
  e_out_id: option(Id.t),
  /* names of OTHER top-level bindings this definition references
     (call/constant dependencies; the hover fan) */
  e_deps: list(string),
  /* PORTOLAN: visible outside its module (not drawn yet) */
  e_exported: bool,
};

type value = {
  v_name: string, /* path-qualified, unique */
  v_label: string, /* bare display name */
  m_path: list(string),
  v_id: Id.t,
  v_key: string, /* node key of the value's type */
  v_ty: string,
  v_err: bool,
  v_def: string, /* the definition, as source text ("" when not carried) */
  /* PORTOLAN: what the record says of a value beyond Hazel's (not drawn yet) */
  v_doc: option(string),
  v_deps: list(string),
  v_exported: bool,
};

/* PORTOLAN: where a definition lives */
type handle =
  Graph.handle = {
    file: string,
    path: string,
    line: int,
    end_line: int,
  };

type t = {
  nodes: list(tynode),
  edges: list(edge),
  values: list(value),
  loose_tests: list(test_info),
  /* every test in program order (subject-attached ones included) */
  all_tests: list(test_info),
  /* Hazel's authoring / livelit fields: always empty here */
  last_def: option((string, Id.t)),
  livelit_defs: list(Id.t),
  /* PORTOLAN: id -> where it is declared */
  handles: list((Id.t, handle)),
};

let empty: t = {
  nodes: [],
  edges: [],
  values: [],
  loose_tests: [],
  all_tests: [],
  last_def: None,
  livelit_defs: [],
  handles: [],
};

let mk_node =
    (
      ~n_id=None,
      ~m_path=[],
      ~ctrs=[],
      ~n_ty=None,
      ~n_doc=None,
      ~n_err=false,
      ~deps=[],
      ~hidden_deps=[],
      ~parts=[],
      ~sat=None,
      ~former=None,
      ~kind,
      ~label,
      key,
    )
    : tynode => {
  key,
  label,
  m_path,
  n_id,
  kind,
  ctrs,
  n_ty,
  n_doc,
  n_err,
  deps,
  hidden_deps,
  parts,
  sat,
  former,
};

let truncate = (n: int, s: string): string =>
  String.length(s) > n ? String.sub(s, 0, n - 1) ++ {js|…|js} : s;

let display_label = (key: Graph.key): string =>
  if (String.length(key) > 0 && key.[0] == '?') {
    "?";
  } else if (String.length(key) >= 2 && String.sub(key, 0, 2) == "{}") {
    "{}";
  } else {
    truncate(20, key);
  };

/* a repeated definition (a second `type pos`) would give two nodes one
   key, and the vdom two keyed children with one key — which breaks its
   child patching (insertBefore of nothing). Later duplicates get `#2`,
   `#3`…; references by key resolve to the first. */
let uniquify_keys = (nodes: list(tynode)): list(tynode) => {
  let seen = Hashtbl.create(16);
  List.map(
    (n: tynode) => {
      let count =
        Option.value(Hashtbl.find_opt(seen, n.key), ~default=0) + 1;
      Hashtbl.replace(seen, n.key, count);
      count == 1
        ? n
        : {
          ...n,
          key: n.key ++ "#" ++ string_of_int(count),
        };
    },
    nodes,
  );
};

let qname = (path: list(string), name: string): string =>
  String.concat(".", path @ [name]);

let is_former_key = (key: Graph.key): bool =>
  String.length(key) >= 3 && String.sub(key, 0, 3) == "{}@";
let former_key = (path: list(string)): Graph.key =>
  "{}@" ++ String.concat(".", path);

/* ---------- PORTOLAN: from the graph record ---------- */

/* PORTOLAN: short labels for long printed types (Hazel cuts a label at 20
   characters; OCaml's inferred types need more care than that). */
module Abbreviate: {
  /* the most characters a label has */
  let limit: int;
  /* A printed type, short enough for a label. */
  let ty: string => string;
} = {
  let limit = 32;
  let dots = {js|…|js};

  let is_id = c =>
    switch (c) {
    | 'a' .. 'z'
    | 'A' .. 'Z'
    | '0' .. '9'
    | '_'
    | '\''
    | '.' => true
    | _ => false
    };

  /* [f] on every maximal run of identifier characters */
  let map_idents = (f: string => string, s: string): string => {
    let b = Buffer.create(String.length(s));
    let n = String.length(s);
    let rec go = (i, start) =>
      if (i >= n) {
        if (start < i) {
          Buffer.add_string(b, f(String.sub(s, start, i - start)));
        };
      } else if (is_id(s.[i])) {
        go(i + 1, start);
      } else {
        if (start < i) {
          Buffer.add_string(b, f(String.sub(s, start, i - start)));
        };
        Buffer.add_char(b, s.[i]);
        go(i + 1, i + 1);
      };
    go(0, 0);
    Buffer.contents(b);
  };

  /* "Virtual_dom.Vdom.Effect.t" -> "Effect.t" */
  let short_path = (id: string): string =>
    switch (List.rev(String.split_on_char('.', id))) {
    | [last, before, _, ..._] => before ++ "." ++ last
    | _ => id
    };

  let closes = c => c == ')' || c == ']' || c == '}';
  let opens = c => c == '(' || c == '[' || c == '{';

  /* the index of the bracket closing the one at [i] */
  let closing = (s: string, i: int): option(int) => {
    let n = String.length(s);
    let rec go = (j, depth) =>
      if (j >= n) {
        None;
      } else if (opens(s.[j])) {
        go(j + 1, depth + 1);
      } else if (closes(s.[j])) {
        depth == 1 ? Some(j) : go(j + 1, depth - 1);
      } else {
        go(j + 1, depth);
      };
    go(i, 0);
  };

  /* A polymorphic variant keeps its first two tags and drops what they
     carry: "[> `Assoc of (string * ...) list | `Null | `Int of int ]"
     -> "[> `Assoc | `Null | …]". Either syntax. */
  let variants = (s: string): string => {
    let n = String.length(s);
    let b = Buffer.create(n);
    /* the tags directly inside the bracket at [i], if it is a variant */
    let tags = (i: int, close: int): option((string, list(string))) => {
      let rec skip = j =>
        j < close && (s.[j] == ' ' || s.[j] == '|') ? skip(j + 1) : j;
      let j = i + 1;
      let (bound, j) =
        j < close && (s.[j] == '>' || s.[j] == '<')
          ? (String.make(1, s.[j]) ++ " ", j + 1) : ("", j);
      if (skip(j) < close && s.[skip(j)] == '`') {
        let rec go = (j, depth, acc) =>
          if (j >= close) {
            List.rev(acc);
          } else if (opens(s.[j])) {
            go(j + 1, depth + 1, acc);
          } else if (closes(s.[j])) {
            go(j + 1, depth - 1, acc);
          } else if (s.[j] == '`' && depth == 0) {
            let rec stop = k => k < close && is_id(s.[k]) ? stop(k + 1) : k;
            let k = stop(j + 1);
            go(k, depth, [String.sub(s, j, k - j), ...acc]);
          } else {
            go(j + 1, depth, acc);
          };
        Some((bound, go(j, 0, [])));
      } else {
        None;
      };
    };
    let rec go = i =>
      if (i < n) {
        switch (s.[i] == '[' ? closing(s, i) : None) {
        | Some(close) =>
          switch (tags(i, close)) {
          | Some((bound, tags)) =>
            let shown =
              switch (tags) {
              | [a, b, _, ..._] => [a, b, dots]
              | l => l
              };
            Buffer.add_string(
              b,
              "[" ++ bound ++ String.concat(" | ", shown) ++ "]",
            );
            go(close + 1);
          | None =>
            Buffer.add_char(b, s.[i]);
            go(i + 1);
          }
        | None =>
          Buffer.add_char(b, s.[i]);
          go(i + 1);
        };
      };
    go(0);
    Buffer.contents(b);
  };

  /* characters, not bytes: "…" is three bytes */
  let length = (s: string): int => {
    let n = ref(0);
    String.iter(c => Char.code(c) land 0xC0 != 0x80 ? incr(n) : (), s);
    n^;
  };

  /* "CanvasGraph.tynode" -> "tynode"; "Effect.t" stays: [t] alone
     names nothing */
  let bare = (id: string): string =>
    switch (List.rev(String.split_on_char('.', id))) {
    | [last, _, ..._] when String.length(last) > 1 => last
    | _ => id
    };

  /* what is inside the brackets nested deeper than [keep] becomes "…",
     unless it is short anyway */
  let collapse = (~keep: int, s: string): string => {
    let b = Buffer.create(String.length(s));
    let rec go = (i, stop, depth) =>
      if (i < stop) {
        switch (opens(s.[i]) ? closing(s, i) : None) {
        | Some(close) when close < stop =>
          Buffer.add_char(b, s.[i]);
          if (depth >= keep
              && length(String.sub(s, i + 1, close - i - 1)) > 6) {
            Buffer.add_string(b, dots);
          } else {
            go(i + 1, close, depth + 1);
          };
          Buffer.add_char(b, s.[close]);
          go(close + 1, stop, depth);
        | _ =>
          Buffer.add_char(b, s.[i]);
          go(i + 1, stop, depth);
        };
      };
    go(0, String.length(s), 0);
    Buffer.contents(b);
  };

  let cut = (s: string): string =>
    if (length(s) <= limit) {
      s;
    } else {
      /* back to the start of a character */
      let rec back = i =>
        i > 0 && Char.code(s.[i]) land 0xC0 == 0x80 ? back(i - 1) : i;
      String.sub(s, 0, back(limit - 1)) ++ dots;
    };

  /* The first of these that fits: the type as printed; with variants
     reduced to their tags; with module paths cut to their last module,
     then dropped; with the inner brackets closed up, then the outer
     ones; cut off. */
  let ty = (s: string): string => {
    let fits = s => length(s) <= limit;
    let steps = [
      variants,
      map_idents(short_path),
      map_idents(bare),
      collapse(~keep=1),
      collapse(~keep=0),
      cut,
    ];
    List.fold_left((s, step) => fits(s) ? s : step(s), s, steps);
  };
};

/* The picture of a graph record.

   The canvas wants a few things the record does not say. They are
   derived here, the way Hazel's extraction does it:

   - satellites: a builtin node (or a type variable) that is a function's
     only argument, its result, or a component is split into one small
     terminal per use-site, docked to the node at the other end;
   - `deps` of a named type: the other named types its body mentions;
   - `former`, where the record gives none: "()" for a type with
     component parts, "+" for a sum;
   - a module's former node ("{}@M"): the host its members cluster on.

   And a few things are drawn differently from how the record says them:

   - an unnamed tuple, list or option (a Derived node with that former)
     that functions use or types are made of is a former dot, as Hazel
     draws a tuple written inline: its glyph, fed by its components;
   - any other unnamed type keeps its text, abbreviated (see Abbreviate);
     the whole of it is in the node's tooltip;
   - a type from outside (Ghost) shows no components of its own;
   - a node that nothing in the picture uses is left out. */
module Read: {
  let graph: Graph.t => t;
} = {
  /* A node of the picture is found by its key: one of the record's, or
     one made here for a terminal ("int@Geo.scale") or a module's former
     ("{}@Geo"). */
  type key = Graph.key;

  let kind = (k: Graph.node_kind): node_kind =>
    switch (k) {
    | Graph.Alias => Alias
    | Graph.Builtin => Builtin
    | Graph.Derived => Derived
    | Graph.Ghost => Ghost
    | Graph.Product => Product
    };

  let status = (s: Graph.test_status): option(TestStatus.t) =>
    switch (s) {
    | Graph.Pass => Some(TestStatus.Pass)
    | Graph.Fail => Some(TestStatus.Fail)
    | Graph.Unknown => None
    };

  /* ---- the record's items, in the canvas's shape ---- */

  /* [deps], [hidden_deps] and [sat] are not in the record: [graph]
     fills them in. */
  let node = (n: Graph.node): tynode => {
    let kind = kind(n.kind);
    {
      key: n.key,
      /* a tuple-formation dot is drawn with its glyph; what it is a tuple
         OF is told by its formation lines (and its key) */
      label: kind == Product && !is_former_key(n.key) ? "()" : n.label,
      m_path: n.m_path,
      n_id: Option.map(_ => n.key, n.at),
      kind,
      /* a record's fields are in its body; `ctrs` would read as a sum */
      ctrs: kind == Alias && n.former == Some("{}") ? [] : n.ctors,
      n_ty: n.n_ty,
      n_doc: n.n_doc,
      n_err: n.n_err,
      deps: [],
      hidden_deps: [],
      /* a type from outside: what it is made of is not this picture's */
      parts: kind == Ghost ? [] : n.parts,
      sat: None,
      former: kind == Ghost ? None : n.former,
    };
  };

  let test_id = (t: Graph.test): Id.t => "test:" ++ t.t_name;

  let test = (t: Graph.test): test_info => {
    t_id: test_id(t),
    status: status(t.t_status),
    t_body: t.t_name,
    t_refs: t.t_refs,
  };

  let edge = (e: Graph.edge): edge => {
    e_name: e.e_name,
    e_label: e.e_label,
    m_path: e.e_m_path,
    e_id: e.e_name,
    e_ty: e.e_ty,
    e_src: e.src,
    dst: e.dst,
    e_doc: e.e_doc,
    e_err: e.e_err,
    e_hole: e.e_hole,
    main: e.main,
    tests: List.map(test, e.tests),
    e_arg_ids: [],
    e_whole_ids: [],
    e_out_id: None,
    e_deps: e.e_deps,
    e_exported: e.e_exported,
  };

  let value = (v: Graph.value): value => {
    v_name: v.v_name,
    v_label: v.v_label,
    m_path: v.v_m_path,
    v_id: v.v_name,
    v_key: v.v_key,
    v_ty: v.v_ty,
    v_err: v.v_err,
    v_def: "",
    v_doc: v.v_doc,
    v_deps: v.v_deps,
    v_exported: v.v_exported,
  };

  /* where each id is declared: nodes, then each function and its tests,
     then values, then loose tests */
  let handles = (g: Graph.t): list((Id.t, handle)) => {
    let of_test = (t: Graph.test) => (test_id(t), t.t_at);
    List.concat([
      List.filter_map(
        (n: Graph.node) => Option.map(h => (n.key, h), n.at),
        g.nodes,
      ),
      List.concat_map(
        (e: Graph.edge) =>
          [(e.e_name, e.e_at), ...List.map(of_test, e.tests)],
        g.edges,
      ),
      List.map((v: Graph.value) => (v.v_name, v.v_at), g.values),
      List.map(of_test, g.loose_tests),
    ]);
  };

  /* ---- what the picture adds ---- */

  /* identifiers in a printed type: "point * shape list" -> point, shape,
     list; a dotted path stays whole ("Geo.point") */
  let idents = (s: string): list(string) => {
    let is_id = c =>
      switch (c) {
      | 'a' .. 'z'
      | 'A' .. 'Z'
      | '0' .. '9'
      | '_'
      | '\''
      | '.' => true
      | _ => false
      };
    let n = String.length(s);
    let rec go = (i, start, acc) =>
      if (i >= n) {
        start < i ? [String.sub(s, start, i - start), ...acc] : acc;
      } else if (is_id(s.[i])) {
        go(i + 1, start, acc);
      } else {
        go(
          i + 1,
          i + 1,
          start < i ? [String.sub(s, start, i - start), ...acc] : acc,
        );
      };
    List.rev(go(0, 0, []));
  };

  /* "shape list": the body is one type under a container */
  let ends_with_container = (ty: string): bool =>
    List.exists(
      c => {
        let lt = String.length(ty)
        and lc = String.length(c);
        lt > lc && String.sub(ty, lt - lc, lc) == c;
      },
      [" list", " array", " option", " seq"],
    );

  let prefixes = (path: list(string)): list(list(string)) => {
    let rec go = (acc, rev_done, rest) =>
      switch (rest) {
      | [] => List.rev(acc)
      | [x, ...xs] =>
        let p = List.rev([x, ...rev_done]);
        go([p, ...acc], [x, ...rev_done], xs);
      };
    go([], [], path);
  };

  /* the glyph an unnamed tuple, list or option is drawn as */
  let glyph_of = (n: tynode): option(string) =>
    switch (n.kind, n.former) {
    | (Derived, Some(("()" | "[]" | "?") as glyph)) when n.parts != [] =>
      Some(glyph)
    | _ => None
    };

  let is_variable = (n: tynode): bool =>
    n.kind == Derived
    && String.length(n.label) >= 2
    && n.label.[0] == '\''
    && !String.contains(n.label, ' ');

  let value_names = (vs: list(value)): string =>
    String.concat(", ", List.map((v: value) => v.v_label, vs));

  /* the tooltip of a node drawn as [label]: its whole text, if the label
     is not that */
  let shown_whole = (n: tynode, label: string): option(string) =>
    n.n_doc == None && label != n.label ? Some(n.label) : n.n_doc;

  let graph = (g: Graph.t): t => {
    let nodes0 = List.map(node, g.nodes);
    let edges = List.map(edge, g.edges);
    let values = List.map(value, g.values);
    let loose_tests = List.map(test, g.loose_tests);
    let all_tests =
      List.concat_map((e: edge) => e.tests, edges) @ loose_tests;

    let by_key: Hashtbl.t(key, tynode) = Hashtbl.create(64);
    List.iter(
      (n: tynode) =>
        if (!Hashtbl.mem(by_key, n.key)) {
          Hashtbl.replace(by_key, n.key, n);
        },
      nodes0,
    );
    let find0 = (k: key): option(tynode) => Hashtbl.find_opt(by_key, k);
    /* who uses a node: the functions it is an end of (their module
       paths), the nodes it is a part of, the values of its type */
    let fn_ends: Hashtbl.t(key, list(string)) = Hashtbl.create(64)
    and hosts: Hashtbl.t(key, tynode) = Hashtbl.create(64)
    and holds: Hashtbl.t(key, list(value)) = Hashtbl.create(16);
    let first = (t, k, x) =>
      if (!Hashtbl.mem(t, k)) {
        Hashtbl.replace(t, k, x);
      };
    List.iter((e: edge) => first(fn_ends, e.e_src, e.m_path), edges);
    List.iter((e: edge) => first(fn_ends, e.dst, e.m_path), edges);
    List.iter(
      (n: tynode) => List.iter(p => first(hosts, p, n), n.parts),
      nodes0,
    );
    List.iter(
      (v: value) =>
        Hashtbl.replace(
          holds,
          v.v_key,
          Option.value(Hashtbl.find_opt(holds, v.v_key), ~default=[]) @ [v],
        ),
      values,
    );
    /* An unnamed tuple, list or option is a former dot where something
       is made of it or a function uses it: a function's end, or a part
       of a declared type, of an argument tuple or of another dot. One
       that only holds values, or is a part of a type shown as text,
       keeps its text. */
    let dots: Hashtbl.t(key, string) = Hashtbl.create(64);
    let rec dot = (k: key) =>
      switch (find0(k)) {
      | Some(n) when !Hashtbl.mem(dots, k) =>
        switch (glyph_of(n)) {
        | Some(glyph) =>
          Hashtbl.replace(dots, k, glyph);
          List.iter(dot, n.parts);
        | None => ()
        }
      | _ => ()
      };
    List.iter(
      (e: edge) => {
        dot(e.e_src);
        dot(e.dst);
      },
      edges,
    );
    List.iter(
      (n: tynode) =>
        if (n.kind == Alias || n.kind == Product) {
          List.iter(dot, n.parts);
        },
      nodes0,
    );
    /* A tuple or a dot is in the module of the first function it is an
       end of. One that is only a part of types stays outside: a module's
       former has room for few members around it. */
    let home = (k: key): list(string) =>
      Option.value(Hashtbl.find_opt(fn_ends, k), ~default=[]);
    /* split into one terminal per use-site: a builtin, a type variable */
    let plain_builtin = (k: key): bool =>
      switch (find0(k)) {
      | Some(n) => n.kind == Builtin || is_variable(n)
      | None => false
      };
    let label_of = (k: key): string =>
      switch (find0(k)) {
      | Some(n) => n.label
      | None => display_label(k)
      };
    let sats: ref(list(tynode)) = ref([]);
    let sat_keys = Hashtbl.create(64);
    /* the terminal of [k] at one use-site, which [dup] tells apart */
    let ensure_sat =
        (~m_path=[], ~anchor_key: key, ~output: bool, ~dup: string, k: key)
        : key => {
      let label = label_of(k);
      let key = label ++ "@" ++ dup;
      if (!Hashtbl.mem(sat_keys, key)) {
        Hashtbl.replace(sat_keys, key, ());
        sats :=
          [
            mk_node(
              ~kind=Builtin,
              ~m_path,
              ~sat=Some((anchor_key, output)),
              ~label,
              key,
            ),
            ...sats^,
          ];
      };
      key;
    };
    let nodes1 =
      List.map(
        (n: tynode) => {
          /* how this node is drawn */
          let n =
            switch (n.kind, Hashtbl.find_opt(dots, n.key)) {
            | (Derived, Some(glyph)) => {
                ...n,
                kind: Product,
                label: glyph,
                former: None,
                m_path: home(n.key),
                n_doc: shown_whole(n, glyph),
              }
            | (Derived, None) =>
              let label =
                switch (
                  Hashtbl.mem(fn_ends, n.key) || Hashtbl.mem(hosts, n.key),
                  Hashtbl.find_opt(holds, n.key),
                ) {
                /* there for its values alone: say which */
                | (false, Some(vs)) =>
                  Abbreviate.ty(value_names(vs) ++ ": " ++ n.label)
                | _ => Abbreviate.ty(n.label)
                };
              {
                /* its text names its components: none are drawn */

                ...n,
                label,
                parts: [],
                n_doc: shown_whole(n, label),
              };
            | (Product, _) when !is_former_key(n.key) => {
                ...n,
                m_path: home(n.key),
              }
            | (Ghost, _) =>
              let label = Abbreviate.ty(n.label);
              {
                ...n,
                label,
                n_doc: shown_whole(n, label),
              };
            | _ => n
            };
          /* components: a builtin part becomes a terminal of its product
             or of the named type it is a component of */
          let parts =
            List.mapi(
              (i, p) =>
                plain_builtin(p)
                  ? ensure_sat(
                      ~m_path=n.m_path,
                      ~anchor_key=n.key,
                      ~output=false,
                      ~dup=n.key ++ "c" ++ string_of_int(i),
                      p,
                    )
                  : p,
              n.parts,
            )
            /* one line per part: a record with five [string list] fields
               would otherwise count as five lines for the layout to
               keep other nodes off */
            |> List.fold_left(
                 (acc, p) => List.mem(p, acc) ? acc : acc @ [p],
                 [],
               );
          let former =
            switch (n.former) {
            | Some("->") => Some({js|→|js})
            | Some(_) as given => given
            | None =>
              switch (n.kind) {
              | Alias
                  when
                    List.length(parts) == 1
                    && (
                      switch (n.n_ty) {
                      | Some(ty) => ends_with_container(ty)
                      | None => false
                      }
                    ) =>
                Some("[]")
              | Alias when parts != [] => Some("()")
              | Alias
                  when
                    switch (n.n_ty) {
                    | Some(ty) => String.contains(ty, '|')
                    | None => false
                    } =>
                Some("+")
              | _ => None
              }
            };
          let deps: list(key) =
            switch (n.kind) {
            | Product =>
              List.filter(p => !plain_builtin(p), n.parts)
              |> List.sort_uniq(compare)
            | Alias =>
              /* the named types the body mentions */
              let named = (id: string): option(key) =>
                List.find_map(
                  (m: tynode) =>
                    m.key != n.key
                    && (
                      m.kind == Alias
                      && (
                        m.key == id
                        || m.key == qname(n.m_path, id)
                        || m.label == id
                        && m.m_path == n.m_path
                      )
                      || m.kind == Ghost
                      && m.key == id
                    )
                      ? Some(m.key) : None,
                  nodes0,
                );
              let of_body =
                switch (n.n_ty) {
                | Some(ty) => List.filter_map(named, idents(ty))
                | None => []
                };
              let of_parts =
                List.filter(
                  p =>
                    switch (find0(p)) {
                    | Some(m) => !plain_builtin(p) && m.key != n.key
                    | None => false
                    },
                  n.parts,
                );
              List.sort_uniq(compare, of_body @ of_parts);
            | _ => []
            };
          {
            ...n,
            parts,
            former,
            deps,
            /* shown through the formation lines of its parts instead */
            hidden_deps: n.kind == Alias && parts != [] ? deps : [],
          };
        },
        nodes0,
      );
    /* functions: a single builtin argument docks at the result, a
       builtin result docks at the input */
    let edges =
      List.map(
        (e: edge) => {
          let src =
            plain_builtin(e.e_src) && !plain_builtin(e.dst)
              ? ensure_sat(
                  ~m_path=e.m_path,
                  ~anchor_key=e.dst,
                  ~output=false,
                  ~dup=e.e_name,
                  e.e_src,
                )
              : e.e_src;
          let dst =
            plain_builtin(e.dst)
              ? ensure_sat(
                  ~m_path=e.m_path,
                  ~anchor_key=src,
                  ~output=true,
                  ~dup=e.e_name,
                  e.dst,
                )
              : e.dst;
          {
            ...e,
            e_src: src,
            dst,
          };
        },
        edges,
      );
    /* a builtin or an outside type that only holds values: say which */
    let nodes1 =
      List.map(
        (n: tynode) =>
          switch (n.kind, Hashtbl.find_opt(holds, n.key)) {
          | (Builtin | Ghost, Some(vs))
              when
                !
                  List.exists(
                    (e: edge) => e.e_src == n.key || e.dst == n.key,
                    edges,
                  )
                && !
                     List.exists(
                       (m: tynode) => List.mem(n.key, m.parts),
                       nodes1,
                     ) => {
              ...n,
              label: Abbreviate.ty(value_names(vs) ++ ": " ++ n.label),
            }
          | _ => n
          },
        nodes1,
      );
    /* what nothing uses is left out: a shared builtin every use of
       which became a terminal, the insides of a type from outside */
    let all = nodes1 @ List.rev(sats^);
    let kept = Hashtbl.create(64);
    let rec keep = (k: key) =>
      if (!Hashtbl.mem(kept, k)) {
        Hashtbl.replace(kept, k, ());
        switch (List.find_opt((n: tynode) => n.key == k, all)) {
        | Some(n) =>
          List.iter(keep, n.parts);
          List.iter(keep, n.deps);
        | None => ()
        };
      };
    List.iter(
      (n: tynode) =>
        if (n.kind == Alias || is_former_key(n.key)) {
          keep(n.key);
        },
      all,
    );
    List.iter(
      (e: edge) => {
        keep(e.e_src);
        keep(e.dst);
      },
      edges,
    );
    List.iter((v: value) => keep(v.v_key), values);
    let nodes2 = List.filter((n: tynode) => Hashtbl.mem(kept, n.key), all);
    /* module formers: one per module path in use */
    let paths =
      List.concat_map((n: tynode) => prefixes(n.m_path), nodes2)
      @ List.concat_map((e: edge) => prefixes(e.m_path), edges)
      @ List.concat_map((v: value) => prefixes(v.m_path), values)
      |> List.fold_left((acc, p) => List.mem(p, acc) ? acc : acc @ [p], []);
    let formers =
      List.filter_map(
        (path: list(string)) => {
          let key = former_key(path);
          List.exists((n: tynode) => n.key == key, nodes2)
            ? None
            : Some(
                mk_node(
                  ~kind=Product,
                  ~m_path=path,
                  ~label=List.nth(path, List.length(path) - 1),
                  key,
                ),
              );
        },
        paths,
      );
    {
      nodes: uniquify_keys(nodes2 @ formers),
      edges,
      values,
      loose_tests,
      all_tests,
      last_def: None,
      livelit_defs: [],
      handles: handles(g),
    };
  };
};

/* The picture of a graph record: see Read. */
let of_graph: Graph.t => t = Read.graph;

/* [of_graph] of a record's JSON; [Error] says what is not a graph record
   about it. */
let of_json = (j: Yojson.Safe.t): result(t, string) =>
  Result.map(of_graph, Graph.of_json(j));
let of_string = (s: string): result(t, string) =>
  Result.map(of_graph, Graph.of_string(s));

let handle_of = (g: t, id: Id.t): option(handle) =>
  List.assoc_opt(id, g.handles);

files.canvas/CanvasOptions.re:
/* CanvasOptions — the layouts and edge styles a reader can switch between.
   The lab's own (CanvasLayoutExperiments) are listed here too; the ones
   written for Portolan are below: three placements (compact, ledger,
   clusters) and two edge styles (metro, straight). Pure geometry over the
   graph record: CanvasLayout calls in at three marked places. */
module Lab = CanvasLayoutExperiments;
type point = Lab.point;

let layouts = [
  ("current", "layered"),
  ("compact", "compact"),
  ("ledger", "ledger"),
  ("clusters", "clusters"),
  ("flow", "function layers"),
  ("dependencies", "type layers"),
  ("packed", "packed groups"),
  ("grid", "grid"),
  ("stable", "stable growth"),
  ("relaxed", "soft anchors"),
];
let edge_styles = [
  ("curves", "curves"),
  ("metro", "metro"),
  ("straight", "straight"),
  ("circuit", "circuit"),
];

let layout = () => Lab.mode^;
let edges = () => Lab.wires^;
let set_layout = (k: string): bool =>
  if (List.mem_assoc(k, layouts)) {
    Lab.mode := k;
    Lab.reset();
    true;
  } else {
    false;
  };
let set_edges = (k: string): bool =>
  if (List.mem_assoc(k, edge_styles)) {
    Lab.wires := k;
    true;
  } else {
    false;
  };

let aspect: ref(float) = ref(1.6);
let grid = 14.;
let snap = (v: float): float => Float.round(v /. grid) *. grid;

/* ---------- source order ---------- */

/* definitions by (file, line); what has no place in the source comes
   after, in the record's order */
let source_order = (g: CanvasGraph.t): (string => int, string => int) => {
  let at: Hashtbl.t(string, (string, int)) = Hashtbl.create(64);
  List.iter(
    ((id, h: CanvasGraph.handle)) =>
      Hashtbl.replace(at, id, (h.file, h.line)),
    g.handles,
  );
  let where = (i, id) =>
    switch (Option.bind(id, Hashtbl.find_opt(at))) {
    | Some((f, l)) => (0, f, l, i)
    | None => (1, "", 0, i)
    };
  let defs =
    List.mapi(
      (i, e: CanvasGraph.edge) =>
        (where(i, Some(e.e_id)), "e:" ++ e.e_name),
      g.edges,
    )
    @ List.mapi(
        (i, n: CanvasGraph.tynode) => (where(i, n.n_id), "n:" ++ n.key),
        List.filter((n: CanvasGraph.tynode) => n.kind == Alias, g.nodes),
      )
    |> List.sort(compare);
  let rank: Hashtbl.t(string, int) = Hashtbl.create(64);
  List.iteri((i, (_, k)) => Hashtbl.replace(rank, k, i), defs);
  let far = List.length(defs);
  let edge_ord = name =>
    Option.value(~default=far, Hashtbl.find_opt(rank, "e:" ++ name));
  /* a node that is not a definition: where it is first used */
  let first_use: Hashtbl.t(string, int) = Hashtbl.create(64);
  List.iter(
    (e: CanvasGraph.edge) => {
      let o = edge_ord(e.e_name);
      List.iter(
        k =>
          switch (Hashtbl.find_opt(first_use, k)) {
          | Some(o') when o' <= o => ()
          | _ => Hashtbl.replace(first_use, k, o)
          },
        [e.e_src, e.dst],
      );
    },
    g.edges,
  );
  let index: Hashtbl.t(string, int) = Hashtbl.create(64);
  List.iteri(
    (i, n: CanvasGraph.tynode) => Hashtbl.replace(index, n.key, i),
    g.nodes,
  );
  let node_ord = key =>
    switch (Hashtbl.find_opt(rank, "n:" ++ key)) {
    | Some(o) => o
    | None =>
      switch (Hashtbl.find_opt(first_use, key)) {
      | Some(o) => o
      | None =>
        far + 1 + Option.value(~default=0, Hashtbl.find_opt(index, key))
      }
    };
  (node_ord, edge_ord);
};

/* ---------- filling a pane-shaped area with boxes ---------- */

/* Boxes (id, w, h) in the order given, stacked into columns left to right;
   the number of columns is the one whose outline is nearest the pane's
   shape. Returns each box's top-left corner. */
let columns =
    (~aspect: float, ~gap: float, boxes: list((string, float, float)))
    : list((string, float, float)) =>
  if (boxes == []) {
    [];
  } else {
    let total = List.fold_left((s, (_, _, h)) => s +. h +. gap, 0., boxes);
    let tallest = List.fold_left((s, (_, _, h)) => max(s, h), 0., boxes);
    let fill = (limit: float) => {
      let (cols, cur, _) =
        List.fold_left(
          ((cols, cur, y), (id, w, h)) =>
            if (cur != [] && y +. h > limit) {
              (cols @ [cur], [(id, w, h, 0.)], h +. gap);
            } else {
              (cols, cur @ [(id, w, h, y)], y +. h +. gap);
            },
          ([], [], 0.),
          boxes,
        );
      let cols = cols @ [cur];
      let (out, width, height) =
        List.fold_left(
          ((out, x, height), col) => {
            let w =
              List.fold_left((s, (_, w, _, _)) => max(s, w), 0., col);
            let h =
              List.fold_left((s, (_, _, h, y)) => max(s, y +. h), 0., col);
            (
              out @ List.map(((id, _, _, y)) => (id, x, y), col),
              x +. w +. gap,
              max(height, h),
            );
          },
          ([], 0., 0.),
          cols,
        );
      (out, width -. gap, height);
    };
    let tries = min(List.length(boxes), 24);
    let (best, _) =
      List.fold_left(
        ((best, score), k) => {
          let (out, w, h) =
            fill(max(tallest, total /. float_of_int(k)) +. 1.);
          let s = abs_float(log(max(1., w) /. max(1., h) /. aspect));
          s < score ? (out, s) : (best, score);
        },
        ([], infinity),
        List.init(tries, i => i + 1),
      );
    best;
  };

/* the same, in rows that wrap */
let shelves = (~aspect, ~gap, boxes) =>
  columns(
    ~aspect=1. /. aspect,
    ~gap,
    List.map(((id, w, h)) => (id, h, w), boxes),
  )
  |> List.map(((id, y, x)) => (id, x, y));

/* ---------- the default's packing, without the list searches ---------- */

/* `Lab.place("components", items, links, [])`, to the same result: a host
   and what docks to it move as one unit, and the connected pieces are
   shelf-packed. The lab finds roots, groups and members by searching lists
   by key for every node, which at a thousand nodes was nearly all of a
   layout's time; this keeps tables. The arithmetic is the lab's. */
let components =
    (items: list(Lab.item), links: list((string, string))): list(Lab.item) => {
  let here: Hashtbl.t(string, Lab.item) = Hashtbl.create(256);
  List.iter(
    (n: Lab.item) =>
      if (!Hashtbl.mem(here, n.key)) {
        Hashtbl.add(here, n.key, n);
      },
    items,
  );
  let rec root = (seen, n: Lab.item) =>
    switch (n.anchor) {
    | Some(k) when !List.mem(k, seen) =>
      switch (Hashtbl.find_opt(here, k)) {
      | Some(host) => root([n.key, ...seen], host)
      | None => n.key
      }
    | _ => n.key
    };
  let root_of: Hashtbl.t(string, string) = Hashtbl.create(256);
  List.iter(
    (n: Lab.item) =>
      if (!Hashtbl.mem(root_of, n.key)) {
        Hashtbl.add(root_of, n.key, root([], n));
      },
    items,
  );
  let members: Hashtbl.t(string, list(Lab.item)) = Hashtbl.create(256);
  List.iter(
    (n: Lab.item) => {
      let r = root([], n);
      Hashtbl.replace(
        members,
        r,
        [n, ...Option.value(~default=[], Hashtbl.find_opt(members, r))],
      );
    },
    List.rev(items),
  );
  let units =
    List.filter_map(
      (host: Lab.item) =>
        if (root([], host) != host.key) {
          None;
        } else {
          let (left, top, right, bottom) =
            List.fold_left(
              ((left, top, right, bottom), n: Lab.item) =>
                (
                  min(left, n.p.x -. n.w /. 2.),
                  min(top, n.p.y -. n.h /. 2.),
                  max(right, n.p.x +. n.w /. 2.),
                  max(bottom, n.p.y +. n.h /. 2.),
                ),
              (infinity, infinity, neg_infinity, neg_infinity),
              Option.value(~default=[], Hashtbl.find_opt(members, host.key)),
            );
          Some({
            ...host,
            p: {
              x: (left +. right) /. 2.,
              y: (top +. bottom) /. 2.,
            },
            w: right -. left,
            h: bottom -. top,
            anchor: None,
          });
        },
      items,
    );
  let links =
    Lab.links_of(items, links)
    |> List.filter_map(((a, b)) =>
         switch (Hashtbl.find_opt(root_of, a), Hashtbl.find_opt(root_of, b)) {
         | (Some(a), Some(b)) when a != b => Some((a, b))
         | _ => None
         }
       )
    |> List.sort_uniq(compare);
  /* the units' connected pieces, each in the units' order, the pieces in
     the order of their first unit */
  let piece: Hashtbl.t(string, string) = Hashtbl.create(256);
  let rec find = k =>
    switch (Hashtbl.find_opt(piece, k)) {
    | Some(p) when p != k =>
      let r = find(p);
      Hashtbl.replace(piece, k, r);
      r;
    | _ => k
    };
  let is_unit: Hashtbl.t(string, unit) = Hashtbl.create(256);
  List.iter((n: Lab.item) => Hashtbl.replace(is_unit, n.key, ()), units);
  List.iter(
    ((a, b)) =>
      if (Hashtbl.mem(is_unit, a) && Hashtbl.mem(is_unit, b)) {
        let ra = find(a)
        and rb = find(b);
        if (ra != rb) {
          Hashtbl.replace(piece, ra, rb);
        };
      },
    links,
  );
  let in_piece: Hashtbl.t(string, list(Lab.item)) = Hashtbl.create(64);
  List.iter(
    (n: Lab.item) => {
      let r = find(n.key);
      Hashtbl.replace(
        in_piece,
        r,
        [n, ...Option.value(~default=[], Hashtbl.find_opt(in_piece, r))],
      );
    },
    List.rev(units),
  );
  let seen: Hashtbl.t(string, unit) = Hashtbl.create(64);
  let pieces =
    List.filter_map(
      (n: Lab.item) => {
        let r = find(n.key);
        if (Hashtbl.mem(seen, r)) {
          None;
        } else {
          Hashtbl.replace(seen, r, ());
          Hashtbl.find_opt(in_piece, r);
        };
      },
      units,
    );
  /* from here on: Lab.packed, per piece */
  let blocks =
    List.map(
      (ns: list(Lab.item)) => {
        let minx =
          List.fold_left(
            (x, n: Lab.item) => min(x, n.p.x -. n.w /. 2.),
            infinity,
            ns,
          );
        let intervals =
          List.map(
            (n: Lab.item) => (n.p.y -. n.h /. 2., n.p.y +. n.h /. 2.),
            ns,
          )
          |> List.sort(compare);
        let (_, gaps) =
          List.fold_left(
            ((end_y, gaps), (lo, hi)) =>
              (
                max(end_y, hi),
                lo -. end_y > 100. && end_y != neg_infinity
                  ? gaps @ [(lo, lo -. end_y -. 100.)] : gaps,
              ),
            (neg_infinity, []),
            intervals,
          );
        let miny =
          List.fold_left(
            (v, n: Lab.item) => min(v, n.p.y -. n.h /. 2.),
            infinity,
            ns,
          );
        let ns =
          List.map(
            (n: Lab.item) =>
              {
                ...n,
                p: {
                  x: n.p.x -. minx,
                  y:
                    n.p.y
                    -. miny
                    -. List.fold_left(
                         (v, (at, amount)) => n.p.y >= at ? v +. amount : v,
                         0.,
                         gaps,
                       ),
                },
              },
            ns,
          );
        let w =
          List.fold_left(
            (v, n: Lab.item) => max(v, n.p.x +. n.w /. 2.),
            0.,
            ns,
          );
        let h =
          List.fold_left(
            (v, n: Lab.item) => max(v, n.p.y +. n.h /. 2.),
            0.,
            ns,
          );
        (ns, w, h);
      },
      pieces,
    );
  let area =
    List.fold_left(
      (a, (_, w, h)) => a +. (w +. 60.) *. (h +. 60.),
      0.,
      blocks,
    );
  let target = max(650., sqrt(area *. 1.5));
  let after: Hashtbl.t(string, point) = Hashtbl.create(256);
  let _ =
    List.fold_left(
      ((x, y, rowh), (ns, w, h)) => {
        let (x, y, rowh) =
          x > 70. && x +. w > target
            ? (70., y +. rowh +. 70., 0.) : (x, y, rowh);
        List.iter(
          (n: Lab.item) =>
            Hashtbl.replace(
              after,
              n.key,
              Lab.{
                x: Lab.snap(n.p.x +. x),
                y: Lab.snap(n.p.y +. y),
              },
            ),
          ns,
        );
        (x +. w +. 70., y, max(rowh, h));
      },
      (70., 70., 0.),
      blocks,
    );
  let before: Hashtbl.t(string, point) = Hashtbl.create(256);
  List.iter((n: Lab.item) => Hashtbl.replace(before, n.key, n.p), units);
  List.map(
    (n: Lab.item) => {
      let k = root([], n);
      switch (Hashtbl.find_opt(before, k), Hashtbl.find_opt(after, k)) {
      | (Some(b), Some(a)) => {
          ...n,
          p: {
            x: n.p.x +. a.x -. b.x,
            y: n.p.y +. a.y -. b.y,
          },
        }
      | _ => n
      };
    },
    items,
  );
};

/* ---------- compact: the layered arrangement, packed ---------- */

/* An unnamed type used in one place (a record's field type, a function's
   only result) docks beside that place instead of taking a row of its own
   layer: the graph with those nodes marked as satellites. */
let dock_single_use = (g: CanvasGraph.t): CanvasGraph.t => {
  let node: Hashtbl.t(string, CanvasGraph.tynode) = Hashtbl.create(64);
  List.iter(
    (n: CanvasGraph.tynode) => Hashtbl.replace(node, n.key, n),
    g.nodes,
  );
  let uses: Hashtbl.t(string, list((string, bool))) = Hashtbl.create(64);
  let use = (k, u) =>
    Hashtbl.replace(
      uses,
      k,
      [u, ...Option.value(~default=[], Hashtbl.find_opt(uses, k))],
    );
  List.iter(
    (e: CanvasGraph.edge) =>
      if (e.e_src != e.dst) {
        use(e.e_src, (e.dst, false));
        use(e.dst, (e.e_src, true));
      },
    g.edges,
  );
  List.iter(
    (n: CanvasGraph.tynode) =>
      List.iter(
        p =>
          if (p != n.key) {
            use(p, (n.key, false));
          },
        List.sort_uniq(compare, n.parts @ n.deps),
      ),
    g.nodes,
  );
  let docked: Hashtbl.t(string, string) = Hashtbl.create(16);
  /* does following anchors from [k] come to [target]? */
  let rec leads_to = (steps, k, target) =>
    k == target
    || steps < 24
    && (
      switch (Hashtbl.find_opt(docked, k)) {
      | Some(a) => leads_to(steps + 1, a, target)
      | None =>
        switch (Hashtbl.find_opt(node, k)) {
        | Some({sat: Some((a, _)), _}) => leads_to(steps + 1, a, target)
        | _ => false
        }
      }
    );
  {
    ...g,
    nodes:
      List.map(
        (n: CanvasGraph.tynode) =>
          switch (n.sat, n.kind, Hashtbl.find_opt(uses, n.key)) {
          | (None, Derived | Ghost, Some([(other, is_result)]))
              when Hashtbl.mem(node, other) && !leads_to(0, other, n.key) =>
            Hashtbl.replace(docked, n.key, other);
            {
              ...n,
              sat: Some((other, is_result)),
            };
          | _ => n
          },
        g.nodes,
      ),
  };
};

let arrange = (g: CanvasGraph.t, items: list(Lab.item)): list(Lab.item) => {
  let (node_ord, _) = source_order(g);
  let parent: Hashtbl.t(string, string) = Hashtbl.create(64);
  let rec find = k =>
    switch (Hashtbl.find_opt(parent, k)) {
    | Some(p) when p != k =>
      let r = find(p);
      Hashtbl.replace(parent, k, r);
      r;
    | _ => k
    };
  let here: Hashtbl.t(string, Lab.item) = Hashtbl.create(64);
  List.iter((n: Lab.item) => Hashtbl.replace(here, n.key, n), items);
  let join = (a, b) =>
    if (Hashtbl.mem(here, a) && Hashtbl.mem(here, b)) {
      let ra = find(a)
      and rb = find(b);
      if (ra != rb) {
        Hashtbl.replace(parent, ra, rb);
      };
    };
  List.iter((e: CanvasGraph.edge) => join(e.e_src, e.dst), g.edges);
  List.iter(
    (n: CanvasGraph.tynode) => {
      List.iter(join(n.key), n.deps @ n.parts);
      switch (n.m_path) {
      | [root, ..._] => join(n.key, "{}@" ++ root)
      | [] => ()
      };
    },
    g.nodes,
  );
  List.iter((n: Lab.item) => Option.iter(join(n.key), n.anchor), items);
  let groups: Hashtbl.t(string, list(Lab.item)) = Hashtbl.create(16);
  List.iter(
    (n: Lab.item) => {
      let r = find(n.key);
      Hashtbl.replace(
        groups,
        r,
        [n, ...Option.value(~default=[], Hashtbl.find_opt(groups, r))],
      );
    },
    items,
  );
  let blocks =
    Hashtbl.fold(
      (r, ns, acc) => {
        let (x0, y0, x1, y1, first) =
          List.fold_left(
            ((x0, y0, x1, y1, first), n: Lab.item) =>
              (
                min(x0, n.p.x -. n.w /. 2.),
                min(y0, n.p.y -. n.h /. 2.),
                max(x1, n.p.x +. n.w /. 2.),
                max(y1, n.p.y +. n.h /. 2.),
                min(first, node_ord(n.key)),
              ),
            (infinity, infinity, neg_infinity, neg_infinity, max_int),
            ns,
          );
        [((first, r), x0, y0, x1 -. x0, y1 -. y0), ...acc];
      },
      groups,
      [],
    )
    |> List.sort(compare);
  let corners =
    shelves(
      ~aspect=aspect^,
      ~gap=42.,
      List.map((((_, r), _, _, w, h)) => (r, w, h), blocks),
    );
  let shift: Hashtbl.t(string, (float, float)) = Hashtbl.create(16);
  List.iter(
    (((_, r), x0, y0, _, _)) =>
      switch (List.find_opt(((id, _, _)) => id == r, corners)) {
      | Some((_, x, y)) => Hashtbl.replace(shift, r, (x -. x0, y -. y0))
      | None => ()
      },
    blocks,
  );
  List.map(
    (n: Lab.item) =>
      switch (Hashtbl.find_opt(shift, find(n.key))) {
      | Some((dx, dy)) => {
          ...n,
          p: {
            x: snap(n.p.x +. dx),
            y: snap(n.p.y +. dy),
          },
        }
      | None => n
      },
    items,
  );
};

/* ---------- ledger and clusters: a type and what is made of and from it ---------- */

let places = (k: string): bool => k == "ledger" || k == "clusters";

/* extents around a head's centre, and where its dependants sit */
type box = {
  l: float,
  r: float,
  u: float,
  d: float,
  at: list((string, float, float)),
};

let place =
    (~radius: string => float, kind: string, g: CanvasGraph.t)
    : list((string, point)) => {
  let (node_ord, edge_ord) = source_order(g);
  let node: Hashtbl.t(string, CanvasGraph.tynode) = Hashtbl.create(64);
  List.iter(
    (n: CanvasGraph.tynode) => Hashtbl.replace(node, n.key, n),
    g.nodes,
  );
  let is_former = (k: string) =>
    String.length(k) >= 3 && String.sub(k, 0, 3) == "{}@";
  /* everything that touches a node: the functions into and out of it
     (other end, whether the node is the result) and what it is part of */
  let touching: Hashtbl.t(string, list((string, bool))) =
    Hashtbl.create(64);
  let touch = (k, use) =>
    Hashtbl.replace(
      touching,
      k,
      [use, ...Option.value(~default=[], Hashtbl.find_opt(touching, k))],
    );
  List.iter(
    (e: CanvasGraph.edge) =>
      if (e.e_src != e.dst) {
        touch(e.e_src, (e.dst, false));
        touch(e.dst, (e.e_src, true));
      },
    g.edges,
  );
  List.iter(
    (n: CanvasGraph.tynode) =>
      List.iter(
        p =>
          if (p != n.key) {
            touch(p, (n.key, false));
          },
        List.sort_uniq(compare, n.parts @ n.deps),
      ),
    g.nodes,
  );
  /* a terminal hangs off its anchor; a tuple that includes a shared type
     hangs off the first one, on its output side; an unnamed type used in
     one place only hangs off that place */
  let host_of = (n: CanvasGraph.tynode): option((string, bool)) =>
    switch (n.sat) {
    | Some((a, out)) when a != n.key && Hashtbl.mem(node, a) =>
      Some((a, out))
    | Some(_) => None
    | None when is_former(n.key) => None
    | None =>
      /* the tuple's first named type, else its first shared part */
      let shared = (want: CanvasGraph.tynode => bool) =>
        List.find_opt(
          p =>
            p != n.key
            && (
              switch (Hashtbl.find_opt(node, p)) {
              | Some(m) => Option.map(fst, m.sat) != Some(n.key) && want(m)
              | None => false
              }
            ),
          n.parts,
        );
      let shared_part =
        n.kind != Product
          ? None
          : (
            switch (shared(m => m.kind == Alias)) {
            | Some(p) => Some(p)
            | None =>
              switch (shared(m => m.kind == Ghost)) {
              | Some(p) => Some(p)
              | None => shared(_ => true)
              }
            }
          );
      let own_terminal = other =>
        switch (Hashtbl.find_opt(node, other)) {
        | Some(m) => Option.map(fst, m.sat) == Some(n.key)
        | None => true
        };
      switch (shared_part, Hashtbl.find_opt(touching, n.key)) {
      | (Some(p), _) => Some((p, true))
      | (None, Some([(other, is_result)]))
          when n.kind != Alias && !own_terminal(other) =>
        Some((other, is_result))
      | _ => None
      };
    };
  let host: Hashtbl.t(string, (string, bool)) = Hashtbl.create(64);
  List.iter(
    (n: CanvasGraph.tynode) =>
      Option.iter(h => Hashtbl.replace(host, n.key, h), host_of(n)),
    g.nodes,
  );
  /* a chain that comes back on itself has no head: cut it */
  let rec head = (seen, k) =>
    switch (Hashtbl.find_opt(host, k)) {
    | Some((h, _)) when !List.mem(h, seen) && List.length(seen) < 24 =>
      head([k, ...seen], h)
    | Some(_) =>
      Hashtbl.remove(host, k);
      k;
    | None => k
    };
  let head_of: Hashtbl.t(string, string) = Hashtbl.create(64);
  List.iter(
    (n: CanvasGraph.tynode) =>
      Hashtbl.replace(head_of, n.key, head([], n.key)),
    g.nodes,
  );
  let kids: Hashtbl.t((string, bool), list(string)) = Hashtbl.create(64);
  /* the function a dependant belongs to, for its order and label room */
  let link: Hashtbl.t(string, (int, float)) = Hashtbl.create(64);
  List.iter(
    (e: CanvasGraph.edge) => {
      /* (the canvas reserves a label's room by its qualified name) */
      let chip = float_of_int(String.length(e.e_name)) *. 7.4 +. 24.;
      List.iter(
        k =>
          switch (Hashtbl.find_opt(link, k)) {
          | Some((o, w)) =>
            Hashtbl.replace(
              link,
              k,
              (min(o, edge_ord(e.e_name)), max(w, chip)),
            )
          | None => Hashtbl.replace(link, k, (edge_ord(e.e_name), chip))
          },
        [e.e_src, e.dst],
      );
    },
    g.edges,
  );
  let kid_ord = k =>
    switch (Hashtbl.find_opt(link, k)) {
    | Some((o, _)) => o
    | None => node_ord(k)
    };
  List.iter(
    (n: CanvasGraph.tynode) =>
      switch (Hashtbl.find_opt(host, n.key)) {
      | Some(side) =>
        Hashtbl.replace(
          kids,
          side,
          [
            n.key,
            ...Option.value(~default=[], Hashtbl.find_opt(kids, side)),
          ],
        )
      | None => ()
      },
    g.nodes,
  );
  let kids_of = (k, right) =>
    Option.value(~default=[], Hashtbl.find_opt(kids, (k, right)))
    |> List.map(c => (kid_ord(c), c))
    |> List.sort(compare)
    |> List.map(snd);
  let orbits: Hashtbl.t(string, int) = Hashtbl.create(8);
  List.iter(
    (e: CanvasGraph.edge) =>
      if (e.e_src == e.dst) {
        Hashtbl.replace(
          orbits,
          e.dst,
          1 + Option.value(~default=0, Hashtbl.find_opt(orbits, e.dst)),
        );
      },
    g.edges,
  );
  let own = (k: string) => {
    let rad = radius(k);
    let n = Hashtbl.find_opt(node, k);
    let text =
      switch (n) {
      | Some(n) when n.kind != Product => String.length(n.label)
      | _ => 0
      };
    let loops = Option.value(~default=0, Hashtbl.find_opt(orbits, k));
    /* a very long label overflows its place rather than widening it */
    let half = max(rad, min(70., float_of_int(text) *. 3.3)) +. 4.;
    let up =
      rad +. 4. +. (loops == 0 ? 0. : float_of_int(loops) *. 24. +. 40.);
    let down = rad +. (text == 0 ? 4. : 17.);
    (rad, half, up, down);
  };
  let chip = k =>
    switch (Hashtbl.find_opt(link, k)) {
    | Some((_, w)) => w
    | None => 0.
    };

  /* ledger: a head with what makes it in rows on its left and what is
     made from it in rows on its right, in source order */
  let rec rows = (depth: int, k: string): box => {
    let (rad, half, up, down) = own(k);
    let side = (right: bool) => {
      let cs = List.map(c => (c, rows(depth + 1, c)), kids_of(k, right));
      if (cs == []) {
        (0., 0., []);
      } else {
        let room = List.fold_left((s, (c, _)) => max(s, chip(c)), 0., cs);
        let inner =
          List.fold_left(
            (s, (_, b: box)) => max(s, right ? b.l : b.r),
            0.,
            cs,
          );
        /* the level run between the bend and the row's end holds the label */
        let bend =
          52. +. 5. *. float_of_int(min(6, (List.length(cs) + 1) / 2));
        let reach =
          snap(
            max(
              half +. 14. +. inner,
              rad +. (room == 0. ? 30. : bend +. room +. 24.) +. inner,
            ),
          );
        /* fields that are plain terminals share rows, a few abreast:
           a record of a dozen strings is not a dozen rows */
        let plain = ((c, b: box)) =>
          b.at == []
          && chip(c) == 0.
          && (
            switch (Hashtbl.find_opt(node, c)) {
            | Some(n) => n.kind == Builtin
            | None => false
            }
          );
        let (plains, others) = List.partition(plain, cs);
        let abreast =
          List.length(plains) >= 9 ? 3 : List.length(plains) >= 4 ? 2 : 1;
        let rec chunk = l =>
          switch (l) {
          | [] => []
          | _ =>
            let row = List.filteri((i, _) => i < abreast, l);
            [row, ...chunk(List.filteri((i, _) => i >= abreast, l))];
          };
        let groups = List.map(x => [x], others) @ chunk(plains);
        let stride = 50.;
        let above = row =>
          List.fold_left((s, (_, b: box)) => max(s, b.u), 0., row);
        let pitch = row =>
          Float.ceil(
            List.fold_left((s, (_, b: box)) => max(s, b.u +. b.d), 0., row)
            /. grid,
          )
          *. grid;
        let total = List.fold_left((s, row) => s +. pitch(row), 0., groups);
        let sx = right ? 1. : (-1.);
        /* the head is level with the middle of its first and last rows */
        let (first, last) =
          switch (groups, List.rev(groups)) {
          | ([f, ..._], [l, ..._]) => (
              above(f),
              total -. pitch(l) +. above(l),
            )
          | _ => (0., 0.)
          };
        let top = -. snap((first +. last) /. 2.);
        let (at, _, out) =
          List.fold_left(
            ((at, y, out), row) => {
              let cy = y +. above(row);
              let (at, out, _) =
                List.fold_left(
                  ((at, out, j), (c, b: box)) => {
                    let x = sx *. (reach +. float_of_int(j) *. stride);
                    (
                      at
                      @ [(c, x, cy)]
                      @ List.map(
                          ((k, x', y')) => (k, x +. x', y' +. cy),
                          b.at,
                        ),
                      max(out, abs_float(x) +. (right ? b.r : b.l)),
                      j + 1,
                    );
                  },
                  (at, out, 0),
                  row,
                );
              (at, y +. pitch(row), out);
            },
            ([], top, 0.),
            groups,
          );
        (out, max(-. top, total +. top), at);
      };
    };
    let (lo, lh, la) = side(false)
    and (ro, rh, ra) = side(true);
    {
      l: max(half, lo),
      r: max(half, ro),
      u: max(up, max(lh, rh)),
      d: max(down, max(lh, rh)),
      at: la @ ra,
    };
  };

  /* clusters: the same dependants on arcs around the head, what makes it
     to the left and what is made from it to the right */
  let flower = (k: string): box => {
    let (rad, half, up, down) = own(k);
    let side = (right: bool) => {
      let cs = List.map(c => (c, rows(1, c)), kids_of(k, right));
      let weight = (b: box) => max(1., (b.u +. b.d +. 6.) /. 40.);
      let total = List.fold_left((s, (_, b)) => s +. weight(b), 0., cs);
      let rings = List.length(cs) > 7 ? 2. : 1.;
      let span =
        min(
          2.9,
          max(List.length(cs) < 2 ? 0.1 : 1.3, total *. 0.5 /. rings),
        );
      let room = List.fold_left((s, (c, _)) => max(s, chip(c)), 0., cs);
      let rho = max(rad +. 40. +. room *. 0.8, total *. 40. /. rings /. span);
      let (at, _) =
        List.fold_left(
          ((at, (before, i)), (c, b: box)) => {
            let w = weight(b);
            let phi = -. span /. 2. +. span *. (before +. w /. 2.) /. total;
            let rho = rho +. (rings > 1. && i mod 2 == 1 ? 72. : 0.);
            let x = (right ? 1. : (-1.)) *. cos(phi) *. rho
            and y = sin(phi) *. rho;
            (
              at
              @ [(c, x, y, b)]
              @ List.map(
                  ((k, x', y')) =>
                    (
                      k,
                      x +. x',
                      y +. y',
                      {
                        ...b,
                        at: [],
                      },
                    ),
                  b.at,
                ),
              (before +. w, i + 1),
            );
          },
          ([], (0., 0)),
          cs,
        );
      at;
    };
    let at = side(false) @ side(true);
    let (l, r, u, d) =
      List.fold_left(
        ((l, r, u, d), (c, x, y, _)) => {
          let (_, half, up, down) = own(c);
          (
            max(l, half -. x),
            max(r, x +. half),
            max(u, up -. y),
            max(d, y +. down),
          );
        },
        (half, half, up, down),
        at,
      );
    {
      l,
      r,
      u,
      d,
      at: List.map(((c, x, y, _)) => (c, x, y), at),
    };
  };

  let heads =
    List.filter(
      (n: CanvasGraph.tynode) => !Hashtbl.mem(host, n.key),
      g.nodes,
    );
  let boxes: Hashtbl.t(string, box) = Hashtbl.create(32);
  List.iter(
    (n: CanvasGraph.tynode) =>
      Hashtbl.replace(
        boxes,
        n.key,
        kind == "clusters" ? flower(n.key) : rows(0, n.key),
      ),
    heads,
  );
  /* columns read left to right: a head sits after the heads it is made
     from (a cycle is cut where source order meets it again) */
  let feeds: Hashtbl.t(string, list(string)) = Hashtbl.create(32);
  let feed = (a, b) =>
    switch (Hashtbl.find_opt(head_of, a), Hashtbl.find_opt(head_of, b)) {
    | (Some(ha), Some(hb)) when ha != hb =>
      let l = Option.value(~default=[], Hashtbl.find_opt(feeds, hb));
      if (!List.mem(ha, l)) {
        Hashtbl.replace(feeds, hb, [ha, ...l]);
      };
    | _ => ()
    };
  List.iter((e: CanvasGraph.edge) => feed(e.e_src, e.dst), g.edges);
  List.iter(
    (n: CanvasGraph.tynode) => List.iter(d => feed(d, n.key), n.deps),
    g.nodes,
  );
  let tier: Hashtbl.t(string, int) = Hashtbl.create(32);
  let rec tier_of = (stack, k) =>
    switch (Hashtbl.find_opt(tier, k)) {
    | Some(t) => t
    | None =>
      let t =
        List.fold_left(
          (t, f) =>
            List.mem(f, stack) ? t : max(t, 1 + tier_of([k, ...stack], f)),
          0,
          Option.value(~default=[], Hashtbl.find_opt(feeds, k)),
        );
      Hashtbl.replace(tier, k, t);
      t;
    };
  let sorted =
    List.map((n: CanvasGraph.tynode) => (node_ord(n.key), n), heads)
    |> List.sort(((a, _), (b, _)) => compare(a, b))
    |> List.map(((o, n: CanvasGraph.tynode)) => (tier_of([], n.key), o, n));
  /* a module's members stay together, where its first one falls */
  let group = (n: CanvasGraph.tynode) =>
    switch (n.m_path) {
    | [root, ..._] => root
    | [] => ""
    };
  let group_at: Hashtbl.t(string, (int, int)) = Hashtbl.create(8);
  List.iter(
    ((t, o, n)) =>
      if (group(n) != "") {
        switch (Hashtbl.find_opt(group_at, group(n))) {
        | Some(at) when at <= (t, o) => ()
        | _ => Hashtbl.replace(group_at, group(n), (t, o))
        };
      },
    sorted,
  );
  let sorted =
    List.map(
      ((t, o, n: CanvasGraph.tynode)) =>
        (
          Option.value(
            ~default=(t, o),
            Hashtbl.find_opt(group_at, group(n)),
          ),
          group(n),
          t,
          o,
          n.key,
        ),
      sorted,
    )
    |> List.sort(compare);
  let corners =
    columns(
      ~aspect=aspect^,
      ~gap=kind == "clusters" ? 28. : 42.,
      List.map(
        ((_, _, _, _, k)) => {
          let b = Hashtbl.find(boxes, k);
          (k, b.l +. b.r, b.u +. b.d);
        },
        sorted,
      ),
    );
  List.concat_map(
    ((k, x, y)) => {
      let b = Hashtbl.find(boxes, k);
      let cx = snap(x +. b.l)
      and cy = snap(y +. b.u);
      [
        (
          k,
          Lab.{
            x: cx,
            y: cy,
          },
        ),
        ...List.map(
             ((c, dx, dy)) =>
               (
                 c,
                 Lab.{
                   x: snap(cx +. dx),
                   y: snap(cy +. dy),
                 },
               ),
             b.at,
           ),
      ];
    },
    corners,
  );
};

/* ---------- edge styles ---------- */

/* what an edge is drawn as: a polyline (rounded when drawn), or a curve
   by its two control points; and where its label would like to sit */
type wire = {
  points: list(point),
  ctrl: option((point, point)),
  label: point,
};

let routes = (): bool => Lab.wires^ == "metro" || Lab.wires^ == "straight";

type end_side =
  | Right
  | Left
  | Below
  | Above;

/* metro: every edge runs level, turns once on a diagonal (or, where it is
   too steep, down a vertical between two diagonals) and runs level again.
   Edges that share a node's side leave it side by side, and turn in the
   order that keeps them from crossing each other. */
let metro =
    (
      ~nodes: list((string, point, float)),
      ~room: string => float,
      edges: list((string, string, string)),
    )
    : list((string, wire)) => {
  let at: Hashtbl.t(string, (point, float)) = Hashtbl.create(64);
  List.iter(((k, p, r)) => Hashtbl.replace(at, k, (p, r)), nodes);
  let plan =
    List.filter_map(
      ((name, a, b)) =>
        switch (Hashtbl.find_opt(at, a), Hashtbl.find_opt(at, b)) {
        | (Some((pa, ra)), Some((pb, rb))) =>
          let dx = pb.x -. pa.x
          and dy = pb.y -. pa.y;
          let level =
            abs_float(dx) >= ra
            +. rb
            +. 30.
            || abs_float(dx) >= abs_float(dy);
          let (sa, sb) =
            level
              ? dx >= 0. ? (Right, Left) : (Left, Right)
              : dy >= 0. ? (Below, Above) : (Above, Below);
          Some((name, a, b, pa, ra, pb, rb, level, sa, sb));
        | _ => None
        },
      edges,
    );
  /* who shares a side of a node, in the order of where they come from */
  let sides:
    Hashtbl.t((string, end_side), list(((float, float, string), string))) =
    Hashtbl.create(64);
  let join = (k, side, other: point, name) => {
    let key =
      switch (side) {
      | Right
      | Left => (other.y, other.x, name)
      | Below
      | Above => (other.x, other.y, name)
      };
    Hashtbl.replace(
      sides,
      (k, side),
      [
        (key, name),
        ...Option.value(~default=[], Hashtbl.find_opt(sides, (k, side))),
      ],
    );
  };
  List.iter(
    ((name, a, b, pa, _, pb, _, _, sa, sb)) => {
      join(a, sa, pb, name);
      join(b, sb, pa, name);
    },
    plan,
  );
  let slot: Hashtbl.t((string, end_side, string), (int, int)) =
    Hashtbl.create(64);
  Hashtbl.iter(
    ((k, side), l) => {
      let l = List.sort(compare, l);
      let n = List.length(l);
      List.iteri(
        (i, (_, name)) => Hashtbl.replace(slot, (k, side, name), (i, n)),
        l,
      );
    },
    sides,
  );
  let port = (p: point, r: float, side, (i, n)): point => {
    let gap = min(5., 1.5 *. r /. float_of_int(max(1, n - 1)));
    let o = (float_of_int(i) -. float_of_int(n - 1) /. 2.) *. gap;
    let c = sqrt(max(0., r *. r -. o *. o));
    switch (side) {
    | Right => {
        x: p.x +. c,
        y: p.y +. o,
      }
    | Left => {
        x: p.x -. c,
        y: p.y +. o,
      }
    | Below => {
        x: p.x +. o,
        y: p.y +. c,
      }
    | Above => {
        x: p.x +. o,
        y: p.y -. c,
      }
    };
  };
  let ends =
    List.map(
      ((name, a, b, pa, ra, pb, rb, level, sa, sb)) => {
        let (ia, na) = Hashtbl.find(slot, (a, sa, name))
        and (ib, nb) = Hashtbl.find(slot, (b, sb, name));
        let s = port(pa, ra, sa, (ia, na))
        and d = port(pb, rb, sb, (ib, nb));
        /* the busier end is where the edge turns */
        let from_src = na >= nb;
        (name, s, d, level, from_src, from_src ? (a, sa, ia) : (b, sb, ib));
      },
      plan,
    );
  /* at a shared side, an edge that turns one way gives way to those that
     go further the same way: they turn first */
  let across = (level, p: point) => level ? p.y : p.x;
  let rise = ((_, s, d, level, from_src, _)) =>
    from_src
      ? across(level, d) -. across(level, s)
      : across(level, s) -. across(level, d);
  let turners: Hashtbl.t((string, end_side), list((int, float))) =
    Hashtbl.create(64);
  List.iter(
    ((_, _, _, _, _, (k, side, i)) as e) =>
      Hashtbl.replace(
        turners,
        (k, side),
        [
          (i, rise(e)),
          ...Option.value(
               ~default=[],
               Hashtbl.find_opt(turners, (k, side)),
             ),
        ],
      ),
    ends,
  );
  List.map(
    ((name, s, d, level, from_src, (k, side, i)) as e) => {
      let rise = rise(e);
      let peers =
        Option.value(~default=[], Hashtbl.find_opt(turners, (k, side)));
      let lane =
        List.length(
          List.filter(
            ((j, r)) =>
              rise > 1.5
              && r > 1.5
              && j > i
              || rise < (-1.5)
              && r < (-1.5)
              && j < i,
            peers,
          ),
        );
      let turning =
        List.length(
          List.filter(((_, r)) => rise > 0. ? r > 1.5 : r < (-1.5), peers),
        );
      /* a frame in which the turning end is at the left and the edge
         runs to the right */
      let (h, o) = from_src ? (s, d) : (d, s);
      let flip = (level ? o.x -. h.x : o.y -. h.y) >= 0. ? 1. : (-1.);
      let into = (p: point): point =>
        level
          ? {
            x: flip *. p.x,
            y: p.y,
          }
          : {
            x: flip *. p.y,
            y: p.x,
          };
      let back = (p: point): point =>
        level
          ? {
            x: flip *. p.x,
            y: p.y,
          }
          : {
            x: p.y,
            y: flip *. p.x,
          };
      let h' = into(h)
      and o' = into(o);
      let span = o'.x -. h'.x;
      let up = abs_float(rise);
      let sg = rise >= 0. ? 1. : (-1.);
      let between =
        min(5., max(1.5, span *. 0.3 /. float_of_int(max(1, turning))));
      let stub =
        min(12. +. float_of_int(lane) *. between, max(6., span *. 0.6));
      let pt = (x, y): point => {
        x,
        y,
      };
      let line =
        if (up < 1.5 || span < 8.) {
          [h', o'];
        } else if (up <= span
                   -. stub
                   -. 12.
                   && (up <= 28. || span -. stub -. up -. 12. >= room(name))) {
          [h', pt(h'.x +. stub, h'.y), pt(h'.x +. stub +. up, o'.y), o'];
        } else {
          let q = min(min(14., (span -. stub -. 8.) /. 2.), up /. 2.);
          let x1 = h'.x +. min(stub, max(4., span -. 4.));
          q < 3.
            ? [h', pt(x1, h'.y), pt(x1, o'.y), o']
            : [
              h',
              pt(x1, h'.y),
              pt(x1 +. q, h'.y +. sg *. q),
              pt(x1 +. q, o'.y -. sg *. q),
              pt(x1 +. 2. *. q, o'.y),
              o',
            ];
        };
      let line = List.map(back, line);
      let points = from_src ? line : List.rev(line);
      /* the label rides the longest level run */
      let (best, len) =
        List.fold_left(
          ((best, len), (a: point, b: point)) =>
            abs_float(a.y -. b.y) < 0.5 && abs_float(a.x -. b.x) > len
              ? (
                Some(
                  Lab.{
                    x: (a.x +. b.x) /. 2.,
                    y: a.y,
                  },
                ),
                abs_float(a.x -. b.x),
              )
              : (best, len),
          (None, 0.),
          Lab.segments(points),
        );
      let label =
        switch (best) {
        | Some(p) when len > 40. => p
        | _ => Lab.along(points, 0.5)
        };
      (
        name,
        {
          points,
          ctrl: None,
          label,
        },
      );
    },
    ends,
  );
};

/* straight: a chord from rim to rim. Edges between the same two nodes (and
   an edge beside a "made of" link) bow apart. Around a busy node the
   labels sit toward the far end, where the chords have spread. */
let straight =
    (
      ~nodes: list((string, point, float)),
      ~links: list((string, string)),
      edges: list((string, string, string)),
    )
    : list((string, wire)) => {
  let at: Hashtbl.t(string, (point, float)) = Hashtbl.create(64);
  List.iter(((k, p, r)) => Hashtbl.replace(at, k, (p, r)), nodes);
  let pair = (a, b) => a <= b ? (a, b) : (b, a);
  let between: Hashtbl.t((string, string), list(string)) =
    Hashtbl.create(64);
  List.iter(
    ((a, b)) =>
      if (!Hashtbl.mem(between, pair(a, b))) {
        Hashtbl.replace(between, pair(a, b), [""]);
      },
    links,
  );
  let degree: Hashtbl.t(string, int) = Hashtbl.create(64);
  List.iter(
    ((name, a, b)) => {
      Hashtbl.replace(
        between,
        pair(a, b),
        Option.value(~default=[], Hashtbl.find_opt(between, pair(a, b)))
        @ [name],
      );
      List.iter(
        k =>
          Hashtbl.replace(
            degree,
            k,
            1 + Option.value(~default=0, Hashtbl.find_opt(degree, k)),
          ),
        [a, b],
      );
    },
    edges,
  );
  let deg = k => Option.value(~default=0, Hashtbl.find_opt(degree, k));
  List.filter_map(
    ((name, a, b)) =>
      switch (Hashtbl.find_opt(at, a), Hashtbl.find_opt(at, b)) {
      | (Some((pa, ra)), Some((pb, rb))) =>
        let unit = (p: point, q: point): point => {
          let l = max(1., Lab.distance(p, q));
          {
            x: (q.x -. p.x) /. l,
            y: (q.y -. p.y) /. l,
          };
        };
        let group = Hashtbl.find(between, pair(a, b));
        let m = List.length(group);
        let rec index = (i, l) =>
          switch (l) {
          | [x, ..._] when x == name => i
          | [_, ...rest] => index(i + 1, rest)
          | [] => 0
          };
        let bow =
          (float_of_int(index(0, group)) -. float_of_int(m - 1) /. 2.)
          *. 22.;
        /* the bow's side is the pair's, not the edge's direction */
        let (ka, _) = pair(a, b);
        let u = ka == a ? unit(pa, pb) : unit(pb, pa);
        let c: point = {
          x: (pa.x +. pb.x) /. 2. -. u.y *. bow *. 2.,
          y: (pa.y +. pb.y) /. 2. +. u.x *. bow *. 2.,
        };
        let ua = unit(pa, c)
        and ub = unit(pb, c);
        let s: point = {
          x: pa.x +. ua.x *. ra,
          y: pa.y +. ua.y *. ra,
        }
        and d: point = {
          x: pb.x +. ub.x *. rb,
          y: pb.y +. ub.y *. rb,
        };
        let third = (p: point, q: point): point => {
          x: p.x +. (q.x -. p.x) *. 2. /. 3.,
          y: p.y +. (q.y -. p.y) *. 2. /. 3.,
        };
        let t =
          deg(a) >= 4 && deg(a) > deg(b)
            ? 0.66 : deg(b) >= 4 && deg(b) > deg(a) ? 0.34 : 0.5;
        let v = 1. -. t;
        Some((
          name,
          {
            points: [],
            ctrl: Some((third(s, c), third(d, c))),
            label: {
              x: v *. v *. s.x +. 2. *. v *. t *. c.x +. t *. t *. d.x,
              y: v *. v *. s.y +. 2. *. v *. t *. c.y +. t *. t *. d.y,
            },
          },
        ));
      | _ => None
      },
    edges,
  );
};

let route = (~nodes, ~links, ~room, edges) =>
  Lab.wires^ == "metro"
    ? metro(~nodes, ~room, edges) : straight(~nodes, ~links, edges);

/* a polyline with its corners rounded (the lab's `path`, wider) */
let path = (points: list(point)): string =>
  if (Lab.wires^ != "metro") {
    Lab.path(points);
  } else {
    switch (points) {
    | [] => ""
    | [first, ...rest] =>
      let fmt = (p: point) => Printf.sprintf("%.1f,%.1f", p.x, p.y);
      let rec draw = (prev, ps) =>
        switch (ps) {
        | [p, next, ...tail] =>
          let back = Lab.distance(prev, p)
          and ahead = Lab.distance(p, next);
          let r = min(10., min(back /. 2., ahead /. 2.));
          let inset = (q: point, d) =>
            d < 0.001
              ? p
              : Lab.{
                  x: p.x +. (q.x -. p.x) *. r /. d,
                  y: p.y +. (q.y -. p.y) *. r /. d,
                };
          " L "
          ++ fmt(inset(prev, back))
          ++ " Q "
          ++ fmt(p)
          ++ " "
          ++ fmt(inset(next, ahead))
          ++ draw(p, [next, ...tail]);
        | [last] => " L " ++ fmt(last)
        | [] => ""
        };
      "M " ++ fmt(first) ++ draw(first, rest);
    };
  };

