/* CanvasLayout — deterministic layered layout for CanvasGraph.
   Grid nodes (aliases, derived, ghosts, and feed-forward products) get
   left-to-right layers by type-dependency; satellite nodes dock beside an
   anchor: per-use builtin terminals beside their consumer, and "loop"
   products — tuple inputs that feed an edge back into one of their own
   components (the MVU update shape) — beside that component, so feedback
   loops stay compact instead of stretching the whole graph. Edges are
   horizontal-tangent cubic béziers; single-argument endofunctions render
   as orbits. Motion between layouts is smoothed by the id-keyed FLIP in
   Animation.re, so this recomputes from scratch. */

type pos = {
  x: float,
  y: float,
};

type node_layout = {
  node: CanvasGraph.tynode,
  p: pos,
  r: float,
};

type edge_layout = {
  edge: CanvasGraph.edge,
  src_p: pos,
  dst_p: pos,
  c1: pos, /* bézier control points (horizontal tangents) */
  c2: pos,
  wire: list(pos), /* optional orthogonal route, including rim endpoints */
  endo: bool, /* src == dst: render as orbit */
  orbit_rank: int, /* stacking index among orbits on the same node */
  label_p: pos,
  /* the label's natural anchor on its curve; when separation pushed the
     chip away, the view draws a leader line back to this point */
  label_anchor: pos,
  /* the chip sits ON the wire (centered on the curve, masking it) rather
     than above it: only when the arrow is long enough to show its head
     and a stretch of line on both sides */
  on_wire: bool,
};

type value_layout = {
  value: CanvasGraph.value,
  p: pos,
  vr: float /* orbit ring radius */
};

type t = {
  nodes: list(node_layout),
  edges: list(edge_layout),
  values: list(value_layout),
  /* (from_key, to_key, from_rim, to_rim) — keys let the drag follower
     re-anchor these without re-deriving rim geometry */
  formations: list((string, string, pos, pos)), /* component → product */
  dep_links: list((string, string, pos, pos)), /* alias-body dep hints */
  width: float,
  height: float,
  /* the normalization translation: final = pre-norm + origin. Click
     placements convert final coords back to the pre-norm frame with it. */
  origin: pos,
};

let margin = 70.;

module Lab = CanvasLayoutExperiments;
/* Expanded cards for the current render, set by CanvasSidebar before all
   layout calls, including the automatic layout before manual placement. */
let card_extents: ref(list((string, (float, float)))) = ref([]);
let to_lab = (p: pos): Lab.point => {
  x: p.x,
  y: p.y,
};
let from_lab = (p: Lab.point): pos => {
  x: p.x,
  y: p.y,
};
let wire_at = (ps, t) => Lab.along(List.map(to_lab, ps), t) |> from_lab;
let edge_path = (~pull=0., el: edge_layout) =>
  if (el.wire != []) {
    let reversed = List.rev(el.wire);
    let points =
      switch (reversed) {
      | [last, prev, ...rest] =>
        let d = max(1., Float.hypot(last.x -. prev.x, last.y -. prev.y));
        List.rev([
          {
            x: last.x +. (prev.x -. last.x) *. pull /. d,
            y: last.y +. (prev.y -. last.y) *. pull /. d,
          },
          prev,
          ...rest,
        ]);
      | _ => el.wire
      };
    /* PORTOLAN: the corner rounding is the edge style's */
    CanvasOptions.path(List.map(to_lab, points));
  } else {
    let d =
      max(1., Float.hypot(el.dst_p.x -. el.c2.x, el.dst_p.y -. el.c2.y));
    Printf.sprintf(
      "M %.1f,%.1f C %.1f,%.1f %.1f,%.1f %.1f,%.1f",
      el.src_p.x,
      el.src_p.y,
      el.c1.x,
      el.c1.y,
      el.c2.x,
      el.c2.y,
      el.dst_p.x +. (el.c2.x -. el.dst_p.x) *. pull /. d,
      el.dst_p.y +. (el.c2.y -. el.dst_p.y) *. pull /. d,
    );
  };
let obstacles = (~cards=[], nodes) =>
  List.map(
    (n: node_layout) => {
      let (w, h) =
        Option.value(
          ~default=(2. *. n.r +. 24., 2. *. n.r +. 34.),
          List.assoc_opt(n.node.key, cards),
        );
      Lab.{
        key: n.node.key,
        p: to_lab(n.p),
        w,
        h,
        anchor: Option.map(fst, n.node.sat),
      };
    },
    nodes,
  );
let placement_cache = ref(("", [], [], []));
/* dot-grid pitch (kept in sync with canvas.css --canvas-grid) */
let grid = 14.;
let snap = (v: float): float => Float.round(v /. grid) *. grid;

let base_radius = 20.;

let node_radius = (~fan: int, n: CanvasGraph.tynode): float => {
  let ctr_bump = float_of_int(min(List.length(n.ctrs), 4)) *. 2.
  and fan_bump = float_of_int(min(fan, 6)) *. 2.5;
  switch (n.kind) {
  | Builtin => 11.
  | Ghost => 14.
  /* hub [T] nodes grow with traffic so their many short edges get
     length to read (orbits and dock rings scale off the radius) */
  | Derived => 15. +. fan_bump
  | Product => 10.
  | Alias => base_radius +. ctr_bump +. fan_bump
  };
};

let strip_brackets = (k: string): option(string) =>
  if (String.length(k) >= 2 && k.[0] == '[') {
    Some(String.sub(k, 1, String.length(k) - 2));
  } else {
    None;
  };

let cubic_mid = (s: pos, c1: pos, c2: pos, d: pos): pos => {
  x: 0.125 *. s.x +. 0.375 *. c1.x +. 0.375 *. c2.x +. 0.125 *. d.x,
  y: 0.125 *. s.y +. 0.375 *. c1.y +. 0.375 *. c2.y +. 0.125 *. d.y,
};

/* unit vector a→b */
let norm = (a: pos, b: pos): pos => {
  let dx = b.x -. a.x
  and dy = b.y -. a.y;
  let l = max(1., sqrt(dx *. dx +. dy *. dy));
  {
    x: dx /. l,
    y: dy /. l,
  };
};

/* the point [d] along the way from [a] toward [b] */
let offset_along = (a: pos, b: pos, d: float): pos => {
  let u = norm(a, b);
  {
    x: a.x +. u.x *. d,
    y: a.y +. u.y *. d,
  };
};

/* How a non-grid node docks to its anchor. */
type dock =
  | DockIn /* builtin terminal on the input side */
  | DockOut /* builtin terminal on the output side */
  | DockLoop /* loop product: above-left of its result component */
  | DockDeriv /* derived [T]: beneath its element type */
  | DockMember; /* module-internal node clustered at its former */

/* ~x_scale stretches grid columns so a small graph fills the available
   panel width; dock offsets stay fixed (satellite distances shouldn't
   stretch), and all edge/rim geometry derives from final positions.
   ~offsets are user drag deltas keyed by node key, applied after auto
   placement (edges/rims then derive from the moved positions, and the
   final normalization translates deltas and auto positions together). */
/* ---- routing for links and arrows ----
   Lines are STRAIGHT. A chain laid in one row (`Int -> Pos -> World`) would
   put the middle node on the long link, so `declutter` below moves such a
   node off the chord at layout time; while a node is being dragged a line
   may pass under it until the release re-lays the graph. (The earlier
   router bent a link around whatever it crossed, and re-bent it on every
   drag frame as the crossings changed: the "waves".) Pure, so the drag
   follower can re-route from positions alone. */
let route_link =
    (
      ~nodes: list(node_layout),
      ~from_key: string,
      ~to_key: string,
      a: pos,
      b: pos,
    )
    : (pos, pos) => {
  let c = (t: float) => {
    x: a.x +. (b.x -. a.x) *. t,
    y: a.y +. (b.y -. a.y) *. t,
  };
  let local =
    List.exists(
      (n: node_layout) =>
        n.node.key == from_key
        && Option.map(fst, n.node.sat) == Some(to_key)
        || n.node.key == to_key
        && Option.map(fst, n.node.sat) == Some(from_key),
      nodes,
    );
  local && abs_float(b.x -. a.x) > 24.
    ? (
      {
        x: a.x +. (b.x -. a.x) *. 0.45,
        y: a.y,
      },
      {
        x: b.x -. (b.x -. a.x) *. 0.45,
        y: b.y,
      },
    )
    : (c(0.33), c(0.67));
};

let link_d = (a: pos, c1: pos, c2: pos, b: pos): string =>
  Printf.sprintf(
    "M %.1f,%.1f C %.1f,%.1f %.1f,%.1f %.1f,%.1f",
    a.x,
    a.y,
    c1.x,
    c1.y,
    c2.x,
    c2.y,
    b.x,
    b.y,
  );

let relation_path = (~nodes, ~from_key, ~to_key, a, b) => {
  let local =
    List.exists(
      (n: node_layout) =>
        n.node.key == from_key
        && Option.map(fst, n.node.sat) == Some(to_key)
        || n.node.key == to_key
        && Option.map(fst, n.node.sat) == Some(from_key),
      nodes,
    );
  if (Lab.wires^ == "circuit" && !local) {
    Lab.route(
      ~obstacles=obstacles(nodes),
      ~src=from_key,
      ~dst=to_key,
      to_lab(a),
      to_lab(b),
    )
    |> Lab.path;
  } else {
    let (c1, c2) = route_link(~nodes, ~from_key, ~to_key, a, b);
    link_d(a, c1, c2, b);
  };
};

/* ---- declutter: nodes step OFF the straight lines between other nodes.
   For every link/arrow chord, a node the chord would run through (not its
   ends) is nudged perpendicular to the chord by the clearance it lacks;
   exactly collinear nodes alternate sides. A few rounds settle chains.
   Fixed nodes (pinned or dragged by the user) stay; a docked satellite
   rides its anchor. */
let declutter =
    (
      ~chords: list((string, string)),
      ~fixed: list(string),
      ~radius_of: string => float,
      nodes: list(node_layout),
    )
    : list(node_layout) => {
  let clear = 12.;
  let tbl: Hashtbl.t(string, pos) = Hashtbl.create(32);
  List.iter(
    (nl: node_layout) => Hashtbl.replace(tbl, nl.node.key, nl.p),
    nodes,
  );
  let anchor_of = (nl: node_layout): option(string) =>
    switch (nl.node.sat) {
    | Some((a, _)) => Some(a)
    | None => None
    };
  let movable = (nl: node_layout): bool =>
    !List.mem(nl.node.key, fixed) && anchor_of(nl) == None;
  let parity: Hashtbl.t(string, float) = Hashtbl.create(32);
  List.iteri(
    (i, nl: node_layout) =>
      Hashtbl.replace(parity, nl.node.key, i mod 2 == 0 ? 1. : (-1.)),
    nodes,
  );
  for (_ in 1 to 6) {
    let delta: Hashtbl.t(string, (float, float)) = Hashtbl.create(16);
    List.iter(
      ((ka, kb)) =>
        switch (Hashtbl.find_opt(tbl, ka), Hashtbl.find_opt(tbl, kb)) {
        | (Some(a), Some(b)) =>
          let dx = b.x -. a.x
          and dy = b.y -. a.y;
          let len = sqrt(dx *. dx +. dy *. dy);
          if (len > 1.) {
            let (ux, uy) = (dx /. len, dy /. len);
            let (nx, ny) = (-. uy, ux);
            List.iter(
              (nl: node_layout) =>
                if (nl.node.key != ka && nl.node.key != kb && movable(nl)) {
                  let p = Hashtbl.find(tbl, nl.node.key);
                  let r = radius_of(nl.node.key);
                  let px = p.x -. a.x
                  and py = p.y -. a.y;
                  let along = px *. ux +. py *. uy;
                  let side = px *. nx +. py *. ny;
                  let need = r +. clear;
                  if (along > r && along < len -. r && abs_float(side) < need) {
                    let dir =
                      abs_float(side) < 0.5
                        ? Hashtbl.find(parity, nl.node.key)
                        : side >= 0. ? 1. : (-1.);
                    let m = need -. abs_float(side);
                    let (ox, oy) =
                      Option.value(
                        ~default=(0., 0.),
                        Hashtbl.find_opt(delta, nl.node.key),
                      );
                    Hashtbl.replace(
                      delta,
                      nl.node.key,
                      (ox +. dir *. nx *. m, oy +. dir *. ny *. m),
                    );
                  };
                },
              nodes,
            );
          };
        | _ => ()
        },
      chords,
    );
    Hashtbl.iter(
      (k, (ox, oy)) => {
        let p = Hashtbl.find(tbl, k);
        Hashtbl.replace(
          tbl,
          k,
          {
            x: p.x +. ox,
            y: p.y +. oy,
          },
        );
      },
      delta,
    );
    List.iter(
      (nl: node_layout) =>
        switch (anchor_of(nl)) {
        | Some(a) =>
          switch (Hashtbl.find_opt(delta, a)) {
          | Some((ox, oy)) =>
            let p = Hashtbl.find(tbl, nl.node.key);
            Hashtbl.replace(
              tbl,
              nl.node.key,
              {
                x: p.x +. ox,
                y: p.y +. oy,
              },
            );
          | None => ()
          }
        | None => ()
        },
      nodes,
    );
  };
  List.map(
    (nl: node_layout) =>
      {
        ...nl,
        p: Hashtbl.find(tbl, nl.node.key),
      },
    nodes,
  );
};

/* A docked terminal can lie directly on its anchor's other relationship.
   Move that terminal off the shared chord before applying manual positions;
   the user's later drag remains rigid and never relocates bystanders. */
let separate_docked_chords =
    (~chords: list((string, string)), nodes: list(node_layout)) => {
  let positions = Hashtbl.create(32);
  List.iter(
    (nl: node_layout) => Hashtbl.replace(positions, nl.node.key, nl.p),
    nodes,
  );
  List.map(
    (nl: node_layout) => {
      let p =
        List.fold_left(
          (p: pos, (ka, kb)) =>
            switch (
              nl.node.kind,
              nl.node.sat,
              Hashtbl.find_opt(positions, ka),
              Hashtbl.find_opt(positions, kb),
            ) {
            | (Builtin, Some((anchor, _)), Some(a), Some(b))
                when
                  nl.node.key != ka
                  && nl.node.key != kb
                  && (anchor == ka || anchor == kb) =>
              let length = sqrt((b.x -. a.x) ** 2. +. (b.y -. a.y) ** 2.);
              let u = norm(a, b);
              let along = (p.x -. a.x) *. u.x +. (p.y -. a.y) *. u.y;
              let side = (p.y -. a.y) *. u.x -. (p.x -. a.x) *. u.y;
              if (length > 1.
                  && along > 0.
                  && along < length
                  && abs_float(side) < nl.r
                  +. 12.) {
                let candidate = dir => {
                  x: p.x -. u.y *. dir *. 42.,
                  y: p.y +. u.x *. dir *. 42.,
                };
                let clearance = (q: pos) =>
                  List.fold_left(
                    (score, other: node_layout) =>
                      other.node.key == nl.node.key
                        ? score
                        : min(
                            score,
                            sqrt(
                              (q.x -. other.p.x)
                              ** 2.
                              +. (q.y -. other.p.y)
                              ** 2.,
                            )
                            -. other.r,
                          ),
                    max_float,
                    nodes,
                  );
                let above = candidate(-1.)
                and below = candidate(1.);
                clearance(above) >= clearance(below) ? above : below;
              } else {
                p;
              };
            | _ => p
            },
          nl.p,
          chords,
        );
      {
        ...nl,
        p,
      };
    },
    nodes,
  );
};

/* PORTOLAN: the two passes above, to the same result, for large graphs.
   Upstream's visit every node for every chord and look each one up by key
   (six rounds of it in declutter): about three seconds of a 1800-node
   layout. These keep the nodes in arrays, and give a terminal only the
   chords that touch its anchor. The originals are kept above, unused, so
   the copy still reads against Hazel's. */
let declutter =
    (
      ~chords: list((string, string)),
      ~fixed: list(string),
      ~radius_of: string => float,
      nodes: list(node_layout),
    )
    : list(node_layout) => {
  /* (named so the unused original is not a compile error) */
  ignore(declutter);
  let clear = 12.;
  let ns = Array.of_list(nodes);
  let n = Array.length(ns);
  let index: Hashtbl.t(string, int) = Hashtbl.create(64);
  Array.iteri(
    (i, nl: node_layout) => Hashtbl.replace(index, nl.node.key, i),
    ns,
  );
  let at = k =>
    switch (Hashtbl.find_opt(index, k)) {
    | Some(i) => i
    | None => (-1)
    };
  /* a key that occurs twice is one place, as in upstream's table */
  let slot = Array.map((nl: node_layout) => at(nl.node.key), ns);
  let xs = Array.map((nl: node_layout) => nl.p.x, ns);
  let ys = Array.map((nl: node_layout) => nl.p.y, ns);
  Array.iteri(
    (i, s) => {
      xs[s] = ns[i].p.x;
      ys[s] = ns[i].p.y;
    },
    slot,
  );
  let anchor =
    Array.map(
      (nl: node_layout) =>
        switch (nl.node.sat) {
        | Some((a, _)) => Some(a)
        | None => None
        },
      ns,
    );
  let movable =
    Array.mapi(
      (i, nl: node_layout) =>
        !List.mem(nl.node.key, fixed) && anchor[i] == None,
      ns,
    );
  let radius = Array.map((nl: node_layout) => radius_of(nl.node.key), ns);
  let parity = Array.make(n, 1.);
  Array.iteri((i, s) => parity[s] = i mod 2 == 0 ? 1. : (-1.), slot);
  let ends = List.map(((ka, kb)) => (at(ka), at(kb)), chords);
  for (_ in 1 to 6) {
    let ox = Array.make(n, 0.);
    let oy = Array.make(n, 0.);
    let moved = Array.make(n, false);
    List.iter(
      ((ia, ib)) =>
        if (ia >= 0 && ib >= 0) {
          let ax = xs[ia]
          and ay = ys[ia];
          let dx = xs[ib] -. ax
          and dy = ys[ib] -. ay;
          let len = sqrt(dx *. dx +. dy *. dy);
          if (len > 1.) {
            let (ux, uy) = (dx /. len, dy /. len);
            let (nx, ny) = (-. uy, ux);
            for (i in 0 to n - 1) {
              let s = slot[i];
              if (s != ia && s != ib && movable[i]) {
                let r = radius[i];
                let px = xs[s] -. ax
                and py = ys[s] -. ay;
                let along = px *. ux +. py *. uy;
                let side = px *. nx +. py *. ny;
                let need = r +. clear;
                if (along > r && along < len -. r && abs_float(side) < need) {
                  let dir =
                    abs_float(side) < 0.5
                      ? parity[s] : side >= 0. ? 1. : (-1.);
                  let m = need -. abs_float(side);
                  ox[s] = ox[s] +. dir *. nx *. m;
                  oy[s] = oy[s] +. dir *. ny *. m;
                  moved[s] = true;
                };
              };
            };
          };
        },
      ends,
    );
    for (s in 0 to n - 1) {
      if (moved[s]) {
        xs[s] = xs[s] +. ox[s];
        ys[s] = ys[s] +. oy[s];
      };
    };
    Array.iteri(
      (i, a) =>
        switch (a) {
        | Some(a) =>
          let ia = at(a);
          if (ia >= 0 && moved[ia]) {
            let s = slot[i];
            xs[s] = xs[s] +. ox[ia];
            ys[s] = ys[s] +. oy[ia];
          };
        | None => ()
        },
      anchor,
    );
  };
  List.mapi(
    (i, nl: node_layout) =>
      {
        ...nl,
        p: {
          x: xs[slot[i]],
          y: ys[slot[i]],
        },
      },
    nodes,
  );
};
let separate_docked_chords =
    (~chords: list((string, string)), nodes: list(node_layout)) => {
  ignore(separate_docked_chords);
  let touching: Hashtbl.t(string, list((string, string))) =
    Hashtbl.create(64);
  List.iter(
    ((ka, kb) as chord) =>
      List.iter(
        k =>
          Hashtbl.replace(
            touching,
            k,
            [
              chord,
              ...Option.value(~default=[], Hashtbl.find_opt(touching, k)),
            ],
          ),
        ka == kb ? [ka] : [ka, kb],
      ),
    List.rev(chords),
  );
  let positions = Hashtbl.create(64);
  List.iter(
    (nl: node_layout) => Hashtbl.replace(positions, nl.node.key, nl.p),
    nodes,
  );
  List.map(
    (nl: node_layout) =>
      switch (nl.node.kind, nl.node.sat) {
      | (Builtin, Some((anchor, _))) when Hashtbl.mem(touching, anchor) =>
        let p =
          List.fold_left(
            (p: pos, (ka, kb)) =>
              switch (
                Hashtbl.find_opt(positions, ka),
                Hashtbl.find_opt(positions, kb),
              ) {
              | (Some(a), Some(b)) when nl.node.key != ka && nl.node.key != kb =>
                let length = sqrt((b.x -. a.x) ** 2. +. (b.y -. a.y) ** 2.);
                let u = norm(a, b);
                let along = (p.x -. a.x) *. u.x +. (p.y -. a.y) *. u.y;
                let side = (p.y -. a.y) *. u.x -. (p.x -. a.x) *. u.y;
                if (length > 1.
                    && along > 0.
                    && along < length
                    && abs_float(side) < nl.r
                    +. 12.) {
                  let candidate = dir => {
                    x: p.x -. u.y *. dir *. 42.,
                    y: p.y +. u.x *. dir *. 42.,
                  };
                  let clearance = (q: pos) =>
                    List.fold_left(
                      (score, other: node_layout) =>
                        other.node.key == nl.node.key
                          ? score
                          : min(
                              score,
                              sqrt(
                                (q.x -. other.p.x)
                                ** 2.
                                +. (q.y -. other.p.y)
                                ** 2.,
                              )
                              -. other.r,
                            ),
                      max_float,
                      nodes,
                    );
                  let above = candidate(-1.)
                  and below = candidate(1.);
                  clearance(above) >= clearance(below) ? above : below;
                } else {
                  p;
                };
              | _ => p
              },
            nl.p,
            Hashtbl.find(touching, anchor),
          );
        {
          ...nl,
          p,
        };
      | _ => nl
      },
    nodes,
  );
};

/* Manual movement is applied after automatic layout. Docked satellites
   inherit their anchor's movement; an explicit satellite pin stays put. */
let apply_manual_positions = (~offsets, ~pins, nodes: list(node_layout)) => {
  let rec displacement = (seen, nl: node_layout): (float, float) =>
    if (List.mem(nl.node.key, seen)) {
      (0., 0.);
    } else {
      switch (List.assoc_opt(nl.node.key, pins)) {
      | Some((x, y)) => (snap(x) -. nl.p.x, snap(y) -. nl.p.y)
      | None =>
        let (dx, dy) =
          Option.value(
            ~default=(0., 0.),
            List.assoc_opt(nl.node.key, offsets),
          );
        let (ax, ay) =
          switch (nl.node.sat) {
          | Some((anchor, _)) =>
            List.find_opt((n: node_layout) => n.node.key == anchor, nodes)
            |> Option.map(n => displacement([nl.node.key, ...seen], n))
            |> Option.value(~default=(0., 0.))
          | None => (0., 0.)
          };
        (dx +. ax, dy +. ay);
      };
    };
  List.map(
    (nl: node_layout) => {
      let (dx, dy) = displacement([], nl);
      {
        ...nl,
        p: {
          x: nl.p.x +. dx,
          y: nl.p.y +. dy,
        },
      };
    },
    nodes,
  );
};

/* Comparison modes keep the same graph and routing; only the rank
   constraints change. Combined remains the production default. */
type ranking =
  | Combined
  | FunctionFlow
  | TypeDependencies;
/* PORTOLAN: upstream's layout_impl is cut in two where its last step
   begins. `layout_core` is everything that does not depend on the frame;
   `layout_frame` translates the result into the frame. A render asks for
   the same graph in several frames, and now pays for the placement once. */
let layout_core =
    (
      ~ranking=Combined,
      ~experiment="current",
      ~circuit=false,
      ~x_scale=1.,
      ~y_scale=1.,
      ~center_within: option(float)=None,
      /* fix the normalization origin (from a no-offsets layout of the
         same graph): user drags must never re-anchor the frame, else
         dragging feeds back into a whole-graph shift */
      ~origin_override: option(pos)=None,
      ~offsets: list((string, (float, float)))=[],
      ~pins: list((string, (float, float)))=[],
      /* expanded type cards: (w, h) per node key. A card is DISPLAY
         only: edges land on its rectangle and the board grows to hold
         it, but it never moves a node — toggling a card is not a
         relayout (the whole-graph re-solve and re-frame it caused threw
         the view in a small pane; neighbours may overlap for now). */
      ~cards: list((string, (float, float)))=[],
      g: CanvasGraph.t,
    ) => {
  /* PORTOLAN: the frame is layout_frame's */
  ignore(center_within);
  ignore(origin_override);
  let t_pre = Util.PerfTimer.now();
  let x_scale =
    experiment == "current"
    || experiment == "flow"
    || experiment == "dependencies"
      ? x_scale : 1.;
  let y_scale =
    experiment == "current"
    || experiment == "flow"
    || experiment == "dependencies"
      ? y_scale : 1.;
  let card_of = (k: string): option((float, float)) =>
    List.assoc_opt(k, cards);
  /* A one-use unknown component is a terminal, not an independent row.
     Shared or function-connected types retain their own layout role. */
  let g = {
    ...g,
    nodes:
      List.map(
        (n: CanvasGraph.tynode) => {
          let consumers =
            List.filter_map(
              (host: CanvasGraph.tynode) =>
                host.key != n.key
                && (
                  List.mem(n.key, host.parts) || List.mem(n.key, host.deps)
                )
                  ? Some(host.key) : None,
              g.nodes,
            )
            |> List.sort_uniq(compare);
          let has_function =
            List.exists(
              (e: CanvasGraph.edge) => e.e_src == n.key || e.dst == n.key,
              g.edges,
            );
          switch (n.kind, n.sat, consumers) {
          | (Ghost, None, [host]) when !has_function => {
              ...n,
              sat: Some((host, false)),
            }
          | _ => n
          };
        },
        g.nodes,
      ),
  };
  /* PORTOLAN: "compact" docks every one-use unnamed type */
  let g = experiment == "compact" ? CanvasOptions.dock_single_use(g) : g;
  /* ---- classify: grid vs docked ---- */
  let fan = (k: string): int =>
    List.length(
      List.filter(
        (e: CanvasGraph.edge) => e.e_src == k || e.dst == k,
        g.edges,
      ),
    );
  let is_loop_product = (n: CanvasGraph.tynode): bool =>
    n.kind == Product
    && List.exists(
         (e: CanvasGraph.edge) =>
           e.e_src == n.key && List.mem(e.dst, n.parts),
         g.edges,
       );
  let loop_anchor = (n: CanvasGraph.tynode): string =>
    switch (
      List.find_opt(
        (e: CanvasGraph.edge) =>
          e.e_src == n.key && List.mem(e.dst, n.parts),
        g.edges,
      )
    ) {
    | Some(e) => e.dst
    | None => ""
    };
  let is_former = (n: CanvasGraph.tynode): bool =>
    String.length(n.key) >= 3 && String.sub(n.key, 0, 3) == "{}@";
  /* a module's internals (any depth) cluster around the OUTERMOST
     module's former: internal aliases, nested formers — the hull closes
     around the cluster */
  let module_anchor = (n: CanvasGraph.tynode): option(string) =>
    switch (n.m_path) {
    | [] => None
    | [root, ..._] =>
      let top_former = "{}@" ++ root;
      if (is_former(n) && n.key == top_former) {
        None; /* the root former itself hosts the cluster */
      } else {
        Some(top_former);
      };
    };
  let docked: list((CanvasGraph.tynode, string, dock)) =
    List.filter_map(
      (n: CanvasGraph.tynode) =>
        switch (n.sat) {
        | Some((anchor, output)) =>
          Some((n, anchor, output ? DockOut : DockIn))
        | None when is_loop_product(n) =>
          Some((n, loop_anchor(n), DockLoop))
        | None when module_anchor(n) != None =>
          Some((n, Option.get(module_anchor(n)), DockMember))
        | None =>
          /* derived [T] docks beneath T when T is itself on the grid */
          /* only lightly-used [T] tucks beneath its element; a derived
             node with real traffic (orbits, loop products, several fns)
             needs its own grid slot and breathing room */
          switch (n.kind, strip_brackets(n.key)) {
          | (Derived, Some(ik)) when fan(n.key) <= 2 =>
            switch (
              List.find_opt((m: CanvasGraph.tynode) => m.key == ik, g.nodes)
            ) {
            | Some(m) when m.sat == None && !is_loop_product(m) =>
              Some((n, ik, DockDeriv))
            | _ => None
            }
          | _ => None
          }
        },
      g.nodes,
    );
  let docked_keys =
    List.map(((n: CanvasGraph.tynode, _, _)) => n.key, docked);
  let grid_nodes =
    List.filter(
      (n: CanvasGraph.tynode) => !List.mem(n.key, docked_keys),
      g.nodes,
    );
  let grid_keys = List.map((n: CanvasGraph.tynode) => n.key, grid_nodes);
  /* ---- placement: delegate to the GraphLayout engine ----
     Rank constraints: alias-body deps (hidden ones included — they still
     order columns), derived [T] after its element, and function flow
     (input strictly left of result). Docked nodes become attachments. */
  let r_of = (n: CanvasGraph.tynode): float =>
    node_radius(~fan=fan(n.key), n);
  let dep_edges =
    List.concat_map(
      (n: CanvasGraph.tynode) =>
        n.deps
        |> List.filter(d => d != n.key)
        |> List.map(d =>
             Util.GraphLayout.Spec.{
               src: d,
               dst: n.key,
               ranked: true,
             }
           ),
      grid_nodes,
    );
  let derived_edges =
    List.filter_map(
      (n: CanvasGraph.tynode) =>
        switch (strip_brackets(n.key)) {
        | Some(ik) when ik != n.key =>
          Some(
            Util.GraphLayout.Spec.{
              src: ik,
              dst: n.key,
              ranked: true,
            },
          )
        | _ => None
        },
      grid_nodes,
    );
  let flow_edges =
    List.filter_map(
      (e: CanvasGraph.edge) =>
        e.e_src != e.dst
          ? Some(
              Util.GraphLayout.Spec.{
                src: e.e_src,
                dst: e.dst,
                ranked: true,
              },
            )
          : None,
      g.edges,
    );
  let function_clearance = (key, anchor) =>
    List.fold_left(
      (space, e: CanvasGraph.edge) =>
        e.e_src == key && e.dst == anchor || e.e_src == anchor && e.dst == key
          ? max(
              space,
              max(48., float_of_int(String.length(e.e_name)) *. 7.4 +. 24.)
              +. 62.,
            )
          : space,
      0.,
      g.edges,
    );
  /* Endomorphism labels stack above their hub. Reserve their column;
     tuple-to-alias feedback labels instead have their own edge corridor. */
  let legend_count = (k: string): int =>
    List.length(
      List.filter(
        (e: CanvasGraph.edge) => e.e_src == k && e.dst == k,
        g.edges,
      ),
    );

  let legend_extent = (k: string): float => {
    let n = legend_count(k);
    n == 0 ? 0. : float_of_int(n) *. 24. +. 28.;
  };
  let attachments =
    List.map(
      ((n: CanvasGraph.tynode, anchor, d)) => {
        let (prefer, dist) =
          switch (d) {
          | DockIn => (
              Util.GraphLayout.Spec.In,
              max(
                n.kind == CanvasGraph.Product ? 44. : 56.,
                function_clearance(n.key, anchor) +. r_of(n),
              ),
            )
          | DockOut => (
              Util.GraphLayout.Spec.Out,
              max(56., function_clearance(n.key, anchor) +. r_of(n)),
            )
          | DockLoop => (
              Util.GraphLayout.Spec.In,
              max(100., function_clearance(n.key, anchor) +. r_of(n)),
            )
          | DockDeriv => (Util.GraphLayout.Spec.Below, 52.)
          | DockMember => (Util.GraphLayout.Spec.Below, 78.)
          };
        Util.GraphLayout.Spec.{
          id: n.key,
          host: anchor,
          /* labeled terminals hang text below the circle: pad the
             collision radius so neighbors keep clear of the label */
          radius: r_of(n) +. (n.label == "" || n.kind == Product ? 0. : 7.),
          prefer,
          dist,
        };
      },
      docked,
    );
  /* alias-body formers RANK their grid parts before the alias:
     [Todo] -> () -> Model must put [Todo] strictly left of Model, both
     for left-to-right reading and so the two hubs never share a column.
     (Loop products stay unranked — feedback must not stretch columns.) */
  let former_rank_edges =
    List.concat_map(
      (n: CanvasGraph.tynode) =>
        switch (n.kind, n.sat) {
        | (Product, Some((alias, _))) =>
          List.map(
            pk =>
              Util.GraphLayout.Spec.{
                src: pk,
                dst: alias,
                ranked: true,
              },
            n.parts,
          )
        /* folded former: the alias's own components rank before it */
        | (Alias, _) when n.parts != [] =>
          List.map(
            pk =>
              Util.GraphLayout.Spec.{
                src: pk,
                dst: n.key,
                ranked: true,
              },
            n.parts,
          )
        | _ => []
        },
      g.nodes,
    );
  /* formation links (component → product) are ordering-only: they pull
     a product's components toward its row without constraining columns */
  let formation_edges =
    List.concat_map(
      (n: CanvasGraph.tynode) =>
        n.kind == CanvasGraph.Product
        || n.kind == CanvasGraph.Alias
        && n.parts != []
          ? List.map(
              pk =>
                Util.GraphLayout.Spec.{
                  src: pk,
                  dst: n.key,
                  ranked: false,
                },
              n.parts,
            )
          : [],
      g.nodes,
    );
  /* member functions pull their module former toward the types they
     touch: unranked ordering edges (row attraction, no column rank) */
  let module_flow_pull =
    List.concat_map(
      (e: CanvasGraph.edge) =>
        switch (e.m_path) {
        | [root, ..._] =>
          let fk = "{}@" ++ root;
          List.mem(fk, grid_keys)
            ? List.filter_map(
                ((k, ranked)) =>
                  k != fk && List.mem(k, grid_keys)
                    ? Some(
                        Util.GraphLayout.Spec.{
                          src: k,
                          dst: fk,
                          ranked,
                        },
                      )
                    : None,
                /* rank the former after member INPUT types so it lands
                   a column over from them; results only order rows */
                [(e.e_src, true), (e.dst, false)],
              )
            : [];
        | [] => []
        },
      g.edges,
    );
  /* pinned nodes with no spec relationships float FREE of the rank
     grid: a freshly placed node would otherwise claim a row and shove
     every auto-laid node down */
  let unrank =
    List.map((e: Util.GraphLayout.Spec.edge) =>
      {
        ...e,
        ranked: false,
      }
    );
  let type_edges = es => ranking == FunctionFlow ? unrank(es) : es;
  let all_spec_edges =
    type_edges(dep_edges @ derived_edges)
    @ (ranking == TypeDependencies ? unrank(flow_edges) : flow_edges)
    @ type_edges(former_rank_edges)
    @ formation_edges
    @ type_edges(module_flow_pull);
  let spec_touches = (k: string): bool =>
    List.exists(
      (e: Util.GraphLayout.Spec.edge) => e.src == k || e.dst == k,
      all_spec_edges,
    )
    || List.exists(
         (a: Util.GraphLayout.Spec.attachment) => a.host == k,
         attachments,
       );
  let free_keys =
    List.filter_map(
      (n: CanvasGraph.tynode) =>
        List.mem_assoc(n.key, pins) && !spec_touches(n.key)
          ? Some(n.key) : None,
      grid_nodes,
    );
  Util.PerfTimer.record("layout/pre", Util.PerfTimer.now() -. t_pre);
  let t_solve = Util.PerfTimer.now();
  /* PORTOLAN: a layout that places every node itself skips the engine */
  let own_places = CanvasOptions.places(experiment);
  let (grid_nodes, all_spec_edges, attachments) =
    own_places ? ([], [], []) : (grid_nodes, all_spec_edges, attachments);
  let res =
    Util.GraphLayout.layout({
      nodes:
        List.filter_map(
          (n: CanvasGraph.tynode) =>
            List.mem(n.key, free_keys)
              ? None
              : Some(
                  Util.GraphLayout.Spec.{
                    id: n.key,
                    radius: r_of(n),
                    extent_above: legend_extent(n.key),
                    extent_below: 0.,
                  },
                ),
          grid_nodes,
        ),
      edges: all_spec_edges,
      attachments,
      col_gap: 64.,
      row_gap: 96.,
      margin,
      x_stretch: x_scale,
      y_stretch: y_scale,
      order_sweeps: 4,
      order_hysteresis: 0.6,
    });
  let placed_layouts: list(node_layout) =
    List.filter_map(
      (n: CanvasGraph.tynode) =>
        Util.GraphLayout.pos_of(res, n.key)
        |> Option.map((p: Util.GraphLayout.pos) =>
             {
               node: n,
               p: {
                 x: p.x,
                 y: p.y,
               },
               r: r_of(n),
             }
           ),
      g.nodes,
    )
    /* free-floating pinned nodes: position straight from the pin (the
       pins pass below re-applies the same value) */
    @ List.filter_map(
        (n: CanvasGraph.tynode) =>
          List.mem(n.key, free_keys)
            ? List.assoc_opt(n.key, pins)
              |> Option.map(((x, y)) =>
                   {
                     node: n,
                     p: {
                       x,
                       y,
                     },
                     r: r_of(n),
                   }
                 )
            : None,
        g.nodes,
      );
  /* PORTOLAN */
  let placed_layouts =
    own_places
      ? {
        let radii: Hashtbl.t(string, float) = Hashtbl.create(64);
        List.iter(
          (n: CanvasGraph.tynode) => Hashtbl.replace(radii, n.key, r_of(n)),
          g.nodes,
        );
        let radius = k =>
          Option.value(~default=base_radius, Hashtbl.find_opt(radii, k));
        let at: Hashtbl.t(string, Lab.point) = Hashtbl.create(64);
        List.iter(
          ((k, p)) => Hashtbl.replace(at, k, p),
          CanvasOptions.place(~radius, experiment, g),
        );
        List.filter_map(
          (n: CanvasGraph.tynode) =>
            Hashtbl.find_opt(at, n.key)
            |> Option.map(p =>
                 {
                   node: n,
                   p: from_lab(p),
                   r: radius(n.key),
                 }
               ),
          g.nodes,
        );
      }
      : placed_layouts;

  /* Declutter the automatic arrangement once, before manual placement.
     A pointer movement must not push unrelated nodes out of its new
     chords. Routing adapts to the final positions below instead. */
  Util.PerfTimer.record("layout/solve", Util.PerfTimer.now() -. t_solve);
  let t_nodes = Util.PerfTimer.now();
  let node_layouts =
    List.map(
      (nl: node_layout) =>
        {
          ...nl,
          p: {
            x: snap(nl.p.x),
            y: snap(nl.p.y),
          },
        },
      placed_layouts,
    );
  /* PORTOLAN: rows and arcs are already clear of each other */
  let declutter = (~chords, ~fixed, ~radius_of, nodes) =>
    own_places ? nodes : declutter(~chords, ~fixed, ~radius_of, nodes);
  let separate_docked_chords = (~chords, nodes) =>
    own_places ? nodes : separate_docked_chords(~chords, nodes);
  /* every straight line the render will draw: function arrows and the
     "made of" links (parts → product, former → alias, element → [T],
     alias-body deps → alias) */
  let node_layouts = {
    let chords =
      List.map((e: CanvasGraph.edge) => (e.e_src, e.dst), g.edges)
      @ List.concat_map(
          (n: CanvasGraph.tynode) =>
            switch (n.kind) {
            | Product =>
              List.map(pk => (pk, n.key), n.parts)
              @ (
                switch (n.sat) {
                | Some((anchor, _)) => [(n.key, anchor)]
                | None => []
                }
              )
            | Alias =>
              List.map(pk => (pk, n.key), n.parts)
              @ List.filter_map(
                  d =>
                    d != n.key && !List.mem(d, n.hidden_deps)
                      ? Some((d, n.key)) : None,
                  n.deps,
                )
            | Derived =>
              switch (strip_brackets(n.key)) {
              | Some(ik) => [(ik, n.key)]
              | None => []
              }
            | _ => []
            },
          g.nodes,
        );
    let circle_r = (k: string): float =>
      List.find_opt((nl: node_layout) => nl.node.key == k, node_layouts)
      |> Option.map((nl: node_layout) => nl.r)
      |> Option.value(~default=base_radius);
    /* PORTOLAN: the same, by table. declutter asks once per chord per
       node per round; searching the list each time was most of a large
       graph's layout. */
    let circle_r = {
      let radii: Hashtbl.t(string, float) = Hashtbl.create(64);
      List.iter(
        (nl: node_layout) =>
          if (!Hashtbl.mem(radii, nl.node.key)) {
            Hashtbl.add(radii, nl.node.key, nl.r);
          },
        node_layouts,
      );
      ignore(circle_r);
      (k: string) => (
        Option.value(~default=base_radius, Hashtbl.find_opt(radii, k)): float
      );
    };
    declutter(~chords, ~fixed=free_keys, ~radius_of=circle_r, node_layouts)
    |> separate_docked_chords(~chords);
  };
  let node_layouts = {
    let items =
      List.map(
        (n: node_layout) => {
          let orbit_count =
            List.length(
              List.filter(
                (e: CanvasGraph.edge) =>
                  e.e_src == n.node.key && e.dst == n.node.key,
                g.edges,
              ),
            );
          let extra = float_of_int(orbit_count) *. 30.;
          let (w, h) =
            Option.value(
              ~default=(
                max(98., 2. *. n.r +. extra +. 36.),
                max(94., 2. *. n.r +. extra +. 44.),
              ),
              Lab.research(experiment)
              || List.mem(
                   experiment,
                   ["packed", "stable", "grid", "relaxed"],
                 )
                ? List.assoc_opt(n.node.key, card_extents^ @ cards) : None,
            );
          Lab.{
            key: n.node.key,
            p: to_lab(n.p),
            w: w +. 20.,
            h: h +. 20.,
            anchor:
              List.find_opt(
                (a: Util.GraphLayout.Spec.attachment) => a.id == n.node.key,
                attachments,
              )
              |> Option.map((a: Util.GraphLayout.Spec.attachment) => a.host),
          };
        },
        node_layouts,
      );
    let links =
      List.map((e: CanvasGraph.edge) => (e.e_src, e.dst), g.edges)
      @ List.concat_map(
          (n: CanvasGraph.tynode) =>
            List.map(
              k => (n.key, k),
              n.deps
              @ n.parts
              @ (
                switch (n.m_path) {
                | [root, ..._] => ["{}@" ++ root]
                | [] => []
                }
              ),
            ),
          g.nodes,
        );
    let signature =
      Lab.scene^ ++ "/" ++ experiment ++ string_of_int(Lab.generation^);
    let keys = List.map((n: Lab.item) => n.key, items);
    let topology = Lab.links_of(items, links);
    let (old_scope, old_keys, old_links, cached) = placement_cache^;
    let clusters =
      List.filter_map(
        (n: CanvasGraph.tynode) =>
          switch (n.m_path) {
          | [root, ..._] => Some(root)
          | [] => None
          },
        g.nodes,
      )
      |> List.sort_uniq(compare)
      |> List.map(root =>
           [
             "{}@" ++ root,
             ...List.filter_map(
                  (n: CanvasGraph.tynode) =>
                    switch (n.m_path) {
                    | [r, ..._] when r == root => Some(n.key)
                    | _ => None
                    },
                  g.nodes,
                ),
           ]
         );
    let placed =
      /* PORTOLAN: Portolan's own placements come first */
      if (own_places) {
        items;
      } else if (experiment == "compact") {
        CanvasOptions.arrange(g, items);
      } else if (Lab.research(experiment)) {
        let result =
          Lab.place(
            ~clusters,
            ~labels=List.map((e: CanvasGraph.edge) => e.e_name, g.edges),
            experiment,
            items,
            links,
            Lab.previous(),
          );
        Lab.remember(result);
        result;
      } else if (!(
                   Lab.research(experiment)
                   || List.mem(
                        experiment,
                        ["packed", "stable", "grid", "relaxed"],
                      )
                 )) {
        /* PORTOLAN: the lab's packing, without its list searches */
        CanvasOptions.components(
          items,
          links,
        );
      } else if (old_scope == signature
                 && old_keys == keys
                 && old_links == topology) {
        cached;
      } else {
        let placed = Lab.place(experiment, items, links, Lab.previous());
        Lab.remember(placed);
        placement_cache := (signature, keys, topology, placed);
        placed;
      };
    List.map(
      (n: node_layout) =>
        switch (Lab.at(placed, n.node.key)) {
        | Some(p) => {
            ...n,
            p: from_lab(p.p),
          }
        | None => n
        },
      node_layouts,
    );
  };
  let node_layouts = apply_manual_positions(~offsets, ~pins, node_layouts);
  let placed: Hashtbl.t(string, (pos, float)) = Hashtbl.create(16);
  List.iter(
    (nl: node_layout) => Hashtbl.replace(placed, nl.node.key, (nl.p, nl.r)),
    node_layouts,
  );
  let pos_of = (k: string): option(pos) =>
    Hashtbl.find_opt(placed, k) |> Option.map(fst);
  let radius_of = (k: string): float =>
    Hashtbl.find_opt(placed, k)
    |> Option.map(snd)
    |> Option.value(~default=base_radius);
  /* edge endpoints land on the node's rim: the circle, or for a card
     the point where the ray toward `b` leaves its rectangle */
  let rim_toward = (a: pos, b: pos, k: string): pos =>
    switch (card_of(k)) {
    | None => offset_along(a, b, radius_of(k))
    | Some((w, h)) =>
      let u = norm(a, b);
      let tx =
        Float.abs(u.x) < 1e-6 ? Float.infinity : w /. 2. /. Float.abs(u.x);
      let ty =
        Float.abs(u.y) < 1e-6 ? Float.infinity : h /. 2. /. Float.abs(u.y);
      let t = Float.min(tx, ty) +. 1.;
      {
        x: a.x +. u.x *. t,
        y: a.y +. u.y *. t,
      };
    };
  let half_w_of = (k: string): float =>
    switch (card_of(k)) {
    | Some((w, _)) => w /. 2. +. 1.
    | None => radius_of(k)
    };

  /* ---- formation + dependency links (rim-to-rim so arrowheads land) ---- */
  let rim_pair =
      (from_k: string, to_k: string): option((string, string, pos, pos)) =>
    switch (pos_of(from_k), pos_of(to_k)) {
    | (Some(fp), Some(tp)) =>
      Some((
        from_k,
        to_k,
        rim_toward(fp, tp, from_k),
        rim_toward(tp, fp, to_k),
      ))
    | _ => None
    };
  let formations =
    List.concat_map(
      (n: CanvasGraph.tynode) =>
        switch (n.kind) {
        | Product =>
          (
            List.sort_uniq(compare, n.parts)
            |> List.filter_map(pk => rim_pair(pk, n.key))
          )
          /* alias-body formers dock at their alias and feed it */
          @ (
            switch (n.sat) {
            | Some((anchor, _)) => rim_pair(n.key, anchor) |> Option.to_list
            | None => []
            }
          )
        /* folded former: components feed the alias node directly */
        | Alias when n.parts != [] =>
          List.sort_uniq(compare, n.parts)
          |> List.filter_map(pk => rim_pair(pk, n.key))
        | Derived =>
          /* a docked [T] node forms from its element type */
          switch (strip_brackets(n.key)) {
          | Some(ik)
              when
                List.exists((m: CanvasGraph.tynode) => m.key == ik, g.nodes) =>
            rim_pair(ik, n.key) |> Option.to_list
          | _ => []
          }
        | _ => []
        },
      g.nodes,
    );
  let dep_links =
    List.concat_map(
      (n: CanvasGraph.tynode) =>
        switch (n.kind) {
        | Alias =>
          n.deps
          |> List.filter(d => d != n.key && !List.mem(d, n.hidden_deps))
          |> List.filter_map(dk => rim_pair(dk, n.key))
        | _ => []
        },
      g.nodes,
    );

  /* ---- edges ---- */
  let fallback = {
    x: margin,
    y: margin,
  };
  let loop_product_edges: list((string, string)) =
    List.filter_map(
      ((n: CanvasGraph.tynode, anchor, d)) =>
        d == DockLoop ? Some((n.key, anchor)) : None,
      docked,
    );
  let orbit_seen: Hashtbl.t(string, int) = Hashtbl.create(4);
  Util.PerfTimer.record("layout/nodes", Util.PerfTimer.now() -. t_nodes);
  let edge_layouts =
    List.map(
      (e: CanvasGraph.edge) => {
        let src_p = Option.value(~default=fallback, pos_of(e.e_src));
        let dst_p = Option.value(~default=fallback, pos_of(e.dst));
        let endo = e.e_src == e.dst;
        let is_loop = List.mem((e.e_src, e.dst), loop_product_edges);
        let orbit_rank =
          if (endo) {
            let k =
              Option.value(~default=0, Hashtbl.find_opt(orbit_seen, e.dst));
            Hashtbl.replace(orbit_seen, e.dst, k + 1);
            k;
          } else {
            0;
          };
        if (endo) {
          let orbit_r =
            radius_of(e.dst) +. 16. +. float_of_int(orbit_rank) *. 15.;
          let apex = {
            x: dst_p.x,
            y: dst_p.y -. orbit_r -. 10.,
          };
          {
            wire: [],
            edge: e,
            src_p,
            dst_p,
            c1: apex,
            c2: apex,
            endo,
            orbit_rank,
            label_p: {
              x: apex.x,
              y: apex.y -. 6.,
            },
            on_wire: false,
            label_anchor: {
              x: apex.x,
              y: apex.y -. 6.,
            },
          };
        } else if (is_loop) {
          /* Feedback needs a shallow arch distinct from the reverse
             component link. Separate handles preserve a broad middle for
             the label, instead of pinching the entire curve at one point. */
          let sign = dst_p.x >= src_p.x ? 1. : (-1.);
          let s =
            rim_toward(
              src_p,
              {
                x: dst_p.x,
                y: src_p.y -. 8.,
              },
              e.e_src,
            );
          let d =
            rim_toward(
              dst_p,
              {
                x: src_p.x,
                y: dst_p.y -. 12.,
              },
              e.dst,
            );
          let span = abs_float(d.x -. s.x);
          let rise = min(28., span *. 0.14);
          let c1 = {
            x: s.x +. sign *. span *. 0.33,
            y: min(s.y, d.y) -. rise,
          };
          let c2 = {
            x: d.x -. sign *. span *. 0.33,
            y: min(s.y, d.y) -. rise,
          };
          let mid = cubic_mid(s, c1, c2, d);
          {
            wire: [],
            edge: e,
            src_p: s,
            dst_p: d,
            c1,
            c2,
            endo,
            orbit_rank,
            label_p: {
              x: mid.x,
              y: mid.y -. 6.,
            },
            on_wire: false,
            label_anchor: {
              x: mid.x,
              y: mid.y -. 6.,
            },
          };
        } else {
          let sign = dst_p.x >= src_p.x ? 1. : (-1.);
          let s = {
            x: src_p.x +. sign *. half_w_of(e.e_src),
            y: src_p.y,
          };
          let d = {
            x: dst_p.x -. sign *. half_w_of(e.dst),
            y: dst_p.y,
          };
          let bend = max(24., min(90., abs_float(d.x -. s.x) *. 0.5));
          /* straight: an S with horizontal handles (declutter has moved
             the nodes off the chord); a same-column arrow runs down the
             column */
          let same_col = abs_float(d.x -. s.x) < 60.;
          let c1 = {
            x: same_col ? s.x : s.x +. sign *. bend,
            y: s.y,
          };
          let c2 = {
            x: same_col ? d.x : d.x -. sign *. bend,
            y: d.y,
          };
          {
            wire: [],
            edge: e,
            src_p: s,
            dst_p: d,
            c1,
            c2,
            endo,
            orbit_rank,
            label_p: {
              let m = cubic_mid(s, c1, c2, d);
              {
                x: m.x,
                y: m.y -. 6.,
              };
            },
            on_wire: false,
            label_anchor: {
              let m = cubic_mid(s, c1, c2, d);
              {
                x: m.x,
                y: m.y -. 6.,
              };
            },
          };
        };
      },
      g.edges,
    );

  let routed = ref([]);
  let edge_layouts =
    circuit
      ? List.map(
          (el: edge_layout) =>
            if (el.endo) {
              el;
            } else {
              let src =
                List.find(
                  (n: node_layout) => n.node.key == el.edge.e_src,
                  node_layouts,
                );
              let dst =
                List.find(
                  (n: node_layout) => n.node.key == el.edge.dst,
                  node_layouts,
                );
              let horizontal =
                abs_float(dst.p.x -. src.p.x)
                >= abs_float(dst.p.y -. src.p.y)
                *. 0.7;
              /* Distinct incident functions use distinct rim ports. A
                 shared destination must not imply a long shared trunk. */
              let port = (node: node_layout, other: node_layout, source) => {
                let coordinate = (p: pos) => horizontal ? p.y : p.x;
                let incident =
                  List.filter(
                    (e: CanvasGraph.edge) =>
                      e.e_src != e.dst
                      && (source ? e.e_src : e.dst) == node.node.key,
                    g.edges,
                  )
                  |> List.sort((a: CanvasGraph.edge, b: CanvasGraph.edge) => {
                       let coord = (e: CanvasGraph.edge) =>
                         coordinate(
                           Option.value(
                             ~default=node.p,
                             pos_of(source ? e.dst : e.e_src),
                           ),
                         );
                       let c = compare(coord(a), coord(b));
                       c == 0 ? compare(a.e_name, b.e_name) : c;
                     });
                let count = List.length(incident);
                let index =
                  List.mapi(
                    (i, e: CanvasGraph.edge) => (e.e_name, i),
                    incident,
                  )
                  |> List.assoc_opt(el.edge.e_name)
                  |> Option.value(~default=0);
                let fraction =
                  count <= 1
                    ? 0.
                    : 0.55
                      *. (
                        2.
                        *. float_of_int(index)
                        /. float_of_int(count - 1)
                        -. 1.
                      );
                let (w, h) =
                  Option.value(
                    ~default=(2. *. node.r, 2. *. node.r),
                    card_of(node.node.key),
                  );
                let sign =
                  horizontal
                    ? other.p.x >= node.p.x ? 1. : (-1.)
                    : other.p.y >= node.p.y ? 1. : (-1.);
                let side =
                  card_of(node.node.key) == None
                    ? sqrt(1. -. fraction *. fraction) : 1.;
                horizontal
                  ? {
                    x: node.p.x +. sign *. w /. 2. *. side,
                    y: node.p.y +. fraction *. h /. 2.,
                  }
                  : {
                    x: node.p.x +. fraction *. w /. 2.,
                    y: node.p.y +. sign *. h /. 2. *. side,
                  };
              };
              let s = port(src, dst, true);
              let d = port(dst, src, false);
              let route =
                Lab.route(
                  ~obstacles=obstacles(~cards, node_layouts),
                  ~src=el.edge.e_src,
                  ~dst=el.edge.dst,
                  ~lane=0,
                  ~occupied=routed^,
                  to_lab(s),
                  to_lab(d),
                )
                |> List.map(from_lab);
              routed := [List.map(to_lab, route), ...routed^];
              let mid = wire_at(route, 0.5);
              {
                ...el,
                wire: route,
                src_p: s,
                dst_p: d,
                label_p: {
                  x: mid.x,
                  y: mid.y -. 6.,
                },
                label_anchor: mid,
              };
            },
          edge_layouts,
        )
      : edge_layouts;
  /* PORTOLAN: the edge styles of CanvasOptions */
  let edge_layouts =
    CanvasOptions.routes()
      ? {
        let wires: Hashtbl.t(string, CanvasOptions.wire) =
          Hashtbl.create(64);
        List.iter(
          ((name, w)) => Hashtbl.replace(wires, name, w),
          CanvasOptions.route(
            ~nodes=
              List.map(
                (n: node_layout) => (n.node.key, to_lab(n.p), n.r),
                node_layouts,
              ),
            ~links=
              List.map(((a, b, _, _)) => (a, b), formations @ dep_links),
            ~room=
              name =>
                List.find_opt(
                  (e: CanvasGraph.edge) => e.e_name == name,
                  g.edges,
                )
                |> Option.map((e: CanvasGraph.edge) =>
                     float_of_int(String.length(e.e_name)) *. 7.4 +. 44.
                   )
                |> Option.value(~default=60.),
            List.filter_map(
              (el: edge_layout) =>
                el.endo
                  ? None : Some((el.edge.e_name, el.edge.e_src, el.edge.dst)),
              edge_layouts,
            ),
          ),
        );
        List.map(
          (el: edge_layout) =>
            switch (Hashtbl.find_opt(wires, el.edge.e_name)) {
            | Some({points: [first, ..._] as points, label, _}) =>
              let wire = List.map(from_lab, points);
              {
                ...el,
                wire,
                src_p: from_lab(first),
                dst_p: List.nth(wire, List.length(wire) - 1),
                label_p: {
                  x: label.x,
                  y: label.y -. 6.,
                },
                label_anchor: from_lab(label),
              };
            | Some({ctrl: Some((c1, c2)), label, _}) =>
              /* a curve: its ends are where the control points leave from */
              let rim = (k, toward: Lab.point) =>
                switch (pos_of(k)) {
                | Some(p) => offset_along(p, from_lab(toward), radius_of(k))
                | None => from_lab(toward)
                };
              {
                ...el,
                wire: [],
                src_p: rim(el.edge.e_src, c1),
                dst_p: rim(el.edge.dst, c2),
                c1: from_lab(c1),
                c2: from_lab(c2),
                label_p: {
                  x: label.x,
                  y: label.y -. 6.,
                },
                label_anchor: from_lab(label),
              };
            | _ => el
            },
          edge_layouts,
        );
      }
      : edge_layouts;

  /* ---- label placement: multi-direction search avoiding BOTH other
     labels and node circles. A label chip renders translate(-50%,-100%):
     its visual box spans x ± w/2 and y-18..y. Candidates spiral outward
     from the natural anchor so dense clusters spread around their
     neighborhood instead of stacking into a column over the nodes. ---- */
  let edge_layouts = {
    let label_half = (el: edge_layout): float =>
      max(24., float_of_int(String.length(el.edge.e_name)) *. 3.7 +. 12.);
    let placed_labels: ref(list((pos, float))) = ref([]);
    let label_hits_label = (p: pos, w: float): bool =>
      List.exists(
        ((q, qw)) =>
          abs_float(q.x -. p.x) < w +. qw && abs_float(q.y -. p.y) < 20.,
        placed_labels^,
      );
    let label_hits_node = (p: pos, w: float): bool =>
      List.exists(
        (nl: node_layout) => {
          let cx = min(max(nl.p.x, p.x -. w), p.x +. w)
          and cy = min(max(nl.p.y, p.y -. 18.), p.y +. 2.);
          Float.hypot(nl.p.x -. cx, nl.p.y -. cy) < nl.r +. 4.;
        },
        node_layouts,
      );
    /* orbit rings are obstacles too: a chip sitting ON the ring line
       reads as part of the circle */
    let orbit_rings =
      List.filter_map(
        (el: edge_layout) =>
          el.endo
            ? Some((
                el.dst_p,
                radius_of(el.edge.dst)
                +. 16.
                +. float_of_int(el.orbit_rank)
                *. 15.,
              ))
            : None,
        edge_layouts,
      );
    let label_hits_ring = (p: pos, w: float): bool =>
      List.exists(
        ((c: pos, ring_r: float)) => {
          let cx = min(max(c.x, p.x -. w), p.x +. w)
          and cy = min(max(c.y, p.y -. 18.), p.y +. 2.);
          let d = Float.hypot(c.x -. cx, c.y -. cy);
          /* box straddles or touches the ring band */
          abs_float(d -. ring_r) < 12. || d < ring_r && ring_r -. d < 26.;
        },
        orbit_rings,
      );
    let candidates = [
      (0., 0.),
      (0., (-24.)),
      (0., 22.),
      (52., 0.),
      ((-52.), 0.),
      (52., (-24.)),
      ((-52.), (-24.)),
      (52., 22.),
      ((-52.), 22.),
      (0., (-48.)),
      (0., 44.),
      (104., 0.),
      ((-104.), 0.),
      (0., (-72.)),
      (0., 66.),
      (52., 44.),
      ((-52.), 44.),
      (104., (-22.)),
      ((-104.), (-22.)),
      (104., 22.),
      ((-104.), 22.),
      (52., (-44.)),
      ((-52.), (-44.)),
      (0., 88.),
      (156., 0.),
      ((-156.), 0.),
    ];
    /* Endo-family labels (orbits + feedback loops on one hub) stack in
       an aligned column directly above their hub — a legend attached to
       the cluster — instead of scattering around cramped arc geometry.
       (Learned from andrew's manual arrangements.) Ordinary edges keep
       on-edge labels, dodging via the candidate search. */
    let is_loop_edge = (el: edge_layout): bool =>
      List.mem((el.edge.e_src, el.edge.dst), loop_product_edges);
    /* legend membership is GEOMETRIC: a loop label stacks only while
       its arc is too short to carry it — stretch the edge (drag the
       product away) and the label comes back to live on it. Orbits
       always stack (their edge is a circle). */
    let edge_len = (el: edge_layout): float =>
      Float.hypot(el.dst_p.x -. el.src_p.x, el.dst_p.y -. el.src_p.y);
    let hub_of = (el: edge_layout): option(string) =>
      el.endo
      || is_loop_edge(el)
      && edge_len(el) < label_half(el)
      *. 2.
      +. 32.
        ? Some(el.edge.dst) : None;
    let hubs =
      List.filter_map(hub_of, edge_layouts) |> List.sort_uniq(compare);
    let stacked: Hashtbl.t(string, pos) = Hashtbl.create(8);
    List.iter(
      hub => {
        let members =
          edge_layouts
          |> List.filter(el => hub_of(el) == Some(hub))
          /* orbit labels first, then loops by their product height */
          /* bottom-up: loop with the closest product first, orbit label
             topmost (matches how the arcs nest visually) */
          |> List.stable_sort((a: edge_layout, b: edge_layout) =>
               switch (a.endo, b.endo) {
               | (true, false) => 1
               | (false, true) => (-1)
               | _ => compare(b.src_p.y, a.src_p.y)
               }
             );
        switch (pos_of(hub)) {
        | None => ()
        | Some(hp) =>
          /* legend base: clear of orbit rings, and of loop products only
             when they actually sit in the column above the hub (they
             prefer up-LEFT precisely to keep this column free) */
          let ring_top =
            List.fold_left(
              (acc, el: edge_layout) =>
                el.endo && el.edge.dst == hub
                  ? min(
                      acc,
                      hp.y
                      -. (
                        radius_of(hub)
                        +. 16.
                        +. float_of_int(el.orbit_rank)
                        *. 15.
                      ),
                    )
                  : el.edge.dst == hub
                    && is_loop_edge(el)
                    && abs_float(el.src_p.x -. hp.x) < 56.
                      ? min(acc, el.src_p.y -. 14.) : acc,
              hp.y -. radius_of(hub),
              edge_layouts,
            );
          List.iteri(
            (i, el: edge_layout) => {
              let base =
                snap(ring_top -. 14. -. grid /. 2. -. 9.) +. grid /. 2. +. 9.;
              let p = {
                x: snap(hp.x),
                y: base -. float_of_int(i) *. 28.,
              };
              Hashtbl.replace(stacked, el.edge.e_name, p);
              placed_labels := [(p, label_half(el)), ...placed_labels^];
            },
            members,
          );
        };
      },
      hubs,
    );
    List.map(
      (el: edge_layout) => {
        switch (Hashtbl.find_opt(stacked, el.edge.e_name)) {
        | Some(p) => {
            ...el,
            label_p: p,
            /* the stack is contextually attached: no leader line */
            label_anchor: p,
            on_wire: false,
          }
        | None =>
          let w = label_half(el);
          let ok = (p: pos): bool =>
            !label_hits_label(p, w)
            && !label_hits_node(p, w)
            && !label_hits_ring(p, w);
          /* labels prefer LIVING ON THEIR EDGE: before jumping off,
             slide along the curve to nearby parameters */
          let curve_at = (t: float): pos =>
            if (el.wire != []) {
              let p = wire_at(el.wire, t);
              {
                x: p.x,
                y: p.y -. 6.,
              };
            } else {
              let u = 1. -. t;
              let b = (a, b, c, d) =>
                u
                *. u
                *. u
                *. a
                +. 3.
                *. u
                *. u
                *. t
                *. b
                +. 3.
                *. u
                *. t
                *. t
                *. c
                +. t
                *. t
                *. t
                *. d;
              {
                x: b(el.src_p.x, el.c1.x, el.c2.x, el.dst_p.x),
                y: b(el.src_p.y, el.c1.y, el.c2.y, el.dst_p.y) -. 6.,
              };
            };
          let snap_label = (p: pos): pos => {
            /* chip renders translate(-50%,-100%): its text center sits
               ~10px above label_p. Dot centers are at grid multiples
               (nodes snap there); putting the text center halfway
               between dot rows means label_p.y = k*grid + grid/2 + 10 */
            x: snap(p.x),
            y: snap(p.y -. grid /. 2. -. 9.) +. grid /. 2. +. 9.,
          };
          let rec pick_abs = (ps: list(pos), fallback) =>
            switch (ps) {
            | [] => fallback()
            | [p0, ...rest] =>
              let p = snap_label(p0);
              ok(p) ? p : pick_abs(rest, fallback);
            };
          let rec pick = (cs: list((float, float))): pos =>
            switch (cs) {
            | [] => snap_label(el.label_p)
            | [(dx, dy), ...rest] =>
              let p =
                snap_label({
                  x: el.label_p.x +. dx,
                  y: el.label_p.y +. dy,
                });
              ok(p) ? p : pick(rest);
            };
          /* ON THE WIRE when the arrow is long enough: the chip (2w wide)
             must leave the arrowhead (9) plus a stretch of line (14)
             visible on both sides; the chip is centered on the curve, so
             the hit boxes (built for a chip standing above its point) are
             checked with the point moved to where such a chip would sit */
          let chord =
            Float.hypot(el.dst_p.x -. el.src_p.x, el.dst_p.y -. el.src_p.y);
          let fits_on_wire = !el.endo && chord -. 2. *. w >= 2. *. (9. +. 14.);
          let on_wire_p =
            if (fits_on_wire) {
              /* PORTOLAN: an edge style's own choice is tried first */
              (CanvasOptions.routes() ? [el.label_anchor] : [])
              @ List.map(
                  t => {
                    let c = curve_at(t);
                    {
                      x: c.x,
                      y: c.y +. 6.,
                    };
                  },
                  [0.5, 0.42, 0.58, 0.34, 0.66, 0.28, 0.72],
                )
              |> List.find_opt((c: pos) =>
                   (
                     el.wire == []
                     || List.exists(
                          ((a: pos, b: pos)) =>
                            abs_float(a.y -. b.y) < 0.1
                            && abs_float(c.y -. a.y) < 0.1
                            && c.x
                            -. w > min(a.x, b.x)
                            +. 10.
                            && c.x
                            +. w < max(a.x, b.x)
                            -. 10.,
                          Lab.segments(el.wire),
                        )
                   )
                   && ok({
                        x: c.x,
                        y: c.y +. 9.,
                      })
                 );
            } else {
              None;
            };
          switch (on_wire_p) {
          | Some(p) =>
            placed_labels :=
              [
                (
                  {
                    x: p.x,
                    y: p.y +. 9.,
                  },
                  w,
                ),
                ...placed_labels^,
              ];
            {
              ...el,
              label_p: p,
              label_anchor: p,
              on_wire: true,
            };
          | None =>
            let on_curve =
              el.endo
                ? []
                : List.map(
                    curve_at,
                    [0.5, 0.42, 0.58, 0.34, 0.66, 0.26, 0.74],
                  );
            let p = pick_abs(on_curve, () => pick(candidates));
            placed_labels := [(p, w), ...placed_labels^];
            {
              ...el,
              label_p: p,
            };
          };
        }
      },
      edge_layouts,
    );
  };

  /* ---- values orbit their type's node: anchor = host center, vr
     staggers rings when a type has several constants ---- */
  let value_layouts = {
    let seen: Hashtbl.t(string, int) = Hashtbl.create(8);
    List.map(
      (v: CanvasGraph.value) => {
        let anchor = Option.value(~default=fallback, pos_of(v.v_key));
        let idx =
          switch (Hashtbl.find_opt(seen, v.v_key)) {
          | Some(n) =>
            Hashtbl.replace(seen, v.v_key, n + 1);
            n + 1;
          | None =>
            Hashtbl.replace(seen, v.v_key, 0);
            0;
          };
        {
          value: v,
          p: anchor,
          vr: radius_of(v.v_key) +. 13. +. float_of_int(idx) *. 7.,
        };
      },
      g.values,
    );
  };

  /* ---- normalize: translate the content bounding box (whatever actually
     hangs furthest — satellites, labels, values) to a snug uniform pad, so
     the internal grid margins never show up as whitespace ---- */
  let pad = 26.;
  let (min_x, min_y, max_x, max_y) = {
    let b =
      List.fold_left(
        ((x0, y0, x1, y1), nl: node_layout) =>
          (
            min(x0, nl.p.x -. nl.r),
            min(y0, nl.p.y -. nl.r),
            max(x1, nl.p.x +. nl.r),
            max(y1, nl.p.y +. nl.r +. 16.) /* name label below the node */
          ),
        (infinity, infinity, neg_infinity, neg_infinity),
        node_layouts,
      );
    let b =
      List.fold_left(
        (bounds, el: edge_layout) =>
          List.fold_left(
            ((x0, y0, x1, y1), p: pos) =>
              (min(x0, p.x), min(y0, p.y), max(x1, p.x), max(y1, p.y)),
            bounds,
            el.wire,
          ),
        b,
        edge_layouts,
      );
    let b =
      List.fold_left(
        ((x0, y0, x1, y1), el: edge_layout) =>
          (
            min(x0, el.label_p.x -. 62.),
            min(y0, el.label_p.y -. 18.),
            max(x1, el.label_p.x +. 62.),
            max(y1, el.label_p.y +. 4.),
          ),
        b,
        edge_layouts,
      );
    List.fold_left(
      ((x0, y0, x1, y1), vl: value_layout) =>
        (
          min(x0, vl.p.x -. vl.vr),
          min(y0, vl.p.y -. vl.vr),
          max(x1, vl.p.x +. vl.vr),
          max(y1, vl.p.y +. vl.vr),
        ),
      b,
      value_layouts,
    );
  };
  /* PORTOLAN: the cut */
  (
    experiment,
    cards,
    node_layouts,
    edge_layouts,
    value_layouts,
    formations,
    dep_links,
    pad,
    (min_x, min_y, max_x, max_y),
  );
};
let layout_frame =
    (
      ~center_within: option(float),
      ~origin_override: option(pos),
      (
        experiment,
        cards,
        node_layouts,
        edge_layouts,
        value_layouts,
        formations,
        dep_links,
        pad,
        (min_x, min_y, max_x, max_y),
      ),
    )
    : t =>
  if (node_layouts == []) {
    {
      nodes: [],
      edges: edge_layouts,
      values: value_layouts,
      formations,
      dep_links,
      width: 2. *. pad,
      height: 2. *. pad,
      origin: {
        x: 0.,
        y: 0.,
      },
    };
  } else {
    /* the normalization shift is grid-aligned so snapped coordinates
       stay on the dot lattice; when the pane is wider than the content,
       center within it (also on-grid) instead of hugging the left */
    let content_w = max_x -. min_x +. 2. *. pad;
    let center_pad =
      switch (center_within) {
      | Some(cw) when cw > content_w => snap((cw -. content_w) /. 2.)
      | _ => 0.
      };
    let (dx, dy) =
      switch (origin_override) {
      | Some(o) => (o.x, o.y)
      | None
          when
            Lab.research(experiment)
            || List.mem(experiment, ["stable", "relaxed", "grid", "packed"]) => (
          0.,
          0.,
        )
      | None => (snap(pad -. min_x) +. center_pad, snap(pad -. min_y))
      };
    let sh = (p: pos): pos => {
      x: p.x +. dx,
      y: p.y +. dy,
    };
    {
      nodes:
        List.map(
          (nl: node_layout) =>
            {
              ...nl,
              p: sh(nl.p),
            },
          node_layouts,
        ),
      edges:
        List.map(
          (el: edge_layout) =>
            {
              ...el,
              wire: List.map(sh, el.wire),
              src_p: sh(el.src_p),
              dst_p: sh(el.dst_p),
              c1: sh(el.c1),
              c2: sh(el.c2),
              label_p: sh(el.label_p),
              label_anchor: sh(el.label_anchor),
            },
          edge_layouts,
        ),
      values:
        List.map(
          (vl: value_layout) =>
            {
              ...vl,
              p: sh(vl.p),
            },
          value_layouts,
        ),
      formations:
        List.map(((ka, kb, a, b)) => (ka, kb, sh(a), sh(b)), formations),
      dep_links:
        List.map(((ka, kb, a, b)) => (ka, kb, sh(a), sh(b)), dep_links),
      /* panned-up content can put the extent above the origin; svg
         size attrs reject negatives (overlays overflow: visible). The
         board also reaches past any card's right/bottom edge (cards do
         not enter the extent that positions the graph, so a card can't
         shift it — but it must be scrollable to). */
      width:
        List.fold_left(
          (acc, (k, (w, _))) =>
            switch (
              List.find_opt(
                (nl: node_layout) => nl.node.key == k,
                node_layouts,
              )
            ) {
            | Some(nl) => max(acc, nl.p.x +. dx +. w /. 2. +. pad)
            | None => acc
            },
          max(0., max_x +. dx +. pad),
          cards,
        ),
      height:
        List.fold_left(
          (acc, (k, (_, h))) =>
            switch (
              List.find_opt(
                (nl: node_layout) => nl.node.key == k,
                node_layouts,
              )
            ) {
            | Some(nl) => max(acc, nl.p.y +. dy +. h /. 2. +. pad)
            | None => acc
            },
          max(0., max_y +. dy +. pad),
          cards,
        ),
      origin: {
        x: dx,
        y: dy,
      },
    };
  };

/* ---- instrumentation: how often and how long a render lays out ---- */
let layout_calls: ref(int) = ref(0);
let layout_ms: ref(float) = ref(0.);
/* Memo: a render lays the same graph out several times (fit check, frame
   viability, the view), and a score's renders repeat with nothing changed —
   ~100 layouts per tool call at 120 nodes (17 ms each) before this. Keyed
   on the graph's identity (extract is memoized per statics, so it is
   stable) and the parameters by value; the last few results are kept. */
type layout_key = {
  k_experiment: (string, string, string, int),
  k_graph: CanvasGraph.t,
  k_x: float,
  k_y: float,
  k_center: option(float),
  k_origin: option(pos),
  k_offsets: list((string, (float, float))),
  k_pins: list((string, (float, float))),
  k_cards: list((string, (float, float))),
  /* PORTOLAN: the pane shape a packing layout aimed for */
  k_aspect: float,
};
let layout_memo: ref(list((layout_key, t))) = ref([]);
let layout_memo_hits: ref(int) = ref(0);
/* PORTOLAN: two memos. `layout_memo` is upstream's, by every parameter.
   `core_memo` holds placements by everything but the frame: the fit check,
   the frame derivation and the view ask for one graph in three or four
   frames, and those now share a placement. `layout_calls` and `layout_ms`
   count placements. */
let same_key = (a: layout_key, b: layout_key) =>
  a.k_experiment == b.k_experiment
  && a.k_graph === b.k_graph
  && a.k_x == b.k_x
  && a.k_y == b.k_y
  && a.k_center == b.k_center
  && a.k_origin == b.k_origin
  && a.k_offsets == b.k_offsets
  && a.k_pins == b.k_pins
  && a.k_cards == b.k_cards
  && a.k_aspect == b.k_aspect;
let core_memo = ref([]);
let layout =
    (
      ~x_scale=1.,
      ~y_scale=1.,
      ~center_within: option(float)=None,
      ~origin_override: option(pos)=None,
      ~offsets: list((string, (float, float)))=[],
      ~pins: list((string, (float, float)))=[],
      ~cards: option(list((string, (float, float))))=?,
      g: CanvasGraph.t,
    )
    : t => {
  let cards = Option.value(~default=card_extents^, cards);
  /* PORTOLAN: only the layered layouts stretch, and only the packing ones
     look at the pane's shape; a key that says otherwise is a wasted solve */
  let stretches = List.mem(Lab.mode^, ["current", "flow", "dependencies"]);
  let packs = CanvasOptions.places(Lab.mode^) || Lab.mode^ == "compact";
  let key = {
    k_experiment: (
      Lab.mode^,
      Lab.wires^,
      Lab.scene^,
      Lab.generation^ + Lab.revision^,
    ),
    k_graph: g,
    k_x: stretches ? x_scale : 1.,
    k_y: stretches ? y_scale : 1.,
    k_center: center_within,
    k_origin: origin_override,
    k_offsets: offsets,
    k_pins: pins,
    k_cards: cards,
    k_aspect: packs ? CanvasOptions.aspect^ : 0.,
  };
  switch (List.find_opt(((k, _)) => same_key(k, key), layout_memo^)) {
  | Some((_, r)) =>
    incr(layout_memo_hits);
    r;
  | None =>
    let core_key = {
      ...key,
      k_center: None,
      k_origin: None,
    };
    let core =
      switch (List.find_opt(((k, _)) => same_key(k, core_key), core_memo^)) {
      | Some((_, c)) => c
      | None =>
        let now = () =>
          Js_of_ocaml.Js.Unsafe.coerce(Js_of_ocaml.Js.Unsafe.global)##._Date##now();
        let t0 = now();
        let c =
          layout_core(
            ~experiment=Lab.mode^,
            ~circuit=Lab.wires^ == "circuit",
            ~ranking=
              Lab.mode^ == "flow"
                ? FunctionFlow
                : Lab.mode^ == "dependencies" ? TypeDependencies : Combined,
            ~x_scale,
            ~y_scale,
            ~offsets,
            ~pins,
            ~cards,
            g,
          );
        incr(layout_calls);
        layout_ms := layout_ms^ +. (now() -. t0);
        Util.PerfTimer.record("canvas-layout", now() -. t0);
        core_memo :=
          [(core_key, c), ...List.filteri((i, _) => i < 3, core_memo^)];
        c;
      };
    let r = layout_frame(~center_within, ~origin_override, core);
    layout_memo :=
      [(key, r), ...List.filteri((i, _) => i < 5, layout_memo^)];
    r;
  };
};

files.canvas/edited/CanvasView.re:
open Virtual_dom.Vdom;
open Node;
open Util.WebUtil;

/* CanvasView — SVG/HTML rendering of a laid-out CanvasGraph. Edges live in
   an underlying SVG (horizontal-tangent béziers; orbits for single-arg
   endofunctions); nodes, labels, values, and the agent avatar are
   absolutely-positioned divs so they can carry stable DOM ids for the
   id-keyed FLIP in Animation.re. Elements are anchored via left/top and
   centered with the standalone CSS `translate` property — never the
   `transform` property, which WAAPI FLIP animations would override
   mid-flight (the label-jump bug). */

let fmt = f => Printf.sprintf("%.1f", f);

let sanitize = (s: string): string =>
  String.map(
    c =>
      switch (c) {
      | 'a' .. 'z'
      | 'A' .. 'Z'
      | '0' .. '9' => c
      | _ => '-'
      },
    s,
  );

let node_dom_id = (key: string): string => "cnode-" ++ sanitize(key);
/* an endofunction is drawn as an orbit ring, not a path */
let orbit_dom_id = (name: string): string => "corbit-" ++ sanitize(name);

/* A geometry layer (edges, hulls, ...) covers the board AND the pan slack
   around it: nodes pinned or dragged above/left of the frame origin sit at
   negative coordinates, and a board whose every node is up there has a
   zero-height box — an SVG of zero area paints nothing, overflow or not
   (labels, being HTML, still showed; the edges did not). The viewBox keeps
   user units = board units, with (0,0) at the board origin. */
let layer_box = (lay: CanvasLayout.t): list(Attr.t) => {
  let s = CanvasRipple.pan_slack;
  let w = lay.width +. 2. *. s
  and h = lay.height +. 2. *. s;
  [
    Attr.create("width", Printf.sprintf("%.1f", w)),
    Attr.create("height", Printf.sprintf("%.1f", h)),
    Attr.create(
      "viewBox",
      Printf.sprintf("%.1f %.1f %.1f %.1f", -. s, -. s, w, h),
    ),
    Attr.create(
      "style",
      Printf.sprintf("left: %.1fpx; top: %.1fpx;", -. s, -. s),
    ),
  ];
};
let edge_dom_id = (name: string): string => "cedge-" ++ sanitize(name);
let path_dom_id = (name: string): string => "cpath-" ++ sanitize(name);
let formation_dom_id = (a: string, b: string): string =>
  "cform-" ++ sanitize(a) ++ "--" ++ sanitize(b);
let value_dom_id = (name: string): string => "cval-" ++ sanitize(name);
let avatar_dom_id = "canvas-avatar";

let anchor_style = (p: CanvasLayout.pos): Attr.t =>
  Attr.create(
    "style",
    Printf.sprintf("left: %spx; top: %spx;", fmt(p.x), fmt(p.y)),
  );

let kind_cls = (k: CanvasGraph.node_kind): string =>
  switch (k) {
  | Alias => "kind-alias"
  | Builtin => "kind-builtin"
  | Derived => "kind-derived"
  | Ghost => "kind-ghost"
  | Product => "kind-product"
  };

/* geometry elements carry their dom id as the vdom KEY: a render during a
   score (a node dragged, a leader appearing) must patch them in place —
   an index-paired replacement would drop their in-flight animations and
   dash state */
/* virtual_dom's svg shim drops the key argument (hyperscript's svg() takes
   three), but its h() reads a `key` PROPERTY: that is how an svg vnode gets
   its key here */
let svg_key = (k: string): Attr.t =>
  Attr.property(
    "key",
    Js_of_ocaml.Js.Unsafe.inject(Js_of_ocaml.Js.string(k)),
  );
let svg = (~key=?, name, attrs, children) =>
  Node.create_svg(
    name,
    ~attrs=
      (
        switch (key) {
        | Some(k) => [svg_key(k)]
        | None => []
        }
      )
      @ attrs,
    children,
  );

let test_pip = (~on_click=?, t: CanvasGraph.test_info): Node.t => {
  let cls =
    switch (t.status) {
    | Some(Pass) => "pip-pass"
    | Some(Fail) => "pip-fail"
    | Some(Indet) => "pip-indet"
    | None => "pip-unknown"
    };
  let click =
    switch (on_click) {
    | Some(f) => [Attr.on_click(_ => f(t)), Attr.title("select this test")]
    | None => []
    };
  div(~attrs=[clss(["test-pip", cls]), ...click], []);
};

let edge_classes =
    (~focused: option(string)=None, e: CanvasGraph.edge): list(string) =>
  [e.main ? "edge-main" : "edge-helper"]
  @ (e.e_hole ? ["edge-hole"] : [])
  @ (e.e_err ? ["edge-err"] : [])
  @ (focused == Some(e.e_name) ? ["edge-focused"] : []);

/* End curves at the arrowhead BASE: pull the path end back along its
   final tangent so the marker (refX=0) occupies the gap and the tip
   lands where the rim point was. */
let pull_back =
    (p: CanvasLayout.pos, toward: CanvasLayout.pos, d: float)
    : CanvasLayout.pos => {
  let dx = toward.x -. p.x
  and dy = toward.y -. p.y;
  let len = max(1., Float.hypot(dx, dy));
  {
    x: p.x +. dx /. len *. d,
    y: p.y +. dy /. len *. d,
  };
};

let edge_svg =
    (
      ~focused: option(string),
      ~radius_of: string => float,
      el: CanvasLayout.edge_layout,
    )
    : list(Node.t) => {
  let e = el.edge;
  let cls = edge_classes(~focused, e);
  if (el.endo) {
    let r = radius_of(e.dst) +. 16. +. float_of_int(el.orbit_rank) *. 15.;
    [
      svg(
        ~key="corbit-" ++ sanitize(e.e_name),
        "circle",
        [
          Attr.id("corbit-" ++ sanitize(e.e_name)),
          clss(["canvas-orbit", ...cls]),
          Attr.create("cx", fmt(el.dst_p.x)),
          Attr.create("cy", fmt(el.dst_p.y)),
          Attr.create("r", fmt(r)),
        ],
        [],
      ),
    ];
  } else {
    /* the marker is 9 long from the path end: pull back exactly that, so
       the arrowhead's tip lands on the rim point */

    let marker =
      List.mem("edge-focused", cls)
        ? "url(#cnv-arrow-focus)" : "url(#cnv-arrow)";
    [
      svg(
        ~key=path_dom_id(e.e_name),
        "path",
        [
          Attr.id(path_dom_id(e.e_name)),
          clss(["canvas-line", "edge-arrow", ...cls]),
          Attr.create("d", CanvasLayout.edge_path(~pull=9., el)),
          Attr.create("marker-end", marker),
        ],
        [],
      ),
    ];
  };
};

