open Util;
open Js_of_ocaml;

/* This implements arbitrary gpu-accelerated css position
 * and scale transition animations via the the FLIP technique
 * (https://aerotwist.com/blog/flip-your-animations/).
 *
 * From the client perspective, it suffices to call the request
 * method with a list of the DOM element ids to animate, as well
 * as some animation settings (keyframes, duration, easing).
 *
 * Some common keyframes are provided in the module at the bottom */

/* This is an extremely partial implementation of the Web Animations
 * API, which currently does not have Js_of_ocaml wrappers */
module Js = {
  /* CSS property-value pairs */
  type keyframe = (string, string);

  type options = {
    duration: int,
    easing: string,
    /* ms before the animation starts; the first keyframe holds meanwhile
       (fill: backwards), so a delayed move/grow-in stays put, then goes */
    delay: int,
  };

  /* Options for CSS Animations API animate method */
  type animation = {
    options,
    keyframes: list(keyframe),
  };

  /* Position & dimensions for a DOM element */
  type box = {
    top: float,
    left: float,
    height: float,
    width: float,
  };

  let box_of = (elem: Js.t(Dom_html.element)): box => {
    let container_rect = elem##getBoundingClientRect;
    {
      top: container_rect##.top,
      left: container_rect##.left,
      height: Js.Optdef.get(container_rect##.height, _ => 0.0),
      width: Js.Optdef.get(container_rect##.width, _ => 0.0),
    };
  };

  let client_height = (): float =>
    try(
      JsUtil.cached_client_height(
        Js.Unsafe.get(Dom_html.document, "documentElement"),
      )
    ) {
    | _ => 0.0
    };

  let inner_height = (): float =>
    Js.Optdef.get(Js.Unsafe.get(Dom_html.window, "innerHeight"), _ => 0.0);

  let check_visible = (client_height, inner_height, box: box): bool => {
    let viewHeight = max(client_height, inner_height);
    !(box.top +. box.height < 0.0 || box.top -. viewHeight >= 0.0);
  };

  let keyframes_unsafe = (keyframes: list(keyframe)): Js.t(Js.js_array('a)) =>
    keyframes
    |> List.map(((prop: string, value: string)) =>
         Js.Unsafe.obj([|(prop, Js.Unsafe.inject(Js.string(value)))|])
       )
    |> Array.of_list
    |> Js.array;

  let options_unsafe =
      ({duration, easing, delay}: options): Js.t(Js.js_array('a)) =>
    [
      ("duration", Js.Unsafe.inject(duration)),
      ("easing", Js.Unsafe.inject(Js.string(easing))),
    ]
    @ (
      delay > 0
        ? [
          ("delay", Js.Unsafe.inject(delay)),
          ("fill", Js.Unsafe.inject(Js.string("backwards"))),
        ]
        : []
    )
    |> Array.of_list
    |> Js.Unsafe.obj;

  /* keyframes with several properties each (the single-property form
     above encodes one property per keyframe) */
  let animate_multi =
      (
        frames: list(list((string, string))),
        options: options,
        elem: Js.t(Dom_html.element),
      )
      : unit => {
    let kf =
      frames
      |> List.map(props =>
           Js.Unsafe.obj(
             props
             |> List.map(((p, v)) => (p, Js.Unsafe.inject(Js.string(v))))
             |> Array.of_list,
           )
         )
      |> Array.of_list
      |> Js.array;
    ignore(
      Js.Unsafe.meth_call(
        elem,
        "animate",
        [|
          Js.Unsafe.inject(kf),
          Js.Unsafe.inject(options_unsafe(options)),
        |],
      ),
    );
  };

  let animate_unsafe =
      (
        keyframes: list(keyframe),
        options: options,
        elem: Js.t(Dom_html.element),
      ) =>
    Js.Unsafe.meth_call(
      elem,
      "animate",
      [|
        Js.Unsafe.inject(keyframes_unsafe(keyframes)),
        Js.Unsafe.inject(options_unsafe(options)),
      |],
    );

  let animate = ({options, keyframes}, elem: Js.t(Dom_html.element)) =>
    if (keyframes != []) {
      switch (animate_unsafe(keyframes, options, elem)) {
      | exception exn =>
        print_endline("Animation: " ++ Printexc.to_string(exn))
      | () => ()
      };
    };
};

open Js;

/* If an element is new, report its new metrics.
 * Otherwise, report both new & old metrics */
type change =
  | New(box)
  | Existing(box, box);

/* Specify a transition for an element */
type transition = {
  /* A unique id used as attribute for
   * the relevant DOM element */
  id: string,
  /* The animation function recieves the diffs
   * for the element's position and scale across a
   * change, which it may use to calculate the
   * parameters for a resulting animation */
  animate: change => animation,
};

/* Internally, transitions must track the initial
 * metrics for an element, gathered in the `Request ` phase */
type transition_internal = {
  id: string,
  animate: change => animation,
  box: option(box),
};

/* Elements and their corresponding animations are tracked
 * here between when the action is used (`request`) and
 * when the animation is executed (`go`) */
let tracked_elems: ref(list(transition_internal)) = ref([]);

let animate_elem = (({box, animate, _}, elem, new_box)): unit =>
  switch (box, new_box) {
  | (Some(init), Some(final)) =>
    Js.animate(animate(Existing(init, final)), elem)
  | (None, Some(final)) => Js.animate(animate(New(final)), elem)
  | (Some(_init), None) =>
    //TODO: Removed case (requires retaining old element somehow)
    ()
  | (None, None) => ()
  };

let filter_visible_elements = (tracked_elems: list(transition_internal)) => {
  let client_height = client_height();
  let inner_height = inner_height();
  List.filter_map(
    (tr: transition_internal) => {
      switch (JsUtil.get_elem_by_id_opt(tr.id)) {
      | None => None
      | Some(elem) =>
        let new_box = box_of(elem);
        check_visible(client_height, inner_height, new_box)
          ? Some((tr, elem, Some(new_box))) : None;
      }
    },
    tracked_elems,
  );
};

/* Stagger bookkeeping for one `go` pass: NEW elements get ascending
   indices (in tracked order) so arrivals can be spread out in time, and
   movers can wait until the arrivals are done. Read inside `animate`
   closures via Actions.move. */
let stagger_index: ref(int) = ref(0);
let stagger_total: ref(int) = ref(0);
/* arrivals never spread over more than this, however many there are */
let stagger_span_cap = 2400;
let stagger_step = (per: int): int =>
  min(per, stagger_span_cap / max(1, stagger_total^));
let stagger_span = (per: int): int =>
  min(stagger_span_cap, stagger_total^ * stagger_step(per));

/* a glide (125ms, Actions.move) restarted mid-glide reads as decoration lag */
let last_caret_glide: ref(float) = ref(0.);
let caret_glide_available = (): bool => {
  let now: float = Js_of_ocaml.Js.Unsafe.global##.Date##now();
  if (now -. last_caret_glide^ > 170.) {
    last_caret_glide := now;
    true;
  } else {
    last_caret_glide := now; /* keep suppressing until input pauses */
    false;
  };
};

/* Request animations. Call this during the MVU update */
/* ids under these prefixes belong to another timeline (the canvas score)
   until the given time: a FLIP request for them would replace a pending
   grow-in or the avatar's path mid-flight, so it is dropped */
let held: ref((list(string), float)) = ref(([], 0.));
let hold = (~prefixes: list(string), ~until_ms: float): unit =>
  held := (prefixes, until_ms);
let shift_hold = (~since: float, dt: float): unit => {
  let (p, u) = held^;
  if (u > since) {
    held := (p, u +. dt);
  };
};
let is_held = (id: string): bool => {
  let (prefixes, until_ms) = held^;
  Js_of_ocaml.Js.Unsafe.coerce(Js_of_ocaml.Js.Unsafe.global)##._Date##now()
  < until_ms
  && List.exists(
       p =>
         String.length(id) >= String.length(p)
         && String.sub(id, 0, String.length(p)) == p,
       prefixes,
     );
};

/* journal hook (set by Main to CanvasLog.log) */
let slow_hook: ref(string => unit) = ref(_ => ());

let request = (transitions: list(transition)): unit => {
  /* the avatar's motion has one owner at a time; say when a generic hop is
     requested for it (or dropped as held) so a replay can pin a teleport */
  List.iter(
    ({id, _}: transition) =>
      if (id == "canvas-avatar") {
        slow_hook^(
          is_held(id)
            ? "avatar: generic hop dropped (score owns it)"
            : "avatar: generic hop requested",
        );
      },
    transitions,
  );
  /* the avatar's transform has one writer (CanvasEnact's driver) */
  let transitions =
    List.filter(
      ({id, _}: transition) => id != "canvas-avatar" && !is_held(id),
      transitions,
    );
  tracked_elems :=
    List.map(
      ({id, animate}: transition) =>
        {
          id,
          box: Option.map(box_of, JsUtil.get_elem_by_id_opt(id)),
          animate,
        },
      transitions,
    )
    @ tracked_elems^;
};

module Keyframes = {
  let transform_translate = (top: float, left: float): keyframe => (
    "transform",
    Printf.sprintf("translate(%fpx, %fpx)", left, top),
  );

  let translate = (~scale=1., init: box, final: box): list(keyframe) => {
    [
      /* rects are measured in screen px; the transform plays inside the
         element's local space. When an ancestor applies CSS zoom, both
         differ from local px by that factor — divide once so the visual
         glide matches the measured hop (else motion plays at zoom^2). */
      transform_translate(
        (init.top -. final.top) /. scale,
        (init.left -. final.left) /. scale,
      ),
      transform_translate(0., 0.),
    ];
  };

  let transform_scale_uniform = (scale: float): keyframe => (
    "transform",
    Printf.sprintf("scale(%f, %f)", scale, scale),
  );

  let scale_from_zero: list(keyframe) = [
    transform_scale_uniform(0.0),
    transform_scale_uniform(1.0),
  ];
};

let easeOutExpo = "cubic-bezier(0.16, 1, 0.3, 1)";

/* (beats and `go` live below Keyframes/easings, which they use) */
/* ---- beats: arrivals + SVG geometry ----
   Elements that don't exist yet when a beat is staged can't be tracked
   by box, so the beat records which ids exist per prefix; at `go`, ids
   that appeared are ARRIVALS and grow in one by one (staggered), and
   tracked SVG geometry (edge paths, formation lines, orbit rings) MORPHS
   from its old attributes to the new ones on the movers' timing instead
   of snapping while the nodes glide. */
type beat_stage = {
  arrival_prefixes: list(string),
  existing: list(string),
  geom_prefixes: list(string),
  /* id -> (attribute, old value) for the geometry we morph */
  geom_old: list((string, list((string, string)))),
  b_delay: int,
  b_stagger: int,
  b_move_dur: int,
  /* when staged: a render that changes nothing (a dormant slide's empty
     first frame, a tick) must not consume the beat — it is kept for the
     next render, up to a short expiry */
  b_staged_at: float,
};
let now_ms = (): float =>
  Js_of_ocaml.Js.Unsafe.coerce(Js_of_ocaml.Js.Unsafe.global)##._Date##now();
let beat_expiry_ms = 900.;
let beat: ref(option(beat_stage)) = ref(None: option(beat_stage));
let staged = (): bool => beat^ != None;
/* the last `go`'s arrivals as (id, delay ms), for choreography that runs
   after the render (the avatar touring the new nodes as they bloom) */
let last_arrivals: ref(list((string, int))) = ref([]);
/* an explicit arrival schedule (id -> delay ms) set by the canvas after
   layout, overriding the generic stagger for the ids it names */
let arrival_schedule: ref(list((string, int))) = ref([]);
let set_arrival_schedule = (s: list((string, int))): unit =>
  arrival_schedule := s;
/* how long movers wait for arrivals when a schedule stretched them */
let arrival_span_override: ref(int) = ref(0);
/* when set, movers and geometry wait until this beat-relative ms (the
   score's Drift act) instead of the arrivals' span */
let movers_at: ref(option(int)) = ref(None);
let set_movers_at = (ms: option(int)): unit => movers_at := ms;
/* new geometry the score has an opinion about: Some(ms) = draw on at that
   beat-relative time; None = keep hidden, the player draws it (a ride) */
let geom_schedule: ref(list((string, option(int)))) = ref([]);
let set_geom_schedule = (s: list((string, option(int)))): unit =>
  geom_schedule := s;
let geom_attrs = ["d", "cx", "cy"];
/* (module Js above shadows Js_of_ocaml.Js: qualify explicitly) */
let attr_of =
    (el: Js_of_ocaml.Js.t(Dom_html.element), name: string): option(string) =>
  Js_of_ocaml.Js.Opt.to_option(
    el##getAttribute(Js_of_ocaml.Js.string(name)),
  )
  |> Option.map(Js_of_ocaml.Js.to_string);
let request_beat =
    (
      ~arrival_prefixes: list(string),
      ~geom_prefixes: list(string),
      ~delay: int,
      ~stagger: int,
      ~move_dur: int,
    )
    : unit => {
  let ids = prefixes => List.concat_map(JsUtil.ids_with_prefix, prefixes);
  beat :=
    Some({
      arrival_prefixes,
      existing: ids(arrival_prefixes),
      geom_prefixes,
      geom_old:
        ids(geom_prefixes)
        |> List.filter_map(id =>
             JsUtil.get_elem_by_id_opt(id)
             |> Option.map(el =>
                  (
                    id,
                    geom_attrs
                    |> List.filter_map(a =>
                         attr_of(el, a) |> Option.map(v => (a, v))
                       ),
                  )
                )
           ),
      b_delay: delay,
      b_stagger: stagger,
      b_move_dur: move_dur,
      b_staged_at: now_ms(),
    });
};
/* CSS value for an SVG geometry attribute */
let geom_css = (attr: string, v: string): string =>
  attr == "d" ? "path(\"" ++ v ++ "\")" : v ++ "px";

/* Execute animations. This is called during the
 * render phase, after recalc but before repaint */
let go_impl = (): unit => {
  let visible =
    tracked_elems^ == [] ? [] : tracked_elems^ |> filter_visible_elements;
  let arrivals =
    switch (beat^) {
    | None => []
    | Some(b) =>
      List.concat_map(JsUtil.ids_with_prefix, b.arrival_prefixes)
      |> List.filter(id => !List.mem(id, b.existing))
      |> List.filter_map(id =>
           JsUtil.get_elem_by_id_opt(id) |> Option.map(el => (id, el))
         )
    };
  /* movers wait for ALL arrivals, tracked or not */
  stagger_total :=
    List.length(arrivals)
    + List.length(List.filter(((tr, _, _)) => tr.box == None, visible));
  stagger_index := 0;
  switch (beat^) {
  | Some(b) when arrivals != [] =>
    let step = stagger_step(b.b_stagger);
    last_arrivals := [];
    arrival_span_override := 0;
    List.iter(
      ((id, el)) => {
        let delay =
          switch (List.assoc_opt(id, arrival_schedule^)) {
          | Some(d) => d
          | None =>
            /* a scored beat stages every arrival; one the score did not
               name appears with the generic stagger — no actor (A2) */
            if (arrival_schedule^ != []) {
              slow_hook^("ORPHAN: arrival " ++ id ++ " unscheduled");
            };
            b.b_delay + stagger_index^ * step;
          };
        arrival_span_override :=
          max(arrival_span_override^, delay - b.b_delay);
        last_arrivals := last_arrivals^ @ [(id, delay)];
        Js.animate(
          {
            options: {
              duration: 220,
              easing: easeOutExpo,
              delay,
            },
            keyframes: Keyframes.scale_from_zero,
          },
          el,
        );
        incr(stagger_index);
      },
      arrivals,
    );
  | _ => ()
  };
  if (visible != []) {
    visible
    |> List.iter(((tr, _, _) as x) => {
         animate_elem(x);
         if (tr.box == None) {
           incr(stagger_index);
         };
       });
    tracked_elems := [];
  };
  switch (beat^) {
  | None => ()
  | Some(b) =>
    let did_anything = ref(arrivals != [] || visible != []);
    let wait =
      switch (movers_at^) {
      | Some(ms) => max(0, ms - b.b_delay)
      | None =>
        b.b_stagger > 0 && stagger_total^ > 0
          ? max(stagger_span(b.b_stagger), arrival_span_override^) + 120 : 0
      };
    /* morph tracked geometry on the movers' timing */
    List.iter(
      ((id, olds)) =>
        switch (JsUtil.get_elem_by_id_opt(id)) {
        | None => ()
        | Some(el) =>
          let frames =
            olds
            |> List.filter_map(((a, old)) =>
                 switch (attr_of(el, a)) {
                 | Some(nw) when nw != old => Some((a, old, nw))
                 | _ => None
                 }
               );
          if (frames != []) {
            did_anything := true;
            let kf = side =>
              List.map(
                ((a, old, nw)) =>
                  (a, geom_css(a, side == `From ? old : nw)),
                frames,
              );
            Js.animate_multi(
              [kf(`From), kf(`To)],
              {
                duration: b.b_move_dur,
                easing: easeOutExpo,
                delay: b.b_delay + wait,
              },
              el,
            );
          };
        },
      b.geom_old,
    );
    /* new geometry (fresh formation lines, orbit rings, edges) DRAWS ON
       from its source end once the arrivals it belongs to have grown
       in — a dash reveal along the stroke, arrowhead held until the end.
       (The canvas's enactment re-stages new function edges with the
       avatar riding them; it cancels this first.) */
    let known = List.map(fst, b.geom_old);
    /* the draw-on trick needs ONE dash the length of the path; a dotted
       line's CSS dash pattern would override a presentation attribute, so
       the pattern goes on the inline style and, for dotted lines, keeps
       the dots: n x (dot gap) covering the length, then a gap of the same
       length. Returns the "on" length the dashoffset animates from. */
    let arm_dash = (el, total: float): float => {
      let css: string =
        Js_of_ocaml.Js.to_string(
          Js_of_ocaml.Js.Unsafe.get(
            Js_of_ocaml.Js.Unsafe.meth_call(
              Js_of_ocaml.Js.Unsafe.global##.window,
              "getComputedStyle",
              [|Js_of_ocaml.Js.Unsafe.inject(el)|],
            ),
            "strokeDasharray",
          ),
        );
      let strip_px = s => {
        let s = String.trim(s);
        let n = String.length(s);
        n > 2 && String.sub(s, n - 2, 2) == "px"
          ? String.sub(s, 0, n - 2) : s;
      };
      let nums =
        css
        |> String.split_on_char(',')
        |> List.concat_map(String.split_on_char(' '))
        |> List.filter_map(s => float_of_string_opt(strip_px(s)));
      let (pattern, on_len) =
        switch (nums) {
        | [dot, gap, ..._] when dot +. gap > 0. && dot +. gap < 40. =>
          let period = dot +. gap;
          let n = int_of_float(ceil(total /. period));
          let on_len = float_of_int(n) *. period;
          (
            String.concat(
              " ",
              List.init(n, _ => Printf.sprintf("%.2f %.2f", dot, gap)),
            )
            ++ Printf.sprintf(" 0 %.1f", on_len),
            on_len,
          );
        | _ => (Printf.sprintf("%.1f %.1f", total, total), total)
        };
      Js_of_ocaml.Js.Unsafe.set(
        Js_of_ocaml.Js.Unsafe.get(el, "style"),
        "strokeDasharray",
        Js_of_ocaml.Js.string(pattern),
      );
      on_len;
    };
    let disarm_dash = el => {
      let st = Js_of_ocaml.Js.Unsafe.get(el, "style");
      Js_of_ocaml.Js.Unsafe.set(
        st,
        "strokeDasharray",
        Js_of_ocaml.Js.string(""),
      );
      Js_of_ocaml.Js.Unsafe.set(
        st,
        "strokeDashoffset",
        Js_of_ocaml.Js.string(""),
      );
      List.iter(
        a =>
          ignore(
            Js_of_ocaml.Js.Unsafe.meth_call(
              el,
              "removeAttribute",
              [|Js_of_ocaml.Js.Unsafe.inject(Js_of_ocaml.Js.string(a))|],
            ),
          ),
        ["stroke-dasharray", "stroke-dashoffset"],
      );
    };
    let set_attr = (el, a: string, v: string) =>
      ignore(
        Js_of_ocaml.Js.Unsafe.meth_call(
          el,
          "setAttribute",
          [|
            Js_of_ocaml.Js.Unsafe.inject(Js_of_ocaml.Js.string(a)),
            Js_of_ocaml.Js.Unsafe.inject(Js_of_ocaml.Js.string(v)),
          |],
        ),
      );
    List.concat_map(JsUtil.ids_with_prefix, b.geom_prefixes)
    |> List.filter(id => !List.mem(id, known))
    |> List.iter(id =>
         switch (JsUtil.get_elem_by_id_opt(id)) {
         | Some(el) =>
           let total: float =
             Js_of_ocaml.Js.Unsafe.meth_call(el, "getTotalLength", [||]);
           /* the journal says how each new line was scheduled — a line left
              visible at render (skipped as too short, or unscheduled) is
              the "already there" state the recorder flags */
           slow_hook^(
             Printf.sprintf(
               "geom: %s len=%.0f %s",
               id,
               total,
               switch (List.assoc_opt(id, geom_schedule^)) {
               | Some(None) => "owned"
               | Some(Some(d)) => Printf.sprintf("at %dms", d)
               | None => "ORPHAN: unscheduled (beat default)"
               },
             ),
           );
           if (total > 4.) {
             did_anything := true;
             let marker = attr_of(el, "marker-end");
             let on_len = arm_dash(el, total);
             switch (marker) {
             | Some(_) => set_attr(el, "marker-end", "none")
             | None => ()
             };
             let owned =
               switch (List.assoc_opt(id, geom_schedule^)) {
               | Some(None) => true
               | _ => false
               };
             let (delay, duration) =
               switch (List.assoc_opt(id, geom_schedule^)) {
               | Some(Some(d)) => (d, 320)
               | _ => (b.b_delay + wait, b.b_move_dur)
               };
             if (owned) {
               /* hidden until its act: the offset sits at full length; the
                  arrowhead is stashed for the player to restore */
               Js_of_ocaml.Js.Unsafe.set(
                 Js_of_ocaml.Js.Unsafe.get(el, "style"),
                 "strokeDashoffset",
                 Js_of_ocaml.Js.string(Printf.sprintf("%.1f", on_len)),
               );
               switch (marker) {
               | Some(m) when m != "none" => set_attr(el, "data-marker", m)
               | _ => ()
               };
             } else {
               Js.animate_multi(
                 [
                   [("strokeDashoffset", Printf.sprintf("%.1f", on_len))],
                   [("strokeDashoffset", "0")],
                 ],
                 {
                   duration,
                   easing: "cubic-bezier(0.65, 0, 0.35, 1)",
                   delay,
                 },
                 el,
               );
               ignore(
                 Js_of_ocaml.Js.Unsafe.global##setTimeout(
                   Js_of_ocaml.Js.Unsafe.callback(() => {
                     switch (marker) {
                     | Some(m) => set_attr(el, "marker-end", m)
                     | None => ()
                     };
                     disarm_dash(el);
                   }),
                   delay + duration,
                 ),
               );
             };
           };
         | None => ()
         }
       );
    /* an idle render leaves a fresh beat staged for the next one */
    if (did_anything^ || now_ms() -. b.b_staged_at > beat_expiry_ms) {
      beat := None;
      arrival_schedule := [];
      movers_at := None;
      geom_schedule := [];
    };
  };
};

module Actions = {
  /* ~stagger: ms between successive NEW elements' arrivals (0 = all at
     once); movers then wait for the arrivals and take ~move_dur, so a
     beat reads "new things appear, then the rest makes room" */
  let move = (~scale=1., ~delay=0, ~stagger=0, ~move_dur=125, id) => {
    id,
    animate: change =>
      switch (change) {
      | New(_) => {
          options: {
            duration: 125,
            easing: easeOutExpo,
            delay: delay + stagger_index^ * stagger_step(stagger),
          },
          keyframes: Keyframes.scale_from_zero,
        }
      | Existing(init, final) => {
          options: {
            duration: move_dur,
            easing: easeOutExpo,
            delay:
              delay
              + (
                switch (movers_at^) {
                | Some(ms) => max(0, ms - delay)
                | None =>
                  stagger > 0 && stagger_total^ > 0
                    ? max(stagger_span(stagger), arrival_span_override^)
                      + 120
                    : 0
                }
              ),
          },
          keyframes: Keyframes.translate(~scale, init, final),
        }
      },
  };
  /* slower, symmetric travel — used for the agent avatar, whose hops
     across the canvas should read as movement, not teleporting */
  let move_slow = (~scale=1., id) => {
    id,
    animate: change => {
      options: {
        duration: 450,
        easing: "cubic-bezier(0.65, 0, 0.35, 1)",
        delay: 0,
      },
      keyframes:
        switch (change) {
        | New(_) => Keyframes.scale_from_zero
        | Existing(init, final) => Keyframes.translate(~scale, init, final)
        },
    },
  };
};

let go = (): unit => {
  let now = () =>
    Js_of_ocaml.Js.Unsafe.coerce(Js_of_ocaml.Js.Unsafe.global)##._Date##now();
  let t0 = now();
  go_impl();
  let ms = now() -. t0;
  if (ms > 60.) {
    slow_hook^(Printf.sprintf("slow: animation pass %.0fms", ms));
  };
};

files.canvas/upstream/CanvasAvatar.re:
/* CanvasAvatar — the agent's second look: a small constellation rig
   (three vertices, three edges) with MOODS, next to the minimal "@"
   glyph. plans/agent-canvas-avatar-spec.md is the spec; this is its
   first pass: idle breathes and turns slowly, thinking spins and swaps
   emoji on the vertices, travel turns the leading vertex toward the
   destination behind a light beam and stretches, arrival squashes and
   settles, editing grows onto the node, drawing/erasing lead with the
   vertex as a pen, errors jitter red.

   The rig lives INSIDE .avatar-body (the WAAPI ride transform's target)
   on its own layers, so state transforms never fight the path:
     .avatar-body  (ride: WAAPI translate)
       .rig-heading  (CSS: --heading rotation, mood scale/squash, edit offset)
         svg.rig > g.rig-spin (CSS: spin / breathe)  + beam + glow
   Mood classes and --heading are written straight to the body element,
   which the view renders with a constant class, so re-renders leave them
   alone. The look is a toolbar toggle persisted in localStorage. */

open Js_of_ocaml;
open Virtual_dom.Vdom;

let look_key = "constellation.avatarLook";

/* localStorage may be absent or a stub (the node test runner): never
   let a storage failure take the module down at load */
let storage_get = (k: string): option(string) =>
  try(
    switch (
      Js.Optdef.to_option(Js.Unsafe.get(Js.Unsafe.global, "localStorage"))
    ) {
    | None => None
    | Some(ls) =>
      Js.Opt.to_option(
        Js.Unsafe.meth_call(
          ls,
          "getItem",
          [|Js.Unsafe.inject(Js.string(k))|],
        ),
      )
      |> Option.map(Js.to_string)
    }
  ) {
  | _ => None
  };
let storage_set = (k: string, v: string): unit =>
  try(
    switch (
      Js.Optdef.to_option(Js.Unsafe.get(Js.Unsafe.global, "localStorage"))
    ) {
    | None => ()
    | Some(ls) =>
      ignore(
        Js.Unsafe.meth_call(
          ls,
          "setItem",
          [|
            Js.Unsafe.inject(Js.string(k)),
            Js.Unsafe.inject(Js.string(v)),
          |],
        ),
      )
    }
  ) {
  | _ => ()
  };

/* "glyph" (the @ box) or "rig" */
let look: ref(string) =
  ref(
    switch (storage_get(look_key)) {
    | Some("glyph") => "glyph"
    | _ => "rig"
    },
  );
let is_rig = (): bool => look^ == "rig";
let toggle_look = (): unit => {
  look := is_rig() ? "glyph" : "rig";
  storage_set(look_key, look^);
  CanvasLog.log("avatar: look -> " ++ look^);
};

/* ---- the body element and its mood ---- */

let body = (): option(Js.t(Dom_html.element)) =>
  Util.JsUtil.get_elem_by_id_opt("canvas-avatar")
  |> Util.OptUtil.and_then(el =>
       Js.Opt.to_option(Js.Unsafe.get(el, "firstElementChild"))
     );

let moods = [
  "travel",
  "arrive",
  "edit",
  "draw",
  "erase",
  "tidy",
  "think",
  "held",
];
let current_mood: ref(string) = ref("");

let set_mood = (m: string): unit => {
  current_mood := m;
  switch (body()) {
  | None => ()
  | Some(b) =>
    let cl = Js.Unsafe.get(b, "classList");
    List.iter(
      x =>
        ignore(
          Js.Unsafe.meth_call(
            cl,
            "remove",
            [|Js.Unsafe.inject(Js.string("mood-" ++ x))|],
          ),
        ),
      moods,
    );
    if (m != "") {
      ignore(
        Js.Unsafe.meth_call(
          cl,
          "add",
          [|Js.Unsafe.inject(Js.string("mood-" ++ m))|],
        ),
      );
    };
  };
};

/* a heading hint from the score (degrees): used until the body actually
   moves, then its own motion steers it */
let heading_hint: ref(option(float)) = ref(None);
let set_heading = (deg: float): unit =>
  heading_hint := Some(deg *. Float.pi /. 180.);
let heading_of =
    ((x0, y0): (float, float), (x1, y1): (float, float)): float =>
  atan2(y1 -. y0, x1 -. x0) *. 180. /. Float.pi;

/* how far the segment about to be traveled goes (board px): the beam
   reaches further for a long trip, as the mockup's did */
let travel_len: ref(float) = ref(0.);
let set_travel_len = (len: float): unit => travel_len := len;
/* the beam fades in and out over a few frames (the demo's beamAlpha) */
let beam_alpha: ref(float) = ref(0.);
let last_thinking: ref(bool) = ref(false);
/* after an arrival the body swings back to a rest pose (sheet 2: rot lerped
   home at dt·2 after travel had turned it to face the heading) — the
   "shedding momentum" spin; here the nearest rest pose, for 1.2 s */
let settle_until: ref(float) = ref(0.);
let settle_home: ref(float) = ref(0.);

/* the arrow being drawn, set by the player for the ride's span: the
   leading vertex sits on the arrow's tip, so the body visibly pulls the
   line. The armed dash length is read off the element (data-on-len), so a
   re-armed ride (re-plan) stays right. */
let pen_path: ref(option(Js.Unsafe.any)) = ref(None);
let pen_tip = (): option((float, float)) =>
  switch (pen_path^) {
  | None => None
  | Some(path) =>
    let attr = (a: string): option(string) =>
      Js.Opt.to_option(
        Js.Unsafe.meth_call(
          path,
          "getAttribute",
          [|Js.Unsafe.inject(Js.string(a))|],
        ),
      )
      |> Option.map(Js.to_string);
    switch (
      attr("data-on-len") |> Util.OptUtil.and_then(float_of_string_opt)
    ) {
    | None => None
    | Some(on_len) =>
      let st =
        Js.Unsafe.meth_call(
          Js.Unsafe.global,
          "getComputedStyle",
          [|Js.Unsafe.inject(path)|],
        );
      let off: string = Js.to_string(Js.Unsafe.get(st, "strokeDashoffset"));
      let px = (v: string) =>
        switch (float_of_string_opt(String.trim(v))) {
        | Some(f) => f
        | None =>
          let n = String.length(v);
          n > 2
            ? Option.value(
                ~default=0.,
                float_of_string_opt(String.trim(String.sub(v, 0, n - 2))),
              )
            : 0.;
        };
      let total: float = Js.Unsafe.meth_call(path, "getTotalLength", [||]);
      let shown = max(0., min(total, on_len -. px(off)));
      let pt =
        Js.Unsafe.meth_call(
          path,
          "getPointAtLength",
          [|Js.Unsafe.inject(shown)|],
        );
      let x: float = Js.Unsafe.get(pt, "x")
      and y: float = Js.Unsafe.get(pt, "y");
      Some((x, y));
    };
  };

/* ---- the rig: three vertices on springs, driven every frame ----
   The mockup's body (plans/agent-canvas-mockups/avatar-concepts-4.html):
   targets on a breathing circle, each vertex a spring toward its target
   (k 170, damping 0.95 critical); traveling turns the triangle so vertex 0
   leads, pulls it ahead of the others (stiff leader, soft followers) and
   squashes on arrival; thinking spins; error jitters and drops an edge.
   The body's own screen motion (the WAAPI ride) gives heading and speed,
   so the beam always points where the body is actually going. */

type vtx = {
  mutable x: float,
  mutable y: float,
  mutable vx: float,
  mutable vy: float,
};

type rig = {
  v: array(vtx),
  mutable t: float,
  mutable rot: float,
  mutable rot_v: float, /* the post-landing swing's angular velocity */
  mutable heading: float,
  mutable speed: float, /* board px/s, smoothed */
  mutable aspect: float,
  mutable aspect_v: float,
  mutable was_traveling: bool,
  mutable last_pos: option((float, float)),
  mutable last_ms: float,
  mutable emoji_next: array(float),
  mutable emoji_cur: array(string),
  mutable running: bool,
};

let tau = 2. *. Float.pi;
let base_r = 11.; /* the triangle spans 22 px; a type node is 40+ */

let rig: rig = {
  v:
    Array.init(
      3,
      i => {
        let a = -. Float.pi /. 2. +. float_of_int(i) *. tau /. 3.;
        {
          x: cos(a) *. base_r,
          y: sin(a) *. base_r,
          vx: 0.,
          vy: 0.,
        };
      },
    ),
  t: Random.float(10.),
  rot: 0.,
  rot_v: 0.,
  heading: -. Float.pi /. 2.,
  speed: 0.,
  aspect: 1.,
  aspect_v: 0.,
  was_traveling: false,
  last_pos: None,
  last_ms: 0.,
  emoji_next: [|0., 0., 0.|],
  emoji_cur: [|{js|🍄|js}, {js|📦|js}, {js|🧩|js}|],
  running: false,
};

/* picked up: the grabbed vertex stays under the pointer (the body itself
   is carried by the pointer) while the other two dangle from it with
   inertia — the workload is paused meanwhile */
let held: ref(option(int)) = ref(None);
let held_shift: ref((float, float)) = ref((0., 0.));
let grab = ((mx, my): (float, float)): unit => {
  let best = ref(0)
  and bd = ref(infinity);
  for (i in 0 to 2) {
    let d = Float.hypot(rig.v[i].x -. mx, rig.v[i].y -. my);
    if (d < bd^) {
      bd := d;
      best := i;
    };
  };
  held := Some(best^);
  held_shift := (0., 0.);
};
/* how far the pointer carried the body since the last frame (board px) */
let nudge = ((dx, dy): (float, float)): unit => {
  let (ax, ay) = held_shift^;
  held_shift := (ax +. dx, ay +. dy);
};
let release = (): unit => {
  held := None;
  rig.speed = 0.;
  rig.last_pos = None;
};

let emoji = [|
  {js|🍄|js},
  {js|📦|js},
  {js|🧩|js},
  {js|🎯|js},
  {js|🐚|js},
  {js|🌰|js},
  {js|🍋|js},
  {js|🥑|js},
  {js|🧀|js},
  {js|🍩|js},
  {js|🐙|js},
  {js|🦀|js},
  {js|🐌|js},
  {js|🐢|js},
  {js|🦉|js},
  {js|🌵|js},
  {js|🌻|js},
  {js|💎|js},
  {js|🔮|js},
  {js|🧸|js},
  {js|🎈|js},
  {js|🎲|js},
  {js|🧲|js},
  {js|🔑|js},
  {js|🪐|js},
  {js|🌙|js},
  {js|⭐|js},
  {js|🐞|js},
  {js|🐝|js},
  {js|🦋|js},
  {js|🍀|js},
|];

let anchor_has = (cls: string): bool =>
  switch (Util.JsUtil.get_elem_by_id_opt("canvas-avatar")) {
  | Some(el) =>
    Js.to_bool(
      Js.Unsafe.meth_call(
        Js.Unsafe.get(el, "classList"),
        "contains",
        [|Js.Unsafe.inject(Js.string(cls))|],
      ),
    )
  | None => false
  };

let lerp = (a, b, t) => a +. (b -. a) *. t;
let set = (el, name: string, v: string): unit =>
  ignore(
    Js.Unsafe.meth_call(
      el,
      "setAttribute",
      [|
        Js.Unsafe.inject(Js.string(name)),
        Js.Unsafe.inject(Js.string(v)),
      |],
    ),
  );
let f1 = (x: float): string => Printf.sprintf("%.1f", x);
let q = (b, sel: string) =>
  Js.Unsafe.meth_call(
    b,
    "querySelectorAll",
    [|Js.Unsafe.inject(Js.string(sel))|],
  );
let item = (nodes, i: int) =>
  Js.Unsafe.meth_call(nodes, "item", [|Js.Unsafe.inject(i)|]);

/* write the rig's current geometry into a root holding .rig-edge /
   .rig-dot / .rig-disc / .rig-emo triples (the body's svg, or a mirror) */
let draw_rig = (root, ~thinking: bool, ~err: bool): unit => {
  let edges = q(root, ".rig-edge")
  and dots = q(root, ".rig-dot")
  and discs = q(root, ".rig-disc")
  and texts = q(root, ".rig-emo");
  let n: int = Js.Unsafe.get(edges, "length");
  if (n >= 3) {
    let hide_edge = err ? int_of_float(rig.t *. 6.) mod 3 : (-1);
    for (i in 0 to 2) {
      let a = rig.v[i]
      and c = rig.v[(i + 1) mod 3];
      let e = item(edges, i);
      set(e, "x1", f1(a.x));
      set(e, "y1", f1(a.y));
      set(e, "x2", f1(c.x));
      set(e, "y2", f1(c.y));
      set(e, "opacity", hide_edge == i ? "0.08" : "0.9");
      let d = item(dots, i);
      set(d, "cx", f1(a.x));
      set(d, "cy", f1(a.y));
      set(d, "opacity", thinking ? "0" : "1");
      let disc = item(discs, i);
      set(disc, "cx", f1(a.x));
      set(disc, "cy", f1(a.y));
      set(disc, "opacity", thinking ? "1" : "0");
      let t = item(texts, i);
      set(t, "x", f1(a.x));
      set(t, "y", f1(a.y));
      set(t, "opacity", thinking ? "1" : "0");
      if (thinking) {
        Js.Unsafe.set(t, "textContent", Js.string(rig.emoji_cur[i]));
      };
    };
  };
};

/* the mirrors on the page: the last one is live; any that has never been
   drawn (a new chat row) gets the current pose once, and keeps it */
let mirrors = (): (list(Js.Unsafe.any), option(Js.Unsafe.any)) => {
  let all =
    Js.Unsafe.meth_call(
      Js.Unsafe.global##.document,
      "querySelectorAll",
      [|Js.Unsafe.inject(Js.string(".rig-mirror"))|],
    );
  let n: int = Js.Unsafe.get(all, "length");
  let fresh = ref([]);
  for (i in 0 to n - 2) {
    let m = item(all, i);
    let dot = item(q(m, ".rig-dot"), 0);
    let cx =
      Js.Opt.to_option(
        Js.Unsafe.meth_call(
          dot,
          "getAttribute",
          [|Js.Unsafe.inject(Js.string("cx"))|],
        ),
      );
    if (cx == None) {
      fresh := [m, ...fresh^];
    };
  };
  (fresh^, n == 0 ? None : Some(item(all, n - 1)));
};

/* one frame: read the body's motion, move the targets, spring, draw */
/* Undo the camera's translation and rendered scale before measuring
   motion. Screen motion alone must not turn thinking into travelling. */
let board_position =
    (~origin: (float, float), ~zoom: float, (x, y): (float, float))
    : (float, float) => {
  let (ox, oy) = origin;
  ((x -. ox) /. zoom, (y -. oy) /. zoom);
};

let step = (b: option(Js.t(Dom_html.element)), now_ms: float): unit => {
  let dt = min(0.05, max(0.001, (now_ms -. rig.last_ms) /. 1000.));
  rig.last_ms = now_ms;
  rig.t = rig.t +. dt;
  /* The ride transform is included, but camera pan and zoom are not.
     Read the rendered zoom: a CSS zoom transition may be between the
     setting's endpoints. */
  /* without a body on stage (canvas hidden, chat open) the rig idles in
     place and only the chat's mirror is drawn */
  let (mdx, mdy) =
    switch (
      b
      |> Util.OptUtil.and_then(b =>
           Js.Opt.to_option(
             Js.Unsafe.meth_call(
               b,
               "closest",
               [|Js.Unsafe.inject(Js.string(".canvas-root"))|],
             ),
           )
           |> Option.map(root => (b, root))
         )
    ) {
    | Some((b, root)) =>
      let rect = Js.Unsafe.meth_call(b, "getBoundingClientRect", [||]);
      let rr = Js.Unsafe.meth_call(root, "getBoundingClientRect", [||]);
      let style =
        Js.Unsafe.meth_call(
          Js.Unsafe.global,
          "getComputedStyle",
          [|Js.Unsafe.inject(root)|],
        );
      let zoom =
        Js.to_string(Js.Unsafe.get(style, "zoom"))
        |> float_of_string_opt
        |> Option.value(~default=1.)
        |> CanvasZoom.clamp;
      let (cx, cy) =
        board_position(
          ~origin=(Js.Unsafe.get(rr, "left"), Js.Unsafe.get(rr, "top")),
          ~zoom,
          (Js.Unsafe.get(rect, "left"), Js.Unsafe.get(rect, "top")),
        );
      let d =
        switch (rig.last_pos) {
        | Some((px, py)) => (cx -. px, cy -. py)
        | None => (0., 0.)
        };
      rig.last_pos = Some((cx, cy));
      d;
    | None =>
      rig.last_pos = None;
      (0., 0.);
    };
  let inst = Float.hypot(mdx, mdy) /. dt;
  rig.speed = lerp(rig.speed, min(inst, 600.), min(1., dt *. 10.));
  let moving = rig.speed > 25.;
  if (Float.hypot(mdx, mdy) > 0.6) {
    let want = atan2(mdy, mdx);
    let da = ref(want -. rig.heading);
    while (da^ > Float.pi) {
      da := da^ -. tau;
    };
    while (da^ < -. Float.pi) {
      da := da^ +. tau;
    };
    rig.heading = rig.heading +. da^ *. min(1., dt *. 8.);
  } else {
    switch (heading_hint^) {
    | Some(h) when !moving =>
      let da = ref(h -. rig.heading);
      while (da^ > Float.pi) {
        da := da^ -. tau;
      };
      while (da^ < -. Float.pi) {
        da := da^ +. tau;
      };
      rig.heading = rig.heading +. da^ *. min(1., dt *. 4.);
    | _ => ()
    };
  };
  let mood = current_mood^;
  let is_held = held^ != None;
  /* the state class is a render-time reading (stale through a score with
     few renders): read the score live, and never think while moving —
     the depicted timeline is the score's, so an enacted edit is editing
     even if the model is literally already thinking about the next step */
  let score_on = CanvasBuffer.score_playing();
  let thinking0 = anchor_has("avatar-think") || mood == "think";
  let err = anchor_has("avatar-err");
  let pen = (mood == "draw" || mood == "erase") && !is_held;
  let traveling = (moving || pen && rig.speed > 8.) && !is_held;
  let thinking = thinking0 && !score_on && !traveling && !pen && !is_held;
  last_thinking := thinking;
  let editing =
    (mood == "edit" || anchor_has("avatar-edit") && score_on)
    && !moving
    && !pen
    && !is_held;
  if (!traveling) {
    /* the trip is over: the beam's reach eases back */
    travel_len := travel_len^ *. (1. -. min(1., dt *. 4.));
  };
  /* arrival: squash along the heading, then spring back */
  if (rig.was_traveling && !traveling) {
    rig.aspect = 0.72;
    rig.aspect_v = 0.;
    /* swing to a rest pose after landing, "shedding momentum": an
       underdamped spring, kicked harder after a faster trip */
    let third = tau /. 3.;
    settle_home := Float.round(rig.rot /. third) *. third;
    settle_until := rig.t +. 1.6;
    let dir = settle_home^ >= rig.rot ? 1. : (-1.);
    rig.rot_v = dir *. (2.5 +. 5. *. min(1., rig.speed /. 220.));
  };
  rig.was_traveling = traveling;
  rig.aspect_v =
    rig.aspect_v
    +. (-. (rig.aspect -. 1.) *. 170. -. rig.aspect_v *. 12.)
    *. dt;
  rig.aspect = rig.aspect +. rig.aspect_v *. dt;
  /* breathing with a slowly drifting amplitude; never quite still */
  let amp = 0.12 *. (0.75 +. 0.25 *. sin(rig.t *. 0.37));
  let breathe = 1. +. amp *. sin(rig.t *. 2.0);
  let r = ref(base_r *. breathe);
  let k = ref(170.)
  and k_follow = ref(170.);
  let jitter = ref(0.);
  let stretch = min(1., rig.speed /. 220.);
  /* spin by state */
  if (traveling) {
    let head_rot = rig.heading +. Float.pi /. 2.;
    let da = ref(head_rot -. rig.rot);
    while (da^ > Float.pi) {
      da := da^ -. tau;
    };
    while (da^ < -. Float.pi) {
      da := da^ +. tau;
    };
    rig.rot = rig.rot +. da^ *. min(1., dt *. 6.);
    k := 240.;
    k_follow := 55.;
  } else if (thinking) {
    rig.rot = rig.rot +. dt *. 1.6 *. (1. +. 0.25 *. sin(rig.t *. 0.7));
    r := r^ *. 1.15;
  } else if (editing) {
    rig.rot = rig.rot +. dt *. 0.5;
    r := r^ *. 1.35;
  } else if (rig.t < settle_until^) {
    /* just landed: an underdamped swing about the rest pose fixed at
       landing (k 60, zeta 0.3: two or three visible overshoots) */
    let k = 60.;
    let d = 2. *. sqrt(k) *. 0.3;
    rig.rot_v =
      rig.rot_v +. ((settle_home^ -. rig.rot) *. k -. rig.rot_v *. d) *. dt;
    rig.rot = rig.rot +. rig.rot_v *. dt;
  } else {
    rig.rot_v = 0.;
    /* idle: a slow turn, so it is never a still picture */
    rig.rot = rig.rot +. dt *. 0.18;
  };
  if (err) {
    jitter := 3.;
    r := r^ *. 0.95;
  };
  /* the rig's center: on the node while editing (the anchor hangs
     above-right of the site by (14, -34)), a gentle bob otherwise */
  let (ox, oy) = editing ? ((-14.), 34.) : (0., 1.4 *. sin(rig.t *. 2.4));
  let hc = cos(rig.heading +. Float.pi /. 2.)
  and hs = sin(rig.heading +. Float.pi /. 2.);
  switch (held^) {
  | Some(g) =>
    /* carried: the grabbed vertex holds still under the pointer; the
       others keep their place on the board as the body moves (inertia),
       then swing back under it on a loose spring */
    let (sx, sy) = held_shift^;
    held_shift := (0., 0.);
    let gv = rig.v[g];
    gv.vx = 0.;
    gv.vy = 0.;
    let side = ref(-1.);
    for (i in 0 to 2) {
      if (i != g) {
        let n = rig.v[i];
        n.x = n.x -. sx *. 0.9;
        n.y = n.y -. sy *. 0.9;
        let tx = gv.x +. side^ *. 7.
        and ty = gv.y +. 15.;
        side := -. side^;
        let kk = 60.;
        let dd = 2. *. sqrt(kk) *. 0.25;
        n.vx = n.vx +. ((tx -. n.x) *. kk -. n.vx *. dd) *. dt;
        n.vy = n.vy +. ((ty -. n.y) *. kk -. n.vy *. dd) *. dt;
        n.x = n.x +. n.vx *. dt;
        n.y = n.y +. n.vy *. dt;
      };
    };
  | None =>
    for (i in 0 to 2) {
      let a = -. Float.pi /. 2. +. float_of_int(i) *. tau /. 3. +. rig.rot;
      let lx = cos(a) *. r^
      and ly = sin(a) *. r^;
      /* squash along the heading frame */
      let ax = lx *. hc +. ly *. hs
      and ay = (-. lx *. hs +. ly *. hc) *. (traveling ? 1. : rig.aspect);
      let tx = ref(ax *. hc -. ay *. hs +. ox)
      and ty = ref(ax *. hs +. ay *. hc +. oy);
      if (traveling && i == 0) {
        let ahead = 16. *. stretch;
        tx := tx^ +. cos(rig.heading) *. ahead;
        ty := ty^ +. sin(rig.heading) *. ahead;
      };
      let n = rig.v[i];
      let kk = i == 0 ? k^ : k_follow^;
      let dd = 2. *. sqrt(kk) *. 0.95;
      n.vx = n.vx +. ((tx^ -. n.x) *. kk -. n.vx *. dd) *. dt;
      n.vy = n.vy +. ((ty^ -. n.y) *. kk -. n.vy *. dd) *. dt;
      n.x = n.x +. n.vx *. dt;
      n.y = n.y +. n.vy *. dt;
      if (jitter^ > 0.) {
        n.x = n.x +. (Random.float(1.) -. 0.5) *. jitter^ *. 2.;
        n.y = n.y +. (Random.float(1.) -. 0.5) *. jitter^ *. 2.;
      };
    }
  };
  /* drawing: the leading vertex is pinned to the arrow's tip (path units
     are board units; the rig's svg is centered on its own box), within a
     reach the springs could plausibly stretch to */
  switch (b, pen ? pen_tip() : None) {
  | (Some(b), Some((tx, ty))) =>
    let svg = item(q(b, ".rig"), 0);
    let root =
      Js.Unsafe.meth_call(
        Js.Unsafe.global##.document,
        "querySelector",
        [|Js.Unsafe.inject(Js.string(".canvas-root"))|],
      );
    if (Js.Opt.test(svg) && Js.Opt.test(root)) {
      let sr = Js.Unsafe.meth_call(svg, "getBoundingClientRect", [||])
      and rr = Js.Unsafe.meth_call(root, "getBoundingClientRect", [||]);
      let sl: float = Js.Unsafe.get(sr, "left")
      and sw: float = Js.Unsafe.get(sr, "width")
      and st: float = Js.Unsafe.get(sr, "top")
      and sh: float = Js.Unsafe.get(sr, "height")
      and rl: float = Js.Unsafe.get(rr, "left")
      and rt: float = Js.Unsafe.get(rr, "top");
      let zoom = CanvasZoom.clamp(CanvasBuffer.canvas_zoom^);
      let ox = (sl +. sw /. 2. -. rl) /. zoom
      and oy = (st +. sh /. 2. -. rt) /. zoom;
      let lx = tx -. ox
      and ly = ty -. oy;
      if (Float.hypot(lx, ly) < 60.) {
        let n = rig.v[0];
        n.x = lx;
        n.y = ly;
        n.vx = 0.;
        n.vy = 0.;
      };
    };
  | _ => ()
  };
  /* thinking: emoji on the vertices, each on its own irregular clock */
  if (thinking) {
    for (i in 0 to 2) {
      if (rig.t >= rig.emoji_next[i]) {
        rig.emoji_cur[i] = emoji[Random.int(Array.length(emoji))];
        rig.emoji_next[i] = rig.t +. 0.25 +. Random.float(0.6);
      };
    };
  };
  switch (b) {
  | Some(b) => draw_rig(b, ~thinking, ~err)
  | None => ()
  };
  /* the chat's brand icon mirrors the live rig (the last one in the
     chat; earlier ones keep the state they froze in) */
  let (fresh, last) = mirrors();
  List.iter(m => draw_rig(m, ~thinking, ~err), fresh);
  switch (last) {
  | Some(m) => draw_rig(m, ~thinking, ~err)
  | None => ()
  };
  /* the beam: the demo's — a sector of spread 0.36 and length 150 at R 18
     (so 8.3 R), filled by a radial gradient from the leading vertex
     (#ffe58a 0.55 -> 0), eased in and out; the glow disc at the vertex */
  switch (b) {
  | None => ()
  | Some(bb) =>
    let lead = rig.v[0];
    let beam = item(q(bb, ".rig-beam"), 0)
    and glow = item(q(bb, ".rig-glow"), 0)
    and grad = item(q(bb, ".rig-beam-grad"), 0);
    let want = traveling && !pen ? 1. : 0.;
    beam_alpha := beam_alpha^ +. (want -. beam_alpha^) *. min(1., dt *. 8.);
    let reach = base_r *. 150. /. 18.;
    let h = rig.heading
    and spread = 0.36;
    set(
      beam,
      "d",
      Printf.sprintf(
        "M %s %s L %s %s A %s %s 0 0 1 %s %s Z",
        f1(lead.x),
        f1(lead.y),
        f1(lead.x +. cos(h -. spread) *. reach),
        f1(lead.y +. sin(h -. spread) *. reach),
        f1(reach),
        f1(reach),
        f1(lead.x +. cos(h +. spread) *. reach),
        f1(lead.y +. sin(h +. spread) *. reach),
      ),
    );
    set(beam, "opacity", f1(beam_alpha^));
    set(grad, "cx", f1(lead.x));
    set(grad, "cy", f1(lead.y));
    set(grad, "r", f1(reach));
    set(glow, "cx", f1(lead.x));
    set(glow, "cy", f1(lead.y));
    set(glow, "opacity", f1(0.5 *. max(beam_alpha^, pen ? 1. : 0.)));
  };
};

let rec loop = (now_ms: float): unit =>
  if (!is_rig()) {
    rig.running = false;
  } else {
    /* a long stall would make the springs explode: the dt clamp in
       step handles it, but a fresh dt anchor is safer */
    if (now_ms -. rig.last_ms > 500.) {
      rig.last_ms = now_ms -. 16.;
    };
    step(body(), now_ms);
    ignore(
      Js.Unsafe.global##requestAnimationFrame(Js.Unsafe.callback(loop)),
    );
  };

let ensure_loop = (): unit =>
  if (!rig.running) {
    rig.running = true;
    rig.last_ms = Js.Unsafe.global##.performance##now() -. 16.;
    ignore(
      Js.Unsafe.global##requestAnimationFrame(Js.Unsafe.callback(loop)),
    );
  };

/* ---- the rig (vdom): static structure only; every animated attribute
   is written by the loop, and the vdom never declares those, so a
   re-render cannot fight it ---- */

let svg = (tag, attrs, kids) => Node.create_svg(tag, ~attrs, kids);

let rig_view = (): Node.t => {
  ensure_loop();
  let three = f => List.init(3, f);
  Node.div(
    ~attrs=[Attr.classes(["rig-box"])],
    [
      svg(
        "svg",
        [
          Attr.classes(["rig"]),
          Attr.create("viewBox", "-40 -40 80 80"),
          Attr.create("width", "80"),
          Attr.create("height", "80"),
        ],
        [
          svg(
            "defs",
            [],
            [
              svg(
                "radialGradient",
                [
                  Attr.id("rig-beam-grad"),
                  Attr.classes(["rig-beam-grad"]),
                  Attr.create("gradientUnits", "userSpaceOnUse"),
                ],
                [
                  svg(
                    "stop",
                    [
                      Attr.create("offset", "0"),
                      Attr.create("stop-color", "#ffe58a"),
                      Attr.create("stop-opacity", "0.55"),
                    ],
                    [],
                  ),
                  svg(
                    "stop",
                    [
                      Attr.create("offset", "1"),
                      Attr.create("stop-color", "#ffe58a"),
                      Attr.create("stop-opacity", "0"),
                    ],
                    [],
                  ),
                ],
              ),
            ],
          ),
          svg(
            "path",
            [
              Attr.classes(["rig-beam"]),
              Attr.create("fill", "url(#rig-beam-grad)"),
            ],
            [],
          ),
          svg(
            "circle",
            [Attr.classes(["rig-glow"]), Attr.create("r", "6")],
            [],
          ),
        ]
        @ three(_ => svg("line", [Attr.classes(["rig-edge"])], []))
        @ three(_ =>
            svg(
              "circle",
              [Attr.classes(["rig-disc"]), Attr.create("r", "6.5")],
              [],
            )
          )
        @ three(i =>
            svg(
              "circle",
              [
