let clean_cut = (s: string): string => {
  let n = String.length(s);
  let rec trim_head = i =>
    if (i < n && Char.code(s.[i]) land 0xC0 == 0x80) {
      trim_head(i + 1);
    } else {
      i;
    };
  let h = trim_head(0);
  let rec trim_tail = j =>
    if (j > h && Char.code(s.[j - 1]) land 0xC0 == 0x80) {
      trim_tail(j - 1);
    } else if (j > h && Char.code(s.[j - 1]) land 0xC0 == 0xC0) {
      j - 1;
    } else {
      j;
    };
  let t = trim_tail(n);
  t > h ? String.sub(s, h, t - h) : "";
