    switch (sx < 0., sy < 0.) {
    | (true, true) => 2 /* bubble up-left of the avatar: tail at BR */
    | (false, true) => 3 /* up-right: BL */
    | (true, false) => 1 /* down-left: TR */
    | (false, false) => 0 /* down-right: TL */
