open Js_of_ocaml;

/* CanvasJelly — inertia for the module metaballs.

   Each hull circle is a damped spring chasing its target (the position
   the layout wants). When nodes move — drags, re-layouts, collapse —
   targets jump and the circles lag, overshoot, and settle; since the
   blob boundary is the union of the circles, the hull visibly
   stretches and wobbles like jelly. Bigger circles are heavier
   (softer springs), so parents slosh behind their contents.

   Targets are pushed by the render and by the drag-time layout applier
   (CanvasView.hull_targets); this module owns the circles' cx/cy while
   any spring is unsettled. */

type spring = {
  mutable x: float,
  mutable y: float,
  mutable vx: float,
  mutable vy: float,
  mutable tx: float,
  mutable ty: float,
  mutable r: float,
  mutable seen: bool,
  /* a scored relayout: the circle GLIDES from (gx, gy) to its target on
     the nodes' own schedule (start, duration, ease-out-expo) instead of
     springing — springs led the nodes by most of a second and overshot
     ("the metaballs are out of sync with the nodes") */
  mutable glide: option((float, float, float, float)) /* gx gy t0 dur */
};

/* ease-out-expo, the movers' curve (Animation.easeOutExpo) */
let ease = (u: float): float =>
  u >= 1. ? 1. : 1. -. Float.pow(2., (-10.) *. u);

let springs: Hashtbl.t(string, spring) = Hashtbl.create(64);
let running = ref(false);
let last_t = ref(0.);

let now = (): float => Js.Unsafe.coerce(Js.Unsafe.global)##._Date##now();

let set_attr = (el, name: string, v: float): unit =>
  ignore(
    Js.Unsafe.meth_call(
      el,
      "setAttribute",
      [|
        Js.Unsafe.inject(Js.string(name)),
        Js.Unsafe.inject(Js.string(Printf.sprintf("%.1f", v))),
      |],
    ),
  );

let rec tick = (): unit => {
  let t = now();
  let dt = min(0.04, max(0.001, (t -. last_t^) /. 1000.));
  last_t := t;
  let energy = ref(0.);
  let dead: ref(list(string)) = ref([]);
  Hashtbl.iter(
    (id, s) => {
      switch (s.glide) {
      | Some((gx, gy, t0, dur)) =>
        let u = dur <= 0. ? 1. : (t -. t0) /. dur;
        if (u >= 1.) {
          s.x = s.tx;
          s.y = s.ty;
          s.vx = 0.;
          s.vy = 0.;
          s.glide = None;
        } else if (u > 0.) {
          let e = ease(u);
          s.x = gx +. (s.tx -. gx) *. e;
          s.y = gy +. (s.ty -. gy) *. e;
        };
      | None =>
        /* stiffness scales inversely with radius: big = heavy = sloshy */
        let k = 260. *. (42. /. max(20., s.r));
        let c = 2. *. Float.sqrt(k) *. 0.62; /* underdamped: wobble */
        let ax = k *. (s.tx -. s.x) -. c *. s.vx
        and ay = k *. (s.ty -. s.y) -. c *. s.vy;
        s.vx = s.vx +. ax *. dt;
        s.vy = s.vy +. ay *. dt;
        s.x = s.x +. s.vx *. dt;
        s.y = s.y +. s.vy *. dt;
      };
      energy :=
        energy^
        +. abs_float(s.tx -. s.x)
        +. abs_float(s.ty -. s.y)
        +. 0.05
        *. (abs_float(s.vx) +. abs_float(s.vy));
      switch (Util.JsUtil.get_elem_by_id_opt(id)) {
      | Some(el) =>
        set_attr(el, "cx", s.x);
        set_attr(el, "cy", s.y);
      | None => dead := [id, ...dead^]
      };
    },
    springs,
  );
  List.iter(id => Hashtbl.remove(springs, id), dead^);
  if (energy^ > 0.8 && Hashtbl.length(springs) > 0) {
    let _ =
      Js.Unsafe.meth_call(
        Js.Unsafe.global##.window,
        "requestAnimationFrame",
        [|Js.Unsafe.inject(Js.Unsafe.callback(() => tick()))|],
      );
    ();
  } else {
    /* settle exactly on target before sleeping */
    Hashtbl.iter(
      (id, s) => {
        s.x = s.tx;
        s.y = s.ty;
        s.vx = 0.;
        s.vy = 0.;
        switch (Util.JsUtil.get_elem_by_id_opt(id)) {
        | Some(el) =>
          set_attr(el, "cx", s.x);
          set_attr(el, "cy", s.y);
        | None => ()
        };
      },
      springs,
    );
    running := false;
  };
};

let kick = (): unit =>
  if (! running^) {
    running := true;
    last_t := now();
    let _ =
      Js.Unsafe.meth_call(
        Js.Unsafe.global##.window,
        "requestAnimationFrame",
        [|Js.Unsafe.inject(Js.Unsafe.callback(() => tick()))|],
      );
    ();
  };

/* push fresh targets; unseen circles are born AT their target (no
   fly-in), known circles keep their current state and chase */
let set_targets =
    /* Some((start, dur)): a staged beat — existing circles glide on the
       nodes' schedule; None: springs (drags, idle relayouts) */
    (
      ~glide: option((float, float))=None,
      ts: list((string, CanvasLayout.pos, float)),
    )
    : unit => {
  Hashtbl.iter((_, s) => s.seen = false, springs);
  List.iter(
    ((id, p: CanvasLayout.pos, r)) =>
      switch (Hashtbl.find_opt(springs, id)) {
      | Some(s) =>
        let moved =
          abs_float(p.x -. s.tx) > 0.5 || abs_float(p.y -. s.ty) > 0.5;
        if (moved) {
          switch (glide) {
          | Some((t0, dur)) => s.glide = Some((s.x, s.y, t0, dur))
          | None => ()
          };
        };
        s.tx = p.x;
        s.ty = p.y;
        s.r = r;
        s.seen = true;
      | None =>
        Hashtbl.replace(
          springs,
          id,
          {
            x: p.x,
            y: p.y,
            vx: 0.,
            vy: 0.,
            tx: p.x,
            ty: p.y,
            r,
            seen: true,
            glide: None,
          },
        )
      },
    ts,
  );
  /* circles gone from the layout: drop their springs */
  let dead =
    Hashtbl.fold((id, s, acc) => s.seen ? acc : [id, ...acc], springs, []);
  List.iter(id => Hashtbl.remove(springs, id), dead);
  kick();
};

/* Opt-in layout lab. Research engines do not change the default. Placement consumes geometry,
   not editor state; histories are scoped to a slide and a variant. */
type point = {
  x: float,
  y: float,
};
type item = {
  key: string,
  p: point,
  w: float,
  h: float,
  anchor: option(string),
};
let modes = [
  ("current", "Current"),
  ("packed", "Packed groups"),
  ("stable", "Stable growth"),
  ("grid", "Grid"),
  ("relaxed", "Soft anchors"),
  ("flow", "Function layers"),
  ("dependencies", "Type layers"),
  ("elk", "ELK layers →"),
  ("elk-down", "ELK layers ↓"),
  ("cola", "CoLa modules"),
  ("cola-live", "CoLa anchored growth"),
];
let research = k => List.mem(k, ["elk", "elk-down", "cola", "cola-live"]);
let revision = ref(0);
let on_result = ref(() => ());
let awaiting_fit = ref(false);
let mode = ref("current");
let wires = ref("curves");
let scene = ref("");
let generation = ref(0);
let histories: ref(list((string, list(item)))) = ref([]);
let known = s => List.mem_assoc(s, modes);
let history_key = () => scene^ ++ "/" ++ mode^;
let previous = () =>
  Option.value(~default=[], List.assoc_opt(history_key(), histories^));
let reset = () => {
  histories := List.remove_assoc(history_key(), histories^);
  incr(generation);
};
let remember = items => {
  histories :=
    [
      (history_key(), items),
      ...List.filteri(
           (i, _) => i < 20,
           List.remove_assoc(history_key(), histories^),
         ),
    ];
};
let snap = x => Float.round(x /. 14.) *. 14.;
let distance = (a: point, b: point) => Float.hypot(a.x -. b.x, a.y -. b.y);
let at = (items, key) => List.find_opt((n: item) => n.key == key, items);
let overlaps = (a: item, b: item, pad) =>
  abs_float(a.p.x -. b.p.x) < (a.w +. b.w)
  /. 2.
  +. pad
  && abs_float(a.p.y -. b.p.y) < (a.h +. b.h)
  /. 2.
  +. pad;
let links_of = (items, links) =>
  links
  @ List.filter_map(
      (n: item) => Option.map(a => (n.key, a), n.anchor),
      items,
    );
let groups = (items, links) => {
  let rec grow = ks => {
    let next =
      List.sort_uniq(
        compare,
        ks
        @ List.concat_map(
            ((a, b)) =>
              List.mem(a, ks) ? [b] : List.mem(b, ks) ? [a] : [],
            links,
          ),
      )
      |> List.filter(k => at(items, k) != None);
    next == List.sort_uniq(compare, ks) ? next : grow(next);
  };
  List.fold_left(
    (acc, n: item) =>
      List.exists(List.mem(n.key), acc) ? acc : acc @ [grow([n.key])],
    [],
    items,
  );
};
/* Remove rows occupied only by other components, then shelf-pack component
   rectangles. This is a deliberately stateless comparison to stable growth. */
let packed = (items, links) => {
  let blocks =
    List.map(
      keys => {
        let ns = List.filter((n: item) => List.mem(n.key, keys), items);
        let minx =
          List.fold_left(
            (x, n: item) => min(x, n.p.x -. n.w /. 2.),
            infinity,
            ns,
          );
        /* Remove only genuinely empty strips. Rows in different columns
           may overlap in y; forcing a gap between every y-coordinate would
           turn a compact graph into a staircase. */
        let intervals =
          List.map(
            (n: item) => (n.p.y -. n.h /. 2., n.p.y +. n.h /. 2.),
            ns,
          )
          |> List.sort(compare);
        let (_, gaps) =
          List.fold_left(
            ((end_y, gaps), (lo, hi)) =>
              (
                max(end_y, hi),
                lo -. end_y > 100. && end_y != neg_infinity
                  ? gaps @ [(lo, lo -. end_y -. 100.)] : gaps,
              ),
            (neg_infinity, []),
            intervals,
          );
        let miny =
          List.fold_left(
            (v, n: item) => min(v, n.p.y -. n.h /. 2.),
            infinity,
            ns,
          );
        let ns =
          List.map(
            (n: item) =>
              {
                ...n,
                p: {
                  x: n.p.x -. minx,
                  y:
                    n.p.y
                    -. miny
                    -. List.fold_left(
                         (v, (at, amount)) => n.p.y >= at ? v +. amount : v,
                         0.,
                         gaps,
                       ),
                },
              },
            ns,
          );

        let w =
          List.fold_left(
            (v, n: item) => max(v, n.p.x +. n.w /. 2.),
            0.,
            ns,
          );
        let h =
          List.fold_left(
            (v, n: item) => max(v, n.p.y +. n.h /. 2.),
            0.,
            ns,
          );
        (ns, w, h);
      },
      groups(items, links),
    );
  let area =
    List.fold_left(
      (a, (_, w, h)) => a +. (w +. 60.) *. (h +. 60.),
      0.,
      blocks,
    );
  let target = max(650., sqrt(area *. 1.5));
  let (_, _, _, out) =
    List.fold_left(
      ((x, y, rowh, acc), (ns, w, h)) => {
        let (x, y, rowh) =
          x > 70. && x +. w > target
            ? (70., y +. rowh +. 70., 0.) : (x, y, rowh);
        (
          x +. w +. 70.,
          y,
          max(rowh, h),
          acc
          @ List.map(
              (n: item) =>
                {
                  ...n,
                  p: {
                    x: snap(n.p.x +. x),
                    y: snap(n.p.y +. y),
                  },
                },
              ns,
            ),
        );
      },
      (70., 70., 0., []),
      blocks,
    );
  out;
};
/* Keep per-use terminals with their host rather than spending a grid cell
   on every Int/String leaf. A cluster occupies its full local envelope. */
let grid = (items, links) => {
  let rec root = (seen, n: item) =>
    switch (n.anchor) {
    | Some(k) when !List.mem(k, seen) =>
      switch (at(items, k)) {
      | Some(host) => root([n.key, ...seen], host)
      | None => n.key
      }
    | _ => n.key
    };
  let keys = groups(items, links) |> List.concat;
  let roots =
    List.filter_map(k => Option.map(n => root([], n), at(items, k)), keys)
    |> List.fold_left((acc, k) => List.mem(k, acc) ? acc : acc @ [k], []);
  let clusters =
    List.map(
      k => {
        let ns = List.filter((n: item) => root([], n) == k, items);
        let x0 =
          List.fold_left(
            (v, n: item) => min(v, n.p.x -. n.w /. 2.),
            infinity,
            ns,
          )
        and y0 =
          List.fold_left(
            (v, n: item) => min(v, n.p.y -. n.h /. 2.),
            infinity,
            ns,
          );
        let w =
          List.fold_left(
            (v, n: item) => max(v, n.p.x +. n.w /. 2. -. x0),
            0.,
            ns,
          )
        and h =
          List.fold_left(
            (v, n: item) => max(v, n.p.y +. n.h /. 2. -. y0),
            0.,
            ns,
          );
        (ns, x0, y0, w, h);
      },
      roots,
    );
  let columns =
    max(
      2,
      int_of_float(
        ceil(sqrt(float_of_int(List.length(clusters)) *. 1.3)),
      ),
    );
  let w =
    List.fold_left(
      (v, (_, _, _, w, _)) => max(v, w +. 75.),
      196.,
      clusters,
    )
  and h =
    List.fold_left(
      (v, (_, _, _, _, h)) => max(v, h +. 70.),
      154.,
      clusters,
    );
  List.mapi(
    (i, (ns, x0, y0, _, _)) =>
      List.map(
        (n: item) =>
          {
            ...n,
            p: {
              x:
                snap(70. +. float_of_int(i mod columns) *. w +. n.p.x -. x0),
              y: snap(70. +. float_of_int(i / columns) *. h +. n.p.y -. y0),
            },
          },
        ns,
      ),
    clusters,
  )
  |> List.concat;
};
let stable = (items, links, old) => {
  let kept =
    List.filter_map(
      (n: item) =>
        Option.map(
          (p: item) =>
            {
              ...n,
              p: p.p,
            },
          at(old, n.key),
        ),
      items,
    );
  if (kept == []) {
    packed(items, links);
  } else {
    List.fold_left(
      (placed, n: item) =>
        if (at(placed, n.key) != None) {
          placed;
        } else {
          let peers =
            List.filter_map(
              ((a, b)) =>
                a == n.key
                  ? at(placed, b) : b == n.key ? at(placed, a) : None,
              links,
            );
          let desired =
            peers == []
              ? {
                x: 100.,
                y: 100.,
              }
              : {
                x:
                  List.fold_left((s, p: item) => s +. p.p.x, 0., peers)
                  /. float_of_int(List.length(peers)),
                y:
                  List.fold_left((s, p: item) => s +. p.p.y, 0., peers)
                  /. float_of_int(List.length(peers)),
              };
          let candidates =
            List.init(12, r =>
              List.init(
                12,
                i => {
                  let angle = float_of_int(i) *. Float.pi /. 6.;
                  let radius = float_of_int(r + 1) *. 84.;
                  {
                    x: snap(max(84., desired.x +. cos(angle) *. radius)),
                    y: snap(max(84., desired.y +. sin(angle) *. radius)),
                  };
                },
              )
            )
            |> List.concat;
          let score = p => {
            let candidate = {
              ...n,
              p,
            };
            let hits =
              List.fold_left(
                (s, q) => overlaps(candidate, q, 24.) ? s +. 1000000. : s,
                0.,
                placed,
              );
            hits +. distance(p, desired) +. 0.05 *. (p.x +. p.y);
          };
          let best =
            List.fold_left(
              (a, b) => score(b) < score(a) ? b : a,
              List.hd(candidates),
              List.tl(candidates),
            );
          placed
          @ [
            {
              ...n,
              p: best,
            },
          ];
        },
      kept,
      items,
    );
  };
};
/* Bounded relaxation, settled before animation. Old positions exert a soft
   pull; overlaps push apart. This intentionally trades stability for space. */
let relaxed = (items, links, old) => {
  let start = stable(items, links, old);
  let current = ref(start);
  for (_ in 1 to 28) {
    current :=
      List.map(
        (n: item) => {
          let target = Option.value(~default=n, at(old, n.key));
          let fx = ref((target.p.x -. n.p.x) *. 0.13)
          and fy = ref((target.p.y -. n.p.y) *. 0.13);
          List.iter(
            (q: item) =>
              if (q.key != n.key && overlaps(n, q, 35.)) {
                let dx = n.p.x -. q.p.x
                and dy = n.p.y -. q.p.y;
                let ox = (n.w +. q.w) /. 2. +. 35. -. abs_float(dx)
                and oy = (n.h +. q.h) /. 2. +. 35. -. abs_float(dy);
                if (ox < oy) {
                  fx := fx^ +. (dx >= 0. ? 1. : (-1.)) *. ox *. 0.3;
                } else {
                  fy := fy^ +. (dy >= 0. ? 1. : (-1.)) *. oy *. 0.3;
                };
              },
            current^,
          );
          List.iter(
            ((a, b)) => {
              let other =
                a == n.key
                  ? at(current^, b) : b == n.key ? at(current^, a) : None;
              switch (other) {
              | Some(q) =>
                let d = distance(n.p, q.p);
                if (d > 220.) {
                  fx := fx^ +. (q.p.x -. n.p.x) *. 0.012;
                  fy := fy^ +. (q.p.y -. n.p.y) *. 0.012;
                };
              | None => ()
              };
            },
            links,
          );
          {
            ...n,
            p: {
              x: max(n.w /. 2. +. 40., n.p.x +. max(-18., min(18., fx^))),
              y: max(n.h /. 2. +. 40., n.p.y +. max(-18., min(18., fy^))),
            },
          };
        },
        current^,
      );
  };
  List.map(
    (n: item) =>
      {
        ...n,
        p: {
          x: snap(n.p.x),
          y: snap(n.p.y),
        },
      },
    current^,
  );
};
/* Engines solve off-thread, returning complete geometry snapshots. Existing
   placements remain visible while pending. Pin/drag offsets are applied later. */
let engine_status = () => {
  Js_of_ocaml.(
    try(
      Js.to_string(
        Js.Unsafe.get(
          Js.Unsafe.get(Js.Unsafe.global, "__canvasResearchState"),
          "status",
        ),
      )
    ) {
    | _ => "Layout engine unavailable"
    }
  );
};
let engine_place = (kind, items, links, old, clusters, topology) => {
  let fallback = stable(items, links, old);
  Js_of_ocaml.(
    try({
      let fn = Js.Unsafe.get(Js.Unsafe.global, "__canvasResearchLayout");
      if (Js.to_string(Js.typeof(fn)) != "function") {
        fallback;
      } else {
        let node = (n: item) =>
          `Assoc([
            ("key", `String(n.key)),
            ("x", `Float(n.p.x)),
            ("y", `Float(n.p.y)),
            ("w", `Float(n.w)),
            ("h", `Float(n.h)),
          ]);
        let payload =
          Yojson.Safe.to_string(
            `Assoc([
              (
                "scope",
                `String(
                  scene^ ++ "/" ++ kind ++ "/" ++ string_of_int(generation^),
                ),
              ),
              ("kind", `String(kind)),
              ("topology", topology),
              ("items", `List(List.map(node, items))),
              ("old", `List(List.map(node, old))),
              (
                "links",
                `List(
                  List.map(
                    ((a, b)) => `List([`String(a), `String(b)]),
                    links,
                  ),
                ),
              ),
              (
                "clusters",
                `List(
                  List.map(
                    ks => `List(List.map(k => `String(k), ks)),
                    clusters,
                  ),
                ),
              ),
            ]),
          );
        let result =
          Js.Unsafe.fun_call(
            fn,
            [|
              Js.Unsafe.inject(Js.string(payload)),
              Js.Unsafe.inject(
                Js.Unsafe.callback(() => {
                  incr(revision);
                  on_result^();
                }),
              ),
            |],
          )
          |> Js.to_string
          |> Yojson.Safe.from_string;
        let float = j =>
          switch (j) {
          | `Float(f) => f
          | `Int(i) => float_of_int(i)
          | _ => failwith("coordinate")
          };
        let positions =
          Yojson.Safe.Util.to_list(result)
          |> List.map(j => {
               let get = k => Yojson.Safe.Util.member(k, j);
               (
                 Yojson.Safe.Util.to_string(get("key")),
                 {
                   x: float(get("x")),
                   y: float(get("y")),
                 },
               );
             });
        if (positions != []) {
          awaiting_fit := false;
        };
        positions == []
          ? fallback
          : List.map(
              (n: item) =>
                {
                  ...n,
                  p:
                    Option.value(
                      ~default=n.p,
                      List.assoc_opt(n.key, positions),
                    ),
                },
              items,
            );
      };
    }) {
    | _ => fallback
    }
  );
};

/* Layout operates on host groups. A terminal remains at its local dock;
   it must not acquire an independent grid cell, relaxation force, or stable
   insertion slot. The root reserves the group's entire occupied envelope. */
let place = (~clusters=[], ~labels=[], kind, items, links, old) => {
  let topology =
    `List([
      `List(List.map(k => `String(k), labels)),
      `List(List.map((n: item) => `String(n.key), items)),
      `List(
        List.map(((a, b)) => `List([`String(a), `String(b)]), links),
      ),
    ]);

  let rec root = (seen, n: item) =>
    switch (n.anchor) {
    | Some(k) when !List.mem(k, seen) =>
      switch (at(items, k)) {
      | Some(host) => root([n.key, ...seen], host)
      | None => n.key
      }
    | _ => n.key
    };
  let root_of = k => Option.map(n => root([], n), at(items, k));
  let roots = List.filter((n: item) => root([], n) == n.key, items);
  let units =
    List.map(
      (host: item) => {
        let members =
          List.filter((n: item) => root([], n) == host.key, items);
        let (left, top, right, bottom) =
          List.fold_left(
            ((left, top, right, bottom), n: item) =>
              (
                min(left, n.p.x -. n.w /. 2.),
                min(top, n.p.y -. n.h /. 2.),
                max(right, n.p.x +. n.w /. 2.),
                max(bottom, n.p.y +. n.h /. 2.),
              ),
            (infinity, infinity, neg_infinity, neg_infinity),
            members,
          );
        {
          ...host,
          p: {
            x: (left +. right) /. 2.,
            y: (top +. bottom) /. 2.,
          },
          w: right -. left,
          h: bottom -. top,
          anchor: None,
        };
      },
      roots,
    );
  let links =
    links_of(items, links)
    |> List.filter_map(((a, b)) =>
         switch (root_of(a), root_of(b)) {
         | (Some(a), Some(b)) when a != b => Some((a, b))
         | _ => None
         }
       )
    |> List.sort_uniq(compare);
  let old_units =
    List.filter_map(
      (n: item) =>
        switch (at(old, n.key), at(items, n.key)) {
        | (Some(previous), Some(host)) =>
          Some({
            ...n,
            p: {
              x: previous.p.x +. n.p.x -. host.p.x,
              y: previous.p.y +. n.p.y -. host.p.y,
            },
          })
        | _ => None
        },
      units,
    );

  let result =
    switch (kind) {
    | "packed"
    | "components" => packed(units, links)
    | "stable" => stable(units, links, old_units)
    | "grid" => grid(units, links)
    | "relaxed" => relaxed(units, links, old_units)
    | k when research(k) =>
      engine_place(
        k,
        units,
        links,
        old_units,
        List.map(
          ks => List.filter_map(root_of, ks) |> List.sort_uniq(compare),
          clusters,
        ),
        topology,
      )
    | _ => units
    };
  List.map(
    (n: item) => {
      let k = root([], n);
      switch (at(units, k), at(result, k)) {
      | (Some(before), Some(after)) => {
          ...n,
          p: {
            x: n.p.x +. after.p.x -. before.p.x,
            y: n.p.y +. after.p.y -. before.p.y,
          },
        }
      | _ => n
      };
    },
    items,
  );
};

/* Bounded Manhattan candidate search. A route may use an outside corridor
   when its short alternatives hit nodes; no shared trunks imply junctions. */
let segments = points => {
  let rec loop = ps =>
    switch (ps) {
    | [a, b, ...rest] => [(a, b), ...loop([b, ...rest])]
    | _ => []
    };
  loop(points);
};
let route =
    (
      ~obstacles: list(item),
      ~src,
      ~dst,
      ~lane=0,
      ~occupied: list(list(point))=[],
      a: point,
      b: point,
    ) => {
  let pad = 12.
  and stub = min(30., max(8., distance(a, b) *. 0.2));
  let outward = (key, p: point, fallback) =>
    switch (at(obstacles, key)) {
    | None => {
        x: p.x +. fallback *. stub,
        y: p.y,
      }
    | Some(n) =>
      let dx = p.x -. n.p.x
      and dy = p.y -. n.p.y;
      abs_float(dx) >= abs_float(dy)
        ? {
          x: p.x +. (dx >= 0. ? stub : -. stub),
          y: p.y,
        }
        : {
          x: p.x,
          y: p.y +. (dy >= 0. ? stub : -. stub),
        };
    };
  let direction = b.x >= a.x ? 1. : (-1.);
  let s = outward(src, a, direction)
  and d = outward(dst, b, -. direction);
  let shift = float_of_int(lane) *. 18.;
  let xs = [
    (a.x +. b.x) /. 2. +. shift,
    min(a.x, b.x) -. 50. -. shift,
    max(a.x, b.x) +. 50. +. shift,
  ];
  let ys = [
    (a.y +. b.y) /. 2. +. shift,
    min(a.y, b.y) -. 50. -. shift,
    max(a.y, b.y) +. 50. +. shift,
  ];
  let mid = {
    x: (a.x +. b.x) /. 2.,
    y: (a.y +. b.y) /. 2.,
  };
  let near =
    List.sort(
      (u: item, v: item) =>
        compare(distance(u.p, mid), distance(v.p, mid)),
      obstacles,
    )
    |> List.filteri((i, _) => i < 8);
  let xs =
    xs
    @ List.concat_map(
        (n: item) => [n.p.x -. n.w /. 2. -. 24., n.p.x +. n.w /. 2. +. 24.],
        near,
      )
  and ys =
    ys
    @ List.concat_map(
        (n: item) => [n.p.y -. n.h /. 2. -. 24., n.p.y +. n.h /. 2. +. 24.],
        near,
      );
  let candidates =
    List.map(
      x =>
        [
          a,
          s,
          {
            x,
            y: s.y,
          },
          {
            x,
            y: d.y,
          },
          d,
          b,
        ],
      xs,
    )
    @ List.map(
        y =>
          [
            a,
            s,
            {
              x: s.x,
              y,
            },
            {
              x: d.x,
              y,
            },
            d,
            b,
          ],
        ys,
      );
  let score = ps => {
    let nonzero =
      segments(ps) |> List.filter(((p, q)) => distance(p, q) > 0.01);
    let rec turns = ss =>
      switch (ss) {
      | [(p, q), (r, s), ...rest] =>
        let dot = (q.x -. p.x) *. (s.x -. r.x) +. (q.y -. p.y) *. (s.y -. r.y);
        (dot < 0. ? 100000. : dot == 0. ? 16. : 0.)
        +. turns([(r, s), ...rest]);
      | _ => 0.
      };
    List.fold_left(
      (score, (u: point, v: point)) => {
        let hits =
          List.fold_left(
            (hits, n: item) =>
              if (n.key == src && u == a || n.key == dst && v == b) {
                hits;
              } else {
                let left = n.p.x -. n.w /. 2. -. pad
                and right = n.p.x +. n.w /. 2. +. pad
                and top = n.p.y -. n.h /. 2. -. pad
                and bottom = n.p.y +. n.h /. 2. +. pad;
                let hit =
                  abs_float(u.x -. v.x) < 0.01
                    ? u.x > left
                      && u.x < right
                      && max(u.y, v.y) > top
                      && min(u.y, v.y) < bottom
                    : u.y > top
                      && u.y < bottom
                      && max(u.x, v.x) > left
                      && min(u.x, v.x) < right;
                hits +. (hit ? 100000. : 0.);
              },
            0.,
            obstacles,
          );
        let overlap =
          u == a || v == b
            ? 0.
            : List.fold_left(
                (sum, path) =>
                  List.fold_left(
                    (sum, (p: point, q: point)) => {
                      let length =
                        abs_float(u.x -. v.x) < 0.01
                        && abs_float(p.x -. q.x) < 0.01
                        && abs_float(u.x -. p.x) < 8.
                          ? max(
                              0.,
                              min(max(u.y, v.y), max(p.y, q.y))
                              -. max(min(u.y, v.y), min(p.y, q.y)),
                            )
                          : abs_float(u.y -. v.y) < 0.01
                            && abs_float(p.y -. q.y) < 0.01
                            && abs_float(u.y -. p.y) < 8.
                              ? max(
                                  0.,
                                  min(max(u.x, v.x), max(p.x, q.x))
                                  -. max(min(u.x, v.x), min(p.x, q.x)),
                                )
                              : 0.;
                      sum +. max(0., length -. 12.) *. 30.;
                    },
                    sum,
                    segments(path),
                  ),
                0.,
                occupied,
              );
        let crossings =
          List.fold_left(
            (sum, path) =>
              List.fold_left(
                (sum, (p: point, q: point)) => {
                  let cross = (a: point, b: point, c: point) =>
                    (b.x -. a.x)
                    *. (c.y -. a.y)
                    -. (b.y -. a.y)
                    *. (c.x -. a.x);
                  sum
                  +. (
                    cross(u, v, p)
                    *. cross(u, v, q) < 0.
                    && cross(p, q, u)
                    *. cross(p, q, v) < 0.
                      ? 40. : 0.
                  );
                },
                sum,
                segments(path),
              ),
            0.,
            occupied,
          );
        score +. distance(u, v) +. hits +. overlap +. crossings;
      },
      turns(nonzero),
      segments(ps),
    );
  };
  List.fold_left(
    (best, ps) => score(ps) < score(best) ? ps : best,
    List.hd(candidates),
    List.tl(candidates),
  );
};
let along = (points, t) => {
  let segs = segments(points);
  let total = List.fold_left((v, (a, b)) => v +. distance(a, b), 0., segs);
  let rec walk = (ss, remaining) =>
    switch (ss) {
    | [(a, b), ...rest] =>
      let d = distance(a, b);
      if (remaining <= d || rest == []) {
        let u = d < 0.001 ? 0. : min(1., remaining /. d);
        {
          x: a.x +. (b.x -. a.x) *. u,
          y: a.y +. (b.y -. a.y) *. u,
        };
      } else {
        walk(rest, remaining -. d);
      };
    | [] => {
        x: 0.,
        y: 0.,
      }
    };
  walk(segs, max(0., min(1., t)) *. total);
};
/* Fixed command topology across routes lets SVG morphs interpolate rather
   than popping when the chosen corridor changes. A small quadratic rounds
   each corner. Degenerate segments are retained deliberately. */
let path = points =>
  switch (points) {
  | [] => ""
  | [first, ...rest] =>
    let fmt = (p: point) => Printf.sprintf("%.1f,%.1f", p.x, p.y);
    let rec draw = (prev, ps) =>
      switch (ps) {
      | [p, next, ...tail] =>
        let back = distance(prev, p)
        and ahead = distance(p, next);
        let r = min(6., min(back /. 2., ahead /. 2.));
        let inset = (q: point, d) =>
          d < 0.001
            ? p
            : {
              x: p.x +. (q.x -. p.x) *. r /. d,
              y: p.y +. (q.y -. p.y) *. r /. d,
            };
        " L "
        ++ fmt(inset(prev, back))
        ++ " Q "
        ++ fmt(p)
        ++ " "
        ++ fmt(inset(next, ahead))
        ++ draw(p, [next, ...tail]);
      | [last] => " L " ++ fmt(last)
      | [] => ""
      };
    "M " ++ fmt(first) ++ draw(first, rest);
  };

files.canvas/upstream/CanvasLog.re:
open Js_of_ocaml;

/* CanvasLog — a copy-pasteable journal of canvas pacing events (beats,
   queue depth, arrivals, auto-fit, avatar moves), for correlating a
   watcher's subjective impressions ("that felt jarring", "too much at
   once") with what actually fired and when.

   From the devtools console:
     copy(__constellationLogText())   put the log on the clipboard
     __constellationLogClear()        start fresh

   Always on (entries only fire on canvas/agent events, so an idle or
   human-editing session stays quiet); ~10s lulls get a gap marker so
   bursts read as separate stanzas. */

let cap = 1200;
/* burst counter, shown in the UI clock and prefixed to log lines so a
   watcher can report "on turn 7 I saw X" and land on the right stanza */
let turn: ref(int) = ref(0);
let next_turn = (): int => {
  turn := turn^ + 1;
  turn^;
};
let turn_no = (): int => turn^;
let entries: ref(list(string)) = ref([]); /* newest first */
let count: ref(int) = ref(0);
let t0: ref(float) = ref(0.);
let last_t: ref(float) = ref(0.);
/* unsaved journal/trace changes pending a localStorage flush */
let dirty: ref(bool) = ref(false);

let now = (): float => Js.Unsafe.coerce(Js.Unsafe.global)##._Date##now();

let iso_now = (): string => {
  let d = Js.Unsafe.new_obj(Js.Unsafe.get(Js.Unsafe.global, "Date"), [||]);
  Js.to_string(Js.Unsafe.meth_call(d, "toISOString", [||]));
};

/* layout trace: a separate ring of node-position lines (grid coords),
   recorded by CanvasSidebar whenever the layout meaningfully changes.
   Console: copy(__constellationLayoutTrace()) — paste alongside the
   journal when a layout event needs diagnosing. */
let layouts: ref(list(string)) = ref([]); /* newest first */
let layouts_count: ref(int) = ref(0);
let layout_cap = 300;
let record_layout = (line: string): unit => {
  dirty := true;
  layouts := [line, ...layouts^];
  layouts_count := layouts_count^ + 1;
  if (layouts_count^ > layout_cap) {
    layouts := List.filteri((i, _) => i < layout_cap, layouts^);
    layouts_count := layout_cap;
  };
};

/* "T7 132.4s" — the same coordinates the journal uses */
let stamp = (): string => {
  let el = t0^ == 0. ? 0. : (now() -. t0^) /. 1000.;
  Printf.sprintf("T%d %.1fs", turn^, el);
};

let push = (line: string): unit => {
  dirty := true;
  entries := [line, ...entries^];
  count := count^ + 1;
  if (count^ > cap) {
    entries := List.filteri((i, _) => i < cap, entries^);
    count := cap;
  };
};

/* the header clock ("T7 · 2:13"): imperative textContent updates on an
   interval, so ticking never re-renders the vdom */
/* ---- persistence: the journal + layout trace survive a dead tab ----
   Flushed to localStorage on a debounce; the PREVIOUS session's copies
   are captured at startup and stay readable via
   __constellationLogPrevious() / __constellationLayoutTracePrevious()
   even after this session starts overwriting the keys. */
let ls_key_log = "constellation:log";
let ls_key_trace = "constellation:trace";
let prev_log: ref(string) = ref("");
let prev_trace: ref(string) = ref("");

let ls_get = (k: string): string =>
  switch (
    Js.Opt.to_option(
      Js.Unsafe.meth_call(
        Js.Unsafe.get(Js.Unsafe.global, "localStorage"),
        "getItem",
        [|Js.Unsafe.inject(Js.string(k))|],
      ),
    )
  ) {
  | Some(v) => Js.to_string(v)
  | None => ""
  | exception _ => ""
  };

let ls_set = (k: string, v: string): unit =>
  switch (
    Js.Unsafe.meth_call(
      Js.Unsafe.get(Js.Unsafe.global, "localStorage"),
      "setItem",
      [|Js.Unsafe.inject(Js.string(k)), Js.Unsafe.inject(Js.string(v))|],
    )
  ) {
  | _ => ()
  | exception _ => ()
  };

let flush = (): unit =>
  if (dirty^) {
    dirty := false;
    ls_set(ls_key_log, String.concat("\n", List.rev(entries^)));
    ls_set(ls_key_trace, String.concat("\n", List.rev(layouts^)));
  };

/* ---- perf heartbeat: main-thread stalls via the longtask observer ----
   Accumulated per window; the interval writes a journal line only when
   stalls actually happened, so healthy sessions stay quiet. */
let lt_count: ref(int) = ref(0);
let lt_max: ref(float) = ref(0.);
let lt_total: ref(float) = ref(0.);

let install_longtask_observer = (): unit =>
  if (Js.Optdef.test(Js.Unsafe.get(Js.Unsafe.global, "PerformanceObserver"))) {
    switch (
      {
        let cb =
          Js.Unsafe.callback((list: Js.t(Js.Unsafe.any)) => {
            let entries: array(Js.t(Js.Unsafe.any)) =
              Js.to_array(Js.Unsafe.meth_call(list, "getEntries", [||]));
            Array.iter(
              e => {
                let d: float = Js.Unsafe.coerce(e)##.duration;
                lt_count := lt_count^ + 1;
                lt_max := max(lt_max^, d);
                lt_total := lt_total^ +. d;
              },
              entries,
            );
          });
        let obs =
          Js.Unsafe.new_obj(
            Js.Unsafe.get(Js.Unsafe.global, "PerformanceObserver"),
            [|Js.Unsafe.inject(cb)|],
          );
        Js.Unsafe.meth_call(
          obs,
          "observe",
          [|
            Js.Unsafe.inject(
              Js.Unsafe.obj([|
                (
                  "entryTypes",
                  Js.Unsafe.inject(Js.array([|Js.string("longtask")|])),
                ),
              |]),
            ),
          |],
        );
      }
    ) {
    | _ => ()
    | exception _ => ()
    };
  };

let ticks: ref(int) = ref(0);
/* forward ref: the heartbeat writes through log(), defined below */
let heartbeat: ref(unit => unit) = ref(() => ());

let update_clock = (): unit =>
  switch (Util.JsUtil.get_elem_by_id_opt("canvas-clock")) {
  | None => ()
  | Some(el) =>
    let txt =
      if (t0^ == 0.) {
        "";
      } else {
        let secs = int_of_float((now() -. t0^) /. 1000.);
        turn^ == 0
          ? Printf.sprintf("%d:%02d", secs / 60, secs mod 60)
          : Printf.sprintf("T%d  %d:%02d", turn^, secs / 60, secs mod 60);
      };
    Js.Unsafe.set(el, "textContent", Js.string(txt));
  };

let installed: ref(bool) = ref(false);
let install = (): unit =>
  if (! installed^) {
    installed := true;
    prev_log := ls_get(ls_key_log);
    prev_trace := ls_get(ls_key_trace);
    Js.Unsafe.set(
      Js.Unsafe.global,
      "__constellationLogPrevious",
      Js.Unsafe.callback(() => Js.string(prev_log^)),
    );
    Js.Unsafe.set(
      Js.Unsafe.global,
      "__constellationLayoutTracePrevious",
      Js.Unsafe.callback(() => Js.string(prev_trace^)),
    );
    /* browser only: under node (the test runner) a live interval keeps
       the event loop alive forever, so the process never exits */
    if (Js.Optdef.test(Js.Unsafe.get(Js.Unsafe.global, "document"))) {
      install_longtask_observer();
      ignore(
        Js.Unsafe.meth_call(
          Js.Unsafe.global,
          "setInterval",
          [|
            Js.Unsafe.inject(
              Js.Unsafe.callback(() => {
                ticks := ticks^ + 1;
                update_clock();
                if (ticks^ mod 4 == 0) {
                  flush();
                };
                if (ticks^ mod 10 == 0 && lt_count^ > 0) {
                  heartbeat^();
                };
              }),
            ),
            Js.Unsafe.inject(500),
          |],
        ),
      );
    };
    Js.Unsafe.set(
      Js.Unsafe.global,
      "__constellationLogText",
      Js.Unsafe.callback(() =>
        Js.string(String.concat("\n", List.rev(entries^)))
      ),
    );
    Js.Unsafe.set(
      Js.Unsafe.global,
      "__constellationLayoutTrace",
      Js.Unsafe.callback(() =>
        Js.string(String.concat("\n", List.rev(layouts^)))
      ),
    );
    Js.Unsafe.set(
      Js.Unsafe.global,
      "__constellationLogClear",
      Js.Unsafe.callback(() => {
        entries := [];
        count := 0;
        t0 := 0.;
        last_t := 0.;
        layouts := [];
        layouts_count := 0;
        dirty := true;
      }),
    );
  };

/* set by CanvasTrajectory: the trace time while a replay runs */
let trace_clock: ref(unit => option(string)) = ref(() => None);

let log = (msg: string): unit => {
  install();
  let t = now();
  if (t0^ == 0.) {
    t0 := t;
    push("log start " ++ iso_now());
  };
  if (last_t^ > 0. && t -. last_t^ > 10000.) {
    push(
      Printf.sprintf("          ~  quiet %.0fs  ~", (t -. last_t^) /. 1000.),
    );
  };
  last_t := t;
  let tlabel = turn^ == 0 ? "  " : Printf.sprintf("T%d", turn^);
  /* while a replay runs every line also carries the TRACE time, so an
     observation "at 38.2" lands on the same clock as the score */
  let msg =
    switch (trace_clock^()) {
    | Some(tc) => "[R " ++ tc ++ "] " ++ msg
    | None => msg
    };
  push(Printf.sprintf("%8.2fs %-3s %s", (t -. t0^) /. 1000., tlabel, msg));
};

heartbeat :=
  (
    () => {
      let phases = Util.PerfTimer.take_summary();
      log(
        Printf.sprintf(
          "perf: %d long task(s), max %.0fms, total %.1fs (last 5s)%s",
          lt_count^,
          lt_max^,
          lt_total^ /. 1000.,
          phases == "" ? "" : " — " ++ phases,
        ),
      );
      lt_count := 0;
      lt_max := 0.;
      lt_total := 0.;
    }
  );

files.canvas/upstream/CanvasRipple.re:
open Js_of_ocaml;

/* The dot lattice, promoted from a repeated CSS background to a 2D
   canvas so dots can MOVE: placing a node splashes a compression wave
   through the grid — dots displace radially under a traveling gaussian
   ring that decays as it expands.

   The element keeps the CSS mask (edge fade) and rides the root's CSS
   zoom; pitch and dot radius are read from the root's inline
   --dot-pitch/--dot-r so zoom-looping behavior is unchanged. Static
   redraws happen only when geometry changes; an rAF loop runs only
   while ripples are live. */

/* ---- the wave medium ----
   A damped 2D wave field simulated at ~half dot resolution over the
   viewport, replacing the old superposed analytic gaussian rings.
   Every disturbance (splash, suction, the drag wake, rainfall) is an
   energy injection into ONE medium, so interference and reflections
   emerge instead of being composed — and dragging a node sheds waves
   along its path like a stick pulled through water (with the wave
   speed tuned below typical drag speed, a Mach-cone wake forms
   physically). Dots displace by the local field gradient: an O(1)
   lookup per dot, cheaper than the old per-ripple loop.

   The field is pinned to CONTENT coordinates (cells shift on scroll)
   so waves stay where they happened while panning. */

/* view state, pushed in by CanvasSidebar each render (and imperatively
   during a pinch): the dots canvas is VIEWPORT-fixed and needs the
   board->screen mapping */
let zoom: ref(float) = ref(1.);
let pan_slack = 392.; /* keep in sync with CanvasSidebar.pan_slack */

/* field resolution, screen px. 7 was ~40% of the main thread during a
   score (a splash per act keeps the medium live; the step allocated a
   fresh field per substep and every dot was redrawn every frame) */
let cell = 9.;
/* live-tunable from the console while the feel is being dialed in:
     __waveTune("stiffness", 0.3)   __waveGet()
   stiffness = (c*dt/cell)^2, CFL-stable below ~0.5 */
let stiffness = ref(0.32);
let damping = ref(0.987); /* per substep: settles in ~1.5 s, not ~3 */
let grad_gain = ref(9.); /* field gradient -> dot displacement px */
let default_amp = 9.;
let stroke_amp = ref(3.6); /* drag-wake deposit per sample point */
let deposit_sigma = ref(1.6); /* injection kernel width, cells */
/* __waveTune("legacy", 1): v1 mechanics for A/B comparison —
   nearest-cell gradient sampling + 3x3 spike deposits. Toggling loads
   that mode's stock constants, stomping any hand tuning. */
let legacy = ref(false);
/* absorbing boundary: the grid is only viewport-sized, and its zero
   border is a hard wall — without absorption every front reflects off
   the panel edges and comes back (reads as motion restarting). The
   sponge ramps extra damping over the outer band so outgoing waves
   die there and the medium reads as infinite. 0 = reflecting walls. */
let sponge_k = ref(0.25);
let sponge_band = 14; /* cells */
/* steep wake gradients can push neighboring dots into each other (they
   visibly merge and 'vanish'); cap the displacement well under the
   14px dot pitch */
let disp_cap = ref(6.);
let apply_preset = (l: bool): unit =>
  if (l) {
    stiffness := 0.35;
    damping := 0.988;
    grad_gain := 5.5;
    stroke_amp := 3.2;
    sponge_k := 0.; /* v1 reflected; keep the A/B faithful */
  } else {
    stiffness := 0.32;
    damping := 0.991;
    grad_gain := 9.;
    stroke_amp := 3.6;
    deposit_sigma := 1.6;
    sponge_k := 0.25;
  };

/* forward refs: deposit/suction are defined below install_knobs */
let deposit_fwd: ref((float, float, float) => unit) = ref((_, _, _) => ());
let suction_fwd: ref(((float, float)) => unit) = ref(_ => ());
let knobs_installed = ref(false);
let n_full: ref(int) = ref(0)
and n_partial: ref(int) = ref(0)
and n_skip: ref(int) = ref(0)
and n_partial_area: ref(float) = ref(0.);

let install_knobs = (): unit =>
  if (! knobs_installed^) {
    knobs_installed := true;
    Js.Unsafe.set(
      Js.Unsafe.global,
      "__waveTune",
      Js.Unsafe.callback((name: Js.t(Js.js_string), v: float) =>
        switch (Js.to_string(name)) {
        | "stiffness" => stiffness := max(0.05, min(0.45, v))
        | "damping" => damping := max(0.9, min(0.999, v))
        | "grad_gain" => grad_gain := v
        | "stroke_amp" => stroke_amp := v
        | "deposit_sigma" => deposit_sigma := max(0.6, min(4., v))
        | "legacy" =>
          legacy := v > 0.5;
          apply_preset(legacy^);
        | "sponge" => sponge_k := max(0., min(0.5, v))
        | "disp_cap" => disp_cap := max(1., v)
        | _ => ()
        }
      ),
    );
    Js.Unsafe.set(
      Js.Unsafe.global,
      "__rippleCounters",
      Js.Unsafe.callback(() =>
        Js.string(
          Printf.sprintf(
            "full=%d partial=%d skip=%d partial_area=%.2f",
            n_full^,
            n_partial^,
            n_skip^,
            n_partial^ == 0
              ? 0. : n_partial_area^ /. float_of_int(n_partial^),
          ),
        )
      ),
    );
    Js.Unsafe.set(
      Js.Unsafe.global,
      "__waveSuction",
      Js.Unsafe.callback((x: float, y: float) => suction_fwd^((x, y))),
    );
    Js.Unsafe.set(
      Js.Unsafe.global,
      "__waveSplash",
      Js.Unsafe.callback((x: float, y: float, amp: float) => {
        let (cx, cy) = (pan_slack +. x *. zoom^, pan_slack +. y *. zoom^);
        deposit_fwd^(cx, cy, amp);
      }),
    );
    Js.Unsafe.set(
      Js.Unsafe.global,
      "__waveGet",
      Js.Unsafe.callback(() =>
        Js.string(
          Printf.sprintf(
            "stiffness=%.3f damping=%.3f grad_gain=%.1f stroke_amp=%.1f deposit_sigma=%.1f sponge=%.2f disp_cap=%.1f legacy=%d",
            stiffness^,
            damping^,
            grad_gain^,
            stroke_amp^,
            deposit_sigma^,
            sponge_k^,
            disp_cap^,
            legacy^ ? 1 : 0,
          ),
        )
      ),
    );
  };

let gw: ref(int) = ref(0);
let gh: ref(int) = ref(0);
let u_cur: ref(array(float)) = ref([||]);
let u_prev: ref(array(float)) = ref([||]);
/* content-px position of cell (0,0) */
let origin_x: ref(float) = ref(0.);
let origin_y: ref(float) = ref(0.);
let sim_active: ref(bool) = ref(false);
let frame_parity: ref(bool) = ref(false);
/* the screen region drawn with live displacement last frame: with
   the viewport still, only the union of that and the current live
   region is cleared and redrawn (the lattice at rest is unchanged
   pixels). None forces a full redraw. */
let dirty_prev: ref(option((float, float, float, float))) = ref(None);
let last_fill: ref(string) = ref("");

/* content-px box of cells the medium is displacing (None: calm) */
let field_box = (): option((float, float, float, float)) =>
  if (gw^ == 0) {
    None;
  } else {
    let w = gw^
    and h = gh^;
    let u = u_cur^;
    let eps = 0.05 /. grad_gain^;
    let i0 = ref(w)
    and i1 = ref(-1)
    and j0 = ref(h)
    and j1 = ref(-1);
    for (j in 0 to h - 1) {
      let row = j * w;
      for (i in 0 to w - 1) {
        if (abs_float(u[row + i]) > eps) {
          if (i < i0^) {
            i0 := i;
          };
          if (i > i1^) {
            i1 := i;
          };
          if (j < j0^) {
            j0 := j;
          };
          if (j > j1^) {
            j1 := j;
          };
        };
      };
    };
    if (i1^ < 0) {
      None;
    } else {
      /* bilinear sampling reaches two cells out */
      Some((
        origin_x^ +. float_of_int(i0^ - 2) *. cell,
        origin_y^ +. float_of_int(j0^ - 2) *. cell,
        origin_x^ +. float_of_int(i1^ + 2) *. cell,
        origin_y^ +. float_of_int(j1^ + 2) *. cell,
      ));
    };
  };

let box_union = (a, b) =>
  switch (a, b) {
  | (None, x)
  | (x, None) => x
  | (Some((ax0, ay0, ax1, ay1)), Some((bx0, by0, bx1, by1))) =>
    Some((
      Float.min(ax0, bx0),
      Float.min(ay0, by0),
      Float.max(ax1, bx1),
      Float.max(ay1, by1),
    ))
  };
let last_step: ref(float) = ref(0.);

let zoom_ref = zoom; /* alias for clarity below */

let idx = (i: int, j: int): int => j * gw^ + i;

let ensure_grid = (cw: int, ch: int): unit => {
  /* the grid extends one sponge-band beyond the viewport on every side
     so absorption happens OFF-SCREEN: a deposit near the visible edge
     must land in live medium, not in the absorbing frame (a node
     removed near the panel edge used to have its suction eaten at
     birth) */
  let w =
    int_of_float(Float.ceil(float_of_int(cw) /. cell)) + 3 + 2 * sponge_band;
  let h =
    int_of_float(Float.ceil(float_of_int(ch) /. cell)) + 3 + 2 * sponge_band;
  if (w != gw^ || h != gh^) {
    /* PRESERVE in-flight waves across resizes: the pane height changes
       whenever the focus strip opens/closes — including the very frame
       a removal's suction is deposited (the dying node's panel closes),
       which used to zero the field and annihilate the ripple. Same
       origin, same cell indices; new cells start calm. */
    let ow = gw^
    and oh = gh^;
    let ou = u_cur^
    and op = u_prev^;
    let nu = Array.make(w * h, 0.)
    and np = Array.make(w * h, 0.);
    if (ow > 0) {
      for (j in 0 to min(h, oh) - 1) {
        for (i in 0 to min(w, ow) - 1) {
          nu[j * w + i] = ou[j * ow + i];
          np[j * w + i] = op[j * ow + i];
        };
      };
    };
    gw := w;
    gh := h;
    u_cur := nu;
    u_prev := np;
  };
};

/* keep the field pinned to content while the viewport scrolls: shift
   cells by whole-cell deltas */
let anchor = (sl: float, st: float): unit => {
  let margin = float_of_int(sponge_band) *. cell;
  let target_x = sl -. cell -. margin
  and target_y = st -. cell -. margin;
  let dx = int_of_float(Float.round((target_x -. origin_x^) /. cell))
  and dy = int_of_float(Float.round((target_y -. origin_y^) /. cell));
  if (dx != 0 || dy != 0) {
    let w = gw^
    and h = gh^;
    let shift = (a: array(float)): array(float) => {
      let b = Array.make(w * h, 0.);
      for (j in 0 to h - 1) {
        for (i in 0 to w - 1) {
          let si = i + dx
          and sj = j + dy;
          if (si >= 0 && si < w && sj >= 0 && sj < h) {
            b[j * w + i] = a[sj * w + si];
          };
        };
      };
      b;
    };
    u_cur := shift(u_cur^);
    u_prev := shift(u_prev^);
    origin_x := origin_x^ +. float_of_int(dx) *. cell;
    origin_y := origin_y^ +. float_of_int(dy) *. cell;
  };
};

/* deposit a SMOOTH gaussian bump at a CONTENT-px point: sharp spikes
   disperse into gridded, anisotropic ringing on a coarse lattice (the
   v1 "not waterlike" artifact); wide smooth kernels launch clean
   circular fronts */
let deposit = (cx: float, cy: float, amp: float): unit =>
  if (gw^ > 0) {
    let fx = (cx -. origin_x^) /. cell
    and fy = (cy -. origin_y^) /. cell;
    let ci = int_of_float(Float.round(fx))
    and cj = int_of_float(Float.round(fy));
    if (legacy^) {
      for (j in cj - 1 to cj + 1) {
        for (i in ci - 1 to ci + 1) {
          if (i >= 0 && i < gw^ && j >= 0 && j < gh^) {
            let k = i == ci && j == cj ? 1.0 : 0.35;
            u_cur^[idx(i, j)] = u_cur^[idx(i, j)] +. amp *. k;
          };
        };
      };
    } else {
      let sg = deposit_sigma^;
      let r = int_of_float(Float.ceil(sg *. 2.5));
      for (j in cj - r to cj + r) {
        for (i in ci - r to ci + r) {
          if (i >= 0 && i < gw^ && j >= 0 && j < gh^) {
            let dx = float_of_int(i) -. fx
            and dy = float_of_int(j) -. fy;
            let d2 = (dx *. dx +. dy *. dy) /. (2. *. sg *. sg);
            u_cur^[idx(i, j)] =
              u_cur^[idx(i, j)] +. amp *. Float.exp(-. d2);
          };
        };
      };
    };
    sim_active := true;
  };

let model_to_content = ((x, y): (float, float)): (float, float) => (
  pan_slack +. x *. zoom_ref^,
  pan_slack +. y *. zoom_ref^,
);

let step_sim = (substeps: int): unit => {
  let w = gw^
  and h = gh^;
  if (w > 0) {
    for (_ in 1 to substeps) {
      let u = u_cur^
      and up = u_prev^;
      /* double-buffer: the previous field becomes the next (no
         allocation per substep) */
      let un = up;
      for (j in 1 to h - 2) {
        for (i in 1 to w - 2) {
          let k = j * w + i;
          let lap = u[k - 1] +. u[k + 1] +. u[k - w] +. u[k + w] -. 4. *. u[k];
          un[k] = damping^ *. (2. *. u[k] -. up[k] +. stiffness^ *. lap);
        };
      };
      if (sponge_k^ > 0.001) {
        /* absorb over the outer band (both fields, so no velocity
           kick); only the band's cells are visited, and with int
           comparisons (polymorphic min was a quarter of the step) */
        let band = sponge_band;
        let absorb = (i, j) => {
          let d = Int.min(Int.min(i, w - 1 - i), Int.min(j, h - 1 - j));
          if (d < band) {
            let t = 1. -. float_of_int(d) /. float_of_int(band);
            let f = 1. -. sponge_k^ *. t *. t;
            let k = j * w + i;
            un[k] = un[k] *. f;
            u[k] = u[k] *. f;
          };
        };
        for (j in 0 to band - 1) {
          for (i in 0 to w - 1) {
            absorb(i, j);
            absorb(i, h - 1 - j);
          };
        };
        for (j in band to h - 1 - band) {
          for (i in 0 to band - 1) {
            absorb(i, j);
            absorb(w - 1 - i, j);
          };
        };
      };
      u_prev := u;
      u_cur := un;
    };
    /* liveness: the medium is live while some cell could still move a
       dot visibly (peak |u| against the gradient gain; a summed
       criterion kept it "live" for seconds after the motion faded,
       redrawing every dot for nothing) */
    let m = ref(0.);
    let u = u_cur^;
    let n = Array.length(u);
    let i = ref(0);
    while (i^ < n) {
      let a = abs_float(u[i^]);
      if (a > m^) {
        m := a;
      };
      i := i^ + 3;
    };
    sim_active := m^ *. grad_gain^ > 0.08;
  };
};

/* field gradient at a content-px point, BILINEARLY interpolated:
   nearest-cell sampling made neighboring dots snap between discrete
   gradients as a wave passed (the v1 jank) */
let displacement_at = (cx: float, cy: float): (float, float) =>
  if (gw^ == 0) {
    (0., 0.);
  } else if (legacy^) {
    let i = int_of_float(Float.round((cx -. origin_x^) /. cell))
    and j = int_of_float(Float.round((cy -. origin_y^) /. cell));
    if (i < 1 || i >= gw^ - 1 || j < 1 || j >= gh^ - 1) {
      (0., 0.);
    } else {
      let u = u_cur^;
      let gx = (u[idx(i + 1, j)] -. u[idx(i - 1, j)]) /. 2.
      and gy = (u[idx(i, j + 1)] -. u[idx(i, j - 1)]) /. 2.;
      (grad_gain^ *. gx, grad_gain^ *. gy);
    };
  } else {
    let fx = (cx -. origin_x^) /. cell
    and fy = (cy -. origin_y^) /. cell;
    let i0 = int_of_float(Float.floor(fx))
    and j0 = int_of_float(Float.floor(fy));
    if (i0 < 1 || i0 >= gw^ - 2 || j0 < 1 || j0 >= gh^ - 2) {
      (0., 0.);
    } else {
      let tx = fx -. float_of_int(i0)
      and ty = fy -. float_of_int(j0);
      let u = u_cur^;
      let grad = (i: int, j: int): (float, float) => (
        (u[idx(i + 1, j)] -. u[idx(i - 1, j)]) /. 2.,
        (u[idx(i, j + 1)] -. u[idx(i, j - 1)]) /. 2.,
      );
      let (g00x, g00y) = grad(i0, j0)
      and (g10x, g10y) = grad(i0 + 1, j0)
      and (g01x, g01y) = grad(i0, j0 + 1)
      and (g11x, g11y) = grad(i0 + 1, j0 + 1);
      let lerp = (a, b, t) => a +. (b -. a) *. t;
      let gx = lerp(lerp(g00x, g10x, tx), lerp(g01x, g11x, tx), ty)
      and gy = lerp(lerp(g00y, g10y, tx), lerp(g01y, g11y, tx), ty);
      let dx = grad_gain^ *. gx
      and dy = grad_gain^ *. gy;
      let n = Float.hypot(dx, dy);
      n > disp_cap^
        ? (dx *. disp_cap^ /. n, dy *. disp_cap^ /. n) : (dx, dy);
    };
  };

/* drag wake: injection along the path between successive drag samples */
let field: ref(option((float, float))) =
  ref(None: option((float, float)));

/* ---- edge pulses: data visibly flowing ----
   A bright dot with a fading tail travels a function edge's bezier
   (model coords) when that function's samples change; on arrival it
   deposits a little energy into the medium. */
type pulse = {
  wire: list((float, float)),
  p0: (float, float),
  p1: (float, float),
  p2: (float, float),
  p3: (float, float),
  t0: float,
};
let pulses: ref(list(pulse)) = ref([]);
let pulse_ms = 650.;

/* removal suction, two-phase: the WAVE MEDIUM cannot pull dots inward
   first — any deposit's leading front propagates OUTWARD and dots ride
   the front (out-in-out, as observed). So the pull phase is ANALYTIC:
   an easing radial displacement drawn directly onto the dots (no field
   involvement), and only the release plants a positive bump in the
   medium for the outgoing rebound ring. */
type suction_t = {
  su_p: (float, float), /* model coords */
  su_t0: float,
};
let suctions: ref(list(suction_t)) = ref([]);
let suction_pull_ms = 380.;
let suction_pull_px = 8.5; /* peak inward displacement */
let suction_pull_r = 110.; /* gaussian reach, screen px */
let suction_rebound = 8.; /* released bump amplitude */

let bezier =
    (
      ((x0, y0), (x1, y1), (x2, y2), (x3, y3)): (
        (float, float),
        (float, float),
        (float, float),
        (float, float),
      ),
      t: float,
    )
    : (float, float) => {
  let mt = 1. -. t;
  let a = mt *. mt *. mt
  and b = 3. *. mt *. mt *. t
  and c = 3. *. mt *. t *. t
  and d = t *. t *. t;
  (
    a *. x0 +. b *. x1 +. c *. x2 +. d *. x3,
    a *. y0 +. b *. y1 +. c *. y2 +. d *. y3,
  );
};

let pulse_at = (p: pulse, t) =>
  p.wire == []
    ? bezier((p.p0, p.p1, p.p2, p.p3), t)
    : {
      let p =
        CanvasLayoutExperiments.along(
          List.map(
            ((x, y)) =>
              CanvasLayoutExperiments.{
                x,
                y,
              },
            p.wire,
          ),
          t,
        );
      (p.x, p.y);
    };

let raf_running: ref(bool) = ref(false);
let draw_queued: ref(bool) = ref(false);

/* Dots render from a pre-rasterized sprite via drawImage instead of
   per-dot arc fills: a 1.5px arc's apparent brightness swings ~2x with
   its subpixel phase, so dots visibly twinkle while a wave displaces
   them; bilinear resampling of a soft sprite keeps peak brightness
   stable in motion (and drawImage is cheaper than path fill). */
let dot_sprite: ref(option(Js.Unsafe.any)) = ref(None);
let dot_sprite_key: ref(string) = ref("");
let sprite_size = 8.; /* css px, dot centered */
let get_dot_sprite = (fill: string, dpr: float): Js.Unsafe.any => {
  let key = Printf.sprintf("%s|%.2f", fill, dpr);
  switch (dot_sprite^) {
  | Some(c) when dot_sprite_key^ == key => c
  | _ =>
    let doc = Js.Unsafe.global##.document;
    /* resolve the fill to rgb so the gradient can fade to a
       same-color transparent (fading to rgba(0,0,0,0) darkens) */
    let probe =
      Js.Unsafe.meth_call(
        doc,
        "createElement",
        [|Js.Unsafe.inject(Js.string("canvas"))|],
      );
    Js.Unsafe.set(probe, "width", 1);
    Js.Unsafe.set(probe, "height", 1);
    let pctx =
      Js.Unsafe.meth_call(
        probe,
        "getContext",
        [|Js.Unsafe.inject(Js.string("2d"))|],
      );
    Js.Unsafe.set(pctx, "fillStyle", Js.string(fill));
    let _ =
      Js.Unsafe.meth_call(
        pctx,
        "fillRect",
        [|
          Js.Unsafe.inject(0),
          Js.Unsafe.inject(0),
          Js.Unsafe.inject(1),
          Js.Unsafe.inject(1),
        |],
      );
    let px: Js.t(Js.Unsafe.any) =
      Js.Unsafe.meth_call(
        pctx,
        "getImageData",
        [|
          Js.Unsafe.inject(0),
          Js.Unsafe.inject(0),
          Js.Unsafe.inject(1),
          Js.Unsafe.inject(1),
        |],
      );
    let data = Js.Unsafe.get(px, "data");
    let ch = (i: int): float => Js.Unsafe.get(data, i);
    let ch = (i: int): int => int_of_float(ch(i));
    let (r, g, b) = (ch(0), ch(1), ch(2));
    let c =
      Js.Unsafe.meth_call(
        doc,
        "createElement",
        [|Js.Unsafe.inject(Js.string("canvas"))|],
      );
    let px_size = int_of_float(Float.ceil(sprite_size *. dpr));
    Js.Unsafe.set(c, "width", px_size);
    Js.Unsafe.set(c, "height", px_size);
    let cx =
      Js.Unsafe.meth_call(
        c,
        "getContext",
        [|Js.Unsafe.inject(Js.string("2d"))|],
      );
    let mid = float_of_int(px_size) /. 2.;
    /* solid core matching the old 0.75px arc, short soft skirt */
    let grad =
      Js.Unsafe.meth_call(
        cx,
        "createRadialGradient",
        [|
          Js.Unsafe.inject(mid),
          Js.Unsafe.inject(mid),
          Js.Unsafe.inject(0.),
          Js.Unsafe.inject(mid),
          Js.Unsafe.inject(mid),
          Js.Unsafe.inject(1.25 *. dpr),
        |],
      );
    let stop = (at: float, a: float) => {
      let _ =
        Js.Unsafe.meth_call(
          grad,
          "addColorStop",
          [|
            Js.Unsafe.inject(at),
            Js.Unsafe.inject(
              Js.string(Printf.sprintf("rgba(%d,%d,%d,%f)", r, g, b, a)),
            ),
          |],
        );
      ();
    };
    stop(0., 1.);
    stop(0.6, 1.);
    stop(1., 0.);
    Js.Unsafe.set(cx, "fillStyle", grad);
    let _ =
      Js.Unsafe.meth_call(
        cx,
        "fillRect",
        [|
          Js.Unsafe.inject(0),
          Js.Unsafe.inject(0),
          Js.Unsafe.inject(px_size),
          Js.Unsafe.inject(px_size),
        |],
      );
    dot_sprite := Some(c);
    dot_sprite_key := key;
    c;
  };
};
/* geometry of the last static draw, to skip redundant repaints */
let last_geom: ref((int, int, float, float, float)) =
  ref((0, 0, 0., 0., 0.));
let geom_unchanged = (cw, ch, sl, st, z): bool =>
  last_geom^ == (cw, ch, sl, st, z);

let now = (): float => Js.Unsafe.coerce(Js.Unsafe.global)##._Date##now();

let parse_px = (s: string): option(float) => {
  let s = String.trim(s);
  let s =
    String.length(s) > 2 && String.sub(s, String.length(s) - 2, 2) == "px"
      ? String.sub(s, 0, String.length(s) - 2) : s;
  float_of_string_opt(s);
};

let css_var = (el: Js.Unsafe.any, name: string): option(float) => {
  let v: Js.t(Js.js_string) =
    Js.Unsafe.meth_call(
      Js.Unsafe.coerce(el)##.style,
      "getPropertyValue",
      [|Js.Unsafe.inject(Js.string(name))|],
    );
  parse_px(Js.to_string(v));
};

let rec draw = (): unit => {
  draw_queued := false;
  install_knobs();
  switch (Util.JsUtil.get_elem_by_id_opt("canvas-dots")) {
  | None =>
    /* the element can be briefly absent mid-patch; if work is pending,
       retry next frame instead of silently dropping the rAF chain */
    if (sim_active^ || suctions^ != [] || pulses^ != []) {
      let _ =
        Js.Unsafe.meth_call(
          Js.Unsafe.global##.window,
          "requestAnimationFrame",
          [|Js.Unsafe.inject(Js.Unsafe.callback(() => draw()))|],
        );
      ();
    }
  | Some(el) =>
    let el = Js.Unsafe.coerce(el);
    /* holder -> #canvas-scroll */
    let scroll = Js.Unsafe.coerce(el##.parentElement)##.parentElement;
    let t = now();
    let dpr: float = Js.Unsafe.coerce(Js.Unsafe.global)##.devicePixelRatio;
    let cw: int = Js.Unsafe.coerce(scroll)##.clientWidth
    and ch: int = Js.Unsafe.coerce(scroll)##.clientHeight;
    let sl: float = Js.Unsafe.coerce(scroll)##.scrollLeft
    and st: float = Js.Unsafe.coerce(scroll)##.scrollTop;
    /* track the VISUAL zoom: during the auto-fit/fit zoom transition the
       computed style interpolates, and following it keeps the lattice
       coupled to the board instead of snapping ahead of it */
    let vis_zoom = {
      let root =
        Js.Opt.to_option(
          Js.Unsafe.meth_call(
            Js.Unsafe.global##.document,
            "querySelector",
            [|Js.Unsafe.inject(Js.string(".canvas-root"))|],
          ),
        );
      switch (root) {
      | None => zoom^
      | Some(root) =>
        let v: Js.t(Js.js_string) =
          Js.Unsafe.meth_call(
            Js.Unsafe.global##.window,
            "getComputedStyle",
            [|Js.Unsafe.inject(root)|],
          )##getPropertyValue(
            Js.string("zoom"),
          );
        switch (float_of_string_opt(String.trim(Js.to_string(v)))) {
        | Some(f) when f > 0.01 => f
        | _ => zoom^
        };
      };
    };
    let zoom_settling = abs_float(vis_zoom -. zoom^) > 0.002;
    let z = max(0.05, vis_zoom);
    let bw = int_of_float(float_of_int(cw) *. dpr)
    and bh = int_of_float(float_of_int(ch) *. dpr);
    if (el##.width != bw || el##.height != bh) {
      el##.width := bw;
      el##.height := bh;
      Js.Unsafe.coerce(el)##.style##.width :=
        Js.string(string_of_int(cw) ++ "px");
      Js.Unsafe.coerce(el)##.style##.height :=
        Js.string(string_of_int(ch) ++ "px");
      last_geom := ((-1), (-1), 0., 0., 0.);
    };
    ensure_grid(cw, ch);
    anchor(sl, st);
    /* advance the medium by wall-clock (capped substeps keep long
       frames stable) */
    /* suction lifecycle: while pulling, the analytic term below moves
       the dots; on expiry, plant the rebound bump in the medium */
    if (suctions^ != []) {
      List.iter(
        (su: suction_t) =>
          if (t -. su.su_t0 > suction_pull_ms) {
            let (mx, my) = su.su_p;
            let (cx, cy) = model_to_content((mx, my));
            let sg = deposit_sigma^;
            deposit_sigma := 2.6;
            deposit(cx, cy, suction_rebound);
            deposit_sigma := sg;
            CanvasLog.log(
              Printf.sprintf(
                "suction rebound: content=(%.0f,%.0f) cell=(%d,%d) grid=(%d,%d)",
                cx,
                cy,
                int_of_float(Float.round((cx -. origin_x^) /. cell)),
                int_of_float(Float.round((cy -. origin_y^) /. cell)),
                gw^,
                gh^,
              ),
            );
          },
        suctions^,
      );
      suctions :=
        List.filter(
          (su: suction_t) => t -. su.su_t0 <= suction_pull_ms,
          suctions^,
        );
    };
    /* the medium runs at half rate: a wave field at 30 Hz reads the
       same, and the full redraw of every dot is the expensive part */
    frame_parity := ! frame_parity^;
    let skip = frame_parity^ && geom_unchanged(cw, ch, sl, st, z);
    if (skip) {
      incr(n_skip);
    };
    if (sim_active^ && !skip) {
      let dt_ms = 8.;
      let elapsed = last_step^ == 0. ? dt_ms : min(48., t -. last_step^);
      step_sim(max(1, min(6, int_of_float(elapsed /. dt_ms))));
      last_step := t;
    } else if (! sim_active^) {
      last_step := t;
    };
    let geom = (cw, ch, sl, st, z);
    if (!skip
        && (
          sim_active^ || pulses^ != [] || suctions^ != [] || geom != last_geom^
        )) {
      let geom_changed = geom != last_geom^;
      last_geom := geom;
      let ctx =
        Js.Unsafe.meth_call(
          el,
          "getContext",
          [|Js.Unsafe.inject(Js.string("2d"))|],
        );
      let mw = float_of_int(cw)
      and mh = float_of_int(ch);
      let fmin = (a: float, b: float) => a < b ? a : b
      and fmax = (a: float, b: float) => a > b ? a : b;
      /* the live region this frame, screen px: the medium's active
         cells, each suction's reach, and every pulse's head-to-tail
         span (pulse positions are computed again below; they are few) */
      let live_box = {
        let su_box =
          List.fold_left(
            (acc, su: suction_t) => {
              let age = (t -. su.su_t0) /. suction_pull_ms;
              if (age >= 0. && age <= 1.) {
                let (mx, my) = su.su_p;
                let (cx, cy) = model_to_content((mx, my));
                let r = suction_pull_r *. 2.5;
                box_union(acc, Some((cx -. r, cy -. r, cx +. r, cy +. r)));
              } else {
                acc;
              };
            },
            None,
            suctions^,
          );
        let pulse_box =
          List.fold_left(
            (acc, p: pulse) => {
              let tt = (t -. p.t0) /. pulse_ms;
              List.fold_left(
                (acc, back) => {
                  let tk = fmax(0., tt -. back);
                  let (mx, my) = pulse_at(p, tk);
                  let cx = mx *. z +. pan_slack
                  and cy = my *. z +. pan_slack;
                  box_union(
                    acc,
                    Some((cx -. 4., cy -. 4., cx +. 4., cy +. 4.)),
                  );
                },
                acc,
                [0., 0.06, 0.12, 0.18],
              );
            },
            None,
            pulses^,
          );
        switch (box_union(box_union(field_box(), su_box), pulse_box)) {
        | None => None
        | Some((x0, y0, x1, y1)) =>
          /* content -> screen, padded by a dot's sprite plus the
             largest displacement, clipped to the viewport */
          let pad = sprite_size /. 2. +. disp_cap^ +. suction_pull_px +. 2.;
          let bx0 = fmax(0., x0 -. sl -. pad)
          and by0 = fmax(0., y0 -. st -. pad)
          and bx1 = fmin(mw, x1 -. sl +. pad)
          and by1 = fmin(mh, y1 -. st +. pad);
          bx0 < bx1 && by0 < by1 ? Some((bx0, by0, bx1, by1)) : None;
        };
      };
      let fill: Js.t(Js.js_string) =
        Js.Unsafe.meth_call(
          Js.Unsafe.global##.window,
          "getComputedStyle",
          [|Js.Unsafe.inject(scroll)|],
        )##getPropertyValue(
          Js.string("--surface-shard"),
        );
      let fill = Js.to_string(fill);
      let fill = fill == "" ? "#d8c9a3" : fill;
      let full = geom_changed || fill != last_fill^;
      last_fill := fill;
      if (full) {
        incr(n_full);
      } else {
        incr(n_partial);
      };
      let region =
        full ? Some((0., 0., mw, mh)) : box_union(live_box, dirty_prev^);
      dirty_prev := live_box;
      let _ =
        Js.Unsafe.meth_call(
          ctx,
          "setTransform",
          [|
            Js.Unsafe.inject(dpr),
            Js.Unsafe.inject(0.),
            Js.Unsafe.inject(0.),
            Js.Unsafe.inject(dpr),
            Js.Unsafe.inject(0.),
            Js.Unsafe.inject(0.),
          |],
        );
      let (rx0, ry0, rx1, ry1) =
        Option.value(region, ~default=(0., 0., 0., 0.));
      if (!full) {
        n_partial_area :=
          n_partial_area^ +. (rx1 -. rx0) *. (ry1 -. ry0) /. (mw *. mh);
      };
      let _ = Js.Unsafe.meth_call(ctx, "save", [||]);
      let _ = Js.Unsafe.meth_call(ctx, "beginPath", [||]);
      let _ =
        Js.Unsafe.meth_call(
          ctx,
          "rect",
          [|
            Js.Unsafe.inject(rx0),
            Js.Unsafe.inject(ry0),
            Js.Unsafe.inject(rx1 -. rx0),
            Js.Unsafe.inject(ry1 -. ry0),
          |],
        );
      let _ = Js.Unsafe.meth_call(ctx, "clip", [||]);
      let _ =
        Js.Unsafe.meth_call(
          ctx,
          "clearRect",
          [|
            Js.Unsafe.inject(rx0),
            Js.Unsafe.inject(ry0),
            Js.Unsafe.inject(rx1 -. rx0),
            Js.Unsafe.inject(ry1 -. ry0),
          |],
        );
      Js.Unsafe.coerce(ctx)##.fillStyle := Js.string(fill);
      let sprite = get_dot_sprite(fill, dpr);
      /* continuous level-of-detail: the "current" grid is the power-of-
         two multiple of the base 14px lattice whose SCREEN pitch lands
         in [14, 28); as zooming grows it past 28 the next finer grid
         (screen pitch [7, 14)) has already faded in underneath and
         takes over — a smooth crossfade instead of the old abrupt
         subdivision */
      let g = ref(14.); /* current grid step, model units */
      let p = ref(14. *. z); /* its screen pitch */
      while (p^ < 14.) {
        g := g^ *. 2.;
        p := p^ *. 2.;
      };
      while (p^ >= 28.) {
        g := g^ /. 2.;
        p := p^ /. 2.;
      };
      let f = (p^ -. 14.) /. 14.; /* 0..1 position between levels */
      let fine_alpha = f *. f; /* ease-in so the fine grid arrives late */
      /* dots fade approaching the PANEL edges (the viewport is the
         frame now, not the board: no more island-and-abyss) */
      let edge = 26.;
      let fade1 = (v: float, extent: float): float => {
        let d = fmin(v, extent -. v);
        d <= 0. ? 0. : fmin(1., d /. edge);
      };
      /* per-frame analytic suction terms: (content center, strength) */
      let su_terms =
        List.filter_map(
          (su: suction_t) => {
            let age = (t -. su.su_t0) /. suction_pull_ms;
            if (age >= 0. && age <= 1.) {
              let (mx, my) = su.su_p;
              let (scx, scy) = model_to_content((mx, my));
              /* fast ease-in then hold; release is the field rebound */
              let e = age < 0.25 ? age /. 0.25 : 1.;
              Some((scx, scy, suction_pull_px *. e));
            } else {
              None;
            };
          },
          suctions^,
        );
      let draw_pass = (step: float, alpha: float, ~skip_coarse: bool) => {
        let reach = sprite_size /. 2. +. disp_cap^ +. suction_pull_px;
        let m0x = (rx0 -. reach +. sl -. pan_slack) /. z
        and m1x = (rx1 +. reach +. sl -. pan_slack) /. z;
        let m0y = (ry0 -. reach +. st -. pan_slack) /. z
        and m1y = (ry1 +. reach +. st -. pan_slack) /. z;
        let i0 = int_of_float(Float.floor(m0x /. step))
        and i1 = int_of_float(Float.ceil(m1x /. step));
        let j0 = int_of_float(Float.floor(m0y /. step))
        and j1 = int_of_float(Float.ceil(m1y /. step));
        for (jy in j0 to j1) {
          for (ix in i0 to i1) {
            /* the fine pass skips points shared with the current grid
               (they are redrawn at full alpha anyway) */
            if (!(skip_coarse && ix mod 2 == 0 && jy mod 2 == 0)) {
              let x = float_of_int(ix) *. step
              and y = float_of_int(jy) *. step;
              /* content px of this dot, displaced by the wave field */
              let cx = x *. z +. pan_slack
              and cy = y *. z +. pan_slack;
              let (dx, dy) = displacement_at(cx, cy);
              /* analytic inward pull toward any active suction */
              let (dx, dy) =
                List.fold_left(
                  ((ax, ay), (scx, scy, amp)) => {
                    let ddx = scx -. cx
                    and ddy = scy -. cy;
                    let d = Float.hypot(ddx, ddy);
                    /* gaussian falloff, sign made explicit: `-. x ** 2.`
                       parses as `(-. x) ** 2.` (positive!) and blew every
                       far dot off-screen */
                    let q = d /. suction_pull_r;
                    let w = amp *. Float.exp(-. (q *. q));
                    /* a very close dot may not cross the sink */
                    let w = min(w, d);
                    d < 1.
                      ? (ax, ay) : (ax +. ddx /. d *. w, ay +. ddy /. d *. w);
                  },
                  (dx, dy),
                  su_terms,
                );
              let sx = cx +. dx -. sl
              and sy = cy +. dy -. st;
              let a = alpha *. fade1(sx, mw) *. fade1(sy, mh);
              if (a > 0.01) {
                Js.Unsafe.coerce(ctx)##.globalAlpha := a;
                let half = sprite_size /. 2.;
                let _ =
                  Js.Unsafe.meth_call(
                    ctx,
                    "drawImage",
                    [|
                      Js.Unsafe.inject(sprite),
                      Js.Unsafe.inject(sx -. half),
                      Js.Unsafe.inject(sy -. half),
                      Js.Unsafe.inject(sprite_size),
                      Js.Unsafe.inject(sprite_size),
                    |],
                  );
                ();
              };
            };
          };
        };
      };
      if (fine_alpha > 0.02) {
        draw_pass(g^ /. 2., fine_alpha, ~skip_coarse=true);
      };
      draw_pass(g^, 1., ~skip_coarse=false);
      /* pulses ride on top of the lattice */
      let (live_pulses, done_pulses) =
        List.partition((p: pulse) => t -. p.t0 < pulse_ms, pulses^);
      pulses := live_pulses;
      List.iter(
        (p: pulse) => {
          let (mx, my) = pulse_at(p, 1.);
          let (cx, cy) = model_to_content((mx, my));
          deposit(cx, cy, 3.5);
        },
        done_pulses,
      );
      List.iter(
        (p: pulse) => {
          let tt = (t -. p.t0) /. pulse_ms;
          /* head + three tail samples fading behind */
          List.iteri(
            (k, back) => {
              let tk = max(0., tt -. back);
              let (mx, my) = pulse_at(p, tk);
              let cx = mx *. z +. pan_slack
              and cy = my *. z +. pan_slack;
              let (ddx, ddy) = displacement_at(cx, cy);
              let sx = cx +. ddx -. sl
              and sy = cy +. ddy -. st;
              let a =
                (k == 0 ? 0.9 : 0.5 -. 0.13 *. float_of_int(k))
                *. fade1(sx, mw)
                *. fade1(sy, mh);
              if (a > 0.02) {
                Js.Unsafe.coerce(ctx)##.globalAlpha := a;
                let _ = Js.Unsafe.meth_call(ctx, "beginPath", [||]);
                let _ =
                  Js.Unsafe.meth_call(
                    ctx,
                    "arc",
                    [|
                      Js.Unsafe.inject(sx),
                      Js.Unsafe.inject(sy),
                      Js.Unsafe.inject(k == 0 ? 1.8 : 1.2),
                      Js.Unsafe.inject(0.),
                      Js.Unsafe.inject(2. *. Float.pi),
                    |],
                  );
                let _ = Js.Unsafe.meth_call(ctx, "fill", [||]);
                ();
              };
            },
            List.init(4, k => float_of_int(k) *. 0.06),
          );
        },
        live_pulses,
      );
      Js.Unsafe.coerce(ctx)##.globalAlpha := 1.;
      let _ = Js.Unsafe.meth_call(ctx, "restore", [||]);
      ();
    };
    if (sim_active^ || pulses^ != [] || suctions^ != [] || zoom_settling) {
      if (! raf_running^) {
        raf_running := true;
      };
      let _ =
        Js.Unsafe.meth_call(
          Js.Unsafe.global##.window,
          "requestAnimationFrame",
          [|Js.Unsafe.inject(Js.Unsafe.callback(() => draw()))|],
        );
      ();
    } else {
      raf_running := false;
    };
  };
};

/* schedule one draw after the current render is painted (post-patch) */
let request_draw = (): unit =>
  if (! draw_queued^ && ! raf_running^) {
    draw_queued := true;
    let _ =
      Js.Unsafe.meth_call(
        Js.Unsafe.global##.window,
        "requestAnimationFrame",
        [|Js.Unsafe.inject(Js.Unsafe.callback(() => draw()))|],
      );
    ();
  };

/* launch a pulse along an edge's bezier (model-space control points) */
let pulse_edge =
    (
      ~wire=[],
      p0: (float, float),
      p1: (float, float),
      p2: (float, float),
      p3: (float, float),
    )
    : unit => {
  pulses :=
    [
      {
        wire,
        p0,
        p1,
        p2,
        p3,
        t0: now(),
      },
      ...pulses^,
    ];
  request_draw();
};

/* splash: one impulse into the medium at a model-space point */
let splash = (~amp: float=default_amp, (x, y): (float, float)): unit => {
  let (cx, cy) = model_to_content((x, y));
  deposit(cx, cy, amp);
  request_draw();
};

let suction = ((x, y): (float, float)): unit => {
  suctions :=
    [
      {
        su_p: (x, y),
        su_t0: now(),
      },
      ...suctions^,
    ];
  sim_active := true;
  request_draw();
};
suction_fwd := suction;
deposit_fwd :=
  (
    (cx, cy, amp) => {
      deposit(cx, cy, amp);
      request_draw();
    }
  );

/* drag wake: deposit energy along the path between successive drag
   samples — the stick pulled through water. Cleared on drop; the shed
   waves persist and ring down on their own. */
let set_field = (p: option((float, float))): unit => {
  switch (field^, p) {
  | (Some((px, py)), Some((x, y))) =>
    let (c0x, c0y) = model_to_content((px, py));
    let (c1x, c1y) = model_to_content((x, y));
    let d = Float.hypot(c1x -. c0x, c1y -. c0y);
    let steps = max(1, int_of_float(d /. cell));
    for (k in 1 to steps) {
      let f = float_of_int(k) /. float_of_int(steps);
      deposit(
        c0x +. (c1x -. c0x) *. f,
        c0y +. (c1y -. c0y) *. f,
        /* speed-scaled, capped: fast pulls churn harder */
        min(stroke_amp^ *. (0.4 +. d /. 24.), stroke_amp^ *. 2.),
      );
    };
  | (None, Some((x, y))) =>
    let (cx, cy) = model_to_content((x, y));
    deposit(cx, cy, stroke_amp^);
  | (_, None) => last_geom := ((-1), (-1), 0., 0., 0.)
  };
  field := p;
  request_draw();
};

files.canvas/upstream/CanvasScore.re:
/* CanvasScore — the staging language. A beat's choreography as a pure,
   validated value built from the graph diff BEFORE anything animates.
   CanvasEnact plays it, Animation takes its arrival times from it, the
   camera its frames. One score per beat; the actor is the only cause;
   effects never precede the actor's arrival. Principles and the shape's
   future (agent-authored emotes/say cues): plans/agent-canvas-principles.md */

type pos = CanvasLayout.pos;

/* where on the board the actor stands */
type site =
  | Node(string)
  | Edge(string)
  | Point(pos)
  | Centroid(list(string))
  | Here;

/* the actor's visible state during an act */
type emote =
  | Think
  | Edit
  | Erase
  | Tidy
  | Look
  | Rest;

/* a change to canvas content */
type effect =
  | Appear(string) /* node key grows in */
  | Form(string, list(string)) /* product dot forms from its parts */
  | Draw(string) /* edge name: the arrow is pulled along its path */
  | Pill(string) /* edge label settles in */
  | Reveal(string) /* edge name: its path draws on, then its pill — no ride
                      (the "and the rest" act when there are more new edges
                      than the actor rides) */
  | Vanish(string) /* node key shrinks out */
  | Erase(string) /* edge name retracts */
  | Change(string) /* cue on a modified element */
  | Drift /* existing nodes glide to their new places */
  | Ripple(site)
  | Say(string);

type timed_effect = {
  effect,
  at: int, /* ms from the act's start */
  dur: int,
};

/* one cause, one actor, one place: travel -> pause -> effects -> settle */
type act = {
  cause: string,
  at: site,
  emote,
  travel_ms: int,
  pause_ms: int,
  effects: list(timed_effect),
  settle_ms: int,
};

type frame = {
  center: pos,
  zoom: float,
};

type score = {
  cause: string,
  acts: list((int, act)), /* absolute start ms, non-decreasing */
  frames: list((int, frame)), /* camera cues, leading the act's travel */
  total_ms: int,
};

type tempo = {
  travel_min: int,
  travel_max: int,
  px_per_ms: float,
  pause: int,
  effect: int,
  settle: int,
  bloom_gap: int, /* a type's terminals bloom this far apart */
  min_gap: int, /* between effects of different acts */
  drift_ms: int,
  /* A2 without exception: every definition and every edge is its own act
     (2026-09-06, andrew: a batch at a centroid reads as "functions
     appearing with the agent standing still"). A long beat is bounded by
     COMPRESSING the tempo toward [floor], never by merging acts. */
  budget_ms: int, /* compress when the beat would run longer than this */
  floor: float /* the smallest compression factor (trial 6: 1.1 s/act was "boom boom boom") */
};

/* 2026-09-04: slowed after trial 6 ("boom boom boom") — about 1.9 s per act */
let tempo = {
  travel_min: 450,
  travel_max: 900,
  px_per_ms: 1.0,
  pause: 500,
  effect: 320,
  settle: 450,
  bloom_gap: 120,
  min_gap: 150,
  drift_ms: 700,
  budget_ms: 24000,
  floor: 0.6,
};

/* the same tempo, every phase scaled by [f] (the ride's own minimum in
   edge_act scales with travel) */
let compress = (t: tempo, f: float): tempo => {
  let sc = x => max(1, int_of_float(float_of_int(x) *. f));
  {
    ...t,
    travel_min: sc(t.travel_min),
    travel_max: sc(t.travel_max),
    px_per_ms: t.px_per_ms /. f,
    pause: sc(t.pause),
    effect: sc(t.effect),
    settle: sc(t.settle),
    bloom_gap: sc(t.bloom_gap),
    min_gap: sc(t.min_gap),
    drift_ms: sc(t.drift_ms),
  };
};

/* ---------------- inputs ---------------- */

type new_node = {
  key: string,
  anchor: option(string), /* a terminal's anchor node, if it is one */
  p: pos,
  /* the story's order: a named definition's place in the program; an
     unnamed glyph (a builtin, a product) the place of the first function
     that needs it; [max_int] when nothing says. Acts follow this, not the
     screen position (2026-09-06: the score opened on `(Int, Int)` at the
     far left instead of the module the agent wrote). */
  order: int,
};

type new_edge = {
  name: string,
  src: string,
  dst: string,
  product: option((string, list(string))) /* new anonymous product source */
};

type diff = {
  d_cause: string,
  added: list(new_node),
  edges: list(new_edge),
  removed: list((string, pos)),
  removed_edges: list((string, pos)), /* name, a point on the arrow */
  /* elements whose LOOK changed (a hole filled, a constructor added, an
     error fixed, a type changed): key or edge name, and where to touch */
  changed: list((string, pos)),
  moved: list((string, pos, pos)), /* key, from, to */
  actor: option(pos),
};

/* ---------------- geometry helpers ---------------- */

let dist = (a: pos, b: pos): float =>
  sqrt((a.x -. b.x) *. (a.x -. b.x) +. (a.y -. b.y) *. (a.y -. b.y));

let travel_for = (~tempo, d: float): int =>
  max(
    tempo.travel_min,
    min(tempo.travel_max, int_of_float(d /. tempo.px_per_ms)),
  );

let centroid = (ps: list(pos)): option(pos) =>
  switch (ps) {
  | [] => None
  | _ =>
    let n = float_of_int(List.length(ps));
    Some({
      x: List.fold_left((s, p: pos) => s +. p.x, 0., ps) /. n,
      y: List.fold_left((s, p: pos) => s +. p.y, 0., ps) /. n,
    });
  };

let site_pos = (~pos_of: string => option(pos), s: site): option(pos) =>
  switch (s) {
  | Node(k) => pos_of(k)
  | Edge(_) => None
  | Point(p) => Some(p)
  | Centroid(ks) => centroid(List.filter_map(pos_of, ks))
  | Here => None
  };

let act_len = (a: act): int => {
  let body =
    List.fold_left(
      (m, e: timed_effect) => max(m, e.at + e.dur),
      a.travel_ms + a.pause_ms,
      a.effects,
    );
  body + a.settle_ms;
};

/* ---------------- planning ---------------- */

/* a definition = a new primary node with the new terminals anchored on it */
type definition = {
  primary: new_node,
  terminals: list(new_node),
};

let definitions = (added: list(new_node)): list(definition) => {
  let is_new = k => List.exists((n: new_node) => n.key == k, added);
  let primaries =
    List.filter(
      (n: new_node) =>
        switch (n.anchor) {
        | None => true
        | Some(a) => !is_new(a) /* an orphan terminal leads its own act */
        },
      added,
    )
    /* program order first; the screen's reading order breaks ties */
    |> List.sort((a: new_node, b: new_node) =>
         compare((a.order, a.p.x, a.p.y), (b.order, b.p.x, b.p.y))
       );
  List.map(
    (p: new_node) =>
      {
        primary: p,
        terminals:
          List.filter(
            (n: new_node) => n.anchor == Some(p.key) && n.key != p.key,
            added,
          ),
      },
    primaries,
  );
};

let definition_act = (~tempo, ~cause, ~from: option(pos), d: definition): act => {
  let travel_ms =
    switch (from) {
    | Some(f) => travel_for(~tempo, dist(f, d.primary.p))
    | None => tempo.travel_min
    };
  let t0 = travel_ms + tempo.pause;
  {
    cause,
    at: Node(d.primary.key),
    emote: Edit,
    travel_ms,
    pause_ms: tempo.pause,
    effects:
      [
        {
          effect: Appear(d.primary.key),
          at: t0,
          dur: tempo.effect,
        },
        {
          effect: Ripple(Node(d.primary.key)),
          at: t0 + 60,
          dur: 0,
        },
      ]
      @ List.mapi(
          (i, t: new_node) =>
            {
              effect: Appear(t.key),
              at: t0 + tempo.bloom_gap * (i + 1),
              dur: tempo.effect,
            },
          d.terminals,
        ),
    settle_ms: tempo.settle,
  };
};

/* every definition at once: still an actor, still a place, one stagger */
let batch_act =
    (~tempo, ~cause, ~from: option(pos), ds: list(definition)): act => {
  let keys = List.map((d: definition) => d.primary.key, ds);
  let c = centroid(List.map((d: definition) => d.primary.p, ds));
  let travel_ms =
    switch (from, c) {
    | (Some(f), Some(c)) => travel_for(~tempo, dist(f, c))
    | _ => tempo.travel_min
    };
  let t0 = travel_ms + tempo.pause;
  let all =
    List.concat_map((d: definition) => [d.primary, ...d.terminals], ds);
  {
    cause,
    at: Centroid(keys),
    emote: Edit,
    travel_ms,
    pause_ms: tempo.pause,
    effects:
      List.mapi(
        (i, n: new_node) =>
          {
            effect: Appear(n.key),
            at: t0 + 80 * i,
            dur: tempo.effect,
          },
        all,
      ),
    settle_ms: tempo.settle,
  };
};

/* more new edges than the actor rides: one act at their centroid reveals
   them all, staggered — every new edge is scheduled by the score, none is
   left to appear with the render (the illegal "labels before edges" state) */
let rest_act =
    (
      ~tempo,
      ~cause,
      ~from: option(pos),
      ~pos_of: string => option(pos),
      es: list(new_edge),
    )
    : act => {
  let dsts = List.filter_map((e: new_edge) => pos_of(e.dst), es);
  let c = centroid(dsts);
  let travel_ms =
    switch (from, c) {
    | (Some(f), Some(c)) => travel_for(~tempo, dist(f, c))
    | _ => tempo.travel_min
    };
  let t0 = travel_ms + tempo.pause;
  {
    cause,
    at: Centroid(List.map((e: new_edge) => e.dst, es)),
    emote: Edit,
    travel_ms,
    pause_ms: tempo.pause,
    effects:
      List.mapi(
        (i, e: new_edge) =>
          {
            effect: Reveal(e.name),
            at: t0 + 150 * i,
            dur: tempo.effect,
          },
        es,
      ),
    settle_ms: tempo.settle,
  };
};

let edge_act =
    (
      ~tempo,
      ~cause,
      ~from: option(pos),
      ~pos_of: string => option(pos),
      ~orphans: list(new_node),
      e: new_edge,
    )
    : act => {
  let sp = pos_of(e.src)
  and dp = pos_of(e.dst);
  let travel_ms =
    switch (from, sp) {
    | (Some(f), Some(s)) => travel_for(~tempo, dist(f, s))
    | _ => tempo.travel_min
    };
  let t0 = travel_ms + tempo.pause;
  let (form, t_draw) =
    switch (e.product) {
    | Some((pk, parts)) =>
      /* a visit per part (a pause each), then the lines draw in — all on
         the beat's tempo, so a compressed score compresses here too */
      let dur = (tempo.pause - 100) * List.length(parts) + tempo.effect;
      (
        [
          {
            effect: Form(pk, parts),
            at: t0,
            dur,
          },
        ],
        t0 + dur + 80,
      );
    | None => ([], t0)
    };
  let ride =
    switch (sp, dp) {
    | (Some(s), Some(d)) =>
      max(tempo.travel_min + 250, travel_for(~tempo, dist(s, d) *. 1.6))
    | _ => tempo.travel_max
    };
  /* a terminal this edge lands on (or leaves from) blooms as it arrives */
  let ends =
    List.filter_map(
      (n: new_node) =>
        n.key == e.dst
          ? Some({
              effect: Appear(n.key),
              at: t_draw + ride,
              dur: tempo.effect,
            })
          : n.key == e.src
              ? Some({
                  effect: Appear(n.key),
                  at: t0,
                  dur: tempo.effect,
                })
              : None,
      orphans,
    );
  {
    cause,
    at: Edge(e.name),
    emote: Edit,
    travel_ms,
    pause_ms: tempo.pause,
    effects:
      form
      @ ends
      @ [
        {
          effect: Draw(e.name),
          at: t_draw,
          dur: ride,
        },
        {
          effect: Pill(e.name),
          at: t_draw + ride,
          dur: tempo.effect,
        },
      ],
    settle_ms: tempo.settle,
  };
};

let removal_act =
    (~tempo, ~cause, ~from: option(pos), (k, p): (string, pos)): act => {
  let travel_ms =
    switch (from) {
    | Some(f) => travel_for(~tempo, dist(f, p))
    | None => tempo.travel_min
    };
  let t0 = travel_ms + tempo.pause;
  {
    cause,
    at: Point(p),
    emote: Erase,
    travel_ms,
    pause_ms: tempo.pause,
    effects: [
      {
        effect: Vanish(k),
        at: t0,
        dur: tempo.effect,
      },
      {
        effect: Ripple(Node(k)),
        at: t0 + 60,
        dur: 0,
      },
    ],
    settle_ms: tempo.settle,
  };
};

/* an arrow is erased at its label: the actor travels there, the line
   retracts and the pill fades */
let erase_act =
    (~tempo, ~cause, ~from: option(pos), (name, p): (string, pos)): act => {
  let travel_ms =
    switch (from) {
    | Some(f) => travel_for(~tempo, dist(f, p))
    | None => tempo.travel_min
    };
  let t0 = travel_ms + tempo.pause;
  {
    cause,
    at: Point(p),
    emote: Erase,
    travel_ms,
    pause_ms: tempo.pause,
    effects: [
      {
        effect: Erase(name),
        at: t0,
        dur: tempo.effect + 200,
      },
      {
        effect: Ripple(Point(p)),
        at: t0 + 60,
        dur: 0,
      },
    ],
    settle_ms: tempo.settle,
  };
};

/* a changed element keeps its old look until the actor touches it: the
   swap and a pulse are the effect */
let change_act =
    (~tempo, ~cause, ~from: option(pos), (k, p): (string, pos)): act => {
  let travel_ms =
    switch (from) {
    | Some(f) => travel_for(~tempo, dist(f, p))
    | None => tempo.travel_min
    };
  let t0 = travel_ms + tempo.pause;
  {
    cause,
    at: Point(p),
    emote: Edit,
    travel_ms,
    pause_ms: tempo.pause,
    effects: [
      {
        effect: Change(k),
        at: t0,
        dur: tempo.effect,
      },
      {
        effect: Ripple(Point(p)),
        at: t0 + 60,
        dur: 0,
      },
    ],
    settle_ms: tempo.settle,
  };
};

let drift_act = (~tempo, ~cause, ~from: option(pos), moved): act => {
  let keys = List.map(((k, _, _)) => k, moved);
  let c = centroid(List.map(((_, _, to_)) => to_, moved));
  let travel_ms =
    switch (from, c) {
    | (Some(f), Some(c)) =>
      min(tempo.travel_max, travel_for(~tempo, dist(f, c)))
    | _ => tempo.travel_min
    };
  let t0 = travel_ms + tempo.pause;
  {
    cause,
    at: Centroid(keys),
    emote: Tidy,
    travel_ms,
    pause_ms: tempo.pause,
    effects: [
      {
        effect: Ripple(Centroid(keys)),
        at: t0,
        dur: 0,
      },
      {
        effect: Drift,
        at: t0,
        dur: tempo.drift_ms,
      },
    ],
    settle_ms: tempo.settle,
  };
};

/* where the actor ends an act (for the next act's travel) */
let act_end_pos = (~pos_of, a: act): option(pos) =>
  switch (a.at) {
  | Edge(name) =>
    /* the ride ends at the codomain: the last Draw's dst is unknown here,
       so callers pass pos_of that resolves edge names to their dst */
    pos_of("edge-end:" ++ name)
  | s => site_pos(~pos_of, s)
  };

/* lay the acts out in time, each starting when the previous settles */
let sequence = (acts: list(act)): (list((int, act)), int) => {
  let (rev, t) =
    List.fold_left(
      ((acc, t), a) => ([(t, a), ...acc], t + act_len(a)),
      ([], 0),
      acts,
    );
  (List.rev(rev), t);
};

let rec plan =
        (~tempo=tempo, ~pos_of: string => option(pos), diff: diff): score => {
  let s = plan_at(~tempo, ~pos_of, diff);
  /* over budget: the same acts, compressed — never merged (A2) */
  if (s.total_ms > tempo.budget_ms && tempo.floor < 1.) {
    let f =
      max(
        tempo.floor,
        float_of_int(tempo.budget_ms) /. float_of_int(s.total_ms),
      );
    plan_at(~tempo=compress(tempo, f), ~pos_of, diff);
  } else {
    s;
  };
}
and plan_at = (~tempo, ~pos_of: string => option(pos), diff: diff): score => {
  let cause = diff.d_cause;
  let pos_of' = k =>
    switch (pos_of(k)) {
    | Some(p) => Some(p)
    | None =>
      switch (List.find_opt((n: new_node) => n.key == k, diff.added)) {
      | Some(n) => Some(n.p)
      | None => List.assoc_opt(k, diff.removed)
      }
    };
  /* a new anonymous product that sources a new edge is formed by that
     edge's act (Form: visit the parts, lines draw in, the dot grows) —
     not a definition of its own */
  let formed =
    List.filter_map(
      (e: new_edge) => Option.map(fst, e.product),
      diff.edges,
    );
  let defs =
    definitions(
      List.filter((n: new_node) => !List.mem(n.key, formed), diff.added),
    );
  let edge_keys =
    List.concat_map((e: new_edge) => [e.src, e.dst], diff.edges);
  /* terminals with an old anchor that a new edge touches ride that edge */
  let (edge_orphans, own_defs) =
    List.partition(
      (d: definition) =>
        d.terminals == []
        && d.primary.anchor != None
        && List.mem(d.primary.key, edge_keys),
      defs,
    );
  let orphans = List.map((d: definition) => d.primary, edge_orphans);
  let edges = diff.edges;
  /* threading the actor's position through the acts */
  let from = ref(diff.actor);
  let mk = f => {
    let a = f(from^);
    let end_ =
      switch (a.at) {
      | Edge(name) =>
        List.find_opt((e: new_edge) => e.name == name, diff.edges)
        |> Util.OptUtil.and_then((e: new_edge) => pos_of'(e.dst))
      | s => site_pos(~pos_of=pos_of', s)
      };
    switch (end_) {
    | Some(p) => from := Some(p)
    | None => ()
    };
    a;
  };
  /* removals: the board keeps the removed elements as ghosts until their
     act (CanvasSidebar's leaving set), so the actor erases something that
     is still there — arrows first (a function goes before its type),
     then nodes, each with its own act */
  let removals =
    List.map(
      e => mk(from => erase_act(~tempo, ~cause, ~from, e)),
      diff.removed_edges,
    )
    @ List.map(
        r => mk(from => removal_act(~tempo, ~cause, ~from, r)),
        diff.removed,
      );
  let changes =
    List.map(
      c => mk(from => change_act(~tempo, ~cause, ~from, c)),
      diff.changed,
    );
  let additions =
    List.map(
      d => mk(from => definition_act(~tempo, ~cause, ~from, d)),
      own_defs,
    );
  let edge_acts =
    List.map(
      e =>
        mk(from =>
          edge_act(~tempo, ~cause, ~from, ~pos_of=pos_of', ~orphans, e)
        ),
      edges,
    );
  /* edges we do not enact still need their terminals to appear */
  let leftover_orphans =
    edges == [] && orphans != []
      ? [
        mk(from =>
          batch_act(
            ~tempo,
            ~cause,
            ~from,
            List.map(
              (n: new_node) =>
                {
                  primary: n,
                  terminals: [],
                },
              orphans,
            ),
          )
        ),
      ]
      : [];
  let drift =
    diff.moved == []
      ? [] : [mk(from => drift_act(~tempo, ~cause, ~from, diff.moved))];
  /* existing nodes make room FIRST when something new arrives, so a new
     node's lines meet nodes that are already where they will be; a beat
     that only moves things is a closing tidy */
  ignore(rest_act);
  let (acts, total_ms) =
    additions @ edge_acts @ leftover_orphans == []
      ? sequence(removals @ changes @ drift)
      : sequence(
          removals @ changes @ drift @ additions @ edge_acts @ leftover_orphans,
        );
  {
    cause,
    acts,
    frames: [],
    total_ms,
  };
};

/* ---------------- framing (C1–C5) ---------------- */

type bbox = {
  x0: float,
  y0: float,
  x1: float,
  y1: float,
};

let bbox_of = (~pad: float, ps: list(pos)): option(bbox) =>
  switch (ps) {
  | [] => None
  | [p, ...rest] =>
    Some(
      List.fold_left(
        (b, q: pos) =>
          {
            x0: min(b.x0, q.x -. pad),
            y0: min(b.y0, q.y -. pad),
            x1: max(b.x1, q.x +. pad),
            y1: max(b.y1, q.y +. pad),
          },
        {
          x0: p.x -. pad,
          y0: p.y -. pad,
          x1: p.x +. pad,
          y1: p.y +. pad,
        },
        rest,
      ),
    )
  };

let bbox_center = (b: bbox): pos => {
  x: (b.x0 +. b.x1) /. 2.,
  y: (b.y0 +. b.y1) /. 2.,
};

/* the viewport's board-space rect at a frame */
let view_rect = (~pane as (w, h): (float, float), f: frame): bbox => {
  let hw = w /. 2. /. f.zoom
  and hh = h /. 2. /. f.zoom;
  {
    x0: f.center.x -. hw,
    y0: f.center.y -. hh,
    x1: f.center.x +. hw,
    y1: f.center.y +. hh,
  };
};

let contains = (~margin: float, outer: bbox, inner: bbox): bool =>
  inner.x0 >= outer.x0
  +. margin
  && inner.x1 <= outer.x1
  -. margin
  && inner.y0 >= outer.y0
  +. margin
  && inner.y1 <= outer.y1
  -. margin;

/* the whole program is shown whenever it fits at this zoom or better —
   a node cut off at the pane's edge is worse than smaller glyphs
   (2026-09-06: at 0.74 the rule fell to a pan that halved `Kind`) */
let whole_fit_min = 0.6;
let frame_margin = 30.;

/* the camera's decision for one act: the required set (actor's site, the
   act's targets, anything not yet exposed) must be in frame; among frames
   that do it, the whole program if it fits at >= 0.75, else the smallest
   pan (and only then a zoom out). None = hold still. */
let frame_for =
    (
      ~pane: (float, float),
      ~cur: frame,
      ~all: list(pos),
      ~required: list(pos),
      /* wanted in view when they fit (C2's unexposed nodes); a set the
         view cannot hold at the minimum zoom made the minimal pan chase
         one edge then the other, every act */
      ~soft: list(pos)=[],
      (),
    )
    : option(frame) => {
  let (w, h) = pane;
  let pad = 44.;
  let fit_of = (b: bbox) =>
    min(
      (w -. 2. *. frame_margin) /. max(1., b.x1 -. b.x0),
      (h -. 2. *. frame_margin) /. max(1., b.y1 -. b.y0),
    );
  let with_soft = bbox_of(~pad, required @ soft);
  let required =
    switch (with_soft) {
    | Some(b) when fit_of(b) >= 0.5 => required @ soft
    | _ => required
    };
  switch (bbox_of(~pad, required)) {
  | None => None
  | Some(req) =>
    /* the program's box is its NODES padded by a node's size — the same
       box the camera's own whole-program framing judges by; the act's
       targets (label points, arrow ends) only have to be in view */
    let whole = bbox_of(~pad=32., all);
    let fit = (b: bbox) =>
      min(
        (w -. 2. *. frame_margin) /. max(1., b.x1 -. b.x0),
        (h -. 2. *. frame_margin) /. max(1., b.y1 -. b.y0),
      );
    let same = (a: frame, b: frame) =>
      dist(a.center, b.center) < 8. && abs_float(a.zoom -. b.zoom) < 0.02;
    /* the whole program is framed as tightly as the camera frames it
       (12 px), so the two never disagree about its zoom */
    let fit_tight = (b: bbox) =>
      min(
        (w -. 24.) /. max(1., b.x1 -. b.x0),
        (h -. 24.) /. max(1., b.y1 -. b.y0),
      );
    let whole_frame =
      switch (whole) {
      | Some(wb) when fit_tight(wb) >= whole_fit_min =>
        Some({
          center: bbox_center(wb),
          zoom: min(1., fit_tight(wb)),
        })
      | _ => None
      };
    switch (whole_frame) {
    | Some(f) =>
      /* the whole program fits: hold while it (and the act's targets) is
         in view; otherwise frame it — never zooming IN mid-score (the
         zoom is a slow variable; the camera eases in between bursts) */
      let vr = view_rect(~pane, cur);
      if (contains(~margin=0., vr, Option.get(whole))
          && contains(~margin=0., vr, req)) {
        None;
      } else {
        let f = {
          ...f,
          zoom: min(cur.zoom, f.zoom),
        };
        same(cur, f) ? None : Some(f);
      };
    | None =>
      let vr = view_rect(~pane, cur);
      /* hysteresis: a target that is in view, even inside the margin
         band, holds the camera — panning it to the band's edge on every
         act made a 26-act score rock 20 px left and right per act */
      if (contains(~margin=6., vr, req)) {
        None;
      } else {
        /* zoom out only if the required set cannot fit at this zoom; and
           when everything currently in view plus the required set fits
           at a readable zoom, keep it all rather than pan a node off the
           edge (C1: the most other content in frame) */
        let in_view =
          List.filter(
            (p: pos) =>
              p.x >= vr.x0 && p.x <= vr.x1 && p.y >= vr.y0 && p.y <= vr.y1,
            all,
          );
        let keep = bbox_of(~pad=32., in_view @ required);
        /* only when the viewer had the WHOLE program in view: then losing
           a node off the edge is the greater harm. A large program pans. */
        let had_whole = List.length(in_view) == List.length(all);
        switch (keep) {
        | Some(kb)
            when
              had_whole
              && !contains(~margin=frame_margin, vr, kb)
              && fit(kb) >= 0.5
              && fit(kb) < cur.zoom =>
          let f = {
            center: bbox_center(kb),
            zoom: fit(kb),
          };
          same(cur, f) ? None : Some(f);
        | _ =>
          let zoom = min(cur.zoom, max(0.5, fit(req)));
          let f0 = {
            ...cur,
            zoom,
          };
          let vr = view_rect(~pane, f0);
          /* minimal pan: shift just enough to bring req inside the margin */
          let dx =
            req.x0 < vr.x0 +. frame_margin
              ? req.x0 -. (vr.x0 +. frame_margin)
              : req.x1 > vr.x1 -. frame_margin
                  ? req.x1 -. (vr.x1 -. frame_margin) : 0.;
          let dy =
            req.y0 < vr.y0 +. frame_margin
              ? req.y0 -. (vr.y0 +. frame_margin)
              : req.y1 > vr.y1 -. frame_margin
                  ? req.y1 -. (vr.y1 -. frame_margin) : 0.;
          let f = {
            center: {
              x: cur.center.x +. dx,
              y: cur.center.y +. dy,
            },
            zoom,
          };
          same(cur, f) ? None : Some(f);
        };
      };
    };
  };
};

/* The camera needs rendered edge endpoints as well as node centers.
   An Edge act has no node site: a node-only lookup silently yields an
   empty required set and leaves the camera behind during the draw. */
let with_edge_positions =
    (
      ~pos_of: string => option(pos),
      ~edges: list((string, pos, pos)),
      key: string,
    )
    : option(pos) =>
  switch (pos_of(key)) {
  | Some(_) as p => p
  | None =>
    List.find_map(
      ((name, src, dst)) =>
        key == "edge-src:" ++ name
          ? Some(src) : key == "edge-end:" ++ name ? Some(dst) : None,
      edges,
    )
  };

/* the positions an act needs in frame */
let act_targets = (~pos_of: string => option(pos), a: act): list(pos) => {
  let site = site_pos(~pos_of, a.at) |> Option.to_list;
  let eff =
    List.concat_map(
      (e: timed_effect) =>
        switch (e.effect) {
        | Appear(k)
        | Vanish(k)
        | Change(k) => Option.to_list(pos_of(k))
        | Form(pk, parts) => List.filter_map(pos_of, [pk, ...parts])
        | Draw(name)
        | Erase(name)
        | Pill(name)
        | Reveal(name) =>
          List.filter_map(pos_of, ["edge-src:" ++ name, "edge-end:" ++ name])
        | Drift
        | Say(_) => []
        | Ripple(s) => Option.to_list(site_pos(~pos_of, s))
        },
      a.effects,
    );
  site @ eff;
};

/* add camera cues: one per act at most, leading its travel. `exposed` =
   keys the viewer has already seen long enough; the rest are required. */
let with_frames =
    (
      ~pane: (float, float),
      ~cur: frame,
      ~pos_of: string => option(pos),
      ~all_keys: list(string),
      ~exposed: list(string),
      s: score,
    )
    : score => {
  let all = List.filter_map(pos_of, all_keys);
  let unexposed =
    List.filter_map(k => List.mem(k, exposed) ? None : pos_of(k), all_keys);
  /* C3: the beat is framed WHOLE before its first act — everything its
     acts will touch, in one view — and held; per-act frames only when an
     act's targets leave it (a 26-act module insert used to pan 200–500 px
     on every act, following the actor around) */
  let beat_targets =
    List.concat_map(((_, a)) => act_targets(~pos_of, a), s.acts);
  let (frames0, cur) =
    switch (
      frame_for(
        ~pane,
        ~cur,
        ~all,
        ~required=beat_targets,
        ~soft=unexposed,
        (),
      )
    ) {
    | Some(f) => ([(0, f)], f)
    | None => ([], cur)
    };
  let (frames, _) =
    List.fold_left(
      ((acc, cur), (t, a)) => {
        let required = act_targets(~pos_of, a);
        switch (frame_for(~pane, ~cur, ~all, ~required, ())) {
        | Some(f) => ([(t, f), ...acc], f)
        | None => (acc, cur)
        };
      },
      (frames0, cur),
      s.acts,
    );
  {
    ...s,
    frames: List.rev(frames),
  };
};

/* ---------------- queries for the player ---------------- */

let effects_abs = (s: score): list((int, act, timed_effect)) =>
  List.concat_map(
    ((t, a)) =>
      List.map((e: timed_effect) => (t + e.at, a, e), a.effects),
    s.acts,
  )
  |> List.sort(((t1, _, _), (t2, _, _)) => compare(t1, t2));

/* node key -> absolute ms its grow-in starts */
/* when each new node becomes visible: Appear at its cue; a product formed
   by an edge act grows at the END of the formation (the player visits
   the parts first, then the dot scales in over its last 320 ms) */
let appear_times = (s: score): list((string, int)) =>
  List.filter_map(
    ((t, _, e: timed_effect)) =>
      switch (e.effect) {
      | Appear(k) => Some((k, t))
      | Form(pk, _) => Some((pk, t + e.dur - min(320, e.dur * 2 / 5)))
      | _ => None
      },
    effects_abs(s),
  );

let drift_at = (s: score): option(int) =>
  List.find_map(
    ((t, _, e: timed_effect)) =>
      switch (e.effect) {
      | Drift => Some(t)
      | _ => None
      },
    effects_abs(s),
  );

/* the actor's own timeline: (t, where, emote). Arrive at t_start+travel,
   hold through the effects, leave at the act's end. Rides (Draw) are
   expanded by the player, which can sample the rendered path. */
let actor_path =
    (~pos_of: string => option(pos), s: score): list((int, pos, emote)) =>
  List.concat_map(
    ((t, a)) => {
      let where =
        switch (a.at) {
        | Edge(name) => pos_of("edge-src:" ++ name)
        | site => site_pos(~pos_of, site)
        };
      switch (where) {
      | None => []
      | Some(p) => [
          (t + a.travel_ms, p, a.emote),
          (t + act_len(a) - a.settle_ms, p, a.emote),
        ]
      };
    },
    s.acts,
  );

/* ---------------- validation (the journal checks, pure) ---------------- */

let validate = (~tempo=tempo, s: score): list(string) => {
  let v = ref([]);
  let bad = msg => v := [msg, ...v^];
  /* act starts never decrease; each act starts after the previous ends */
  ignore(
    List.fold_left(
      (prev_end, (t, a)) => {
        if (t < prev_end) {
          bad(
            Printf.sprintf(
              "OVERLAP: act at %dms starts before %dms",
              t,
              prev_end,
            ),
          );
        };
        t + act_len(a);
      },
      0,
      s.acts,
    ),
  );
  /* the actor precedes every effect */
  List.iter(
    ((_, a)) =>
      List.iter(
        (e: timed_effect) =>
          if (e.at < a.travel_ms + a.pause_ms) {
            bad(
              Printf.sprintf(
                "ORPHAN: effect at %dms before the actor arrives (%dms)",
                e.at,
                a.travel_ms + a.pause_ms,
              ),
            );
          },
        a.effects,
      ),
    s.acts,
  );
  /* structural effects of different acts keep a minimum gap */
  let structural = (e: timed_effect) =>
    switch (e.effect) {
    | Appear(_)
    | Draw(_)
    | Vanish(_)
    | Erase(_)
    | Drift => true
    | _ => false
    };
  ignore(
    List.fold_left(
      (prev, (t, a, e)) =>
        if (structural(e)) {
          switch (prev) {
          | Some((pt, pa)) when pa !== a && t - pt < tempo.min_gap =>
            bad(
              Printf.sprintf(
                "CROWDED: effects %dms apart across acts (min %d)",
                t - pt,
                tempo.min_gap,
              ),
            );
            Some((t, a));
          | _ => Some((t, a))
          };
        } else {
          prev;
        },
      None,
      effects_abs(s),
    ),
  );
  /* frames lead their act and never run backwards */
  ignore(
    List.fold_left(
      (prev, (t, _)) => {
        if (t < prev) {
          bad(
            Printf.sprintf("FRAME: cue at %dms after one at %dms", t, prev),
          );
        };
        t;
      },
      0,
      s.frames,
    ),
  );
  if (s.total_ms > 60000) {
    bad(Printf.sprintf("LONG: %dms", s.total_ms));
  };
  List.rev(v^);
};

/* A2's coverage: every element the diff adds is staged by some effect of
   the score (Appear/Form for nodes, Draw/Reveal for edges); anything else
   would appear at render with no actor — an ORPHAN. Removals are listed
   until removal choreography exists (they vanish at render today). */
let coverage = (diff: diff, s: score): list(string) => {
  let effects =
    List.map(((_, _, e: timed_effect)) => e.effect, effects_abs(s));
  let node_staged = k =>
    List.exists(
      fun
      | Appear(k') => k' == k
      | Form(pk, _) => pk == k
      | _ => false,
      effects,
    );
  let edge_staged = n =>
    List.exists(
      fun
      | Draw(n')
      | Reveal(n') => n' == n
      | _ => false,
      effects,
    );
  List.filter_map(
    (n: new_node) =>
      node_staged(n.key)
        ? None : Some("ORPHAN: node " ++ n.key ++ " unstaged"),
    diff.added,
  )
  @ List.filter_map(
      (e: new_edge) =>
        edge_staged(e.name)
          ? None : Some("ORPHAN: edge " ++ e.name ++ " unstaged"),
      diff.edges,
    )
  @ List.filter_map(
      ((k, _)) =>
        List.exists(
          fun
          | Vanish(k') => k' == k
          | _ => false,
          effects,
        )
          ? None : Some("ORPHAN: removal " ++ k ++ " unstaged"),
      diff.removed,
    )
  @ List.filter_map(
      ((n, _)) =>
        List.exists(
          fun
          | Erase(n') => n' == n
          | _ => false,
          effects,
        )
          ? None : Some("ORPHAN: erased edge " ++ n ++ " unstaged"),
      diff.removed_edges,
    )
  @ List.filter_map(
      ((k, _)) =>
        List.exists(
          fun
          | Change(k') => k' == k
          | _ => false,
          effects,
        )
          ? None : Some("ORPHAN: change of " ++ k ++ " unstaged"),
      diff.changed,
    );
};

/* absolute cue times of the Change effects (the staged old looks swap
   then) */
let change_times = (s: score): list((string, int)) =>
  List.filter_map(
    ((t, _, e: timed_effect)) =>
      switch (e.effect) {
      | Change(k) => Some((k, t))
      | _ => None
      },
    effects_abs(s),
  );

/* ---------------- journal ---------------- */

/* a Point site is named by what the act does there (its first targeted
   effect), so the journal reads "edit@damage" not "edit@·" */
let act_target_name = (a: act): option(string) =>
  List.find_map(
    (e: timed_effect) =>
      switch (e.effect) {
      | Change(k)
      | Vanish(k)
      | Appear(k) => Some(k)
      | Erase(n)
      | Draw(n)
      | Reveal(n) => Some(n)
      | _ => None
      },
    a.effects,
  );

let site_to_string = (s: site): string =>
  switch (s) {
  | Node(k) => k
  | Edge(n) => "ƒ" ++ n
  | Point(_) => "·"
  | Centroid(ks) => Printf.sprintf("%d nodes", List.length(ks))
  | Here => "here"
  };

let emote_to_string = (e: emote): string =>
  switch (e) {
  | Think => "think"
  | Edit => "edit"
  | Erase => "erase"
  | Tidy => "tidy"
  | Look => "look"
  | Rest => "rest"
  };

let act_to_string = ((t, a): (int, act)): string => {
  let n = kind =>
    List.length(
      List.filter((e: timed_effect) => kind(e.effect), a.effects),
    );
  let appear =
    n(e =>
      switch (e) {
      | Appear(_) => true
      | _ => false
      }
    );
  let bits =
    (appear > 0 ? [Printf.sprintf("+%d", appear)] : [])
    @ (
      n(e =>
        switch (e) {
        | Draw(_) => true
        | _ => false
        }
      )
      > 0
        ? ["draw"] : []
    )
    @ (
      n(e =>
        switch (e) {
        | Vanish(_) => true
        | _ => false
        }
      )
      > 0
        ? ["vanish"] : []
    )
    @ (
      n(e =>
        switch (e) {
        | Drift => true
        | _ => false
        }
      )
      > 0
        ? ["drift"] : []
    );
  Printf.sprintf(
    "%.1fs %s@%s %s",
    float_of_int(t) /. 1000.,
    emote_to_string(a.emote),
    switch (a.at, act_target_name(a)) {
    | (Point(_), Some(n)) => n
    | _ => site_to_string(a.at)
    },
    String.concat(" ", bits),
  );
};

let to_string = (s: score): string =>
  Printf.sprintf(
    "score[%s]: %d act(s) %.1fs, %d frame(s) — %s",
    s.cause,
    List.length(s.acts),
    float_of_int(s.total_ms) /. 1000.,
    List.length(s.frames),
    String.concat("; ", List.map(act_to_string, s.acts)),
  );

files.canvas/upstream/CanvasZoom.re:
/* Overview and direct manipulation share a zoom range. Automatic follow
   has its own, higher readability floor in CanvasCamera/CanvasScore. */
let min_zoom = 0.01;
let max_zoom = 2.5;
let clamp = (z: float): float => max(min_zoom, min(max_zoom, z));

/* Padding is in screen pixels, so an overview keeps a visible margin
   even when the graph needs a very small scale. */
let fit = (~width: float, ~height: float, ~aw: float, ~ah: float): float =>
  clamp(
    min(
      max(1., aw -. 32.) /. max(1., width),
      max(1., ah -. 32.) /. max(1., height),
    ),
  );

files.canvas/upstream/OptUtil.re:
let get = (if_none, o) =>
  switch (o) {
  | None => if_none()
  | Some(a) => a
  };
let get_or_fail = s => get(() => failwith(s));
let get_or_raise = e => get(() => raise(e));

let map2 = (f, o1, o2) =>
  switch (o1, o2) {
  | (None, _)
  | (_, None) => None
  | (Some(v1), Some(v2)) => Some(f(v1, v2))
  };

let some_if = (cond, a) => cond ? Some(a) : None;

let zip = (o1, o2) =>
  switch (o1, o2) {
  | (None, _)
  | (_, None) => None
  | (Some(a), Some(b)) => Some((a, b))
  };
let unzip = (o: option(('a, 'b))): (option('a), option('b)) =>
  switch (o) {
  | None => (None, None)
  | Some((a, b)) => (Some(a), Some(b))
  };
let traverse = (f: 'a => option('b), l: list('a)): option(list('b)) =>
  List.fold_right(
    (x, acc) => map2((y, ys) => [y, ...ys], f(x), acc),
    l,
    Some([]),
  );

let sequence = (l: list(option('a))): option(list('a)) =>
  traverse(Fun.id, l);

let and_then = (f, o) => Option.bind(o, f);

let replace = (f: 'a => option('a), o: 'a): 'a =>
  switch (f(o)) {
  | Some(a) => a
  | None => o
  };
let fold_left_opt:
  type a acc. ((acc, a) => option(acc), list(a), acc) => option(acc) =
  (f, list, init) => {
    let rec aux = (acc, rest) =>
      switch (rest) {
      | [] => Some(acc)
      | [x, ...xs] =>
        switch (f(acc, x)) {
        | None => None
        | Some(nextAcc) => aux(nextAcc, xs)
        }
      };
    aux(init, list);
  };

let filter = (f: 'a => bool, o: option('a)): option('a) =>
  switch (o) {
  | None => None
  | Some(a) => f(a) ? Some(a) : None
  };

let value_exn = (~none, o) => get(() => raise(none), o);

module Syntax = {
  let ( let* ) = Option.bind;
  let (let+) = (o, f) => Option.map(f, o);
  let (and+) = zip;
};

files.canvas/upstream/PerfTimer.re:
/* Wall-clock phase timers for the agent tool path and the canvas: each
   `time(label, f)` adds f's duration to its label; `summary()` renders
   the totals with counts and resets. Dependency-free (Date.now), so any
   layer can report; the constellation journal prints the summary on its
   5-second perf line and after each tool. */
open Js_of_ocaml;

let now = (): float => Js.Unsafe.coerce(Js.Unsafe.global)##._Date##now();

let totals: Hashtbl.t(string, (float, int)) = Hashtbl.create(16);

let record = (label: string, ms: float): unit => {
  let (t, n) =
    Option.value(Hashtbl.find_opt(totals, label), ~default=(0., 0));
  Hashtbl.replace(totals, label, (t +. ms, n + 1));
};

let time = (label: string, f: unit => 'a): 'a => {
  let t0 = now();
  let r = f();
  record(label, now() -. t0);
  r;
};

let reset = (): unit => Hashtbl.reset(totals);

/* "statics 312ms×2 | node-map 40ms×2 | edit 205ms×1", biggest first */
let summary = (): string => {
  let rows =
    Hashtbl.fold((k, (t, n), acc) => [(k, t, n), ...acc], totals, [])
    |> List.sort(((_, a, _), (_, b, _)) => compare(b, a));
  String.concat(
    " | ",
    List.map(
      ((k, t, n)) => Printf.sprintf("%s %.0fms×%d", k, t, n),
      rows,
    ),
  );
};

let take_summary = (): string => {
  let s = summary();
  reset();
  s;
};

files.extract/extract.re:
/* Reads a dune project's .cmt files and builds the Portolan graph.

   Two passes over the typed trees:
   1. [collect]: flatten every module (and nested module) into a list of
      items, and record which names the project declares, so that a
      reference from one file to another can be resolved.
   2. [emit]: turn each item into a node, an edge, a value or a test.

   Nothing here needs the compiler's environment or load path: paths are
   resolved by hand against the names collected in pass 1.

   A module that cannot be read this time (it does not type-check, or its
   annotations are older than its source) can be carried over from an
   earlier graph: see "carrying over" below. */

module G = Portolan_graph.Graph;
open Typedtree;

/* ---------- strings and files ---------- */

let (/\/) = Filename.concat;

/* "Vector__Scene" -> ["Vector"; "Scene"] */
let split_double_underscore = (s: string): list(string) => {
  let n = String.length(s);
  let rec go = (start, i, acc) =>
    if (i + 1 >= n) {
      List.rev([String.sub(s, start, n - start), ...acc]);
    } else if (s.[i] == '_' && s.[i + 1] == '_' && i > start) {
      go(i + 2, i + 2, [String.sub(s, start, i - start), ...acc]);
    } else {
      go(start, i + 1, acc);
    };

  List.filter(part => part != "", go(0, 0, []));
};

/* Collapse every run of whitespace into one space. */
let one_line = (s: string): string =>
  String.split_on_char(
    ' ',
    String.map(
      fun
      | '\n'
      | '\t'
      | '\r' => ' '
      | c => c,
      s,
    ),
  )
  |> List.filter(w => w != "")
  |> String.concat(" ");

let contains = (~sub: string, s: string): bool => {
  let n = String.length(sub)
  and m = String.length(s);
  let rec at = i => i + n <= m && (String.sub(s, i, n) == sub || at(i + 1));
  at(0);
};

let dedup = (l: list(string)): list(string) =>
  List.fold_left(
    (acc, x) =>
      if (List.mem(x, acc)) {
        acc;
      } else {
        [x, ...acc];
      },
    [],
    l,
  )
  |> List.rev;

let qualify = (mpath: list(string), name: string): string =>
  String.concat(".", mpath @ [name]);

/* Every .cmt / .cmti under [dir], sorted. */
let rec find_cmts = (dir: string): list(string) =>
  switch (Sys.readdir(dir)) {
  | exception (Sys_error(_)) => []
  | entries =>
    Array.sort(compare, entries);
    Array.to_list(entries)
    |> List.concat_map(entry => {
         let path = dir /\/ entry;
         if (Sys.is_directory(path)) {
           find_cmts(path);
         } else if (Filename.check_suffix(entry, ".cmt")
                    || Filename.check_suffix(entry, ".cmti")) {
           [path];
         } else {
           [];
         };
       });
  };

/* ---------- what pass 1 collects ---------- */

/* What an interface lets through. [Only sg]: just what [sg] lists. */
type vis =
  | All
  | Only(Types.signature)
  | Nothing;

/* Where an item sits: its enclosing modules, and what they export. */
type scope = {
  mpath: list(string),
  vis,
};

type item =
  | Type_item(scope, type_declaration)
  | Value_item(scope, value_binding, Location.t) /* loc of the whole item */
  | Prim_item(scope, value_description); /* external f : ... */

/* One compilation unit (one .ml file). The three tables map the idents
   the unit declares to their qualified names; idents are only unique
   within a unit, so each unit has its own. */
type unit_info = {
  u_modname: string, /* as compiled: "Vector__Scene" */
  u_mpath: list(string), /* as shown: ["Scene"] */
  u_file: string, /* relative to the root: "lib/scene.ml" */
  u_str: structure,
  u_vis: vis,
  u_types: Ident.Tbl.t(string),
  u_mods: Ident.Tbl.t(string),
  u_vals: Ident.Tbl.t(string),
  u_mtys: Ident.Tbl.t(Types.signature), /* [module type S = sig ... end] */
  mutable u_items: list(item) /* reversed */
};

/* A test before the graph is assembled. */
type found_test = {
  ft_test: G.test,
  ft_uses: list(string), /* the project names its body mentions */
  /* For an Alcotest case, which is written apart from what it tests: */
  ft_alcotest: option(alcotest),
}
and alcotest = {
  /* the qualified name of its file's module and a ".": the definitions
     under it are helpers, looked through to what they use */
  a_helpers: string,
  /* its suite and its place in it, when the suite is written out */
  a_case: option((string, int)),
  /* the top-level function that is its body, when it is one */
  a_fn: option(string),
};

/* A top-level definition before the graph is assembled: [mentions] are
   the project names its body refers to, not yet filtered. */
type def =
  | Edge(G.edge, list(string))
  | Value(G.value, list(string))
  /* from an earlier graph: what they mention is already in the record */
  | Carried_edge(G.edge)
  | Carried_value(G.value);

type ctx = {
  failing: option(list((string, int))),
  units: Hashtbl.t(string, unit_info), /* by compiled name */
  /* dune's alias modules: ("Vector", "Scene") -> "Vector__Scene" */
  wrappers: Hashtbl.t((string, string), string),
  /* [module S = Scene] inside the project: "Other.S" -> "Scene" */
  mod_aliases: Hashtbl.t(string, string),
  /* every type the project declares, by node key */
  type_decls: Hashtbl.t(string, (unit_info, scope, type_declaration)),
  /* every top-level value the project binds, by qualified name */
  def_names: Hashtbl.t(string, unit),
  /* modules carried over from an earlier graph, by compiled name: the
     name the graph shows them under ("Geo") */
  carried_units: Hashtbl.t(string, string),
  /* keys of the types those modules declare */
  carried_types: Hashtbl.t(string, unit),
  /* the earlier graph's nodes, by key (the carried ones as they are now) */
  previous_nodes: Hashtbl.t(string, G.node),
  seen: Hashtbl.t(string, unit), /* node keys already emitted */
  mutable nodes: list(G.node), /* reversed */
  mutable defs: list(def), /* reversed */
  mutable tests: list(found_test) /* reversed */
};

/* ---------- resolving paths to project names ---------- */

let unit_name = (ctx: ctx, modname: string): option(string) =>
  switch (Hashtbl.find_opt(ctx.units, modname)) {
  | Some(u) => Some(String.concat(".", u.u_mpath))
  | None => Hashtbl.find_opt(ctx.carried_units, modname)
  };

/* The qualified name of the project module a path denotes, if any. */
let rec module_prefix = (ctx: ctx, u: unit_info, p: Path.t): option(string) =>
  switch (p) {
  | Pident(id) =>
    switch (Ident.Tbl.find_opt(u.u_mods, id)) {
    | Some(prefix) => Some(prefix)
    | None =>
      if (Ident.persistent(id)) {
        unit_name(ctx, Ident.name(id));
      } else {
        None;
      }
    }
  | [@implicit_arity] Pdot(Pident(w), sub)
      when Hashtbl.mem(ctx.wrappers, (Ident.name(w), sub)) =>
    /* Vector.Scene, through dune's alias module */
    unit_name(ctx, Hashtbl.find(ctx.wrappers, (Ident.name(w), sub)))
  | [@implicit_arity] Pdot(m, sub) =>
    module_prefix(ctx, u, m)
    |> Option.map(prefix => {
         let q = prefix ++ "." ++ sub;
         Option.value(Hashtbl.find_opt(ctx.mod_aliases, q), ~default=q);
       })
  | Papply(_)
  | Pextra_ty(_) => None
  };

/* The node key of a project type, if the path names one. [from] is the
   module the reference is written in. */
let project_type =
    (ctx: ctx, u: unit_info, ~from: list(string), p: Path.t): option(string) => {
  let declared = key =>
    if (Hashtbl.mem(ctx.type_decls, key)
        || Hashtbl.mem(ctx.carried_types, key)) {
      Some(key);
    } else {
      None;
    };
  switch (p) {
  | Pident(id) =>
    switch (Ident.Tbl.find_opt(u.u_types, id)) {
    | Some(key) => Some(key)
    | None =>
      /* An ident pass 1 did not see (it came through an include, say):
         look the name up in the enclosing modules, innermost first. */
      let rec outward = (
        fun
        | [] => None
        | [_, ...rest] as rev_mpath =>
          switch (declared(qualify(List.rev(rev_mpath), Ident.name(id)))) {
          | Some(key) => Some(key)
          | None => outward(rest)
          }
      );

      outward(List.rev(from));
    }
  | [@implicit_arity] Pdot(m, name) =>
    Option.bind(module_prefix(ctx, u, m), prefix =>
      declared(prefix ++ "." ++ name)
    )
  | Papply(_)
  | Pextra_ty(_) => None
  };
};

/* The qualified name of a project top-level value, if the path names one.
   Local variables are idents pass 1 never registered, so they fall out. */
let project_value = (ctx: ctx, u: unit_info, p: Path.t): option(string) =>
  switch (p) {
  | Pident(id) => Ident.Tbl.find_opt(u.u_vals, id)
  | [@implicit_arity] Pdot(m, name) =>
    Option.bind(
      module_prefix(ctx, u, m),
      prefix => {
        let q = prefix ++ "." ++ name;
        if (Hashtbl.mem(ctx.def_names, q)) {
          Some(q);
        } else {
          None;
        };
      },
    )
  | Papply(_)
  | Pextra_ty(_) => None
  };

let is_predef = (p: Path.t): bool =>
  switch (p) {
  | Pident(id) => Ident.is_predef(id)
  | _ => false
  };

/* A type from outside the project, named the way one would write it:
   "Stdlib.Format.formatter" -> "Format.formatter", "Lib__Mod.t" -> "Lib.Mod.t". */
let outside_name = (p: Path.t): string => {
  let name = String.concat(".", split_double_underscore(Path.name(p)));
  let stdlib = "Stdlib.";
  if (String.starts_with(~prefix=stdlib, name)) {
    String.sub(
      name,
      String.length(stdlib),
      String.length(name) - String.length(stdlib),
    );
  } else {
    name;
  };
};

/* "Scene.Sub.t" as written from inside [from]: the enclosing modules the
   two have in common are dropped. */
let relative = (~from: list(string), key: string): string => {
  let rec drop = (parts, from) =>
    switch (parts, from) {
    | ([p, ...[_, ..._] as parts'], [f, ...from']) when p == f =>
      drop(parts', from')
    | _ => parts
    };

  String.concat(".", drop(String.split_on_char('.', key), from));
};

/* ---------- printing types ---------- */

/* Printtyp prints paths as the type checker stored them ([Vector__Scene.shape],
   or a bare [shape] whose meaning depends on the file). To choose the names
   ourselves we print a copy of the type in which every named type is
   replaced by an ident carrying the name we want. Type variables are shared
   with the original, so they keep their names; object and polymorphic
   variant types are left as they are. */
let rec rename =
        (name_of: Path.t => option(string), ty: Types.type_expr)
        : Types.type_expr => {
  let rename = rename(name_of);
  switch (Types.get_desc(ty)) {
  | [@implicit_arity] Tconstr(p, args, _) =>
    let p =
      switch (name_of(p)) {
      | Some(name) => Path.Pident(Ident.create_persistent(name))
      | None => p
      };

    Btype.newgenty(
      [@implicit_arity] Tconstr(p, List.map(rename, args), ref(Types.Mnil)),
    );
  | [@implicit_arity] Tarrow(label, a, b, c) =>
    Btype.newgenty(
      [@implicit_arity] Tarrow(label, rename(a), rename(b), c),
    )
  | Ttuple(l) => Btype.newgenty(Ttuple(List.map(rename, l)))
  | [@implicit_arity] Tpoly(t, vars) =>
    Btype.newgenty([@implicit_arity] Tpoly(rename(t), vars))
  | _ => ty
  };
};

/* The name a path is printed with: qualified ("Scene.shape", for keys) or
   as written from [from] ("shape", for labels). Built-in types keep their
   own printing. */
let name_of =
    (
      ctx: ctx,
      u: unit_info,
      ~qualified: bool,
      ~from: list(string),
      p: Path.t,
    )
    : option(string) =>
  if (is_predef(p)) {
    None;
  } else {
    switch (project_type(ctx, u, ~from, p)) {
    | Some(key) =>
      Some(
        if (qualified) {
          key;
        } else {
          relative(~from, key);
        },
      )
    | None => Some(outside_name(p))
    };
  };

/* Run a Format printer onto one line. */
let to_line = (pp: (Format.formatter, 'a) => unit, x: 'a): string => {
  let buffer = Buffer.create(80);
  let ppf = Format.formatter_of_buffer(buffer);
  Format.pp_set_margin(ppf, 1_000_000);
  pp(ppf, x);
  Format.pp_print_flush(ppf, ());
  one_line(Buffer.contents(buffer));
};

let print_type =
    (
      ctx: ctx,
      u: unit_info,
      ~qualified: bool,
      ~from: list(string),
      ty: Types.type_expr,
    )
    : string => {
  /* [reset] forgets earlier idents; [type_scheme] restarts variables at 'a. */
  Printtyp.reset();
  to_line(
    Printtyp.type_scheme,
    rename(name_of(ctx, u, ~qualified, ~from), ty),
  );
};

/* The right-hand side of a type declaration, [None] if it has none. */
let decl_rhs =
    (ctx: ctx, u: unit_info, ~from: list(string), d: type_declaration)
    : option(string) => {
  let ty = rename(name_of(ctx, u, ~qualified=false, ~from));
  let label = (l: Types.label_declaration) => {
    ...l,
    ld_type: ty(l.ld_type),
  };
  let ctor = (c: Types.constructor_declaration) => {
    ...c,
    cd_args:
      switch (c.cd_args) {
      | Cstr_tuple(l) => Cstr_tuple(List.map(ty, l))
      | Cstr_record(l) => Cstr_record(List.map(label, l))
      },
    cd_res: Option.map(ty, c.cd_res),
  };

  let decl = d.typ_type;
  let decl = {
    ...decl,
    type_manifest: Option.map(ty, decl.type_manifest),
    type_kind:
      switch (decl.type_kind) {
      | [@implicit_arity] Type_record(l, r) =>
        [@implicit_arity] Type_record(List.map(label, l), r)
      | [@implicit_arity] Type_variant(l, r) =>
        [@implicit_arity] Type_variant(List.map(ctor, l), r)
      | (Type_abstract(_) | Type_open) as k => k
      },
  };

  Printtyp.reset();
  /* Prints "type shape = Circle of ... | ...": keep what follows the "=". */
  let printed = to_line(Printtyp.type_declaration(d.typ_id), decl);
  let sep = " = ";
  let rec find = i =>
    if (i + String.length(sep) > String.length(printed)) {
      None;
    } else if (String.sub(printed, i, String.length(sep)) == sep) {
      Some(i + String.length(sep));
    } else {
      find(i + 1);
    };

  find(0)
  |> Option.map(start => {
       let rhs = String.sub(printed, start, String.length(printed) - start);
       if (String.length(rhs) > 200) {
         String.sub(rhs, 0, 200) ++ " ...";
       } else {
         rhs;
       };
     });
};

/* ---------- handles, docs, visibility ---------- */

let handle =
    (u: unit_info, mpath: list(string), name: string, loc: Location.t)
    : G.handle => {
  file: u.u_file,
  path: String.concat("/", mpath @ [name]),
  line: loc.loc_start.pos_lnum,
  end_line: loc.loc_end.pos_lnum,
};

/* A doc comment reaches the typed tree as [@ocaml.doc "..."]. */
let doc_of = (attrs: attributes): option(string) =>
  List.find_map(
    (a: Parsetree.attribute) =>
      switch (a.attr_name.txt, a.attr_payload) {
      | (
          "ocaml.doc" | "doc",
          PStr([
            {
              pstr_desc:
                [@implicit_arity]
                Pstr_eval(
                  {
                    pexp_desc:
                      Pexp_constant(
                        [@implicit_arity] Pconst_string(s, _, _),
                      ),
                    _,
                  },
                  _,
                ),
              _,
            },
          ]),
        ) =>
        Some(String.trim(s))
      | _ => None
      },
    attrs,
  );

/* Doc comments are often written in the .mli only: look there too. */
let sig_doc = (vis: vis, ~is_type: bool, name: string): option(string) =>
  switch (vis) {
  | All
  | Nothing => None
  | Only(sg) =>
    List.find_map(
      fun
      | [@implicit_arity] Types.Sig_value(id, vd, _)
          when !is_type && Ident.name(id) == name =>
        doc_of(vd.val_attributes)
      | [@implicit_arity] Types.Sig_type(id, decl, _, _)
          when is_type && Ident.name(id) == name =>
        doc_of(decl.type_attributes)
      | _ => None,
      sg,
    )
  };

let first_some = (a: option('a), b: option('a)): option('a) =>
  switch (a) {
  | Some(_) => a
  | None => b
  };

let value_exported = (vis: vis, name: string): bool =>
  switch (vis) {
  | All => true
  | Nothing => false
  | Only(sg) =>
    List.exists(
      fun
      | [@implicit_arity] Types.Sig_value(id, _, _) => Ident.name(id) == name
      | _ => false,
      sg,
    )
  };

/* (exported, abstract) */
let type_visibility = (vis: vis, name: string): (bool, bool) =>
  switch (vis) {
  | All => (true, false)
  | Nothing => (false, false)
  | Only(sg) =>
    let find = (
      fun
      | [@implicit_arity] Types.Sig_type(id, decl, _, _)
          when Ident.name(id) == name =>
        Some(decl)
      | _ => None
    );

    switch (List.find_map(find, sg)) {
    | None => (false, false)
    | Some(decl) =>
      switch (decl.type_kind, decl.type_manifest) {
      | (Type_abstract(_), None) => (true, true)
      | _ => (true, false)
      }
    };
  };

/* The items of a module type, when it is written out or is a module type
   declared earlier in the same file. One from elsewhere cannot be looked
   into without the compiler's environment. */
let signature_of =
    (u: unit_info, mty: Types.module_type): option(Types.signature) =>
  switch (mty) {
  | Mty_signature(sg) => Some(sg)
  | Mty_ident(Pident(id)) => Ident.Tbl.find_opt(u.u_mtys, id)
  | _ => None
  };

/* What is visible of submodule [name]. If its signature cannot be looked
   into, treat it as fully exported. */
let sub_vis = (u: unit_info, vis: vis, name: string): vis =>
  switch (vis) {
  | All => All
  | Nothing => Nothing
  | Only(sg) =>
    let find = (
      fun
      | [@implicit_arity] Types.Sig_module(id, _, md, _, _)
          when Ident.name(id) == name =>
        Some(md.md_type)
      | _ => None
    );

    switch (List.find_map(find, sg)) {
    | None => Nothing
    | Some(mty) =>
      switch (signature_of(u, mty)) {
      | Some(sg) => Only(sg)
      | None => All
      }
    };
  };

/* [(M : S)] and [module M : S = ...]: peel the constraints off, narrowing
   what is visible by each signature. The outer restriction wins. */
let rec strip_constraint =
        (u: unit_info, me: module_expr, vis: vis): (module_expr, vis) =>
  switch (me.mod_desc) {
  | [@implicit_arity] Tmod_constraint(inner, mty, _, _) =>
    let vis =
      switch (vis, signature_of(u, mty)) {
      | (All, Some(sg)) => Only(sg)
      | _ => vis
      };

    strip_constraint(u, inner, vis);
  | _ => (me, vis)
  };

/* ---------- pass 1: collect ---------- */

/* [within] is where the items are when they do not say: a ppx writes
   [include struct ... end] after the type it derives from, and may leave
   what is inside without a location. */
let rec collect =
        (
          ~within: option(Location.t)=?,
          ctx: ctx,
          u: unit_info,
          scope: scope,
          items: list(structure_item),
        )
        : unit => {
  let push = item => u.u_items = [item, ...u.u_items];
  let placed = (loc: Location.t): Location.t =>
    switch (within) {
    | Some(around) when loc.loc_start.pos_lnum == 0 => around
    | _ => loc
    };
  let declare_value = (id, name) => {
    let q = qualify(scope.mpath, name);
    Ident.Tbl.replace(u.u_vals, id, q);
    Hashtbl.replace(ctx.def_names, q, ());
  };

  List.iter(
    (si: structure_item) =>
      switch (si.str_desc) {
      | [@implicit_arity] Tstr_type(_, decls) =>
        List.iter(
          (d: type_declaration) => {
            let key = qualify(scope.mpath, d.typ_name.txt);
            Ident.Tbl.replace(u.u_types, d.typ_id, key);
            Hashtbl.replace(ctx.type_decls, key, (u, scope, d));
            push([@implicit_arity] Type_item(scope, d));
          },
          decls,
        )
      | [@implicit_arity] Tstr_value(_, bindings) =>
        let several = List.length(bindings) > 1;
        List.iter(
          (vb: value_binding) => {
            List.iter(
              ((id, name: Location.loc(string), _, _)) =>
                declare_value(id, name.txt),
              pat_bound_idents_full(vb.vb_pat),
            );
            let loc =
              if (several) {
                vb.vb_loc;
              } else {
                si.str_loc;
              };
            push([@implicit_arity] Value_item(scope, vb, placed(loc)));
          },
          bindings,
        );
      | Tstr_primitive(vd) =>
        declare_value(vd.val_id, vd.val_name.txt);
        push([@implicit_arity] Prim_item(scope, vd));
      | Tstr_modtype({
          mtd_id,
          mtd_type: Some({mty_type: Mty_signature(sg), _}),
          _,
        }) =>
        Ident.Tbl.replace(u.u_mtys, mtd_id, sg)
      | Tstr_module(mb) => collect_module(ctx, u, scope, mb)
      | Tstr_recmodule(mbs) => List.iter(collect_module(ctx, u, scope), mbs)
      | Tstr_include({incl_mod, incl_type, _}) =>
        /* [include struct ... end] is walked in place. The included names
           get fresh idents in the enclosing module ([incl_type]): map
           those to the same qualified names. Other includes are skipped. */
        switch (strip_constraint(u, incl_mod, scope.vis)) {
        | ({mod_desc: Tmod_structure(s), _}, _) =>
          collect(~within=placed(si.str_loc), ctx, u, scope, s.str_items);
          List.iter(
            fun
            | [@implicit_arity] Types.Sig_value(id, _, _) => {
                let q = qualify(scope.mpath, Ident.name(id));
                if (Hashtbl.mem(ctx.def_names, q)) {
                  Ident.Tbl.replace(u.u_vals, id, q);
                };
              }
            | [@implicit_arity] Sig_type(id, _, _, _) => {
                let q = qualify(scope.mpath, Ident.name(id));
                if (Hashtbl.mem(ctx.type_decls, q)) {
                  Ident.Tbl.replace(u.u_types, id, q);
                };
              }
            | [@implicit_arity] Sig_module(id, _, _, _, _) =>
              Ident.Tbl.replace(
                u.u_mods,
                id,
                qualify(scope.mpath, Ident.name(id)),
              )
            | _ => (),
            incl_type,
          );
        | _ => ()
        }
      | _ => ()
      },
    items,
  );
}

and collect_module =
    (ctx: ctx, u: unit_info, scope: scope, mb: module_binding): unit =>
  switch (mb.mb_id, mb.mb_name.txt) {
  | (Some(id), Some(name)) =>
    let prefix = qualify(scope.mpath, name);
    let (me, vis) =
      strip_constraint(u, mb.mb_expr, sub_vis(u, scope.vis, name));
    switch (me.mod_desc) {
    | Tmod_structure(s) =>
      Ident.Tbl.replace(u.u_mods, id, prefix);
      collect(
        ctx,
        u,
        {
          mpath: scope.mpath @ [name],
          vis,
        },
        s.str_items,
      );
    | [@implicit_arity] Tmod_ident(p, _) =>
      /* [module S = Scene]: S is another name for a project module */
      switch (module_prefix(ctx, u, p)) {
      | Some(target) =>
        Ident.Tbl.replace(u.u_mods, id, target);
        Hashtbl.replace(ctx.mod_aliases, prefix, target);
      | None => ()
      }
    | _ => () /* functors, applications, first-class modules: not followed */
    };
  | _ => ()
  }; /* module _ = ... */

/* ---------- nodes ---------- */

let add_node = (ctx: ctx, n: G.node): unit => {
  Hashtbl.replace(ctx.seen, n.key, ());
  ctx.nodes = [n, ...ctx.nodes];
};

/* A node that is not a declaration of the project. */
let plain_node = (~former=None, ~key, ~label, ~kind, ~parts, ()): G.node => {
  key,
  label,
  m_path: [],
  kind,
  ctors: [],
  n_ty: None,
  n_doc: None,
  n_err: false,
  parts,
  former,
  abstract: false,
  exported: true,
  at: None,
};

let ctors_of = (d: type_declaration): list(string) =>
  switch (d.typ_kind, d.typ_manifest) {
  | (Ttype_variant(cds), _) =>
    List.map((c: constructor_declaration) => c.cd_name.txt, cds)
  | (Ttype_record(lds), _) =>
    List.map((l: label_declaration) => l.ld_name.txt, lds)
  | (_, Some({ctyp_desc: [@implicit_arity] Ttyp_variant(fields, _, _), _})) =>
    /* type t = [ `A | `B ] */
    List.filter_map(
      (f: row_field) =>
        switch (f.rf_desc) {
        | [@implicit_arity] Ttag(tag, _, _) => Some(tag.txt)
        | Tinherit(_) => None
        },
      fields,
    )
  | _ => []
  };

let builtin = (ctx: ctx, name: string): string => {
  if (!Hashtbl.mem(ctx.seen, name)) {
    add_node(
      ctx,
      plain_node(~key=name, ~label=name, ~kind=Builtin, ~parts=[], ()),
    );
  };
  name;
};

let ghost = (ctx: ctx, name: string): string => {
  if (!Hashtbl.mem(ctx.seen, name)) {
    add_node(
      ctx,
      plain_node(~key=name, ~label=name, ~kind=Ghost, ~parts=[], ()),
    );
  };
  name;
};

let is_variable = (ty: Types.type_expr): bool =>
  switch (Types.get_desc(ty)) {
  | Tvar(_)
  | Tunivar(_) => true
  | _ => false
  };

/* [a -> ?b:c -> d] as ([a; c], d). An optional argument is stored as
   [c option]: unwrap it. */
let rec flatten_arrow =
        (ty: Types.type_expr): (list(Types.type_expr), Types.type_expr) =>
  switch (Types.get_desc(ty)) {
  | [@implicit_arity] Tpoly(t, _) => flatten_arrow(t)
  | [@implicit_arity] Tarrow(label, arg, rest, _) =>
    let arg =
      switch (label, Types.get_desc(arg)) {
      | (Optional(_), [@implicit_arity] Tconstr(p, [t], _))
          when Path.same(p, Predef.path_option) => t
      | _ => arg
      };

    let (args, result) = flatten_arrow(rest);
    ([arg, ...args], result);
  | _ => ([], ty)
  };

/* Emit the Alias node of a declared type, the first time it is reached:
   at its declaration, or at an earlier reference from another file. Its
   component nodes follow it. */
let rec touch_alias = (ctx: ctx, key: string): unit =>
  if (!Hashtbl.mem(ctx.seen, key)) {
    switch (Hashtbl.find_opt(ctx.type_decls, key)) {
    | None => add_previous(ctx, key) /* declared by a carried module */
    | Some((u, scope, d)) =>
      let name = d.typ_name.txt;
      let (exported, abstract) = type_visibility(scope.vis, name);
      /* Seen from here on, so that a type that is a part of itself
         ([type t = { next : t option }]) stops. The parts' nodes are
         collected aside and put after this one. */
      Hashtbl.replace(ctx.seen, key, ());
      let before = ctx.nodes;
      ctx.nodes = [];
      let (former, parts) = formed_from(ctx, u, ~from=scope.mpath, d);
      let after = ctx.nodes;
      let node: G.node = {
        key,
        label: name,
        m_path: scope.mpath,
        kind: Alias,
        ctors: ctors_of(d),
        n_ty: decl_rhs(ctx, u, ~from=scope.mpath, d),
        n_doc:
          first_some(
            doc_of(d.typ_attributes),
            sig_doc(scope.vis, ~is_type=true, name),
          ),
        n_err: false,
        parts,
        former,
        abstract,
        exported,
        at: Some(handle(u, scope.mpath, name, d.typ_loc)),
      };
      ctx.nodes = after @ [node, ...before];
    };
  }

/* A node of the earlier graph, with the nodes it is made of, in the
   order pass 2 emits them: a declared type before its parts, any other
   node after. A type that is no longer declared anywhere becomes a
   Ghost, so that what refers to it stays attached. */
and add_previous = (ctx: ctx, key: string): unit =>
  if (!Hashtbl.mem(ctx.seen, key)) {
    if (Hashtbl.mem(ctx.type_decls, key)) {
      touch_alias(ctx, key);
    } else {
      switch (Hashtbl.find_opt(ctx.previous_nodes, key)) {
      | Some(n) when n.kind == Alias && Hashtbl.mem(ctx.carried_types, key) =>
        add_node(ctx, n);
        List.iter(add_previous(ctx), n.parts);
      | Some(n) when n.kind != Alias =>
        Hashtbl.replace(ctx.seen, key, ());
        List.iter(add_previous(ctx), n.parts);
        ctx.nodes = [n, ...ctx.nodes];
      | _ =>
        add_node(
          ctx,
          plain_node(~key, ~label=key, ~kind=Ghost, ~parts=[], ()),
        )
      };
    };
  }

/* What a declared type is formed with, and from which nodes. */
and formed_from =
    (ctx: ctx, u: unit_info, ~from: list(string), d: type_declaration)
    : (option(string), list(string)) =>
  switch (d.typ_type.type_kind, d.typ_type.type_manifest) {
  | ([@implicit_arity] Type_record(labels, _), _) => (
      Some("{}"),
      List.map(
        (l: Types.label_declaration) =>
          node_of_type(ctx, u, ~from, l.ld_type),
        labels,
      ),
    )
  | (Type_abstract(_), Some(ty)) =>
    switch (Types.get_desc(ty)) {
    /* [type json = Yojson.Safe.t]: another name for one type */
    | [@implicit_arity] Tconstr(_, [], _) => (
        Some("="),
        [node_of_type(ctx, u, ~from, ty)],
      )
    | _ => formed(ctx, u, ~from, ty)
    }
  | _ => (None, [])
  }

/* What a type expression is formed with, and from which nodes: a tuple
   "()", a list or an array "[]", an option "?", a function "->" (its
   arguments, then its result). Any other type applied to arguments has
   no former: its parts are the type itself, when the project declares
   it, and the arguments. Type variables are not parts. */
and formed =
    (ctx: ctx, u: unit_info, ~from: list(string), ty: Types.type_expr)
    : (option(string), list(string)) => {
  let nodes = l =>
    List.filter(t => !is_variable(t), l)
    |> List.map(node_of_type(ctx, u, ~from));
  let is = (p, predef) => Path.same(p, predef);
  switch (Types.get_desc(ty)) {
  | [@implicit_arity] Tpoly(t, _) => formed(ctx, u, ~from, t)
  | Ttuple(l) => (Some("()"), nodes(l))
  | Tarrow(_) =>
    let (args, result) = flatten_arrow(ty);
    (Some("->"), nodes(args @ [result]));
  | [@implicit_arity] Tconstr(p, [arg], _)
      when is(p, Predef.path_list) || is(p, Predef.path_array) => (
      Some("[]"),
      nodes([arg]),
    )
  | [@implicit_arity] Tconstr(p, [arg], _) when is(p, Predef.path_option) => (
      Some("?"),
      nodes([arg]),
    )
  | [@implicit_arity] Tconstr(p, args, _) =>
    let declared =
      switch (project_type(ctx, u, ~from, p)) {
      | Some(key) =>
        touch_alias(ctx, key);
        [key];
      | None => []
      };
    (None, dedup(declared @ nodes(args)));
  | _ => (None, [])
  };
}

/* The node a type expression stands for.
   - a project type (bare, or applied to type variables only): its Alias
   - a built-in without arguments (int, string, exn, ...): a Builtin
   - an outside type without arguments (Buffer.t): a Ghost
   - anything else (tuple, arrow, variable, [shape list], [int tree],
     [(shape, string) result]): a Derived node keyed by its printed form,
     with the nodes of its own components as parts (see [formed]). */
and node_of_type =
    (ctx: ctx, u: unit_info, ~from: list(string), ty: Types.type_expr)
    : string =>
  switch (Types.get_desc(ty)) {
  | [@implicit_arity] Tpoly(t, _) => node_of_type(ctx, u, ~from, t)
  | [@implicit_arity] Tconstr(p, args, _) =>
    switch (project_type(ctx, u, ~from, p)) {
    | Some(key) when List.for_all(is_variable, args) =>
      touch_alias(ctx, key);
      key;
    | Some(_) => derived(ctx, u, ~from, ty)
    | None =>
      if (args != []) {
        derived(ctx, u, ~from, ty);
      } else if (is_predef(p)) {
        builtin(ctx, Path.name(p));
      } else {
        ghost(ctx, outside_name(p));
      }
    }
  | _ => derived(ctx, u, ~from, ty)
  }

and derived =
    (ctx: ctx, u: unit_info, ~from: list(string), ty: Types.type_expr)
    : string => {
  let key = print_type(ctx, u, ~qualified=true, ~from, ty);
  if (!Hashtbl.mem(ctx.seen, key)) {
    let (former, parts) = formed(ctx, u, ~from, ty);
    let label = print_type(ctx, u, ~qualified=false, ~from, ty);
    add_node(
      ctx,
      plain_node(~former, ~key, ~label, ~kind=Derived, ~parts, ()),
    );
  };
  key;
};

/* The source of a function of several arguments: one Product node per
   distinct list of argument nodes. [labels] are the arguments as written. */
let product =
    (ctx: ctx, arg_keys: list(string), ~labels: list(string)): string => {
  let key = "(" ++ String.concat(", ", arg_keys) ++ ")";
  if (!Hashtbl.mem(ctx.seen, key)) {
    let label = "(" ++ String.concat(", ", labels) ++ ")";
    add_node(
      ctx,
      plain_node(~key, ~label, ~kind=Product, ~parts=arg_keys, ()),
    );
  };
  key;
};

/* ---------- expressions: mentions, holes, tests ---------- */

/* Qualified names of the project's top-level values an expression refers to. */
let mentions = (ctx: ctx, u: unit_info, e: expression): list(string) => {
  let found = ref([]);
  let expr = (it: Tast_iterator.iterator, e: expression) => {
    switch (e.exp_desc) {
    | [@implicit_arity] Texp_ident(p, _, _) =>
      switch (project_value(ctx, u, p)) {
      | Some(name) => found := [name, ...found^]
      | None => ()
      }
    | _ => ()
    };
    Tast_iterator.default_iterator.expr(it, e);
  };

  let it = {
    ...Tast_iterator.default_iterator,
    expr,
  };
  it.expr(it, e);
  dedup(List.rev(found^));
};

let is_unit_value = (e: expression): bool =>
  switch (e.exp_desc) {
  | [@implicit_arity] Texp_construct(_, {cstr_name: "()", _}, []) => true
  | _ => false
  };

/* Is the body of a definition a placeholder? The body is what is left
   after the parameters: [fun x y -> BODY] or [function _ -> BODY]. */
let rec is_hole = (e: expression): bool =>
  switch (e.exp_desc) {
  | [@implicit_arity] Texp_function(_, Tfunction_body(body)) =>
    is_hole(body)
  | [@implicit_arity] Texp_function(_, Tfunction_cases({cases: [c], _})) =>
    is_hole(c.c_rhs)
  | [@implicit_arity]
    Texp_assert(
      {
        exp_desc:
          [@implicit_arity] Texp_construct(_, {cstr_name: "false", _}, []),
        _,
      },
      _,
    ) =>
    true
  | [@implicit_arity]
    Texp_apply(
      {exp_desc: [@implicit_arity] Texp_ident(p, _, _), _},
      [(_, Some(arg))],
    ) =>
    switch (outside_name(p), arg.exp_desc) {
    | ("failwith", Texp_constant([@implicit_arity] Const_string(s, _, _))) =>
      let s = String.lowercase_ascii(s);
      contains(~sub="todo", s) || contains(~sub="not implemented", s);
    | ("Obj.magic", _) => is_unit_value(arg)
    | _ => false
    }
  | _ => false
  };

/* ppx_inline_test turns [let%test "name" = e] into

     let () = Ppx_inline_test_lib.test ~config ~descr:(lazy "name") ~tags
                ~filename ~line_number ~start_pos ~end_pos (fun () -> e)

   ([test_unit] for [let%test_unit]; older versions pass [~descr] as a
   plain string, or go through [Ppx_inline_test_lib.Runtime]). Returns the
   description and the closure. */
let inline_test = (e: expression): option((string, expression)) => {
  let rec string_of = (e: expression) =>
    switch (e.exp_desc) {
    | Texp_constant([@implicit_arity] Const_string(s, _, _)) => Some(s)
    | Texp_lazy(e) => string_of(e)
    | _ => None
    };

  switch (e.exp_desc) {
  | [@implicit_arity]
    Texp_apply({exp_desc: [@implicit_arity] Texp_ident(p, _, _), _}, args)
      when
        String.starts_with(~prefix="Ppx_inline_test_lib", Path.name(p))
        && List.mem(Path.last(p), ["test", "test_unit"]) =>
    let descr =
      List.find_map(
        fun
        | (Asttypes.Labelled("descr"), Some(d)) => string_of(d)
        | _ => None,
        args,
      );

    let closure =
      List.find_map(
        fun
        | (Asttypes.Nolabel, Some(c)) => Some(c)
        | _ => None,
        List.rev(args),
      );

    Option.map(c => (Option.value(descr, ~default=""), c), closure);
  | _ => None
  };
};

let status = (ctx: ctx, file: string, line: int): G.test_status =>
  switch (ctx.failing) {
  | None => Unknown
  | Some(l) =>
    if (List.mem((file, line), l)) {
      Fail;
    } else {
      Pass;
    }
  };

let add_test =
    (
      ctx: ctx,
      u: unit_info,
      ~mpath: list(string),
      ~name: string,
      ~path_name: string,
      ~loc: Location.t,
      body: expression,
    )
    : unit => {
  let t_at = handle(u, mpath, path_name, loc);
  let test: G.test = (
    {
      t_name: name,
      t_status: status(ctx, u.u_file, t_at.line),
      t_refs: [],
      t_at,
    }: G.test
  );

  ctx.tests = [
    {
      ft_test: test,
      ft_uses: mentions(ctx, u, body),
      ft_alcotest: None,
    },
    ...ctx.tests,
  ];
};

/* Record every inline test in an expression. They sit at the top of a
   [let () = ...], or deeper inside a [let%test_module]. */
let find_inline_tests =
    (ctx: ctx, u: unit_info, ~mpath: list(string), e: expression): unit => {
  let expr = (it: Tast_iterator.iterator, e: expression) =>
    switch (inline_test(e)) {
    | Some((descr, closure)) =>
      let name =
        if (descr == "") {
          Printf.sprintf("line %d", e.exp_loc.loc_start.pos_lnum);
        } else {
          descr;
        };

      add_test(
        ctx,
        u,
        ~mpath,
        ~name,
        ~path_name=name,
        ~loc=e.exp_loc,
        closure,
      );
    | None => Tast_iterator.default_iterator.expr(it, e)
    };

  let it = {
    ...Tast_iterator.default_iterator,
    expr,
  };
  it.expr(it, e);
};

/* An Alcotest case, [Alcotest.test_case "name" `Quick f], or the same
   through a wrapper of one's own ([case("name", f)]): an application
   that makes a test case from a literal name and, last, a function.
   Returns the name and the function. */
let alcotest_case = (e: expression): option((string, expression)) => {
  let is_case = (ty: Types.type_expr) =>
    switch (Types.get_desc(ty)) {
    | [@implicit_arity] Tconstr(p, _, _) =>
      Path.last(p) == "test_case" && contains(~sub="Alcotest", Path.name(p))
    | _ => false
    };
  switch (e.exp_desc) {
  | [@implicit_arity] Texp_apply(_, args) when is_case(e.exp_type) =>
    let plain =
      List.filter_map(
        fun
        | (Asttypes.Nolabel, Some(arg)) => Some(arg)
        | _ => None,
        args,
      );
    let name =
      List.find_map(
        (arg: expression) =>
          switch (arg.exp_desc) {
          | Texp_constant([@implicit_arity] Const_string(s, _, _)) =>
            Some(s)
          | _ => None
          },
        plain,
      );
    switch (name, List.rev(plain)) {
    | (Some(name), [body, _, ..._]) => Some((name, body))
    | _ => None
    };
  | _ => None
  };
};

/* [a; b; c] as written, [None] for a list that is computed. */
let rec list_literal = (e: expression): option(list(expression)) =>
  switch (e.exp_desc) {
  | [@implicit_arity] Texp_construct(_, {cstr_name: "::", _}, [head, tail]) =>
    Option.map(rest => [head, ...rest], list_literal(tail))
  | [@implicit_arity] Texp_construct(_, {cstr_name: "[]", _}, []) =>
    Some([])
  | _ => None
  };

/* Record every Alcotest case in an expression. Its status, and where it
   is when its body is a function defined elsewhere in the file, are
   filled in by [assemble]. */
let find_alcotest_cases =
    (ctx: ctx, u: unit_info, ~mpath: list(string), e: expression): unit => {
  let add = (~suite: option((string, int)), ~loc, name, body: expression) => {
    let fn =
      switch (body.exp_desc) {
      | [@implicit_arity] Texp_ident(p, _, _) => project_value(ctx, u, p)
      | _ => None
      };
    let name =
      switch (suite) {
      | Some((suite, _)) => suite ++ ": " ++ name
      | None => name
      };
    ctx.tests = [
      {
        ft_test: {
          t_name: name,
          t_status: Unknown,
          t_refs: [],
          t_at: handle(u, mpath, name, loc),
        },
        ft_uses: mentions(ctx, u, body),
        ft_alcotest:
          Some({
            a_helpers: String.concat(".", u.u_mpath) ++ ".",
            a_case: suite,
            a_fn: fn,
          }),
      },
      ...ctx.tests,
    ];
  };
  let expr = (it: Tast_iterator.iterator, e: expression) =>
    switch (alcotest_case(e), e.exp_desc) {
    | (Some((name, body)), _) =>
      add(~suite=None, ~loc=e.exp_loc, name, body)
    /* ("suite", [case; case]) */
    | (
        None,
        Texp_tuple([
          {
            exp_desc:
              Texp_constant([@implicit_arity] Const_string(suite, _, _)),
            _,
          },
          cases,
        ]),
      )
        when list_literal(cases) != None =>
      List.iteri(
        (i, case: expression) =>
          switch (alcotest_case(case)) {
          | Some((name, body)) =>
            add(~suite=Some((suite, i)), ~loc=case.exp_loc, name, body)
          | None => it.expr(it, case)
          },
        Option.get(list_literal(cases)),
      )
    | (None, _) => Tast_iterator.default_iterator.expr(it, e)
    };

  let it = {
    ...Tast_iterator.default_iterator,
    expr,
  };
  it.expr(it, e);
};

/* ---------- pass 2: emit ---------- */

let is_unit_type = (ty: Types.type_expr): bool =>
  switch (Types.get_desc(ty)) {
  | [@implicit_arity] Tconstr(p, [], _) => Path.same(p, Predef.path_unit)
  | _ => false
  };

/* One top-level name: a test ([let test_xxx () = ...]), an edge (arrow
   type) or a value. [body] is [None] for an external. */
let define =
    (
      ctx: ctx,
      u: unit_info,
      scope: scope,
      ~name: string,
      ~ty: Types.type_expr,
      ~loc: Location.t,
      ~attrs: attributes,
      ~body: option(expression),
    )
    : unit => {
  let from = scope.mpath;
  let qname = qualify(from, name);
  let at = handle(u, from, name, loc);
  let print = print_type(ctx, u, ~qualified=false, ~from);
  /* [let f : 'a. ...] is stored under a quantifier: look through it. */
  let ty =
    switch (Types.get_desc(ty)) {
    | [@implicit_arity] Tpoly(t, _) => t
    | _ => ty
    };
  let prefix = "test_";
  switch (flatten_arrow(ty), body) {
  | (([arg], _), Some(body))
      when
        String.starts_with(~prefix, name)
        && String.length(name) > String.length(prefix)
        && is_unit_type(arg) =>
    let short =
      String.sub(
        name,
        String.length(prefix),
        String.length(name) - String.length(prefix),
      );

    add_test(ctx, u, ~mpath=from, ~name=short, ~path_name=name, ~loc, body);
  | (([], _), _) =>
    let value: G.value = (
      {
        v_name: qname,
        v_label: name,
        v_m_path: from,
        v_key: node_of_type(ctx, u, ~from, ty),
        v_ty: print(ty),
        v_doc:
          first_some(
            doc_of(attrs),
            sig_doc(scope.vis, ~is_type=false, name),
          ),
        v_err: false,
        v_deps: [],
        v_exported: value_exported(scope.vis, name),
        v_at: at,
      }: G.value
    );

    let uses =
      switch (body) {
      | Some(e) => mentions(ctx, u, e)
      | None => []
      };
    ctx.defs = [[@implicit_arity] Value(value, uses), ...ctx.defs];
  | ((args, result), _) =>
    let arg_keys = List.map(node_of_type(ctx, u, ~from), args);
    let src =
      switch (arg_keys) {
      | [key] => key
      | keys => product(ctx, keys, ~labels=List.map(print, args))
      };

    let dst = node_of_type(ctx, u, ~from, result);
    let edge: G.edge = (
      {
        e_name: qname,
        e_label: name,
        e_m_path: from,
        e_ty: print(ty),
        src,
        dst,
        e_doc:
          first_some(
            doc_of(attrs),
            sig_doc(scope.vis, ~is_type=false, name),
          ),
        e_err: false,
        e_hole:
          switch (body) {
          | Some(e) => is_hole(e)
          | None => false
          },
        main: false,
        e_deps: [],
        e_exported: value_exported(scope.vis, name),
        tests: [],
        e_at: at,
      }: G.edge
    );

    let uses =
      switch (body) {
      | Some(e) => mentions(ctx, u, e)
      | None => []
      };
    ctx.defs = [[@implicit_arity] Edge(edge, uses), ...ctx.defs];
  };
};

let emit = (ctx: ctx, u: unit_info, item: item): unit =>
  switch (item) {
  | [@implicit_arity] Type_item(scope, d) =>
    touch_alias(ctx, qualify(scope.mpath, d.typ_name.txt))
  | [@implicit_arity] Prim_item(scope, vd) =>
    define(
      ctx,
      u,
      scope,
      ~name=vd.val_name.txt,
      ~ty=vd.val_val.val_type,
      ~loc=vd.val_loc,
      ~attrs=vd.val_attributes,
      ~body=None,
    )
  | [@implicit_arity] Value_item(scope, vb, loc) =>
    switch (pat_bound_idents_full(vb.vb_pat)) {
    | [] =>
      /* [let () = ...] or [let _ = ...]: only of interest for its tests */
      find_inline_tests(ctx, u, ~mpath=scope.mpath, vb.vb_expr);
      find_alcotest_cases(ctx, u, ~mpath=scope.mpath, vb.vb_expr);
    | bound =>
      /* [let suite = [test_case ...]] */
      find_alcotest_cases(ctx, u, ~mpath=scope.mpath, vb.vb_expr);
      List.iter(
        ((_, name: Location.loc(string), ty, _)) =>
          define(
            ctx,
            u,
            scope,
            ~name=name.txt,
            ~ty,
            ~loc,
            ~attrs=vb.vb_attributes,
            ~body=Some(vb.vb_expr),
          ),
        bound,
      );
    }
  };

/* Fill in what needs the whole project: deps, tests per edge, [main]. */
let assemble = (ctx: ctx): G.t => {
  let def_name =
    fun
    | [@implicit_arity] Edge(e, _)
    | Carried_edge(e) => e.e_name
    | [@implicit_arity] Value(v, _)
    | Carried_value(v) => v.v_name;
  let uses_of =
    fun
    | [@implicit_arity] Edge(_, uses)
    | [@implicit_arity] Value(_, uses) => uses
    | Carried_edge(e) => e.e_deps
    | Carried_value(v) => v.v_deps;
  /* A name bound twice ([let x = 1 let x = x + 1]): the last one stands.
     [ctx.defs] is reversed, so the last binding of a name comes first. */
  let kept = Hashtbl.create(64);
  let defs =
    List.fold_left(
      (acc, d) =>
        if (Hashtbl.mem(kept, def_name(d))) {
          acc;
        } else {
          Hashtbl.replace(
            kept,
            def_name(d),
            switch (d) {
            | Edge(_)
            | Carried_edge(_) => true
            | Value(_)
            | Carried_value(_) => false
            },
          );
          [d, ...acc];
        },
      [],
      ctx.defs,
    );

  let is_def = name => Hashtbl.mem(kept, name);
  let is_edge = name => Hashtbl.find_opt(kept, name) == Some(true);
  let uses_by_name = Hashtbl.create(64)
  and edge_handles = Hashtbl.create(64);
  List.iter(
    d => {
      Hashtbl.replace(uses_by_name, def_name(d), uses_of(d));
      switch (d) {
      | [@implicit_arity] Edge(e, _)
      | Carried_edge(e) => Hashtbl.replace(edge_handles, e.e_name, e.e_at)
      | Value(_)
      | Carried_value(_) => ()
      };
    },
    defs,
  );
  /* A function of a test file that is the body of an Alcotest case is
     that test, not a function of the project: it is not an edge. */
  let test_fn = (t: found_test): option(string) =>
    switch (t.ft_alcotest) {
    | Some({a_fn: Some(f), a_helpers, _})
        when
          String.starts_with(~prefix=a_helpers, f)
          && Hashtbl.mem(edge_handles, f) =>
      Some(f)
    | _ => None
    };
  List.iter(t => Option.iter(Hashtbl.remove(kept), test_fn(t)), ctx.tests);
  let defs = List.filter(d => is_def(def_name(d)), defs);
  let uses_of_name = name =>
    Option.value(Hashtbl.find_opt(uses_by_name, name), ~default=[]);
  /* What an Alcotest case exercises: the project's functions outside
     its own file that its body mentions, or that the helpers it
     mentions in its file do, however many helpers deep. A case that
     reaches none is attached to the functions of its file it mentions. */
  let exercised = (a: alcotest, t: found_test): list(string) => {
    let seen = Hashtbl.create(16);
    let found = ref([]);
    let rec visit = name =>
      if (!Hashtbl.mem(seen, name)) {
        Hashtbl.replace(seen, name, ());
        if (String.starts_with(~prefix=a.a_helpers, name)) {
          List.iter(visit, uses_of_name(name));
        } else if (is_edge(name)) {
          found := [name, ...found^];
        };
      };
    List.iter(visit, t.ft_uses);
    switch (List.rev(found^), test_fn(t)) {
    | ([], Some(f)) => List.filter(is_edge, uses_of_name(f))
    | ([], None) => List.filter(is_edge, t.ft_uses)
    | (outside, _) => outside
    };
  };
  /* Failed if the test run named it (see extract.rei), or reported a
     location inside it. */
  let cases =
    List.filter_map(
      (t: found_test) =>
        Option.bind(t.ft_alcotest, a =>
          Option.map(((suite, i)) => ("alcotest:" ++ suite, i), a.a_case)
        ),
      ctx.tests,
    );
  let alcotest_status = (a: alcotest, at: G.handle): G.test_status =>
    switch (ctx.failing) {
    | None => Unknown
    | Some(l) =>
      let named =
        switch (a.a_case) {
        | Some((suite, i)) => List.mem(("alcotest:" ++ suite, i), l)
        | None => false
        };
      /* a case named as failing that is none of the cases whose suite
         is known: it may be this one */
      let unclaimed =
        a.a_case == None
        && List.exists(
             ((f, _) as failed) =>
               String.starts_with(~prefix="alcotest:", f)
               && !List.mem(failed, cases),
             l,
           );
      let located =
        List.exists(
          ((file, line)) =>
            file == at.file && at.line <= line && line <= at.end_line,
          l,
        );
      if (named || located) {
        Fail;
      } else if (unclaimed) {
        Unknown;
      } else {
        Pass;
      };
    };
  let tests =
    List.rev_map(
      (t: found_test) =>
        switch (t.ft_alcotest) {
        | None => {
            ...t.ft_test,
            t_refs: List.filter(is_edge, t.ft_uses),
          }
        | Some(a) =>
          let t_at =
            switch (Option.map(Hashtbl.find(edge_handles), test_fn(t))) {
            | Some(at) => at
            | None => t.ft_test.t_at
            };
          {
            ...t.ft_test,
            t_refs: exercised(a, t),
            t_status: alcotest_status(a, t_at),
            t_at,
          };
        },
      ctx.tests,
    );
  /* In the order they are in their file: a case found where it is run
     may have been placed at its function, further up. The tests of a
     file follow one another. */
  let tests = {
    let rec by_file = (l: list(G.test)) =>
      switch (l) {
      | [] => []
      | [t, ..._] =>
        let here = (o: G.test) => o.t_at.file == t.t_at.file;
        let rec split = (same, l) =>
          switch (l) {
          | [o, ...rest] when here(o) => split([o, ...same], rest)
          | _ => (List.rev(same), l)
          };
        let (same, rest) = split([], l);
        List.stable_sort(
          (a: G.test, b: G.test) => compare(a.t_at.line, b.t_at.line),
          same,
        )
        @ by_file(rest);
      };
    by_file(tests);
  };

  /* For each name: how many other definitions and tests mention it, and
     which tests do. */
  let users = Hashtbl.create(64)
  and tests_of = Hashtbl.create(64);
  let count = name =>
    Hashtbl.replace(
      users,
      name,
      1 + Option.value(Hashtbl.find_opt(users, name), ~default=0),
    );

  List.iter(
    d =>
      List.iter(
        n =>
          if (n != def_name(d)) {
            count(n);
          },
        uses_of(d),
      ),
    defs,
  );
  List.iter(
    (t: G.test) =>
      List.iter(
        n => {
          count(n);
          Hashtbl.replace(
            tests_of,
            n,
            [
              t,
              ...Option.value(Hashtbl.find_opt(tests_of, n), ~default=[]),
            ],
          );
        },
        t.t_refs,
      ),
    tests,
  );
  let tests_of = name =>
    List.rev(Option.value(Hashtbl.find_opt(tests_of, name), ~default=[]));
  let deps = (name, uses) => List.filter(n => n != name && is_def(n), uses);
  let edges =
    List.filter_map(
      fun
      | Value(_)
      | Carried_value(_) => None
      | [@implicit_arity] Edge(e, uses) =>
        Some({
          ...e,
          e_deps: deps(e.e_name, uses),
          main:
            Option.value(Hashtbl.find_opt(users, e.e_name), ~default=0) >= 2,
          tests: tests_of(e.e_name),
        })
      /* [main] and the deps stay as they were, less what is gone */
      | Carried_edge(e) =>
        Some({
          ...e,
          e_deps: deps(e.e_name, e.e_deps),
          tests: tests_of(e.e_name),
        }),
      defs,
    );

  {
    nodes: List.rev(ctx.nodes),
    edges,
    values:
      List.filter_map(
        fun
        | [@implicit_arity] Value(v, uses) =>
          Some({
            ...v,
            v_deps: deps(v.v_name, uses),
          })
        | Carried_value(v) =>
          Some({
            ...v,
            v_deps: deps(v.v_name, v.v_deps),
          })
        | Edge(_)
        | Carried_edge(_) => None,
        defs,
      ),
    loose_tests: List.filter((t: G.test) => t.t_refs == [], tests),
  };
};

/* ---------- reading the build directory ---------- */

/* dune preprocesses lib/scene.ml into lib/scene.pp.ml and compiles that;
   a Reason source lib/scene.re is compiled as lib/scene.re.ml. */
let strip_pp = (file: string): string => {
  let swap = ((suffix, by)) =>
    if (Filename.check_suffix(file, suffix)) {
      Some(Filename.chop_suffix(file, suffix) ++ by);
    } else {
      None;
    };

  List.find_map(
    swap,
    [
      (".re.pp.ml", ".re"),
      (".re.ml", ".re"),
      (".pp.ml", ".ml"),
      (".rei.pp.mli", ".rei"),
      (".rei.mli", ".rei"),
      (".pp.mli", ".mli"),
    ],
  )
  |> Option.value(~default=file);
};

let in_project = (~root: string, f: string): bool =>
  Filename.is_relative(f)
  && Sys.file_exists(root /\/ f)
  && !Sys.is_directory(root /\/ f);

/* The source file of an implementation, relative to the root: the file the
   compiler was given, or else the file the first located item points to
   (a Reason source, say). [None] if neither is in the project, as for the
   files dune generates. */
let source_file =
    (~root: string, cmt: Cmt_format.cmt_infos, str: structure)
    : option(string) => {
  let from_items =
    List.find_map(
      (si: structure_item) => {
        let f = si.str_loc.loc_start.pos_fname;
        if (f == "" || f == "_none_") {
          None;
        } else {
          Some(f);
        };
      },
      str.str_items,
    );

  List.find_opt(
    in_project(~root),
    Option.to_list(Option.map(strip_pp, cmt.cmt_sourcefile))
    @ Option.to_list(from_items),
  );
};

/* dune writes an alias module per wrapped library (source: vector.ml-gen)
   holding [module Scene = Vector__Scene]. Not part of the graph, but it
   says what [Vector.Scene] means. */
let read_alias_module = (ctx: ctx, modname: string, str: structure): unit =>
  List.iter(
    (si: structure_item) =>
      switch (si.str_desc) {
      | Tstr_module({
          mb_name: {txt: Some(sub), _},
          mb_expr: {mod_desc: [@implicit_arity] Tmod_ident(p, _), _},
          _,
        }) =>
        Hashtbl.replace(ctx.wrappers, (modname, sub), Path.name(p))
      | _ => ()
      },
    str.str_items,
  );

/* The signature of the .cmti next to a .cmt, when the module has an .mli. */
let interface_of = (cmt_path: string): vis => {
  let cmti = cmt_path ++ "i";
  if (!Sys.file_exists(cmti)) {
    All;
  } else {
    switch (Cmt_format.read_cmt(cmti).cmt_annots) {
    | Interface(sg) => Only(sg.sig_type)
    | _ => All
    | exception _ => All
    };
  };
};

/* A module whose source has an interface, but whose interface could not
   be read: it did not compile. What the module exports is then unknown. */
let interface_lost = (~root: string, ~file: string, vis: vis): bool =>
  switch (vis) {
  | All => in_project(~root, file ++ "i")
  | Only(_)
  | Nothing => false
  };

/* Names shown for the units: "Scene" for Vector__Scene. When two units
   would get the same name, fall back to "Vector.Scene", then to the short
   name tagged with its directory. [also] are the compiled names of units
   that are not being read but keep their names (the carried ones). */
let name_units =
    (~also: list(string), found: list((string, string, structure, vis)))
    : list((list(string), (string, string, structure, vis))) => {
  let short = modname =>
    switch (List.rev(split_double_underscore(modname))) {
    | [last, ..._] => [last]
    | [] => [modname]
    };

  let dotted = split_double_underscore;
  let modnames = List.map(((modname, _, _, _)) => modname, found) @ also;
  /* how many units each candidate name would be given to */
  let tally = name_of => {
    let t = Hashtbl.create(16);
    List.iter(
      x =>
        Hashtbl.replace(
          t,
          name_of(x),
          1 + Option.value(Hashtbl.find_opt(t, name_of(x)), ~default=0),
        ),
      modnames,
    );
    x => Hashtbl.find(t, name_of(x)) == 1;
  };

  let unique_short = tally(short)
  and unique_dotted = tally(dotted);
  List.map(
    ((modname, file, _, _) as x) => {
      let mpath =
        if (unique_short(modname)) {
          short(modname);
        } else if (unique_dotted(modname)) {
          dotted(modname);
        } else {
          [
            String.concat("", short(modname))
            ++ "@"
            ++ Filename.dirname(file),
          ];
        };

      (mpath, x);
    },
    found,
  );
};

/* ---------- carrying over ---------- */

/* While a file does not type-check it has no usable annotations, and its
   definitions would drop out of the graph until it builds again. Given
   the graph of an earlier extraction, such a file's nodes, edges, values
   and tests are taken from there instead, moved to where Locate finds
   them in the source as it stands. */

/* What an earlier graph says about one file. */
type carried = {
  c_file: string,
  c_prefix: list(string), /* the file's module, as shown: ["Geo"] */
  c_nodes: list(G.node),
  c_edges: list(G.edge),
  c_values: list(G.value),
  c_tests: list(G.test),
};

/* Every test of a graph, once, in order. */
let all_tests = (g: G.t): list(G.test) => {
  let seen = Hashtbl.create(16);
  List.concat_map((e: G.edge) => e.tests, g.edges)
  @ g.loose_tests
  |> List.filter((t: G.test) => {
       let first = !Hashtbl.mem(seen, (t.t_at, t.t_name));
       Hashtbl.replace(seen, (t.t_at, t.t_name), ());
       first;
     });
};

/* The files a graph's definitions are in. */
let files_of = (g: G.t): list(string) =>
  List.filter_map(
    (n: G.node) => Option.map((h: G.handle) => h.file, n.at),
    g.nodes,
  )
  @ List.map((e: G.edge) => e.e_at.file, g.edges)
  @ List.map((v: G.value) => v.v_at.file, g.values)
  @ List.map((t: G.test) => t.t_at.file, all_tests(g))
  |> List.sort_uniq(compare);

/* "lib/geo.ml" -> "Geo" */
let module_of_file = (file: string): string =>
  String.capitalize_ascii(
    Filename.remove_extension(Filename.basename(file)),
  );

/* The name a file's module was shown under: the start of its definitions'
   module paths, up to the file's own module (see [name_units]). */
let prefix_of = (file: string, m_paths: list(list(string))): list(string) => {
  let own = module_of_file(file);
  let is_own = part =>
    part == own || String.starts_with(~prefix=own ++ "@", part);
  let rec upto =
    fun
    | [] => None
    | [part, ..._] when is_own(part) => Some([part])
    | [part, ...rest] => Option.map(p => [part, ...p], upto(rest));
  switch (List.find_map(upto, m_paths)) {
  | Some(prefix) => prefix
  | None => [own]
  };
};

/* A handle moved to where its item is now. [None]: the source parses and
   has no such item any more. */
let relocate =
    (located: option(Locate.t), kinds: list(Locate.kind), h: G.handle)
    : option(G.handle) =>
  switch (located) {
  | None => Some(h)
  | Some(l) =>
    switch (List.find_map(kind => Locate.find(l, kind, h.path), kinds)) {
    | Some((line, end_line)) =>
      Some({
        ...h,
        line,
        end_line,
      })
    | None =>
      if (l.exact) {
        None;
      } else {
        Some(h);
      }
    }
  };

let carry =
    (~root: string, ~build: string, previous: G.t, file: string): carried => {
  let here = (h: G.handle) => h.file == file;
  let nodes =
    List.filter(
      (n: G.node) =>
        switch (n.at) {
        | Some(h) => here(h)
        | None => false
        },
      previous.nodes,
    );
  let edges = List.filter((e: G.edge) => here(e.e_at), previous.edges);
  let values = List.filter((v: G.value) => here(v.v_at), previous.values);
  let tests =
    List.filter((t: G.test) => here(t.t_at), all_tests(previous));
  let prefix =
    prefix_of(
      file,
      List.map((n: G.node) => n.m_path, nodes)
      @ List.map((e: G.edge) => e.e_m_path, edges)
      @ List.map((v: G.value) => v.v_m_path, values)
      @ List.map(
          (t: G.test) => String.split_on_char('/', t.t_at.path),
          tests,
        ),
    );
  let located = Locate.source(~root, ~build, ~prefix, file);
  let by_line = (line_of, l) =>
    List.stable_sort((a, b) => compare(line_of(a), line_of(b)), l);
  let moved = (h: G.handle, (line, end_line)): G.handle => {
    ...h,
    line,
    end_line,
  };
  /* A value that is not written in the file was derived by a ppx from
     a type, and was placed where the type is: it follows the type. */
  let relocate_def = (h: G.handle): option(G.handle) =>
    switch (relocate(located, [Locate.Val], h), located) {
    | (Some(at), Some(l)) when Locate.find(l, Locate.Val, h.path) == None =>
      let around =
        List.find_map(
          (n: G.node) =>
            switch (n.at) {
            | Some(t) when t.line <= h.line && h.end_line <= t.end_line =>
              Some(Locate.find(l, Locate.Type, t.path))
            | _ => None
            },
          nodes,
        );
      switch (around) {
      | Some(Some(span)) => Some(moved(h, span))
      | Some(None) when l.exact => None /* its type is gone */
      | _ => Some(at)
      };
    | (at, _) => at
    };
  /* An inline test without a description is named by its text
     ("<<total empty = 0>>") or its line ("line 12"). When it is not
     found under that name it is looked for by its place among the
     tests without a description of its module, if there are still as
     many of them. */
  let parent = (path: string): string =>
    switch (String.rindex_opt(path, '/')) {
    | Some(i) => String.sub(path, 0, i)
    | None => ""
    };
  let by_line_number = (t: G.test) =>
    String.starts_with(~prefix="line ", t.t_name);
  let undescribed = (t: G.test) =>
    by_line_number(t) || String.starts_with(~prefix="<<", t.t_name);
  let place = (t: G.test): option((int, int)) => {
    let fellows =
      List.filter(
        (o: G.test) =>
          undescribed(o) && parent(o.t_at.path) == parent(t.t_at.path),
        tests,
      )
      |> by_line((o: G.test) => o.t_at.line);
    let find = k =>
      Option.bind(located, l =>
        Locate.find(
          l,
          Locate.Test,
          parent(t.t_at.path) ++ "/" ++ Locate.unnamed(k),
        )
      );
    let rec index = (k, l) =>
      switch (l) {
      | [] => None
      | [o, ..._] when o === t => Some(k)
      | [_, ...rest] => index(k + 1, rest)
      };
    if (undescribed(t)
        && find(List.length(fellows)) != None
        && find(List.length(fellows) + 1) == None) {
      Option.bind(index(1, fellows), find);
    } else {
      None;
    };
  };
  {
    c_file: file,
    c_prefix: prefix,
    c_nodes:
      List.filter_map(
        (n: G.node) =>
          Option.bind(n.at, relocate(located, [Locate.Type]))
          |> Option.map(at =>
               {
                 ...n,
                 n_err: false,
                 at: Some(at),
               }
             ),
        nodes,
      ),
    c_edges:
      List.filter_map(
        (e: G.edge) =>
          relocate_def(e.e_at)
          |> Option.map(e_at =>
               {
                 ...e,
                 e_err: false,
                 e_at,
               }
             ),
        edges,
      )
      |> by_line((e: G.edge) => e.e_at.line),
    c_values:
      List.filter_map(
        (v: G.value) =>
          relocate_def(v.v_at)
          |> Option.map(v_at =>
               {
                 ...v,
                 v_err: false,
                 v_at,
               }
             ),
        values,
      )
      |> by_line((v: G.value) => v.v_at.line),
    c_tests:
      List.filter_map(
        (t: G.test) => {
          /* [let test_x () = ...] and the function of an Alcotest case
             are found as values, an inline test by its description */
          let by_name =
            Option.bind(located, l =>
              List.find_map(
                kind => Locate.find(l, kind, t.t_at.path),
                [Locate.Test, Locate.Val],
              )
            );
          let t_at =
            switch (located, by_name, place(t)) {
            | (None, _, _) => Some(t.t_at)
            | (Some(_), Some(span), _)
            | (Some(_), None, Some(span)) => Some(moved(t.t_at, span))
            | (Some(l), None, None) =>
              if (l.exact && !by_line_number(t)) {
                None;
              } else {
                Some(t.t_at);
              }
            };
          Option.map(
            (t_at: G.handle) =>
              if (by_line_number(t)) {
                let t_name = Printf.sprintf("line %d", t_at.line);
                {
                  ...t,
                  t_name,
                  t_status: G.Unknown,
                  t_at: {
                    ...t_at,
                    path: parent(t_at.path) ++ "/" ++ t_name,
                  },
                };
              } else {
                {
                  ...t,
                  t_status: G.Unknown,
                  t_at,
                };
              },
            t_at,
          );
        },
        tests,
      )
      |> by_line((t: G.test) => t.t_at.line),
  };
};

/* The compiled names a carried file's module may be referred to by, when
   its annotations do not say: its own name, and that name behind one of
   dune's alias modules. */
let guess_modnames = (ctx: ctx, file: string): list(string) => {
  let own = module_of_file(file);
  let wrapped =
    Hashtbl.fold(
      ((_, sub), modname, acc) =>
        if (sub == own) {
          [modname, ...acc];
        } else {
          acc;
        },
      ctx.wrappers,
      [],
    );
  List.sort(compare, wrapped) @ [own];
};

let register_carried = (ctx: ctx, ~modnames: list(string), c: carried): unit => {
  List.iter(
    modname =>
      if (!Hashtbl.mem(ctx.units, modname)
          && !Hashtbl.mem(ctx.carried_units, modname)) {
        Hashtbl.replace(
          ctx.carried_units,
          modname,
          String.concat(".", c.c_prefix),
        );
      },
    modnames,
  );
  List.iter(
    (n: G.node) => {
      Hashtbl.replace(ctx.carried_types, n.key, ());
      Hashtbl.replace(ctx.previous_nodes, n.key, n);
    },
    c.c_nodes,
  );
  List.iter(
    (e: G.edge) => Hashtbl.replace(ctx.def_names, e.e_name, ()),
    c.c_edges,
  );
  List.iter(
    (v: G.value) => Hashtbl.replace(ctx.def_names, v.v_name, ()),
    c.c_values,
  );
};

/* A carried file's turn in pass 2: the nodes its definitions need, in
   the earlier graph's order, then the definitions and tests. */
let emit_carried = (ctx: ctx, previous: G.t, c: carried): unit => {
  let needed = Hashtbl.create(32);
  let rec need = key =>
    if (!Hashtbl.mem(needed, key)) {
      Hashtbl.replace(needed, key, ());
      switch (Hashtbl.find_opt(ctx.previous_nodes, key)) {
      | Some(n)
          when
            !Hashtbl.mem(ctx.type_decls, key)
            && (n.kind != Alias || Hashtbl.mem(ctx.carried_types, key)) =>
        List.iter(need, n.parts)
      | _ => ()
      };
    };
  let keys =
    List.map((n: G.node) => n.key, c.c_nodes)
    @ List.concat_map((e: G.edge) => [e.src, e.dst], c.c_edges)
    @ List.map((v: G.value) => v.v_key, c.c_values);
  List.iter(need, keys);
  List.iter(
    (n: G.node) =>
      if (Hashtbl.mem(needed, n.key)) {
        add_previous(ctx, n.key);
      },
    previous.nodes,
  );
  List.iter(add_previous(ctx), keys); /* any the earlier graph lacks */
  /* in source order, edges and values apart: only the order within each
     shows in the graph */
  List.iter(
    (e: G.edge) => ctx.defs = [Carried_edge(e), ...ctx.defs],
    c.c_edges,
  );
  List.iter(
    (v: G.value) => ctx.defs = [Carried_value(v), ...ctx.defs],
    c.c_values,
  );
  List.iter(
    (t: G.test) =>
      ctx.tests = [
        {
          ft_test: t,
          ft_uses: t.t_refs,
          ft_alcotest: None,
        },
        ...ctx.tests,
      ],
    c.c_tests,
  );
};

/* Are a module's annotations those of its source as it stands? dune
   leaves the old ones in place when a file stops parsing, or when a
   module it depends on stops compiling. The compiler records a digest of
   the file it was given; that file is [dir]'s copy of the source or one
   of its preprocessed forms, which dune removes when the source no
   longer parses. */
let up_to_date = (~dir: string, cmt: Cmt_format.cmt_infos): bool =>
  switch (cmt.cmt_sourcefile, cmt.cmt_source_digest) {
  | (Some(f), Some(digest)) =>
    let path =
      if (Filename.is_relative(f)) {
        dir /\/ f;
      } else {
        f;
      };
    switch (Digest.file(path)) {
    | d => d == digest
    | exception _ => false
    };
  | _ => true
  };

/* Set [err] on the definitions the compiler's errors fall in: by line
   for an error in an implementation; for one in an interface, the
   definition its [val] or [type] stands for. */
let mark_broken =
    (
      ~root: string,
      ~build: string,
      ~prefixes: list((string, list(string))),
      broken: list((string, int)),
      g: G.t,
    )
    : G.t =>
  if (broken == []) {
    g;
  } else {
    let by_line = (h: G.handle) =>
      List.exists(
        ((file, line)) =>
          file == h.file && h.line <= line && line <= h.end_line,
        broken,
      );
    /* (implementation file, kind, entry path) */
    let by_name =
      List.concat_map(
        ((file, line)) =>
          if (Filename.check_suffix(file, ".mli")
              || Filename.check_suffix(file, ".rei")) {
            let impl = String.sub(file, 0, String.length(file) - 1);
            switch (List.assoc_opt(impl, prefixes)) {
            | None => []
            | Some(prefix) =>
              switch (Locate.source(~root, ~build, ~prefix, file)) {
              | None => []
              | Some(located) =>
                List.map(
                  ((kind, path)) => (impl, kind, path),
                  Locate.containing(located, line),
                )
              }
            };
          } else {
            [];
          },
        broken,
      );
    let hit = (kind, h: G.handle) =>
      by_line(h) || List.mem((h.file, kind, h.path), by_name);
    {
      ...g,
      nodes:
        List.map(
          (n: G.node) =>
            switch (n.at) {
            | Some(h) when hit(Locate.Type, h) => {
                ...n,
                n_err: true,
              }
            | _ => n
            },
          g.nodes,
        ),
      edges:
        List.map(
          (e: G.edge) =>
            if (hit(Locate.Val, e.e_at)) {
              {
                ...e,
                e_err: true,
              };
            } else {
              e;
            },
          g.edges,
        ),
      values:
        List.map(
          (v: G.value) =>
            if (hit(Locate.Val, v.v_at)) {
              {
                ...v,
                v_err: true,
              };
            } else {
              v;
            },
          g.values,
        ),
    };
  };

/* ---------- the entry point ---------- */

/* One file's turn in pass 2. */
type turn =
  | Fresh(unit_info)
  | Carried(carried);

let extract =
    (
      ~root: string,
      ~build_dir: string,
      ~failing: option(list((string, int))),
      ~previous: option(G.t),
      ~broken: list((string, int)),
    )
    : result(G.t, string) => {
  let ctx = {
    failing,
    units: Hashtbl.create(16),
    wrappers: Hashtbl.create(16),
    mod_aliases: Hashtbl.create(16),
    type_decls: Hashtbl.create(64),
    def_names: Hashtbl.create(64),
    carried_units: Hashtbl.create(8),
    carried_types: Hashtbl.create(16),
    previous_nodes: Hashtbl.create(64),
    seen: Hashtbl.create(64),
    nodes: [],
    defs: [],
    tests: [],
  };

  let dir = root /\/ build_dir /\/ "default";
  let cmts =
    List.filter(f => Filename.check_suffix(f, ".cmt"), find_cmts(dir));
  let previous_files =
    switch (previous) {
    | Some(g) => files_of(g)
    | None => []
    };
  /* Read every implementation. A file that failed to type-check has only
     a partial tree: it is left out. So is one whose annotations are out
     of date or whose interface did not compile, when the earlier graph
     has it. [lost] remembers what such modules are compiled as. */
  let unreadable = ref(0);
  let lost = ref([]);
  let found =
    List.filter_map(
      path =>
        switch (Cmt_format.read_cmt(path)) {
        | exception _ =>
          incr(unreadable);
          None;
        | cmt =>
          let lose = file => lost := [(file, cmt.cmt_modname), ...lost^];
          switch (cmt.cmt_annots) {
          | Implementation(str) =>
            let generated =
              switch (cmt.cmt_sourcefile) {
              | Some(f) => Filename.check_suffix(f, "-gen")
              | None => false
              };

            if (generated) {
              read_alias_module(ctx, cmt.cmt_modname, str);
              None;
            } else {
              switch (source_file(~root, cmt, str)) {
              | Some(file) =>
                let vis = interface_of(path);
                if (List.mem(file, previous_files)
                    && (
                      !up_to_date(~dir, cmt)
                      || interface_lost(~root, ~file, vis)
                    )) {
                  lose(file);
                  None;
                } else {
                  Some((cmt.cmt_modname, file, str, vis));
                };
              | None => None
              };
            };
          | _ =>
            incr(unreadable);
            Option.map(strip_pp, cmt.cmt_sourcefile)
            |> Option.iter(file =>
                 if (in_project(~root, file)) {
                   lose(file);
                 }
               );
            None;
          };
        },
      cmts,
    );

  /* The same source can be compiled more than once: keep the first. */
  let sources = Hashtbl.create(16);
  let found =
    List.filter(
      ((_, file, _, _)) => {
        let first = !Hashtbl.mem(sources, file);
        Hashtbl.replace(sources, file, ());
        first;
      },
      found,
    );

  /* What is carried over: the earlier graph's files that were not read
     this time and still exist. */
  let carried =
    switch (previous) {
    | None => []
    | Some(g) =>
      List.filter(
        file => !Hashtbl.mem(sources, file) && in_project(~root, file),
        previous_files,
      )
      |> List.map(carry(~root, ~build=dir, g))
    };

  if (found == [] && carried == []) {
    Error(
      if (cmts == []) {
        Printf.sprintf(
          "no .cmt files under %s (build the project with: dune build --root . --build-dir %s @check)",
          dir,
          build_dir,
        );
      } else {
        Printf.sprintf(
          "no module under %s could be read (%d of %d .cmt files unreadable or not type-checked)",
          dir,
          unreadable^,
          List.length(cmts),
        );
      },
    );
  } else {
    let carried =
      List.map(
        c =>
          (
            switch (List.assoc_opt(c.c_file, lost^)) {
            | Some(modname) => [modname]
            | None => guess_modnames(ctx, c.c_file)
            },
            c,
          ),
        carried,
      );
    let units =
      name_units(
        ~also=List.map(((modnames, _)) => List.hd(modnames), carried),
        found,
      )
      |> List.map(((mpath, (modname, file, str, vis))) =>
           {
             u_modname: modname,
             u_mpath: mpath,
             u_file: file,
             u_str: str,
             u_vis: vis,
             u_types: Ident.Tbl.create(16),
             u_mods: Ident.Tbl.create(8),
             u_vals: Ident.Tbl.create(32),
             u_mtys: Ident.Tbl.create(8),
             u_items: [],
           }
         )
      |> List.sort((a, b) => compare(a.u_file, b.u_file));

    List.iter(
      u =>
        if (!Hashtbl.mem(ctx.units, u.u_modname)) {
          Hashtbl.replace(ctx.units, u.u_modname, u);
        },
      units,
    );
    Option.iter(
      (g: G.t) =>
        List.iter(
          (n: G.node) => Hashtbl.replace(ctx.previous_nodes, n.key, n),
          g.nodes,
        ),
      previous,
    );
    List.iter(
      ((modnames, c)) => register_carried(ctx, ~modnames, c),
      carried,
    );
    List.iter(
      u =>
        collect(
          ctx,
          u,
          {
            mpath: u.u_mpath,
            vis: u.u_vis,
          },
          u.u_str.str_items,
        ),
      units,
    );
    /* Pass 2, file by file in the order of their names, carried files
       taking their turn among the others. */
    let file_of =
      fun
      | Fresh(u) => u.u_file
      | Carried(c) => c.c_file;
    List.map(u => Fresh(u), units)
    @ List.map(((_, c)) => Carried(c), carried)
    |> List.stable_sort((a, b) => compare(file_of(a), file_of(b)))
    |> List.iter(
         fun
         | Fresh(u) => List.iter(emit(ctx, u), List.rev(u.u_items))
         | Carried(c) => emit_carried(ctx, Option.get(previous), c),
       );
    Ok(
      mark_broken(
        ~root,
        ~build=dir,
        ~prefixes=
          List.map(u => (u.u_file, u.u_mpath), units)
          @ List.map(((_, c)) => (c.c_file, c.c_prefix), carried),
        broken,
        assemble(ctx),
      ),
    );
  };
};

files.extract/locate.re:
/* Where the top-level items of a source file are now, by name.

   Used when a module cannot be type-checked: its definitions are carried
   over from an earlier graph, and this says where each one sits in the
   source as it stands. Three ways of finding out, best first:

   1. the parse tree dune's preprocessing left in the build directory
      (Reason sources: lib/a.re.ml; ppx: lib/a.pp.ml). It is there exactly
      when the current source parses;
   2. the compiler's parser on the source text (.ml and .mli);
   3. a scan of the text for binders, by indentation, when the file does
      not parse. This one is approximate. */

type kind =
  | Type
  | Val /* a let-bound name, an external, a [val] */
  | Test; /* an inline test, by its description */

type t = {
  /* From a parse tree: a name that is not listed is not in the file. */
  exact: bool,
  /* (kind, entry path such as "Geo/Angle/to_deg") -> (first, last line) */
  spans: Hashtbl.t((kind, string), (int, int)),
};

let find = (t: t, kind: kind, path: string): option((int, int)) =>
  Hashtbl.find_opt(t.spans, (kind, path));

/* The items whose span holds [line]. */
let containing = (t: t, line: int): list((kind, string)) =>
  Hashtbl.fold(
    (item, (first, last), acc) =>
      if (first <= line && line <= last) {
        [item, ...acc];
      } else {
        acc;
      },
    t.spans,
    [],
  )
  |> List.sort(compare);

let add =
    (
      spans,
      kind: kind,
      mpath: list(string),
      name: string,
      first: int,
      last: int,
    ) =>
  /* a name bound twice: the last one stands */
  Hashtbl.replace(
    spans,
    (kind, String.concat("/", mpath @ [name])),
    (first, last),
  );

/* ---------- from a parse tree ---------- */

open Parsetree;

let add_loc = (spans, kind, mpath, name, loc: Location.t) =>
  add(spans, kind, mpath, name, loc.loc_start.pos_lnum, loc.loc_end.pos_lnum);

/* An inline test without a description has nothing to be looked up by
   but its place among the others of its module: "#1", "#2", ... */
let unnamed = (n: int): string => "#" ++ string_of_int(n);

let add_unnamed_lines = (spans, mpath, first: int, last: int) => {
  let rec free = n =>
    if (Hashtbl.mem(
          spans,
          (Test, String.concat("/", mpath @ [unnamed(n)])),
        )) {
      free(n + 1);
    } else {
      n;
    };
  add(spans, Test, mpath, unnamed(free(1)), first, last);
};

let add_unnamed = (spans, mpath, loc: Location.t) =>
  add_unnamed_lines(
    spans,
    mpath,
    loc.loc_start.pos_lnum,
    loc.loc_end.pos_lnum,
  );

let pattern_names = (p: pattern): list(string) => {
  let found = ref([]);
  let pat = (it: Ast_iterator.iterator, p: pattern) => {
    switch (p.ppat_desc) {
    | Ppat_var(name)
    | [@implicit_arity] Ppat_alias(_, name) => found := [name.txt, ...found^]
    | _ => ()
    };
    Ast_iterator.default_iterator.pat(it, p);
  };

  let it = {
    ...Ast_iterator.default_iterator,
    pat,
  };
  it.pat(it, p);
  List.rev(found^);
};

let rec strip_constraint = (me: module_expr): module_expr =>
  switch (me.pmod_desc) {
  | [@implicit_arity] Pmod_constraint(inner, _) => strip_constraint(inner)
  | _ => me
  };

let string_constant = (e: expression): option(string) =>
  switch (e.pexp_desc) {
  | Pexp_constant([@implicit_arity] Pconst_string(s, _, _)) => Some(s)
  | Pexp_lazy({
      pexp_desc: Pexp_constant([@implicit_arity] Pconst_string(s, _, _)),
      _,
    }) =>
    Some(s)
  | _ => None
  };

let is_inline_test = (f: Longident.t): bool =>
  switch (Longident.flatten(f)) {
  | ["Ppx_inline_test_lib", ...rest] =>
    switch (List.rev(rest)) {
    | ["test" | "test_unit", ..._] => true
    | _ => false
    }
  | _ => false
  | exception _ => false
  };

/* Inline tests as ppx_inline_test leaves them (see Extract.inline_test):
   [Ppx_inline_test_lib.test ~descr:(lazy "name") ... (fun () -> e)]. */
let expanded_tests = (spans, mpath, e: expression) => {
  let expr = (it: Ast_iterator.iterator, e: expression) =>
    switch (e.pexp_desc) {
    | [@implicit_arity] Pexp_apply({pexp_desc: Pexp_ident(f), _}, args)
        when is_inline_test(f.txt) =>
      let descr =
        List.find_map(
          fun
          | (Asttypes.Labelled("descr"), d) => string_constant(d)
          | _ => None,
          args,
        );
      switch (descr) {
      | Some(name) when name != "" =>
        add_loc(spans, Test, mpath, name, e.pexp_loc)
      | _ => add_unnamed(spans, mpath, e.pexp_loc)
      };
    | _ => Ast_iterator.default_iterator.expr(it, e)
    };

  let it = {
    ...Ast_iterator.default_iterator,
    expr,
  };
  it.expr(it, e);
};

/* [within]: where the items are when they do not say (what a ppx wrote
   after a type, see Extract.collect). */
/* Alcotest cases whose body is written in place, under the names
   Extract gives them: [test_case "name" ...] as "name", and inside
   [("suite", [...])] any call with a literal name as "suite: name" (it
   may be a wrapper of [test_case]; without types one cannot tell, and a
   span nobody asks for does no harm). */
let alcotest_cases = (spans, mpath, e: expression) => {
  let name_of = (args): option(string) =>
    List.find_map(
      fun
      | (Asttypes.Nolabel, arg) => string_constant(arg)
      | _ => None,
      args,
    );
  let is_test_case = (f: Longident.t) =>
    switch (Longident.last(f)) {
    | "test_case" => true
    | _ => false
    | exception _ => false
    };
  let rec list_literal = (e: expression): option(list(expression)) =>
    switch (e.pexp_desc) {
    | [@implicit_arity]
      Pexp_construct(
        {txt: Lident("::"), _},
        Some({pexp_desc: Pexp_tuple([head, tail]), _}),
      ) =>
      Option.map(rest => [head, ...rest], list_literal(tail))
    | [@implicit_arity] Pexp_construct({txt: Lident("[]"), _}, None) =>
      Some([])
    | _ => None
    };
  let expr = (it: Ast_iterator.iterator, e: expression) =>
    switch (e.pexp_desc) {
    | [@implicit_arity] Pexp_apply({pexp_desc: Pexp_ident(f), _}, args)
        when is_test_case(f.txt) && name_of(args) != None =>
      add_loc(spans, Test, mpath, Option.get(name_of(args)), e.pexp_loc)
    | Pexp_tuple([suite, cases])
        when string_constant(suite) != None && list_literal(cases) != None =>
      List.iter(
        (case: expression) =>
          switch (case.pexp_desc) {
          | [@implicit_arity] Pexp_apply(_, args) when name_of(args) != None =>
            add_loc(
              spans,
              Test,
              mpath,
              Option.get(string_constant(suite))
              ++ ": "
              ++ Option.get(name_of(args)),
              case.pexp_loc,
            )
          | _ => it.expr(it, case)
          },
        Option.get(list_literal(cases)),
      )
    | _ => Ast_iterator.default_iterator.expr(it, e)
    };

  let it = {
    ...Ast_iterator.default_iterator,
    expr,
  };
  it.expr(it, e);
};

let rec structure =
        (
          ~within: option(Location.t)=?,
          spans,
          mpath: list(string),
          items: structure,
        )
        : unit => {
  let placed = (loc: Location.t): Location.t =>
    switch (within) {
    | Some(around) when loc.loc_start.pos_lnum == 0 => around
    | _ => loc
    };
  List.iter(
    (si: structure_item) =>
      switch (si.pstr_desc) {
      | [@implicit_arity] Pstr_type(_, decls) =>
        List.iter(
          (d: type_declaration) =>
            add_loc(spans, Type, mpath, d.ptype_name.txt, d.ptype_loc),
          decls,
        )
      | [@implicit_arity] Pstr_value(_, bindings) =>
        let several = List.length(bindings) > 1;
        List.iter(
          (vb: value_binding) => {
            let loc =
              if (several) {
                vb.pvb_loc;
              } else {
                si.pstr_loc;
              };
            switch (pattern_names(vb.pvb_pat)) {
            | [] =>
              expanded_tests(spans, mpath, vb.pvb_expr);
              alcotest_cases(spans, mpath, vb.pvb_expr);
            | names =>
              alcotest_cases(spans, mpath, vb.pvb_expr);
              List.iter(
                name => add_loc(spans, Val, mpath, name, placed(loc)),
                names,
              );
            };
          },
          bindings,
        );
      | Pstr_primitive(vd) =>
        add_loc(spans, Val, mpath, vd.pval_name.txt, vd.pval_loc)
      | Pstr_module(mb) => module_binding(spans, mpath, mb)
      | Pstr_recmodule(mbs) => List.iter(module_binding(spans, mpath), mbs)
      | Pstr_include({pincl_mod, _}) =>
        switch (strip_constraint(pincl_mod).pmod_desc) {
        | Pmod_structure(s) =>
          structure(~within=placed(si.pstr_loc), spans, mpath, s)
        | _ => ()
        }
      /* [let%test "name" = e], before ppx_inline_test has run */
      | [@implicit_arity]
        Pstr_extension(
          (
            {txt: ("test" | "test_unit" | "test_module") as ext, _},
            PStr([{pstr_desc: [@implicit_arity] Pstr_value(_, [vb]), _}]),
          ),
          _,
        ) =>
        switch (ext, vb.pvb_pat.ppat_desc, vb.pvb_expr.pexp_desc) {
        | ("test_module", _, Pexp_pack(me)) =>
          switch (strip_constraint(me).pmod_desc) {
          | Pmod_structure(s) => structure(spans, mpath, s)
          | _ => ()
          }
        | (
            "test" | "test_unit",
            Ppat_constant([@implicit_arity] Pconst_string(name, _, _)),
            _,
          ) =>
          add_loc(spans, Test, mpath, name, si.pstr_loc)
        | ("test" | "test_unit", _, _) =>
          add_unnamed(spans, mpath, si.pstr_loc)
        | _ => ()
        }
      | _ => ()
      },
    items,
  );
}

and module_binding = (spans, mpath, mb: module_binding): unit =>
  switch (mb.pmb_name.txt, strip_constraint(mb.pmb_expr).pmod_desc) {
  | (Some(name), Pmod_structure(s)) => structure(spans, mpath @ [name], s)
  | _ => ()
  };

let rec signature = (spans, mpath: list(string), items: signature): unit =>
  List.iter(
    (si: signature_item) =>
      switch (si.psig_desc) {
      | Psig_value(vd) =>
        add_loc(spans, Val, mpath, vd.pval_name.txt, vd.pval_loc)
      | [@implicit_arity] Psig_type(_, decls) =>
        List.iter(
          (d: type_declaration) =>
            add_loc(spans, Type, mpath, d.ptype_name.txt, d.ptype_loc),
          decls,
        )
      | Psig_module({
          pmd_name: {txt: Some(name), _},
          pmd_type: {pmty_desc: Pmty_signature(sg), _},
          _,
        }) =>
        signature(spans, mpath @ [name], sg)
      | _ => ()
      },
    items,
  );

/* ---------- getting a parse tree ---------- */

let read_file = (path: string): option(string) =>
  switch (open_in_bin(path)) {
  | exception (Sys_error(_)) => None
  | ic =>
    Fun.protect(
      ~finally=() => close_in_noerr(ic),
      () =>
        switch (really_input_string(ic, in_channel_length(ic))) {
        | s => Some(s)
        | exception _ => None
        },
    )
  };

/* A parse tree as dune's preprocessors write it: the compiler's magic
   number, the source file's name, the tree. The magic number is checked,
   so a tree of another compiler version is not read. */
let read_ast = (path: string, ~magic: string): option('ast) =>
  switch (open_in_bin(path)) {
  | exception (Sys_error(_)) => None
  | ic =>
    Fun.protect(
      ~finally=() => close_in_noerr(ic),
      () =>
        switch (really_input_string(ic, String.length(magic))) {
        | m when m == magic =>
          let _name: string = input_value(ic);
          Some(input_value(ic));
        | _ => None
        | exception _ => None
        },
    )
  };

type tree =
  | Impl(Parsetree.structure)
  | Intf(Parsetree.signature);

let parse_text = (~file: string, ~intf: bool, text: string): option(tree) => {
  let lexbuf = Lexing.from_string(text);
  Location.init(lexbuf, file);
  /* the lexer's warnings would go to stderr */
  ignore(Warnings.parse_options(false, "-a"));
  switch (
    if (intf) {
      Intf(Parse.interface(lexbuf));
    } else {
      Impl(Parse.implementation(lexbuf));
    }
  ) {
  | tree => Some(tree)
  | exception _ => None
  };
};

/* [file] is relative to [root]; [build] is the build context directory,
   where dune keeps a file's preprocessed forms next to its copy. */
let tree = (~root: string, ~build: string, file: string): option(tree) => {
  let has = Filename.check_suffix(file);
  let base = Filename.remove_extension(file);
  let intf = has(".mli") || has(".rei");
  let read = name => {
    let path = Filename.concat(build, name);
    if (intf) {
      Option.map(
        t => Intf(t),
        read_ast(path, ~magic=Config.ast_intf_magic_number),
      );
    } else {
      Option.map(
        t => Impl(t),
        read_ast(path, ~magic=Config.ast_impl_magic_number),
      );
    };
  };
  let preprocessed =
    if (has(".ml")) {
      [base ++ ".pp.ml"];
    } else if (has(".mli")) {
      [base ++ ".pp.mli"];
    } else if (has(".re")) {
      [file ++ ".pp.ml", file ++ ".ml"];
    } else if (has(".rei")) {
      [file ++ ".pp.mli", file ++ ".mli"];
    } else {
      [];
    };
  switch (List.find_map(read, preprocessed)) {
  | Some(tree) => Some(tree)
  | None when has(".ml") || has(".mli") =>
    Option.bind(
      read_file(Filename.concat(root, file)),
      parse_text(~file, ~intf),
    )
  | None => None
  };
};

/* ---------- from the text ---------- */

/* A scan for binders by indentation. A line opens an item of a module
   when it starts with [let], [and], [type], [external] or [val] at the
   indentation of that module's body; [module M = ...] opens a module,
   which lasts until a line indented no deeper than it. An item runs to
   the line before the next line at its indentation that opens something
   (an item, a module, [open], a comment, ...) or before the first line
   indented less. A module whose signature is written out before its body
   ([module M : sig ... end = struct ... end]) is found by the line where
   the body starts. Handles both syntaxes; knows nothing of strings or
   comments that span lines. */

let is_ident_char = c =>
  switch (c) {
  | 'a' .. 'z'
  | 'A' .. 'Z'
  | '0' .. '9'
  | '_'
  | '\'' => true
  | _ => false
  };

/* The identifier at [i], and where it ends. */
let ident_at = (s: string, i: int): (string, int) => {
  let n = String.length(s);
  let rec stop = j =>
    if (j < n && is_ident_char(s.[j])) {
      stop(j + 1);
    } else {
      j;
    };
  let j = stop(i);
  (String.sub(s, i, j - i), j);
};

let rec skip_spaces = (s: string, i: int): int =>
  if (i < String.length(s) && (s.[i] == ' ' || s.[i] == '\t')) {
    skip_spaces(s, i + 1);
  } else {
    i;
  };

type line =
  | Blank
  | Item(int, kind, string) /* indentation, kind, name ("": a test without one) */
  | Module(int, string)
  /* [end = struct], [} = {]: a module's signature ends, its body starts */
  | Body(int)
  | Opener(int) /* starts something that is not an item: open, a comment, ... */
  | Other(int);

let openers = [
  "let",
  "and",
  "type",
  "module",
  "external",
  "val",
  "open",
  "include",
  "exception",
  "class",
];

/* [last] is the kind of the item an [and] continues. */
let classify = (~last: kind, s: string): line => {
  let n = String.length(s);
  let d = skip_spaces(s, 0);
  let starts = prefix =>
    d
    + String.length(prefix) <= n
    && String.sub(s, d, String.length(prefix)) == prefix;
  let ends = suffix => {
    let t = String.trim(s);
    String.ends_with(~suffix, t);
  };
  if (d >= n || s.[d] == '\r') {
    Blank;
  } else if (starts("}")
             && ends("= {")
             || starts("end")
             && ends("= struct")) {
    Body(d);
  } else if (starts("[@@") && !starts("[@@@")) {
    Other
      (d); /* an attribute of the item above */
  } else if (List.exists(starts, ["(*", "/*", "//", "[@", "[%%", "#"])) {
    Opener(d);
  } else {
    let (word, after) = ident_at(s, d);
    let after_word = skip_spaces(s, after);
    /* the name of a value: [rec] aside, the next identifier, or an
       operator in parentheses */
    let value_name = i => {
      let (w, j) = ident_at(s, i);
      let (w, j) =
        if (w == "rec") {
          let i = skip_spaces(s, j);
          let (w, j) = ident_at(s, i);
          (w, w == "" ? i : j);
        } else {
          (w, w == "" ? i : j);
        };
      let operator =
        if (w == "" && j < n && s.[j] == '(') {
          switch (String.index_from_opt(s, j, ')')) {
          | Some(close) =>
            let op = String.trim(String.sub(s, j + 1, close - j - 1));
            let symbol = c => !is_ident_char(c) && c != ' ' && c != ',';
            if (op != "" && String.for_all(symbol, op)) {
              Some(op);
            } else {
              None;
            };
          | None => None
          };
        } else {
          None;
        };
      switch (operator) {
      | Some(op) => Item(d, Val, op)
      | None when w == "" || w == "_" => Opener(d)
      | None => Item(d, Val, w)
      };
    };
    /* the name of a type: OCaml writes its parameters first */
    let type_name = i => {
      let (w, j) = ident_at(s, i);
      let i =
        if (w == "nonrec") {
          skip_spaces(s, j);
        } else {
          i;
        };
      let rec skip_params = i =>
        if (i >= n) {
          i;
        } else if (s.[i] == '(') {
          switch (String.index_from_opt(s, i, ')')) {
          | Some(close) => skip_params(skip_spaces(s, close + 1))
          | None => n
          };
        } else if (s.[i] == '\''
                   || s.[i] == '+'
                   || s.[i] == '-'
                   || s.[i] == '!') {
          let rec past = j =>
            if (j < n
                && (
                  is_ident_char(s.[j])
                  || s.[j] == '+'
                  || s.[j] == '-'
                  || s.[j] == '!'
                )) {
              past(j + 1);
            } else {
              j;
            };
          skip_params(skip_spaces(s, past(i)));
        } else {
          i;
        };
      let (w, _) = ident_at(s, skip_params(i));
      if (w == "") {
        Opener(d);
      } else {
        Item(d, Type, w);
      };
    };
    switch (word) {
    | "let" when after < n && s.[after] == '%' =>
      /* let%test "name" = ... */
      let (ext, j) = ident_at(s, after + 1);
      let j = skip_spaces(s, j);
      if ((ext == "test" || ext == "test_unit") && j < n && s.[j] == '"') {
        switch (String.index_from_opt(s, j + 1, '"')) {
        | Some(close) => Item(d, Test, String.sub(s, j + 1, close - j - 1))
        | None => Opener(d)
        };
      } else if (ext == "test" || ext == "test_unit") {
        Item(d, Test, "");
      } else {
        Opener(d);
      };
    | "let"
    | "external"
    | "val" => value_name(after_word)
    | "type" => type_name(after_word)
    | "and" =>
      switch (last) {
      | Type => type_name(after_word)
      | Val
      | Test => value_name(after_word)
      }
    | "module" =>
      let (w, j) = ident_at(s, after_word);
      let (w, _) =
        if (w == "rec") {
          ident_at(s, skip_spaces(s, j));
        } else {
          (w, j);
        };
      if (w == "" || w == "type") {
        Opener(d);
      } else {
        Module(d, w);
      };
    | w when List.mem(w, openers) => Opener(d)
    | _ => Other(d)
    };
  };
};

let scan = (~prefix: list(string), text: string): t => {
  let spans = Hashtbl.create(64);
  let lines = Array.of_list(String.split_on_char('\n', text));
  let n = Array.length(lines);
  /* classify, carrying the kind an [and] continues */
  let last = ref(Val);
  let classes =
    Array.map(
      s => {
        let c = classify(~last=last^, s);
        switch (c) {
        | Item(_, (Type | Val) as k, _) => last := k
        | _ => ()
        };
        c;
      },
      lines,
    );
  let indent =
    fun
    | Blank => None
    | Item(d, _, _)
    | Module(d, _)
    | Body(d)
    | Opener(d)
    | Other(d) => Some(d);
  /* the last line of the item that starts on line [i] (0-based) */
  let last_line = (i, d) => {
    let rec go = (j, last) =>
      if (j >= n) {
        last;
      } else {
        switch (classes[j]) {
        | Blank => go(j + 1, last)
        | c =>
          let dj = Option.get(indent(c));
          let opens =
            switch (c) {
            | Other(_) => false
            | _ => true
            };
          if (dj < d || dj == d && opens) {
            last;
          } else {
            go(j + 1, j);
          };
        };
      };
    go(i + 1, i);
  };
  /* open modules, innermost first: (indentation, name, body indentation) */
  let stack = ref([]);
  Array.iteri(
    (i, c) =>
      switch (indent(c)) {
      | None => ()
      | Some(d) =>
        stack :=
          List.filter(
            ((md, _, _)) =>
              switch (c) {
              /* the module it is the body of stays open, and what its
                 signature declared is found again, defined, below */
              | Body(_) => md <= d
              | _ => md < d
              },
            stack^,
          );
        switch (c, stack^) {
        | (Body(_), [(md, name, _), ...rest]) when md == d =>
          stack := [(md, name, None), ...rest]
        | _ => ()
        };
        let body =
          switch (stack^) {
          | [] => 0
          | [(md, _, None), ..._] when md == d => (-1) /* the [Body] line itself */
          | [(md, name, None), ...rest] =>
            stack := [(md, name, Some(d)), ...rest];
            d;
          | [(_, _, Some(body)), ..._] => body
          };
        let mpath = prefix @ List.rev_map(((_, name, _)) => name, stack^);
        if (d == body) {
          switch (c) {
          | Item(_, Test, "") =>
            add_unnamed_lines(spans, mpath, i + 1, last_line(i, d) + 1)
          | Item(_, kind, name) =>
            add(spans, kind, mpath, name, i + 1, last_line(i, d) + 1)
          | Module(_, name) => stack := [(d, name, None), ...stack^]
          | _ => ()
          };
        };
      },
    classes,
  );
  {
    exact: false,
    spans,
  };
};

/* ---------- the entry point ---------- */

/* [prefix] is the name of the file's module as the graph shows it
   (["Geo"]): entry paths start with it. [None] if the file cannot be
   read at all. */
let source =
    (~root: string, ~build: string, ~prefix: list(string), file: string)
    : option(t) =>
  switch (tree(~root, ~build, file)) {
  | Some(tree) =>
    let spans = Hashtbl.create(64);
    switch (tree) {
    | Impl(s) => structure(spans, prefix, s)
    | Intf(s) => signature(spans, prefix, s)
    };
    Some({
      exact: true,
      spans,
    });
  | None =>
    Option.map(scan(~prefix), read_file(Filename.concat(root, file)))
  };

files.extract/main.re:
/* portolan-extract <root> [--build-dir DIR] [--failing file:line,file:line]
                           [--previous FILE] [--broken file:line,file:line]

   Prints the graph of the dune project at <root> as JSON on stdout.
   The project's annotations must have been built first:
     dune build --root . --build-dir _build_portolan @check

   When that build fails, the modules that did not compile have no
   annotations. Pass the graph printed by an earlier run (--previous) to
   keep them in the picture as they were, and the compiler's error
   locations (--broken) to mark the definitions they fall in. */

let usage = "usage: portolan-extract <root> [--build-dir DIR] [--failing file:line,file:line] [--previous FILE] [--broken file:line,file:line]";

let die = message => {
  prerr_endline(message);
  exit(1);
};

/* "lib/scene.ml:20,lib/scene.ml:31" -> [("lib/scene.ml", 20); ...] */
let parse_lines = (~flag: string, s: string): list((string, int)) =>
  String.split_on_char(',', s)
  |> List.filter(entry => String.trim(entry) != "")
  |> List.map(entry => {
       let entry = String.trim(entry);
       switch (String.rindex_opt(entry, ':')) {
       | None => die(flag ++ ": expected file:line, got " ++ entry)
       | Some(i) =>
         let file = String.sub(entry, 0, i);
         let line = String.sub(entry, i + 1, String.length(entry) - i - 1);
         switch (int_of_string_opt(line)) {
         | Some(line) => (file, line)
         | None => die(flag ++ ": expected file:line, got " ++ entry)
         };
       };
     });

let () = {
  let root = ref(None);
  let build_dir = ref("_build_portolan");
  let failing = ref(None);
  let previous = ref(None);
  let broken = ref([]);
  let rec parse =
    fun
    | [] => ()
    | ["--build-dir", dir, ...rest] => {
        build_dir := dir;
        parse(rest);
      }
    | ["--failing", list, ...rest] => {
        failing := Some(parse_lines(~flag="--failing", list));
        parse(rest);
      }
    | ["--broken", list, ...rest] => {
        broken := parse_lines(~flag="--broken", list);
        parse(rest);
      }
    | ["--previous", file, ...rest] => {
        let text =
          switch (In_channel.with_open_bin(file, In_channel.input_all)) {
          | text => text
          | exception (Sys_error(message)) => die("--previous: " ++ message)
          };
        switch (Portolan_graph.Graph.of_string(text)) {
        | Ok(graph) => previous := Some(graph)
        | Error(message) =>
          die("--previous: " ++ file ++ " is not a graph: " ++ message)
        };
        parse(rest);
      }
    | ["-h" | "--help", ..._] => {
        print_endline(usage);
        exit(0);
      }
    | [arg, ...rest]
        when root^ == None && !String.starts_with(~prefix="-", arg) => {
        root := Some(arg);
        parse(rest);
      }
    | [arg, ..._] => die("unexpected argument: " ++ arg ++ "\n" ++ usage);

  parse(List.tl(Array.to_list(Sys.argv)));
  switch (root^) {
  | None => die(usage)
  | Some(root) =>
    switch (
      Portolan_extract.Extract.extract(
        ~root,
        ~build_dir=build_dir^,
        ~failing=failing^,
        ~previous=previous^,
        ~broken=broken^,
      )
    ) {
    | Ok(graph) => print_endline(Portolan_graph.Graph.to_string(graph))
    | Error(message) => die("portolan-extract: " ++ message)
    }
  };
};

files.extract/test/test_extract.re:
/* Checks the graphs extracted from the example projects.

   Each example's annotations are built here the first time it is used,
   and the tests of a broken build copy an example to a temporary
   directory and build it there, so dune must be on the path. */

module G = Portolan_graph.Graph;
module Extract = Portolan_extract.Extract;
module Locate = Portolan_extract.Locate;

let build_dir = "_build_portolan";

/* The repository root: $PORTOLAN_ROOT, or the nearest directory above
   the working directory that holds the examples. Under [dune test] the
   working directory is _build/default/extract/test. */
let repo_root: string = (
  {
    let is_root = dir =>
      List.for_all(
        path => Sys.file_exists(List.fold_left(Filename.concat, dir, path)),
        [["examples", "vector", "dune-project"], ["portolan"]],
      );

    let rec up = dir =>
      if (is_root(dir)) {
        Some(dir);
      } else {
        let parent = Filename.dirname(dir);
        if (parent == dir) {
          None;
        } else {
          up(parent);
        };
      };

    let from_env =
      switch (Sys.getenv_opt("PORTOLAN_ROOT")) {
      | Some(dir) when is_root(dir) => Some(dir)
      | _ => None
      };

    switch (from_env, up(Sys.getcwd())) {
    | (Some(dir), _)
    | (None, Some(dir)) => dir
    | (None, None) =>
      prerr_endline(
        "test_extract: the examples were not found. Set PORTOLAN_ROOT to the repository.",
      );
      exit(1);
    };
  }: string
);

/* An example project, its annotations built (once per run). */
let example = {
  let built = Hashtbl.create(4);
  name => {
    let dir = List.fold_left(Filename.concat, repo_root, ["examples", name]);
    if (!Hashtbl.mem(built, name)) {
      Hashtbl.replace(built, name, ());
      let code =
        Sys.command(
          Printf.sprintf(
            "cd %s && dune build --root . --build-dir %s @check > /dev/null 2>&1",
            Filename.quote(dir),
            build_dir,
          ),
        );
      if (code != 0) {
        Printf.eprintf("test_extract: examples/%s does not build\n%!", name);
      };
    };
    dir;
  };
};

let extract = (~failing=?, name): G.t =>
  switch (
    Portolan_extract.Extract.extract(
      ~root=example(name),
      ~build_dir,
      ~failing,
      ~previous=None,
      ~broken=[],
    )
  ) {
  | Ok(g) => g
  | Error(message) => Alcotest.failf("extract %s: %s", name, message)
  };

let node = (g: G.t, key): G.node =>
  switch (List.find_opt((n: G.node) => n.key == key, g.nodes)) {
  | Some(n) => n
  | None => Alcotest.failf("no node %s", key)
  };

let edge = (g: G.t, name): G.edge =>
  switch (List.find_opt((e: G.edge) => e.e_name == name, g.edges)) {
  | Some(e) => e
  | None => Alcotest.failf("no edge %s", name)
  };

let value = (g: G.t, name): G.value =>
  switch (List.find_opt((v: G.value) => v.v_name == name, g.values)) {
  | Some(v) => v
  | None => Alcotest.failf("no value %s", name)
  };

let kind =
  Alcotest.testable(
    (ppf, k) => Format.pp_print_string(ppf, G.kind_to_string(k)),
    (==),
  );
let strings = Alcotest.(list(string));
let has_edge = (g: G.t, name) =>
  List.exists((e: G.edge) => e.e_name == name, g.edges);
let has_node = (g: G.t, key) =>
  List.exists((n: G.node) => n.key == key, g.nodes);
let in_file = (file, g: G.t): list(string) =>
  List.filter_map(
    (e: G.edge) => e.e_at.file == file ? Some(e.e_name) : None,
    g.edges,
  );
let test_names = (e: G.edge) => List.map((t: G.test) => t.t_name, e.tests);

