  check(plane, "Path.t", Some("[]"), ["Point.t"]);
  check(plane, "Path.ends", Some("?"), ["Point.pair"]);
  List.iter(name => check_well_formed(name, extract(name)), examples);
  /* in the JSON: a string, or no field at all */
