  let broken = broken_build(dir);
  Alcotest.(check(list(pair(string, int))))(
    "the compiler's error",
    [("lib/point.re", line_of(dir, "lib/point.re", "p.x ++ factor"))],
    broken,
  );
  check_route(
    "the source parses: dune's tree is there",
