let (/) = Filename.concat;

type source =
  | Live(Project.t, Agent.t)
  | Replay({
      lines: list(Event.Line.t),
      speed: float,
    });

/* ---------- requests ---------- */

let url_decode = s => {
  let b = Buffer.create(String.length(s));
  let i = ref(0);
  while (i^ < String.length(s)) {
    switch (s.[i^]) {
    | '%' when i^ + 2 < String.length(s) =>
      try(
        {
          Buffer.add_char(
            b,
            Char.chr(int_of_string("0x" ++ String.sub(s, i^ + 1, 2))),
          );
          i := i^ + 2;
        }
      ) {
      | _ => Buffer.add_char(b, '%')
      }
    | '+' => Buffer.add_char(b, ' ')
    | c => Buffer.add_char(b, c)
    };
    incr(i);
  };
  Buffer.contents(b);
};

/* "/path?a=1&b=2" -> ("/path", [("a", "1"), ("b", "2")]) */
let parse_target = target =>
  switch (String.index_opt(target, '?')) {
  | None => (url_decode(target), [])
  | Some(i) =>
    let q = String.sub(target, i + 1, String.length(target) - i - 1);
    (
      url_decode(String.sub(target, 0, i)),
      List.filter_map(
        kv =>
          switch (String.index_opt(kv, '=')) {
          | Some(j) =>
            Some((
              url_decode(String.sub(kv, 0, j)),
              url_decode(String.sub(kv, j + 1, String.length(kv) - j - 1)),
            ))
          | None => None
          },
        String.split_on_char('&', q),
      ),
    );
  };

type request = {
  meth: string,
  path: string,
  query: list((string, string)),
  body: string,
};

let read_request = ic => {
  let (meth, target) =
    switch (String.split_on_char(' ', String.trim(input_line(ic)))) {
    | [m, t, ..._] => (m, t)
    | _ => ("", "/")
    };
  let rec headers = acc =>
    switch (String.trim(input_line(ic))) {
    | "" => acc
    | l =>
      switch (String.index_opt(l, ':')) {
      | Some(i) =>
        headers([
          (
            String.lowercase_ascii(String.sub(l, 0, i)),
            String.trim(String.sub(l, i + 1, String.length(l) - i - 1)),
          ),
          ...acc,
        ])
      | None => headers(acc)
      }
    };
  let body =
    switch (List.assoc_opt("content-length", headers([]))) {
    | Some(n) => really_input_string(ic, int_of_string(n))
    | None => ""
    };
  let (path, query) = parse_target(target);
  {
    meth,
    path,
    query,
    body,
  };
};

/* ---------- responses ---------- */

let ctype = path => {
  let has = Filename.check_suffix(path);
  if (has(".html")) {
    "text/html; charset=utf-8";
  } else if (has(".js")) {
    "text/javascript; charset=utf-8";
  } else if (has(".css")) {
    "text/css; charset=utf-8";
  } else if (has(".json") || has(".jsonl")) {
    "application/json; charset=utf-8";
  } else if (has(".svg")) {
    "image/svg+xml";
  } else if (has(".woff2")) {
    "font/woff2";
  } else {
    "text/plain; charset=utf-8";
  };
};

let respond =
    (
      oc,
      ~status="200 OK",
      ~ctype="text/plain; charset=utf-8",
      ~headers=[],
      body,
    ) => {
  Printf.fprintf(
    oc,
    "HTTP/1.1 %s\r\nContent-Type: %s\r\nContent-Length: %d\r\nCache-Control: no-store\r\nConnection: close\r\n%s\r\n%s",
    status,
    ctype,
    String.length(body),
    String.concat(
      "",
      List.map(((name, value)) => name ++ ": " ++ value ++ "\r\n", headers),
    ),
    body,
  );
  flush(oc);
};

let not_found = oc => respond(oc, ~status="404 Not Found", "not found");
let ok = oc => respond(oc, ~ctype="application/json", "{\"ok\":true}");

let serve_file = (oc, path) =>
  if (!List.mem("..", String.split_on_char('/', path))
      && Sys.file_exists(path)
      && !Sys.is_directory(path)) {
    respond(oc, ~ctype=ctype(path), Files.read(path));
  } else {
    not_found(oc);
  };

/* ---------- the event stream ---------- */

let sse_headers = oc => {
  output_string(
    oc,
    "HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nCache-Control: no-cache\r\nConnection: keep-alive\r\n\r\n",
  );
  flush(oc);
};

let sse = (oc, s) => {
  output_string(oc, "data: ");
  output_string(oc, s);
  output_string(oc, "\n\n");
};

let sse_event = (oc, line) => sse(oc, Event.Line.to_string(line));

/* Live: the trace so far at once, then a marker, then events as they
   come. A viewer joining late needs only the latest graph, so the
   backlog's graph events are sent as one. If the trace is started over,
   the same again from its start. */
let events_live = oc => {
  sse_headers(oc);
  let cursor = ref(Bus.origin);
  while (true) {
    let (batch, next, from_start) = Bus.wait(cursor^);
    cursor := next;
    if (from_start) {
      sse(oc, "{\"type\":\"reset\"}");
      List.iter(sse_event(oc), Graphs.collapse(batch));
      sse(oc, "{\"type\":\"caught_up\"}");
    } else {
      List.iter(sse_event(oc), batch);
    };
    flush(oc);
  };
};

/* Replay: a recorded trace, with its own timing, from the start for each viewer. */
let events_replay = (oc, ~lines, ~speed) => {
  sse_headers(oc);
  sse(oc, "{\"type\":\"caught_up\"}");
  flush(oc);
  let prev = ref(0);
  List.iter(
    line => {
      let t = Option.value(Event.Line.time(line), ~default=prev^);
      let gap = Float.min(2.0, float_of_int(t - prev^) /. 1000. /. speed);
      if (gap > 0.005) {
        Thread.delay(gap);
      };
      prev := t;
      sse_event(oc, line);
      flush(oc);
    },
    lines,
  );
  sse(oc, "{\"type\":\"replay_end\"}");
  flush(oc);
  while (true) {
    Thread.delay(30.);
    output_string(oc, ": keep\n\n");
    flush(oc);
  };
};

/* ---------- routes ---------- */

let refmt = (oc, project, query) => {
  let param = name => List.assoc_opt(name, query);
  let number = name => Option.bind(param(name), int_of_string_opt);
  switch (Option.bind(param("file"), Project.file(project))) {
  | None => not_found(oc)
  | Some(path) =>
    let first = Option.value(number("line"), ~default=1)
    and last = number("end_line");
    let (text, converted) =
      switch (Option.bind(param("to"), Syntax.of_string)) {
      | Some(target) => Syntax.convert(~path, ~first, ~last, ~target)
      | None => (Syntax.slice(~first, ~last, Files.read(path)), false)
      };
    respond(
      oc,
      ~headers=converted ? [] : [("X-Portolan-Converted", "no")],
      text,
    );
  };
};

/* The user's answer to a request of the agent's, from the page's JSON. */
let answer = json =>
  switch (Yojson.Safe.Util.member("id", json), Event.answer_of_json(json)) {
  | (`String(id), Some(answer)) => Some((id, answer))
  | _ => None
  };

let route = (oc, ~home, source, {meth, path, query, body}) =>
  switch (meth, path, source) {
  | ("GET", "/events", Live(_)) => events_live(oc)
  | ("GET", "/events", Replay({lines, speed})) =>
    events_replay(oc, ~lines, ~speed)
  | ("GET", "/" | "/index.html", _) =>
    serve_file(oc, home / "web" / "index.html")
  | ("GET", "/trace", _) =>
    respond(
      oc,
      ~ctype="application/json; charset=utf-8",
      String.concat(
        "\n",
        List.map(
          Event.Line.to_string,
          switch (source) {
          | Live(_) => Bus.all()
          | Replay({lines, _}) => lines
          },
        ),
      ),
    )
  | ("GET", "/source", Live(project, _)) =>
    switch (
      Option.bind(List.assoc_opt("file", query), Project.file(project))
    ) {
    | Some(file) => respond(oc, Files.read(file))
    | None => not_found(oc)
    }
  | ("GET", "/source" | "/refmt", Replay(_)) => not_found(oc)
  | ("GET", "/refmt", Live(project, _)) => refmt(oc, project, query)
  | ("POST", "/prompt", Live(_, agent)) =>
    let (text, about) =
      switch (Yojson.Safe.from_string(body)) {
      | json => (
          Yojson.Safe.Util.(json |> member("text") |> to_string),
          Event.about_of_json(Yojson.Safe.Util.member("about", json)),
        )
      | exception _ => (body, None)
      };
    if (String.trim(text) != "") {
      Agent.prompt(agent, ~about?, text);
    };
    ok(oc);
  | ("POST", "/answer", Live(_, agent)) =>
    switch (answer(Yojson.Safe.from_string(body))) {
    | Some((id, answer)) =>
      Agent.answer(agent, ~id, answer);
      ok(oc);
    | None
    | exception _ => respond(oc, ~status="400 Bad Request", "no")
    }
  | ("POST", "/new", Live(project, agent)) =>
    Conversation.start_new(project, agent);
    ok(oc);
  | ("POST", "/types", Live(_)) =>
    let texts =
      try(
        Yojson.Safe.Util.(
          Yojson.Safe.from_string(body)
          |> member("types")
          |> to_list
          |> List.map(to_string)
        )
      ) {
      | _ => []
      };
    let answer =
      Syntax.types(texts)
      |> List.map(
           fun
           | Some(t) => `String(t)
           | None => `Null,
         );
    respond(
      oc,
      ~ctype="application/json; charset=utf-8",
      Yojson.Safe.to_string(`Assoc([("types", `List(answer))])),
    );
  | ("POST", "/stop", Live(_, agent)) =>
    Agent.stop(agent);
    ok(oc);
  /* The other code bases this page can switch to: the list a running
     `portolan hub` wrote, or else the recorded runs that ship with the page. */
  | ("GET", "/projects.json", _) =>
    let hub = home / "local" / "hub" / "projects.json";
    serve_file(
      oc,
      Sys.file_exists(hub) ? hub : home / "web" / "projects.json",
    );
  | ("GET", p, _) when String.starts_with(~prefix="/runs/", p) =>
    serve_file(
      oc,
      home / "site" / "runs" / String.sub(p, 6, String.length(p) - 6),
    )
  | ("GET", p, _) when String.starts_with(~prefix="/canvas/", p) =>
    serve_file(
      oc,
      home / "canvas" / "dist" / String.sub(p, 8, String.length(p) - 8),
    )
  | ("GET", p, _) =>
    serve_file(oc, home / "web" / String.sub(p, 1, String.length(p) - 1))
  | _ => respond(oc, ~status="405 Method Not Allowed", "no")
  };

let handle = (~home, source, fd) => {
  let ic = Unix.in_channel_of_descr(fd)
  and oc = Unix.out_channel_of_descr(fd);
  try(route(oc, ~home, source, read_request(ic))) {
  | _ =>
    /* Usually the viewer has gone; if not, say that it went wrong. */
    try(respond(oc, ~status="500 Internal Server Error", "error")) {
    | _ => ()
    }
  };
  try(flush(oc)) {
  | _ => ()
  };
  try(Unix.close(fd)) {
  | _ => ()
  };
};

let serve = (~port, ~home, source) => {
  let sock = Unix.socket(Unix.PF_INET, Unix.SOCK_STREAM, 0);
  Unix.setsockopt(sock, Unix.SO_REUSEADDR, true);
  Unix.bind(sock, Unix.ADDR_INET(Unix.inet_addr_loopback, port));
  Unix.listen(sock, 64);
  Printf.printf("Portolan: http://127.0.0.1:%d/\n%!", port);
  while (true) {
    switch (Unix.accept(sock)) {
    | (fd, _) => ignore(Thread.create(handle(~home, source), fd))
    | exception (Unix.Unix_error(Unix.EINTR, _, _)) => ()
    };
  };
};

files.sidecar/main.re:
/* The Portolan sidecar.

   One process, started for one project directory. It
   - watches the project's source files; on a change it builds the
     annotations into a build directory of its own, runs the extractor and
     the tests, and emits a new graph snapshot when the graph changed;
   - runs a coding agent (Claude Code in its headless streaming mode, or a
     scripted stand-in) and relays its stream;
   - serves the page and a server-sent event stream carrying both;
   - appends every event to the project's trace file, which is loaded
     again at the next start and which `replay` plays back.

   Files on disk are the truth: the model is re-derived from them after
   every change, whoever made it.

   The modules, each with its interface:
     Files     reading and writing files, folders git ignores
     Run       a shell command with a timeout
     Project   the watched project: paths, state folder, opam switch
     Event     what the sidecar reports, and its JSON
     Bus       events as they happen, the trace file, waiting readers
     Delta     the change from one JSON object to another
     Graphs    graph events: whole graphs and changes between them
     Watcher   file changes -> build -> graph -> tests
     Permissions  what the user chose to always allow the agent
     Protocol  Claude Code's stream: its lines read, ours written
     Turn      where the agent's turn stands: state, requests, last change
     Claude    Claude Code as a process in the project
     Script    the scripted stand-in
     Agent     whichever of the two the user talks to
     Conversation  starting a new one, keeping the old trace
     Syntax    OCaml <-> Reason conversion of a slice of a file
     Http      the page, the event stream, the routes
   This file reads the arguments and starts them.

   Dependencies: unix, threads, str, yojson. The graph is treated as
   opaque JSON here; only the extractor and the canvas know its shape. */

open Portolan_sidecar;

let (/) = Filename.concat;

let usage = "usage:
  portolan serve <project-dir> [flags]   watch a dune project and serve its page
  portolan replay <trace.jsonl> [--port N] [--speed X]   play back a recorded trace
  portolan compact <trace.jsonl> <out.jsonl>   rewrite an older trace, which holds every graph
                                whole, with graph changes: much smaller, plays the same
  portolan help

flags for serve:
  --port N                      port to serve on (default 8791)
  --agent claude|script:FILE    Claude Code (the default), or a scripted stand-in
  --model NAME                  the model Claude Code uses
  --nudge FILE                  text added to the agent's instructions
  --allow PATTERN               let the agent use one more tool without asking: a Claude Code
                                allowed-tool pattern such as 'Bash(make:*)'. Repeatable.
  --project-switch NAME_OR_DIR  the opam switch the project's builds, tests and the agent's
                                shell run in. Default: the project's own _opam folder if it
                                has one, otherwise the switch Portolan itself runs in.
  --extract FILE                the extractor executable (default: the one built in --home)
  --home DIR                    the Portolan folder holding web/ and canvas/dist/

The project's compiler must be OCaml 5.2.x for now: the extractor reads compiled annotations.
Without asking, the agent may edit files, run any dune command, and run ls, cat, head, tail,
wc, grep, rg, find, mkdir, git status, git diff, git log, opam list and ocamlfind list.
For anything else it waits, and the chat shows the request to allow once, always (remembered
in the project's .portolan/allow) or deny. In the chat, `stop` ends the agent's turn and `new`
starts a new conversation, keeping the trace so far in .portolan/conversations/.
The trace of a project is .portolan/trace.jsonl in its folder; it carries on across restarts.";

type options = {
  mutable port: int,
  mutable home: option(string),
  mutable agent: string,
  mutable model: option(string),
  mutable nudge: option(string),
  mutable allow: list(string),
  mutable project_switch: option(string),
  mutable extractor: option(string),
  mutable speed: float,
};

let absolute = p => Filename.is_relative(p) ? Sys.getcwd() / p : p;

let fail = message => {
  prerr_endline("portolan: " ++ message);
  exit(2);
};

/* Reads the flags into [o]; returns the arguments that are not flags. */
let rec flags = o =>
  fun
  | ["--port", n, ...rest] => {
      switch (int_of_string_opt(n)) {
      | Some(n) => o.port = n
      | None => fail("--port takes a number")
      };
      flags(o, rest);
    }
  | ["--home", dir, ...rest] => {
      o.home = Some(absolute(dir));
      flags(o, rest);
    }
  | ["--agent", kind, ...rest] => {
      o.agent = kind;
      flags(o, rest);
    }
  | ["--model", name, ...rest] => {
      o.model = Some(name);
      flags(o, rest);
    }
  | ["--nudge", file, ...rest] => {
      o.nudge = Some(absolute(file));
      flags(o, rest);
    }
  | ["--allow", pattern, ...rest] => {
      o.allow = o.allow @ [pattern];
      flags(o, rest);
    }
  | ["--project-switch", switch_, ...rest] => {
      o.project_switch = Some(switch_);
      flags(o, rest);
    }
  | ["--extract", file, ...rest] => {
      o.extractor = Some(absolute(file));
      flags(o, rest);
    }
  | ["--speed", x, ...rest] => {
      switch (float_of_string_opt(x)) {
      | Some(x) when x > 0. => o.speed = x
      | _ => fail("--speed takes a positive number")
      };
      flags(o, rest);
    }
  | [arg, ...rest] => [arg, ...flags(o, rest)]
  | [] => [];

/* The Portolan folder: the nearest one above the executable holding the page. */
let find_home = () => {
  let rec up = (d, n) =>
    if (Sys.file_exists(d / "web" / "index.html")) {
      d;
    } else if (n == 0 || d == "/") {
      Sys.getcwd();
    } else {
      up(Filename.dirname(d), n - 1);
    };
  up(Filename.dirname(Unix.realpath(Sys.executable_name)), 6);
};

let serve = (o, ~home, dir) => {
  let kind =
    switch (Agent.kind_of_string(o.agent)) {
    | Some(Agent.Script(file)) => Agent.Script(absolute(file))
    | Some(kind) => kind
    | None => fail("--agent takes claude or script:FILE")
    };
  let project =
    switch (Project.at(~opam_switch=?o.project_switch, dir)) {
    | Ok(project) => project
    | Error(message) => fail(message)
    };
  let earlier = Bus.record(Project.trace(project));
  Bus.emit(Session({restart: earlier > 0}));
  Bus.emit(
    Hello({
      project: Project.name(project),
      agent: o.agent,
      mode: Live,
      opam_switch: Project.opam_switch(project),
    }),
  );
  if (earlier > 0) {
    /* Whatever the agent was doing when the last session ended, it is not now. */
    Bus.emit(
      Agent_state(Idle),
    );
  };
  /* A project that had no `dune-project` when first served is a new one,
     and stays one across restarts: its agent gets the starting hints. */
  let started_empty = Project.state(project, "new");
  if (earlier == 0
      && !
           Sys.file_exists(
             Filename.concat(Project.root(project), "dune-project"),
           )) {
    Files.write(started_empty, "");
  };
  let agent =
    Agent.make(
      ~kind,
      ~model=?o.model,
      ~instructions=
        [home / "sidecar" / "agent-prompt.md"]
        @ (
          Sys.file_exists(started_empty)
            ? [home / "sidecar" / "agent-prompt-new.md"] : []
        )
        @ Option.to_list(o.nudge),
      ~allow=o.allow,
      project,
    );
  Watcher.start(
    ~extractor=
      Option.value(
        o.extractor,
        ~default=home / "_build" / "default" / "extract" / "main.exe",
      ),
    ~cause=() => Agent.take_cause(agent),
    project,
  );
  Http.serve(~port=o.port, ~home, Http.Live(project, agent));
};

/* The events of a trace file. */
let trace = file =>
  try(
    List.map(Event.Line.of_string, Files.lines(Files.read(absolute(file))))
  ) {
  | Sys_error(message) => fail(message)
  };

let replay = (o, ~home, file) => {
  let lines = trace(file);
  Http.serve(
    ~port=o.port,
    ~home,
    Http.Replay({
      lines,
      speed: o.speed,
    }),
  );
};

let compact = (file, out) =>
  Files.write(
    absolute(out),
    String.concat(
      "\n",
      List.map(Event.Line.to_string, Graphs.compact(trace(file))),
    )
    ++ "\n",
  );

let () = {
  Sys.set_signal(Sys.sigpipe, Sys.Signal_ignore);
  let o = {
    port: 8791,
    home: None,
    agent: "claude",
    model: None,
    nudge: None,
    allow: [],
    project_switch: None,
    extractor: None,
    speed: 1.0,
  };
  let positional = flags(o, List.tl(Array.to_list(Sys.argv)));
  let home =
    switch (o.home) {
    | Some(home) => home
    | None => find_home()
    };
  switch (positional) {
  | ["serve", dir] => serve(o, ~home, dir)
  | ["replay", file] => replay(o, ~home, file)
  | ["compact", file, out] => compact(file, out)
  | ["help" | "--help" | "-h", ..._] => print_endline(usage)
  | _ =>
    prerr_endline(usage);
    exit(2);
  };
};

files.sidecar/permissions.re:
let file = project => Project.state(project, "allow");

let remembered = project =>
  try(List.map(String.trim, Files.lines(Files.read(file(project))))) {
  | Sys_error(_) => []
  };

let fresh = (~known, patterns) =>
  List.rev(
    List.fold_left(
      (acc, p) => {
        let p = String.trim(p);
        p == "" || List.mem(p, known) || List.mem(p, acc)
          ? acc : [p, ...acc];
      },
      [],
      patterns,
    ),
  );

let remember = (project, patterns) => {
  let known = remembered(project);
  let fresh = fresh(~known, patterns);
  if (fresh != []) {
    Files.write(file(project), String.concat("\n", known @ fresh) ++ "\n");
  };
};

/* ---------- patterns to offer ---------- */

/* Tools whose first argument names what they do. */
let families = [
  "git",
  "opam",
  "dune",
  "esy",
  "npm",
  "npx",
  "yarn",
  "pnpm",
  "cargo",
  "docker",
  "gh",
  "brew",
  "pip",
  "pip3",
];

let risky = [
  "rm",
  "sudo",
  "sh",
  "bash",
  "zsh",
  "eval",
  "curl",
  "wget",
  "chmod",
  "chown",
  "kill",
  "dd",
];

let is_word = s =>
  s != ""
  && s.[0] >= 'a'
  && s.[0] <= 'z'
  && String.for_all(
       c => c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '-',
       s,
     );

/* `git -C . status --short` -> `git -C . status`: up to the sub-command. */
let rec through_subcommand =
  fun
  | [] => None
  | [w, ..._] when is_word(w) => Some([w])
  | [w, ...rest] =>
    Option.map(found => [w, ...found], through_subcommand(rest));

let widen = command =>
  switch (List.filter(w => w != "", String.split_on_char(' ', command))) {
  /* Already a pattern. */
  | _
      when
        String.ends_with(~suffix=":*", command)
        || String.ends_with(~suffix=" *", command) => command
  | [first, ...rest] when List.mem(first, families) =>
    switch (through_subcommand(rest)) {
    | Some(words) => String.concat(" ", [first, ...words]) ++ ":*"
    | None => command
    }
  | [first, ..._] when is_word(first) && !List.mem(first, risky) =>
    first ++ ":*"
  | _ => command
  };

/* The commands of a pipeline or a sequence, split where the shell would;
   quoting is not looked at, which is good enough for a suggestion. */
let parts = command =>
  Str.split(Str.regexp("&&\\|||\\|[|;\n]"), command)
  |> List.map(String.trim)
  |> List.filter(part => part != "");

let suggest = (~tool, ~input, ~suggestions) => {
  open Yojson.Safe.Util;
  let text = (json, name) =>
    switch (member(name, json)) {
    | `String(s) => Some(s)
    | _ => None
    };
  let rules =
    (
      try(to_list(suggestions)) {
      | _ => []
      }
    )
    |> List.filter(s =>
         text(s, "type") == Some("addRules")
         && text(s, "behavior") == Some("allow")
       )
    |> List.concat_map(s =>
         try(to_list(member("rules", s))) {
         | _ => []
         }
       )
    |> List.filter_map(r =>
         switch (text(r, "toolName"), text(r, "ruleContent")) {
         | (Some("Bash"), Some(command)) =>
           Some("Bash(" ++ widen(command) ++ ")")
         | (Some(name), Some(content)) =>
           Some(name ++ "(" ++ content ++ ")")
         | (Some(name), None) => Some(name)
         | (None, _) => None
         }
       );
  let fallback =
    switch (tool, text(input, "command"), text(input, "file_path")) {
    | ("Bash", Some(command), _) =>
      List.map(part => "Bash(" ++ widen(part) ++ ")", parts(command))
    /* A file outside the project: everything in its folder. */
    | (_, _, Some(path)) when !Filename.is_relative(path) => [
        tool ++ "(/" ++ Filename.dirname(path) ++ "/**)",
      ]
    | _ => [tool]
    };
  List.sort_uniq(compare, rules == [] ? fallback : rules);
};

let rule = pattern =>
  switch (String.index_opt(pattern, '(')) {
  | Some(i) when String.ends_with(~suffix=")", pattern) =>
    `Assoc([
      ("toolName", `String(String.sub(pattern, 0, i))),
      (
        "ruleContent",
        `String(String.sub(pattern, i + 1, String.length(pattern) - i - 2)),
      ),
    ])
  | _ => `Assoc([("toolName", `String(pattern))])
  };

