let (/) = Filename.concat;

type t = {
  root: string,
  opam_switch: option(string),
  env: option(array(string)),
};

let root = p => p.root;
let name = p => Filename.basename(p.root);
let opam_switch = p => p.opam_switch;
let env = p => p.env;

let build_dir = "_build_portolan";
let ensure_build_dir = p => Files.private_dir(p.root / build_dir);

let state_dir = p => p.root / ".portolan";
let state = (p, name) => state_dir(p) / name;

let trace = p => {
  let path = state(p, "trace.jsonl");
  if (!Sys.file_exists(path)) {
    let stamped =
      Sys.readdir(state_dir(p))
      |> Array.to_list
      |> List.filter(f =>
           String.starts_with(~prefix="trace-", f)
           && String.ends_with(~suffix=".jsonl", f)
         )
      |> List.sort((a, b) => compare(b, a));
    switch (stamped) {
    | [newest, ..._] => Files.write(path, Files.read(state(p, newest)))
    | [] => ()
    };
  };
  path;
};

let is_file = path =>
  switch (Unix.stat(path).Unix.st_kind) {
  | Unix.S_REG => true
  | _
  | exception _ => false
  };

let file = (p, rel) =>
  if (rel != ""
      && Filename.is_relative(rel)
      && !List.mem("..", String.split_on_char('/', rel))
      && is_file(p.root / rel)) {
    Some(p.root / rel);
  } else {
    None;
  };

let relative = (p, path) => {
  let prefix = p.root ++ "/";
  let n = String.length(prefix);
  if (String.length(path) > n && String.starts_with(~prefix, path)) {
    Some(String.sub(path, n, String.length(path) - n));
  } else {
    None;
  };
};

let run = (~timeout=?, p, command) =>
  Run.cmd(~timeout?, ~env=?p.env, ~cwd=p.root, command);

/* ---------- the switch ---------- */

let is_dir = path =>
  try(Sys.is_directory(path)) {
  | Sys_error(_) => false
  };

/* "NAME=value" lines, as `env` prints them. A line that does not start a
   variable continues the value before it. */
let parse_env = out => {
  let starts_variable = line =>
    switch (String.index_opt(line, '=')) {
    | Some(i) when i > 0 =>
      String.for_all(
        c =>
          c == '_'
          || c >= 'A'
          && c <= 'Z'
          || c >= 'a'
          && c <= 'z'
          || c >= '0'
          && c <= '9',
        String.sub(line, 0, i),
      )
    | _ => false
    };
  List.fold_left(
    (acc, line) =>
      switch (acc) {
      | _ when starts_variable(line) => [line, ...acc]
      | [prev, ...rest] => [prev ++ "\n" ++ line, ...rest]
      | [] => []
      },
    [],
    String.split_on_char('\n', String.trim(out)),
  )
  |> List.rev
  |> Array.of_list;
};

let switch_env = name => {
  let enter =
    Printf.sprintf(
      "opam exec --switch=%s --set-switch -- env",
      Filename.quote(name),
    );
  let cwd = Sys.getcwd();
  switch (Run.cmd(~timeout=60., ~cwd, enter ++ " 2>/dev/null")) {
  | (0, out) when String.trim(out) != "" => Ok(parse_env(out))
  | _ =>
    let (_, why) = Run.cmd(~timeout=60., ~cwd, enter ++ " 2>&1 >/dev/null");
    Error(
      Printf.sprintf(
        "could not enter the opam switch %s\n%s",
        name,
        String.trim(why),
      ),
    );
  };
};

/* A switch given as a folder is named by its absolute path; the `_opam`
   folder inside one stands for the folder holding it. */
let switch_name = s =>
  if (is_dir(s)
      && (String.contains(s, '/') || String.starts_with(~prefix=".", s))) {
    let dir = Unix.realpath(s);
    Filename.basename(dir) == "_opam" ? Filename.dirname(dir) : dir;
  } else {
    s;
  };

let at = (~opam_switch=?, dir) => {
  let dir = Filename.is_relative(dir) ? Sys.getcwd() / dir : dir;
  if (!Sys.file_exists(dir)) {
    Files.mkdir_p(dir);
    Files.write(dir / "dune-workspace", "(lang dune 3.16)\n");
  };
  let root = Unix.realpath(dir);
  Files.private_dir(root / ".portolan");
  let entered =
    switch (opam_switch) {
    | Some(s) =>
      let s = switch_name(s);
      Result.map(env => (Some(s), Some(env)), switch_env(s));
    | None when is_dir(root / "_opam") =>
      /* Found, not asked for: if it cannot be entered, say so and carry on. */
      switch (switch_env(root)) {
      | Ok(env) => Ok((Some(root), Some(env)))
      | Error(message) =>
        prerr_endline("portolan: " ++ message);
        Ok((None, None));
      }
    | None => Ok((None, None))
    };
  Result.map(
    ((opam_switch, env)) =>
      {
        root,
        opam_switch,
        env,
      },
    entered,
  );
};

files.sidecar/protocol.re:
type request = {
  id: string,
  tool: string,
  input: Yojson.Safe.t,
  suggestions: Yojson.Safe.t,
  tool_use: option(string),
};

type said =
  | Began(Yojson.Safe.t, option(string))
  | Ended(Yojson.Safe.t)
  | Told(Yojson.Safe.t)
  | Asked(request)
  | Asked_other(string)
  | Withdrew(string)
  | Nothing
  | Raw(string);

/* ---------- reading ---------- */

let control_request = (ev: Yojson.Safe.t) => {
  open Yojson.Safe.Util;
  let id = ev |> member("request_id") |> to_string;
  let request = ev |> member("request");
  switch (request |> member("subtype")) {
  | `String("can_use_tool") =>
    Asked({
      id,
      tool: request |> member("tool_name") |> to_string,
      input: request |> member("input"),
      suggestions: request |> member("permission_suggestions"),
      tool_use: request |> member("tool_use_id") |> to_string_option,
    })
  | _ => Asked_other(id)
  };
};

let read = line =>
  switch (Yojson.Safe.from_string(line)) {
  | `Assoc(fields) as ev =>
    let field = name =>
      Option.value(List.assoc_opt(name, fields), ~default=`Null);
    switch (field("type"), field("subtype")) {
    | (`String("control_request"), _) =>
      try(control_request(ev)) {
      | _ => Nothing
      }
    | (`String("control_cancel_request"), _) =>
      switch (field("request_id")) {
      | `String(id) => Withdrew(id)
      | _ => Nothing
      }
    | (`String("control_response"), _) => Nothing
    | (`String("system"), `String("init")) =>
      Began(
        ev,
        switch (field("session_id")) {
        | `String(id) => Some(id)
        | _ => None
        },
      )
    | (`String("result"), _) => Ended(ev)
    | _ => Told(ev)
    };
  | _
  | exception _ => String.trim(line) == "" ? Nothing : Raw(line)
  };

let cause = (~relative, ev) => {
  open Yojson.Safe.Util;
  let found = ref(None);
  /* A block that is not as expected ends the look; what was found stands. */
  try(
    if (ev |> member("type") |> to_string == "assistant") {
      ev
      |> member("message")
      |> member("content")
      |> to_list
      |> List.iter(block =>
           if (block |> member("type") |> to_string == "tool_use") {
             let name = block |> member("name") |> to_string;
             let input = block |> member("input");
             let text = key =>
               try(input |> member(key) |> to_string) {
               | _ => ""
               };
             switch (name) {
             | "Write"
             | "Edit"
             | "MultiEdit" =>
               let file = text("file_path");
               found :=
                 Some(
                   Event.Wrote({
                     tool: name,
                     file: Option.value(relative(file), ~default=file),
                   }),
                 );
             | "Bash" =>
               found := Some(Ran(Event.clip(~n=120, text("command"))))
             | _ => ()
             };
           }
         );
    }
  ) {
  | _ => ()
  };
  found^;
};

/* ---------- writing ---------- */

type message = Yojson.Safe.t;

let to_string = (message: message) => Yojson.Safe.to_string(message);

let str = (s): Yojson.Safe.t => `String(s);

let prompt = (text): message =>
  `Assoc([
    ("type", str("user")),
    ("message", `Assoc([("role", str("user")), ("content", str(text))])),
  ]);

let allow = (~rules=[], input): Yojson.Safe.t =>
  `Assoc(
    [("behavior", str("allow")), ("updatedInput", input)]
    @ (
      rules == []
        ? []
        : [
          (
            "updatedPermissions",
            `List([
              `Assoc([
                ("type", str("addRules")),
                ("rules", `List(List.map(Permissions.rule, rules))),
                ("behavior", str("allow")),
                /* For the running process; the next one is started with
                   the remembered patterns. */
                ("destination", str("session")),
              ]),
            ]),
          ),
        ]
    ),
  );

let decision = (~input, answer: Event.answer): Yojson.Safe.t =>
  switch (answer) {
  | Once => allow(input)
  | Always(patterns) => allow(~rules=patterns, input)
  | Deny =>
    `Assoc([
      ("behavior", str("deny")),
      (
        "message",
        str(
          "The user declined this in Portolan's chat. Do not retry it; carry on another way or ask what they would prefer.",
        ),
      ),
    ])
  | Answers(answers) =>
    let answers =
      `Assoc(List.map(((q, label)) => (q, str(label)), answers));
    allow(
      switch (input) {
      | `Assoc(fields) =>
        `Assoc(
          List.remove_assoc("answers", fields) @ [("answers", answers)],
        )
      | other => other
      },
    );
  };

let response = (fields): message =>
  `Assoc([
    ("type", str("control_response")),
    ("response", `Assoc(fields)),
  ]);

let answer = (~id, ~input, answer): message =>
  response([
    ("subtype", str("success")),
    ("request_id", str(id)),
    ("response", decision(~input, answer)),
  ]);

let refusal = (~id): message =>
  response([
    ("subtype", str("error")),
    ("request_id", str(id)),
    ("error", str("Portolan does not handle this request.")),
  ]);

let interrupt = (~id): message =>
  `Assoc([
    ("type", str("control_request")),
    ("request_id", str(id)),
    ("request", `Assoc([("subtype", str("interrupt"))])),
  ]);

files.sidecar/run.re:
let cmd = (~timeout=120., ~env=?, ~cwd, command) => {
  let (r, w) = Unix.pipe(~cloexec=true, ());
  let argv = [|
    "/bin/sh",
    "-c",
    Printf.sprintf("cd %s && %s", Filename.quote(cwd), command),
  |];
  let devnull = Unix.openfile("/dev/null", [Unix.O_RDONLY], 0);
  let pid =
    switch (env) {
    | Some(env) =>
      Unix.create_process_env("/bin/sh", argv, env, devnull, w, w)
    | None => Unix.create_process("/bin/sh", argv, devnull, w, w)
    };
  Unix.close(devnull);
  Unix.close(w);
  let buf = Buffer.create(4096)
  and chunk = Bytes.create(4096);
  let deadline = Unix.gettimeofday() +. timeout;
  let timed_out = ref(false);
  let rec loop = () => {
    let left = deadline -. Unix.gettimeofday();
    if (left <= 0.) {
      timed_out := true;
      try(Unix.kill(pid, Sys.sigkill)) {
      | Unix.Unix_error(_) => ()
      };
    } else {
      switch (Unix.select([r], [], [], Float.min(left, 1.0))) {
      | ([], _, _) => loop()
      | _ =>
        let n =
          try(Unix.read(r, chunk, 0, 4096)) {
          | Unix.Unix_error(_) => 0
          };
        if (n > 0) {
          Buffer.add_subbytes(buf, chunk, 0, n);
          loop();
        };
      | exception (Unix.Unix_error(Unix.EINTR, _, _)) => loop()
      };
    };
  };
  loop();
  Unix.close(r);
  let code =
    switch (snd(Unix.waitpid([], pid))) {
    | Unix.WEXITED(n) => n
    | _ => 125
    | exception (Unix.Unix_error(_)) => 125
    };
  (timed_out^ ? 124 : code, Buffer.contents(buf));
};

files.sidecar/script.re:
let (/) = Filename.concat;

type t = {
  file: string,
  root: string,
  turn: Turn.t,
  /* Guards the fields below. Not held while calling [Turn]. */
  m: Mutex.t,
  /* Signals that one of them changed. */
  wake: Condition.t,
  /* Which play is the current one, and whether a stop was asked of it. */
  mutable play: int,
  mutable halt: bool,
  answered: Hashtbl.t(string, Event.answer),
};

let make = (~file, project, turn) => {
  file,
  root: Project.root(project),
  turn,
  m: Mutex.create(),
  wake: Condition.create(),
  play: 0,
  halt: false,
  answered: Hashtbl.create(4),
};

let locked = (s, f) => {
  Mutex.lock(s.m);
  Fun.protect(~finally=() => Mutex.unlock(s.m), f);
};

/* ---------- steps ---------- */

type step =
  | Say(string)
  | Wait(int)
  | Write({
      file: string,
      content: string,
    })
  | Edit({
      file: string,
      old: string,
      by: string,
    })
  | Ask({
      tool: string,
      input: Yojson.Safe.t,
    });

let step_of_json = (json: Yojson.Safe.t) =>
  Yojson.Safe.Util.(
    switch (json) {
    | `Assoc([("say", `String(text))]) => Some(Say(text))
    | `Assoc([("wait", `Int(ms))]) => Some(Wait(ms))
    | `Assoc([("write", w)]) =>
      Some(
        Write({
          file: w |> member("file") |> to_string,
          content: w |> member("content") |> to_string,
        }),
      )
    | `Assoc([("edit", e)]) =>
      Some(
        Edit({
          file: e |> member("file") |> to_string,
          old: e |> member("old") |> to_string,
          by: e |> member("new") |> to_string,
        }),
      )
    | `Assoc([("ask", r)]) =>
      Some(
        Ask({
          tool: r |> member("tool") |> to_string,
          input: r |> member("input"),
        }),
      )
    | _ => None
    }
  );

let replace = (~old, ~by, text) =>
  switch (Str.search_forward(Str.regexp_string(old), text, 0)) {
  | i =>
    let after = i + String.length(old);
    Some(
      String.sub(text, 0, i)
      ++ by
      ++ String.sub(text, after, String.length(text) - after),
    );
  | exception Not_found => None
  };

/* What the agent is told of the user's answer, and whether it is an error. */
let outcome = (answer: Event.answer) =>
  switch (answer) {
  | Deny => (true, "The user denied this.")
  | Answers(answers) => (
      false,
      String.concat(
        "; ",
        List.map(((q, answer)) => q ++ " = " ++ answer, answers),
      ),
    )
  | Once
  | Always(_) => (false, "Allowed.")
  };

/* ---------- playing ---------- */

exception Stopped;

let run = s => {
  let mine =
    locked(
      s,
      () => {
        s.play = s.play + 1;
        s.halt = false;
        s.play;
      },
    );
  Turn.happened(s.turn, Began);
  /* Ends the play when it was stopped; false once it has been forgotten. */
  let live = () =>
    locked(s, () =>
      if (s.play != mine) {
        false;
      } else if (s.halt) {
        raise(Stopped);
      } else {
        true;
      }
    );
  let str = text => `String(text);
  let message = (role, blocks) =>
    if (live()) {
      Turn.happened(
        s.turn,
        Told(
          `Assoc([
            ("type", str(role)),
            (
              "message",
              `Assoc([("role", str(role)), ("content", `List(blocks))]),
            ),
          ]),
        ),
      );
    };
  let uses = ref(0);
  let tool = (name, input) => {
    incr(uses);
    let id = Printf.sprintf("script_%d_%d", mine, uses^);
    message(
      "assistant",
      [
        `Assoc([
          ("type", str("tool_use")),
          ("id", str(id)),
          ("name", str(name)),
          ("input", input),
        ]),
      ],
    );
    id;
  };
  let result = (~error=false, id, text) =>
    message(
      "user",
      [
        `Assoc([
          ("type", str("tool_result")),
          ("tool_use_id", str(id)),
          ("content", str(text)),
          ("is_error", `Bool(error)),
        ]),
      ],
    );
  let abs = f => Filename.is_relative(f) ? s.root / f : f;
  let step =
    fun
    | Say(text) =>
      message(
        "assistant",
        [`Assoc([("type", str("text")), ("text", str(text))])],
      )
    | Wait(ms) =>
      /* In short naps, so a stop is noticed. */
      for (_ in 1 to max(1, Int.div(ms, 100))) {
        if (live()) {
          Thread.delay(0.1);
        };
      }
    | Write({file, content}) => {
        let file = abs(file);
        let id =
          tool(
            "Write",
            `Assoc([("file_path", str(file)), ("content", str(content))]),
          );
        Files.mkdir_p(Filename.dirname(file));
        Files.write(file, content);
        result(id, "File written.");
      }
    | Edit({file, old, by}) => {
        let file = abs(file);
        let id =
          tool(
            "Edit",
            `Assoc([
              ("file_path", str(file)),
              ("old_string", str(old)),
              ("new_string", str(by)),
            ]),
          );
        switch (replace(~old, ~by, Files.read(file))) {
        | Some(text) =>
          Files.write(file, text);
          result(id, "Edited.");
        | None => result(~error=true, id, "Error: old text not found.")
        };
      }
    | Ask({tool: name, input}) => {
        let id = tool(name, input);
        Turn.happened(
          s.turn,
          Asked({
            id,
            tool: name,
            input,
            suggestions: `Null,
            tool_use: Some(id),
          }),
        );
        let answer =
          locked(
            s,
            () => {
              while (s.play == mine && !s.halt && !Hashtbl.mem(s.answered, id)) {
                Condition.wait(s.wake, s.m);
              };
              Hashtbl.find_opt(s.answered, id);
            },
          );
        switch (answer) {
        | Some(answer) =>
          let (error, text) = outcome(answer);
          result(~error, id, text);
        | None => ignore(live())
        };
      };
  let finish = error =>
    if (locked(s, () => s.play == mine)) {
      Turn.happened(
        s.turn,
        Ended(
          `Assoc([
            ("type", str("result")),
            ("subtype", str(error ? "error_during_execution" : "success")),
            ("is_error", `Bool(error)),
          ]),
        ),
      );
    };
  switch (
    Yojson.Safe.from_file(s.file)
    |> Yojson.Safe.Util.member("steps")
    |> Yojson.Safe.Util.to_list
    |> List.iter(json =>
         if (live()) {
           Option.iter(step, step_of_json(json));
         }
       )
  ) {
  | () => finish(false)
  | exception Stopped => finish(true)
  | exception e =>
    Bus.emit(
      Error({
        where: "script",
        message: Printexc.to_string(e),
      }),
    );
    finish(true);
  };
};

let play = s => ignore(Thread.create(run, s));

let answer = (s, ~id, answer) =>
  locked(
    s,
    () => {
      Hashtbl.replace(s.answered, id, answer);
      Condition.broadcast(s.wake);
    },
  );

let stop = s =>
  locked(
    s,
    () => {
      s.halt = true;
      Condition.broadcast(s.wake);
    },
  );

let forget = s =>
  locked(
    s,
    () => {
      s.play = s.play + 1;
      Hashtbl.reset(s.answered);
      Condition.broadcast(s.wake);
    },
  );

files.sidecar/syntax.re:
type t =
  | Ml
  | Re;

let name =
  fun
  | Ml => "ml"
  | Re => "re";

let of_string =
  fun
  | "ml" => Some(Ml)
  | "re" => Some(Re)
  | _ => None;

/* The syntax a file is written in, and whether it is an interface. */
let of_path = path =>
  switch (Filename.extension(path)) {
  | ".ml" => Some((Ml, false))
  | ".mli" => Some((Ml, true))
  | ".re" => Some((Re, false))
  | ".rei" => Some((Re, true))
  | _ => None
  };

let slice = (~first, ~last, text) => {
  let lines = Array.of_list(String.split_on_char('\n', text));
  let n = Array.length(lines);
  let first = max(1, first);
  let last = min(n, Option.value(last, ~default=n));
  if (first > last) {
    "";
  } else {
    String.concat(
      "\n",
      Array.to_list(Array.sub(lines, first - 1, last - first + 1)),
    );
  };
};

let convert = (~path, ~first, ~last, ~target) => {
  let original = slice(~first, ~last, Files.read(path));
  switch (of_path(path)) {
  | None => (original, false)
  | Some((source, _)) when source == target => (original, true)
  | Some((source, interface)) =>
    let tmp = Filename.temp_file("portolan-", Filename.extension(path));
    Fun.protect(
      ~finally=
        () =>
          try(Sys.remove(tmp)) {
          | Sys_error(_) => ()
          },
      () => {
        Files.write(tmp, original);
        let command =
          Printf.sprintf(
            "refmt --parse %s --print %s --interface %b %s 2>/dev/null",
            name(source),
            name(target),
            interface,
            Filename.quote(tmp),
          );
        switch (Run.cmd(~timeout=20., ~cwd=Filename.dirname(tmp), command)) {
        | (0, converted) when String.trim(converted) != "" => (
            converted,
            true,
          )
        | _ => (original, false)
        };
      },
    );
  };
};

/* ---------- types ---------- */

/* Printed types already converted, by their OCaml text. */
let converted: Hashtbl.t(string, option(string)) = Hashtbl.create(1024);
let lock = Mutex.create();

/* refmt breaks long types over lines and leaves trailing commas; a type
   on the canvas is one line. */
let one_line = text => {
  let sub = (pattern, by, s) =>
    Str.global_replace(Str.regexp(pattern), by, s);
  let s = String.trim(sub("[ \n\t]+", " ", text));
  let s =
    String.ends_with(~suffix=";", s)
      ? String.sub(s, 0, String.length(s) - 1) : s;
  let s = sub(",? \\([})]\\)", "\\1", s) |> sub("\\([{(]\\) ", "\\1");
  String.starts_with(~prefix="| ", s)
    ? String.sub(s, 2, String.length(s) - 2) : s;
};

let split_types = (~count, converted) => {
  let bodies =
    Str.full_split(Str.regexp("^type p[0-9]+ ="), converted)
    |> List.filter_map(
         fun
         | Str.Text(body) when String.trim(body) != "" =>
           Some(one_line(body))
         | _ => None,
       );
  List.length(bodies) == count ? Some(bodies) : None;
};

/* One `refmt` run over all the texts, each as the body of a type
   definition; [None] if `refmt` rejects any of them. */
let batch = texts => {
  let tmp = Filename.temp_file("portolan-types-", ".ml");
  Fun.protect(
    ~finally=
      () =>
        try(Sys.remove(tmp)) {
        | Sys_error(_) => ()
        },
    () => {
      Files.write(
        tmp,
        String.concat(
          "\n",
          List.mapi((i, t) => Printf.sprintf("type p%d = %s", i, t), texts),
        ),
      );
      let command =
        Printf.sprintf(
          "refmt --parse ml --print re --print-width 400 %s 2>/dev/null",
          Filename.quote(tmp),
        );
      switch (Run.cmd(~timeout=30., ~cwd=Filename.dirname(tmp), command)) {
      | (0, out) => split_types(~count=List.length(texts), out)
      | _ => None
      };
    },
  );
};

/* Halves a rejected batch until the texts `refmt` cannot read are alone. */
let rec convert_all = texts =>
  switch (texts) {
  | [] => []
  | _ =>
    switch (batch(texts)) {
    | Some(bodies) => List.map(Option.some, bodies)
    | None =>
      switch (texts) {
      | [_] => [None]
      | _ =>
        let half = List.length(texts) / 2;
        convert_all(List.filteri((i, _) => i < half, texts))
        @ convert_all(List.filteri((i, _) => i >= half, texts));
      }
    }
  };

let types = texts => {
  Mutex.lock(lock);
  Fun.protect(
    ~finally=() => Mutex.unlock(lock),
    () => {
      let fresh =
        List.sort_uniq(compare, texts)
        |> List.filter(t =>
             String.trim(t) != "" && !Hashtbl.mem(converted, t)
           );
      List.iter2(Hashtbl.replace(converted), fresh, convert_all(fresh));
      List.map(t => Option.join(Hashtbl.find_opt(converted, t)), texts);
    },
  );
};

