  );

let texts = lines => List.map(Event.Line.to_string, lines);

/* The graph a viewer arriving after [lines] is sent. */
let latest = lines =>
  List.find_map(Event.Line.drawing, Graphs.collapse(lines));

let tests = [
  case("the first graph is sent whole", () =>
    Alcotest.(check(bool))(
      "whole",
      true,
      Graphs.encode(~previous=None, ~since=0, graph(20))
      == (Whole(graph(20)), 0),
    )
  ),
  case("a small change is sent as a change, and counted", () =>
    switch (
      Graphs.encode(~previous=Some(graph(20)), ~since=100, graph(21))
    ) {
    | (Change(change), since) =>
      Alcotest.check(
        json,
        "the change gives the new graph",
        graph(21),
        Delta.apply(graph(20), change),
      );
      Alcotest.(check(int))("bytes since", 100 + size(change), since);
    | (Whole(_), _) => Alcotest.fail("sent whole")
    }
  ),
  case("a change half the size of the graph is sent whole", () =>
    Alcotest.(check(bool))(
      "whole",
      true,
      Graphs.encode(~previous=Some(graph(2)), ~since=0, graph(20))
      == (Whole(graph(20)), 0),
    )
  ),
  case("changes that add up to a whole graph send it whole again", () => {
    let whole = size(graph(21));
    Alcotest.(check(bool))(
      "whole",
      true,
      Graphs.encode(
        ~previous=Some(graph(20)),
        ~since=whole - 10,
        graph(21),
      )
      == (Whole(graph(21)), 0),
    );
  }),
  case("a late viewer gets one whole graph, where the last one was", () => {
    let change =
      switch (Delta.diff(graph(20), graph(21))) {
      | Some(change) => change
      | None => Alcotest.fail("no change")
      };
    Alcotest.check(
      strings,
      "events",
      texts([
        build(1),
        build(3),
        graph_line(4, Whole(graph(21))),
        build(5),
      ]),
      texts(
        Graphs.collapse([
          build(1),
          graph_line(2, Whole(graph(20))),
          build(3),
          graph_line(4, Change(change)),
          build(5),
        ]),
      ),
    );
  }),
  case("a trace without graphs is sent as it is", () =>
    Alcotest.check(
      strings,
      "events",
      texts([build(1), build(2)]),
      texts(Graphs.collapse([build(1), build(2)])),
    )
  ),
  case("changes with no whole graph before them are left out", () =>
    Alcotest.check(
      strings,
      "events",
      texts([build(1), build(3)]),
      texts(
        Graphs.collapse([
          build(1),
          graph_line(2, Change(parse({|{"drop":["edges"]}|}))),
          build(3),
        ]),
      ),
    )
  ),
  case("a compacted trace is smaller and ends with the same graph", () => {
    let whole =
      [build(0)]
      @ List.init(8, i => graph_line(i + 1, Whole(graph(20 + i))))
      @ [build(9)];
    let compacted = Graphs.compact(whole);
    let bytes = lines =>
      List.fold_left(
        (n, text) => n + String.length(text),
        0,
        texts(lines),
      );
    Alcotest.(check(bool))(
      "smaller",
      true,
      bytes(compacted) < bytes(whole),
    );
    Alcotest.(check(int))(
      "as many events",
      List.length(whole),
      List.length(compacted),
    );
    Alcotest.(check(bool))(
      "the first graph stays whole",
      true,
      Event.Line.draws(List.nth(compacted, 1)) == Some(`Whole),
    );
    Alcotest.(check(bool))(
      "the same graph at the end",
      true,
      latest(compacted) == Some(Whole(graph(27))),
    );
    Alcotest.check(
      strings,
      "compacting again changes nothing",
      texts(compacted),
      texts(Graphs.compact(compacted)),
    );
  }),
];

files.sidecar/test/test_permissions.re:
open Portolan_sidecar;
open Testing;

/* The patterns offered for a shell command nothing else suggests. */
let offered = command =>
  Permissions.suggest(
    ~tool="Bash",
    ~input=`Assoc([("command", `String(command))]),
    ~suggestions=`Null,
  );

let offers = (command, patterns) =>
  Alcotest.check(strings, command, patterns, offered(command));

let tests = [
  case("a command is widened to its leading word", () => {
    offers("python3 gen.py --all", ["Bash(python3:*)"]);
    offers("make", ["Bash(make:*)"]);
  }),
  case("a tool with sub-commands is widened to the sub-command", () => {
    offers("git push origin main", ["Bash(git push:*)"]);
    offers("git -C . status --short", ["Bash(git -C . status:*)"]);
    offers("opam install yojson", ["Bash(opam install:*)"]);
  }),
  case("a tool with sub-commands and none given stays exact", () =>
    offers("git --version", ["Bash(git --version)"])
  ),
  case("a risky command stays exact", () => {
    offers("rm -rf _build", ["Bash(rm -rf _build)"]);
    offers("sudo make install", ["Bash(sudo make install)"]);
    offers("curl https://example.com", ["Bash(curl https://example.com)"]);
  }),
  case("a command that is already a pattern is kept", () =>
    offers("make:*", ["Bash(make:*)"])
  ),
  case("a pipeline offers a pattern for each command, sorted", () =>
    offers(
      "ocamlformat --check lib/scene.ml && git -C . status --short | head -3",
      ["Bash(git -C . status:*)", "Bash(head:*)", "Bash(ocamlformat:*)"],
    )
  ),
  case("the same command twice is offered once", () =>
    offers("ls lib; ls test", ["Bash(ls:*)"])
  ),
  case("a file outside the project offers its folder", () =>
    Alcotest.check(
      strings,
      "patterns",
      ["Read(//etc/**)"],
      Permissions.suggest(
        ~tool="Read",
        ~input=parse({|{"file_path":"/etc/hosts"}|}),
        ~suggestions=`Null,
      ),
    )
  ),
  case("a tool with nothing to narrow it is offered whole", () => {
    let whole = (tool, input) =>
      Alcotest.check(
        strings,
        tool,
        [tool],
        Permissions.suggest(~tool, ~input=parse(input), ~suggestions=`Null),
      );
    whole("WebSearch", {|{"query":"ocaml"}|});
    whole("Edit", {|{"file_path":"lib/scene.ml"}|});
  }),
  case("Claude Code's suggested rules win, with commands widened", () =>
    Alcotest.check(
      strings,
      "patterns",
      ["Bash(git push:*)", "Bash(python3:*)", "Read(//etc/**)", "WebFetch"],
      Permissions.suggest(
        ~tool="Bash",
        ~input=parse({|{"command":"something else entirely"}|}),
        ~suggestions=
          parse(
            {|[{"type":"addRules","behavior":"allow","destination":"localSettings","rules":[
                 {"toolName":"Bash","ruleContent":"python3 gen.py"},
                 {"toolName":"Bash","ruleContent":"git push origin main"},
                 {"toolName":"Read","ruleContent":"//etc/**"},
                 {"toolName":"WebFetch"}]},
               {"type":"setMode","mode":"acceptEdits"},
               {"type":"addRules","behavior":"deny","rules":[{"toolName":"Bash","ruleContent":"ls"}]}]|},
          ),
      ),
    )
  ),
  case("a pattern is a tool and what it may do, as Claude Code's rule", () => {
    let rule = (pattern, expected) =>
      Alcotest.check(
        json,
        pattern,
        parse(expected),
        Permissions.rule(pattern),
      );
    rule("Bash(make:*)", {|{"toolName":"Bash","ruleContent":"make:*"}|});
    rule(
      "Bash(git -C . status)",
      {|{"toolName":"Bash","ruleContent":"git -C . status"}|},
    );
    rule("WebSearch", {|{"toolName":"WebSearch"}|});
  }),
  case("only patterns not yet remembered are added, trimmed, each once", () =>
    Alcotest.check(
      strings,
      "fresh",
      ["Bash(git commit:*)", "Read(//etc/**)"],
      Permissions.fresh(
        ~known=["Bash(git add:*)", "Bash(ocamlformat:*)"],
        [
          "Bash(git add:*)",
          " Bash(git commit:*) ",
          "Bash(ocamlformat:*)",
          "",
          "Read(//etc/**)",
          "Bash(git commit:*)",
        ],
      ),
    )
  ),
];

files.sidecar/test/test_protocol.re:
open Portolan_sidecar;
open Testing;

let said = (line, expected) =>
  Alcotest.(check(bool))(line, true, Protocol.read(line) == expected);

let written = (expected, message) =>
  Alcotest.(check(string))(expected, expected, Protocol.to_string(message));

/* Paths under /project are the project's. */
let relative = path => {
  let root = "/project/";
  String.starts_with(~prefix=root, path)
    ? Some(
        String.sub(
          path,
          String.length(root),
          String.length(path) - String.length(root),
        ),
      )
    : None;
};

let tool_use = (name, input) =>
  Printf.sprintf(
    {|{"type":"tool_use","id":"toolu_1","name":"%s","input":%s}|},
    name,
    input,
  );

let assistant = blocks =>
  parse(
    Printf.sprintf(
      {|{"type":"assistant","message":{"role":"assistant","content":[%s]}}|},
      String.concat(",", blocks),
    ),
  );

let cause = (name, blocks, expected) =>
  Alcotest.(check(bool))(
    name,
    true,
    Protocol.cause(~relative, assistant(blocks)) == expected,
  );

let questions = {|{"questions":[{"question":"Which?","options":[{"label":"A"},{"label":"B"}]}]}|};

let tests = [
  case("the start of a turn names Claude Code's session", () => {
    let init = {|{"type":"system","subtype":"init","session_id":"abc","model":"haiku"}|};
    said(init, Began(parse(init), Some("abc")));
    let bare = {|{"type":"system","subtype":"init"}|};
    said(bare, Began(parse(bare), None));
  }),
  case("a result ends the turn", () => {
    let result = {|{"type":"result","subtype":"success","is_error":false}|};
    said(result, Ended(parse(result)));
  }),
  case("any other event of the stream is passed on", () =>
    List.iter(
      line => said(line, Told(parse(line))),
      [
        {|{"type":"assistant","message":{"role":"assistant","content":[]}}|},
        {|{"type":"system","subtype":"status"}|},
        {|{"type":"stream_event","event":{"type":"content_block_delta"}}|},
        {|{"no type":true}|},
      ],
    )
  ),
  case("a request to use a tool is read whole", () =>
    said(
      {|{"type":"control_request","request_id":"req_a","request":{"subtype":"can_use_tool","tool_name":"Bash","input":{"command":"make"},"permission_suggestions":[{"type":"setMode"}],"tool_use_id":"toolu_a"}}|},
      Asked({
        id: "req_a",
        tool: "Bash",
        input: parse({|{"command":"make"}|}),
        suggestions: parse({|[{"type":"setMode"}]|}),
        tool_use: Some("toolu_a"),
      }),
    )
  ),
  case("a request may come without suggestions or a tool use", () =>
    said(
      {|{"type":"control_request","request_id":"req_c","request":{"subtype":"can_use_tool","tool_name":"Read","input":{"file_path":"/etc/hosts"}}}|},
      Asked({
        id: "req_c",
        tool: "Read",
        input: parse({|{"file_path":"/etc/hosts"}|}),
        suggestions: `Null,
        tool_use: None,
      }),
    )
  ),
  case("a request of another kind is owed a refusal", () =>
    said(
      {|{"type":"control_request","request_id":"req_u","request":{"subtype":"mcp_message"}}|},
      Asked_other("req_u"),
    )
  ),
  case("a request too malformed to answer is dropped", () =>
    List.iter(
      line => said(line, Nothing),
      [
        {|{"type":"control_request","request":{"subtype":"can_use_tool"}}|},
        {|{"type":"control_request","request_id":"r"}|},
        {|{"type":"control_request","request_id":"r","request":{"subtype":"can_use_tool","input":{}}}|},
      ],
    )
  ),
  case("a request can be withdrawn", () => {
    said(
      {|{"type":"control_cancel_request","request_id":"req_x"}|},
      Withdrew("req_x"),
    );
    said({|{"type":"control_cancel_request"}|}, Nothing);
  }),
  case("the acknowledgement of a request of ours says nothing", () =>
    said(
      {|{"type":"control_response","response":{"subtype":"success","request_id":"stop-1"}}|},
      Nothing,
    )
  ),
  case("output that is not a JSON object is raw, unless it is blank", () => {
    said("this is not json", Raw("this is not json"));
    said("{\"type\":\"assis", Raw("{\"type\":\"assis"));
    said("[1,2]", Raw("[1,2]"));
    said("12", Raw("12"));
    said("", Nothing);
    said("  \t", Nothing);
  }),
  case("a write or an edit is the cause, by its path in the project", () => {
    cause(
      "write",
      [tool_use("Write", {|{"file_path":"/project/lib/scene.ml"}|})],
      Some(
        Wrote({
          tool: "Write",
          file: "lib/scene.ml",
        }),
      ),
    );
    cause(
      "edit outside",
      [tool_use("MultiEdit", {|{"file_path":"/etc/hosts"}|})],
      Some(
        Wrote({
          tool: "MultiEdit",
          file: "/etc/hosts",
        }),
      ),
    );
  }),
  case("a shell command is the cause, cut if it is long", () => {
    cause(
      "short",
      [tool_use("Bash", {|{"command":"dune build"}|})],
      Some(Ran("dune build")),
    );
    cause(
      "long",
      [
        tool_use("Bash", "{\"command\":\"" ++ String.make(200, 'x') ++ "\"}"),
      ],
      Some(Ran(String.make(120, 'x') ++ "\n…")),
    );
  }),
  case("of several tool uses the last one that changes files is the cause", () =>
    cause(
      "three",
      [
        tool_use("Bash", {|{"command":"ls"}|}),
        tool_use("Edit", {|{"file_path":"/project/a.ml"}|}),
        tool_use("Read", {|{"file_path":"/project/b.ml"}|}),
      ],
      Some(
        Wrote({
          tool: "Edit",
          file: "a.ml",
        }),
      ),
    )
  ),
  case("words, reads and results change nothing", () => {
    cause("text", [{|{"type":"text","text":"Write Bash Edit"}|}], None);
    cause(
      "read",
      [tool_use("Read", {|{"file_path":"/project/a.ml"}|})],
      None,
    );
    Alcotest.(check(bool))(
      "a result",
      true,
      Protocol.cause(
        ~relative,
        parse(
          {|{"type":"user","message":{"role":"user","content":[{"type":"tool_result","tool_use_id":"toolu_1","content":"Edit"}]}}|},
        ),
      )
      == None,
    );
    Alcotest.(check(bool))(
      "not a message",
      true,
      Protocol.cause(~relative, parse({|{"type":"result"}|})) == None
      && Protocol.cause(~relative, parse("[]")) == None,
    );
  }),
  case("a prompt goes in as the user's message", () =>
    written(
      {|{"type":"user","message":{"role":"user","content":"Add a perimeter."}}|},
      Protocol.prompt("Add a perimeter."),
    )
  ),
  case("allowing once gives the tool its input back", () =>
    written(
      {|{"type":"control_response","response":{"subtype":"success","request_id":"req_b","response":{"behavior":"allow","updatedInput":{"command":"rm -rf old"}}}}|},
      Protocol.answer(
        ~id="req_b",
        ~input=parse({|{"command":"rm -rf old"}|}),
        Once,
      ),
    )
  ),
  case("allowing always adds the patterns as rules for the session", () =>
    written(
      {|{"type":"control_response","response":{"subtype":"success","request_id":"req_a","response":{"behavior":"allow","updatedInput":{"command":"git push"},"updatedPermissions":[{"type":"addRules","rules":[{"toolName":"Bash","ruleContent":"git push:*"},{"toolName":"WebSearch"}],"behavior":"allow","destination":"session"}]}}}|},
      Protocol.answer(
        ~id="req_a",
        ~input=parse({|{"command":"git push"}|}),
        Always(["Bash(git push:*)", "WebSearch"]),
      ),
    )
  ),
  case("allowing always with no patterns is allowing once", () =>
    Alcotest.(check(string))(
      "same line",
      Protocol.to_string(Protocol.answer(~id="r", ~input=`Null, Once)),
      Protocol.to_string(
        Protocol.answer(~id="r", ~input=`Null, Always([])),
      ),
    )
  ),
  case("a denial tells the agent not to retry", () =>
    written(
      {|{"type":"control_response","response":{"subtype":"success","request_id":"req_c","response":{"behavior":"deny","message":"The user declined this in Portolan's chat. Do not retry it; carry on another way or ask what they would prefer."}}}|},
      Protocol.answer(~id="req_c", ~input=parse("{}"), Deny),
    )
  ),
  case("answers go back in the questions' input, replacing any there", () => {
    written(
      {|{"type":"control_response","response":{"subtype":"success","request_id":"req_q","response":{"behavior":"allow","updatedInput":{"questions":[{"question":"Which?","options":[{"label":"A"},{"label":"B"}]}],"answers":{"Which?":"B"}}}}}|},
      Protocol.answer(
        ~id="req_q",
        ~input=parse(questions),
        Answers([("Which?", "B")]),
      ),
    );
    written(
      {|{"type":"control_response","response":{"subtype":"success","request_id":"req_q","response":{"behavior":"allow","updatedInput":{"questions":[],"answers":{"Which?":"A, B"}}}}}|},
      Protocol.answer(
        ~id="req_q",
        ~input=parse({|{"answers":{"old":"x"},"questions":[]}|}),
        Answers([("Which?", "A, B")]),
      ),
    );
  }),
  case("a request Portolan does not handle is refused", () =>
    written(
      {|{"type":"control_response","response":{"subtype":"error","request_id":"req_u","error":"Portolan does not handle this request."}}|},
      Protocol.refusal(~id="req_u"),
    )
  ),
  case("a stop is an interrupt request", () =>
    written(
      {|{"type":"control_request","request_id":"stop-7","request":{"subtype":"interrupt"}}|},
      Protocol.interrupt(~id="stop-7"),
    )
  ),
];

