/* What the tests share. */

let case = (name, f) => Alcotest.test_case(name, `Quick, f);

let parse = Yojson.Safe.from_string;

let json =
  Alcotest.testable(
    (ppf, j) => Format.pp_print_string(ppf, Yojson.Safe.to_string(j)),
    Yojson.Safe.equal,
  );

let strings = Alcotest.(list(string));

files.sidecar/turn.re:
type standing = {
  /* The state last reported. */
  state: Event.state,
  finished: int,
  /* Requests waiting for the user's answer, oldest first: id and the
     tool's input. */
  pending: list((string, Yojson.Safe.t)),
};

let idle = {
  state: Idle,
  finished: 0,
  pending: [],
};

type happening =
  | Began
  | Told(Yojson.Safe.t)
  | Ended(Yojson.Safe.t)
  | Asked(Protocol.request)
  | Withdrew(string)
  | Answered(string, Event.answer)
  | Exited
  | Forgotten;

/* In [state], reported if that is a change. */
let now = (s, state) =>
  s.state == state
    ? (s, [])
    : (
      {
        ...s,
        state,
      },
      [Event.Agent_state(state)],
    );

let cancelled = pending =>
  List.map(
    ((id, _)) =>
      Event.Answer({
        id,
        answer: None,
      }),
    pending,
  );

let step = (s, happening) =>
  switch (happening) {
  | Began => now(s, Running)
  | Told(ev) => (s, [Event.Agent(ev)])
  | Ended(ev) =>
    let (next, reported) =
      now(
        {
          ...s,
          finished: s.finished + 1,
          pending: [],
        },
        Idle,
      );
    (next, [Event.Agent(ev)] @ cancelled(s.pending) @ reported);
  | Asked({id, tool, input, suggestions, tool_use}) =>
    let (next, reported) =
      now(
        {
          ...s,
          pending: List.remove_assoc(id, s.pending) @ [(id, input)],
        },
        Waiting,
      );
    (
      next,
      [
        Event.Ask({
          id,
          tool,
          input,
          /* A question is answered, not allowed. */
          patterns:
            tool == "AskUserQuestion"
              ? [] : Permissions.suggest(~tool, ~input, ~suggestions),
          tool_use,
        }),
        ...reported,
      ],
    );
  | Withdrew(id) when List.mem_assoc(id, s.pending) => (
      {
        ...s,
        pending: List.remove_assoc(id, s.pending),
      },
      cancelled([(id, `Null)]),
    )
  | Answered(id, answer) when List.mem_assoc(id, s.pending) =>
    let left = {
      ...s,
      pending: List.remove_assoc(id, s.pending),
    };
    let (next, reported) =
      left.pending == [] ? now(left, Running) : (left, []);
    (
      next,
      [
        Event.Answer({
          id,
          answer: Some(answer),
        }),
        ...reported,
      ],
    );
  | Withdrew(_)
  | Answered(_) => (s, [])
  | Exited =>
    let (next, reported) =
      now(
        {
          ...s,
          pending: [],
        },
        Exited,
      );
    (next, cancelled(s.pending) @ reported);
  | Forgotten => (
      {
        ...s,
        state: Idle,
        pending: [],
      },
      [],
    )
  };

let state = s => s.state;
let finished = s => s.finished;
let waiting = (s, id) => List.assoc_opt(id, s.pending);

type t = {
  project: Project.t,
  m: Mutex.t,
  mutable standing,
  /* What the agent last did to the files; guarded by its own lock. */
  cause_m: Mutex.t,
  mutable cause: option(Event.cause),
};

let make = project => {
  project,
  m: Mutex.create(),
  standing: idle,
  cause_m: Mutex.create(),
  cause: None,
};

let locked = (t, f) => {
  Mutex.lock(t.m);
  Fun.protect(~finally=() => Mutex.unlock(t.m), f);
};

/* Call with [t.m] held. */
let take = (t, happening) => {
  let (next, events) = step(t.standing, happening);
  t.standing = next;
  List.iter(Bus.emit, events);
};

let happened = (t, happening) => {
  switch (happening) {
  | Told(ev)
  | Ended(ev) =>
    switch (Protocol.cause(~relative=Project.relative(t.project), ev)) {
    | Some(cause) =>
      Mutex.lock(t.cause_m);
      t.cause = Some(cause);
      Mutex.unlock(t.cause_m);
    | None => ()
    }
  | _ => ()
  };
  locked(t, () => take(t, happening));
};

let answered = (t, ~id, answer) =>
  locked(
    t,
    () => {
      let input = waiting(t.standing, id);
      if (input != None) {
        take(t, Answered(id, answer));
      };
      input;
    },
  );

let standing = t => locked(t, () => t.standing);

let take_cause = t => {
  Mutex.lock(t.cause_m);
  let cause = t.cause;
  t.cause = None;
  Mutex.unlock(t.cause_m);
  Option.value(cause, ~default=Event.By_hand);
};

files.sidecar/watcher.re:
let (/) = Filename.concat;

type t = {
  project: Project.t,
  extractor: string,
  cause: unit => Event.cause,
  /* The graph last sent, as compact JSON. */
  mutable last_graph: option(string),
  /* The failing tests of the last test run; None before the first. */
  mutable last_failing: option(list((string, int))),
};

/* ---------- which files count ---------- */

/* An OCaml or Reason file, as opposed to a dune file. */
let is_code = name =>
  List.exists(
    ext => Filename.check_suffix(name, ext),
    [".ml", ".mli", ".re", ".rei", ".mll", ".mly"],
  );

let is_source = name =>
  is_code(name)
  || List.mem(name, ["dune", "dune-project", "dune-workspace"]);

/* Build folders, hidden folders and the like are not the project's own. */
let is_skipped = name =>
  name == "" || name.[0] == '.' || name.[0] == '_' || name == "node_modules";

/* Every source file with its time and size: differs when anything changed. */
let signature = root => {
  let rec scan = (acc, dir) =>
    Array.fold_left(
      (acc, name) =>
        if (is_skipped(name)) {
          acc;
        } else {
          let p = dir / name;
          switch (Unix.lstat(p)) {
          | {Unix.st_kind: Unix.S_DIR, _} => scan(acc, p)
          | {Unix.st_kind: Unix.S_REG, st_mtime, st_size, _}
              when is_source(name) => [
              (p, st_mtime, st_size),
              ...acc,
            ]
          | _ => acc
          | exception (Unix.Unix_error(_)) => acc
          };
        },
      acc,
      try(Sys.readdir(dir)) {
      | Sys_error(_) => [||]
      },
    );
  List.sort(compare, scan([], root));
};

/* ---------- reading tool output ---------- */

/* Every `File "lib/scene.ml", line 21` in a compiler's or a test runner's
   output, as (file, line), in order, without repeats. */
let locations = out => {
  let acc = ref([]);
  let key = "File \"";
  let rec go = i =>
    switch (Str.search_forward(Str.regexp_string(key), out, i)) {
    | exception Not_found => ()
    | j =>
      let s = j + String.length(key);
      switch (String.index_from_opt(out, s, '"')) {
      | Some(e) =>
        let file = String.sub(out, s, e - s);
        let rest = String.sub(out, e, min(40, String.length(out) - e));
        try(
          /* "line 3" or, for an error over several lines, "lines 3-5". */
          Scanf.sscanf(rest, "\", line%_[s] %d", n =>
            if (!List.mem((file, n), acc^)) {
              acc := [(file, n), ...acc^];
            }
          )
        ) {
        | _ => ()
        };
      | None => ()
      };
      go(s + 1);
    };
  go(0);
  List.rev(acc^);
};

/* The cases Alcotest lists as failed, "[FAIL]  suite  0  name.", each
   as ("alcotest:" ++ suite, its place in the suite): how the extractor
   is told of them. Alcotest prints a location for the first failure only. */
let alcotest_failures = out => {
  let line =
    Str.regexp("\\[FAIL\\] +\\([^ ]+\\( [^ ]+\\)*\\) +\\([0-9]+\\)   ");
  let rec go = (i, acc) =>
    switch (Str.search_forward(line, out, i)) {
    | exception Not_found => List.rev(acc)
    | _ =>
      let failed = (
        "alcotest:" ++ Str.matched_group(1, out),
        int_of_string(Str.matched_group(3, out)),
      );
      go(Str.match_end(), List.mem(failed, acc) ? acc : [failed, ...acc]);
    };
  go(0, []);
};

/* The locations that are in the project's own sources, relative to its
   root; those in build folders or outside the project are dropped. */
let in_project = (project, locs) =>
  List.filter_map(
    ((file, line)) => {
      let rel =
        Filename.is_relative(file)
          ? Some(file) : Project.relative(project, file);
      switch (rel) {
      | Some(rel)
          when
            !List.exists(is_skipped, String.split_on_char('/', rel))
            && Project.file(project, rel) != None =>
        Some((rel, line))
      | _ => None
      };
    },
    locs,
  );

/* ---------- the extractor ---------- */

let last_graph_file = ".portolan" / "last-graph.json";

/* Runs the extractor. [broken] is None after a good build; after a failed
   one it holds the error locations, and the extractor is also given the
   last graph to carry over what no longer compiles. */
let extract = (w, ~broken) => {
  let pairs = l =>
    String.concat(
      ",",
      List.map(((f, n)) => Printf.sprintf("%s:%d", f, n), l),
    );
  let flag = (name, value) => " " ++ name ++ " " ++ Filename.quote(value);
  let failing =
    switch (w.last_failing) {
    | Some(l) => flag("--failing", pairs(l))
    | None => ""
    };
  let carried =
    switch (broken) {
    | Some(locs) =>
      (
        Project.file(w.project, last_graph_file) != None
          ? flag("--previous", last_graph_file) : ""
      )
      ++ flag("--broken", pairs(locs))
    | None => ""
    };
  let errors = Project.state(w.project, "extract.err");
  let (code, out) =
    Run.cmd(
      ~timeout=60.,
      ~cwd=Project.root(w.project),
      Printf.sprintf(
        "%s . --build-dir %s%s%s 2>%s",
        Filename.quote(w.extractor),
        Project.build_dir,
        failing,
        carried,
        Filename.quote(errors),
      ),
    );
  let graph =
    try(code == 0 ? Some(Yojson.Safe.from_string(out)) : None) {
    | _ => None
    };
  switch (graph) {
  | Some(graph) => Ok(graph)
  | None =>
    let said =
      try(Files.read(errors)) {
      | Sys_error(_) => ""
      };
    Error(String.trim(said ++ "\n" ++ out));
  };
};

/* Whether the build folder holds any compiled annotation at all. */
let anything_compiled = project => {
  let rec any = dir =>
    Array.exists(
      name => {
        let p = dir / name;
        Filename.check_suffix(name, ".cmt")
        || Filename.check_suffix(name, ".cmti")
        || (
          try(Sys.is_directory(p)) {
          | Sys_error(_) => false
          }
        )
        && any(p);
      },
      try(Sys.readdir(dir)) {
      | Sys_error(_) => [||]
      },
    );
  any(Project.root(project) / Project.build_dir / "default");
};

/* Draws the graph and sends it, with its cause [why], if it is new. */
let emit_graph = (w, ~why, ~broken=?, ()) =>
  switch (extract(w, ~broken)) {
  | Ok(graph) =>
    let json = Yojson.Safe.to_string(graph);
    if (Some(json) != w.last_graph) {
      w.last_graph = Some(json);
      Files.write(Project.root(w.project) / last_graph_file, json);
      Graphs.emit(~cause=why, ~partial=broken != None, graph);
    };
  /* A failed build with no graph to show for it: the page keeps the last
     picture. A good build with nothing compiled yet has nothing to say. */
  | Error(_) when broken != None || !anything_compiled(w.project) => ()
  | Error(output) => Bus.emit(Extract_failed(Event.clip(output)))
  };

/* ---------- one round ---------- */

let cycle = w =>
  if (Sys.file_exists(Project.root(w.project) / "dune-project")) {
    Project.ensure_build_dir(w.project);
    /* Asked once per change, sent or not, so a cause is never left over
       for a later change by someone else. */
    let why = w.cause();
    let started = Unix.gettimeofday();
    let (code, out) =
      Project.run(
        w.project,
        Printf.sprintf(
          "dune build --root . --build-dir %s @check 2>&1",
          Project.build_dir,
        ),
      );
    Bus.emit(
      Build({
        ok: code == 0,
        output: Event.clip(out),
        ms: int_of_float((Unix.gettimeofday() -. started) *. 1000.),
      }),
    );
    if (code == 0) {
      /* First with the test results we already had, so pips do not blink. */
      emit_graph(w, ~why, ());
      let (tcode, tout) =
        Project.run(
          ~timeout=90.,
          w.project,
          Printf.sprintf(
            "dune test --root . --build-dir %s 2>&1",
            Project.build_dir,
          ),
        );
      /* Dune names its own files too (the test rule in a `dune` file). */
      let failing =
        List.filter(((f, _)) => is_code(f), locations(tout))
        @ alcotest_failures(tout);
      w.last_failing = Some(failing);
      Bus.emit(
        Tests({
          ok: tcode == 0,
          output: Event.clip(tout),
          failing,
        }),
      );
      emit_graph(w, ~why=Tested, ());
    } else {
      emit_graph(
        w,
        ~why,
        ~broken=in_project(w.project, locations(out)),
        (),
      );
    };
  };

/* ---------- start ---------- */

/* Where the last session left off, read from the bus's backlog. */
let resume = w => {
  switch (Graphs.resume(Bus.all())) {
  | Some(graph) =>
    let json = Yojson.Safe.to_string(graph);
    w.last_graph = Some(json);
    Files.write(Project.root(w.project) / last_graph_file, json);
  | None =>
    /* No graph on the page: a file left from another trace is not its past. */
    try(Sys.remove(Project.root(w.project) / last_graph_file)) {
    | Sys_error(_) => ()
    }
  };
  switch (Bus.last(Tests)) {
  | Some(Tests({failing, _})) => w.last_failing = Some(failing)
  | _ => ()
  };
};

/* The extractor reads annotations written by the project's compiler, and
   only understands those of its own compiler version. */
let check_compiler = w =>
  switch (Project.run(~timeout=20., w.project, "ocamlc -version 2>/dev/null")) {
  | (0, version)
      when !String.starts_with(~prefix="5.2.", String.trim(version)) =>
    Bus.emit(
      Error({
        where: "switch",
        message:
          "the project's compiler is OCaml "
          ++ String.trim(version)
          ++ "; Portolan can only draw projects built with OCaml 5.2.x for now",
      }),
    )
  | _ => ()
  };

let start = (~extractor, ~cause, project) => {
  let w = {
    project,
    extractor,
    cause,
    last_graph: None,
    last_failing: None,
  };
  resume(w);
  let run = () => {
    check_compiler(w);
    let last = ref([])
    and settled = ref([]);
    while (true) {
      try({
        let s = signature(Project.root(project));
        /* Act once the tree has been the same for two looks in a row. */
        if (s != last^ && s == settled^) {
          last := s;
          cycle(w);
        };
        settled := s;
      }) {
      | e =>
        Bus.emit(
          Error({
            where: "watcher",
            message: Printexc.to_string(e),
          }),
        )
      };
      Thread.delay(0.25);
    };
  };
  ignore(Thread.create(run, ()));
};
